INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42964, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会場は非常の熱気に包まれた。", "corrected_sentence": "会場は非常な熱気に包まれた。", "error_description": "程度を表す連体修飾は「非常な」。「非常の」は緊急の意味の形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "非常", "is_correct": true, "explanation": "文中の「非常な」は語幹「非常」に連体の「な」が付いた形で、語幹の「非常」が正しい。"}, {"text": "非常だった", "is_correct": false, "explanation": "「非常だった」は過去の断定の形で、名詞「暑さ」を修飾する位置には使えない。"}, {"text": "非常でない", "is_correct": false, "explanation": "「非常でない」は否定形で、「暑さ」を修飾すると意味が逆になる。"}, {"text": "非常だろう", "is_correct": false, "explanation": "「非常だろう」は推量の形で、名詞「暑さ」を修飾できない。"}], "correct_form": "非常", "base_form": "非常だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"非常": "文中の「非常な」は語幹「非常」に連体の「な」が付いた形で、語幹の「非常」が正しい。", "非常だった": "「非常だった」は過去の断定の形で、名詞「暑さ」を修飾する位置には使えない。", "非常でない": "「非常でない」は否定形で、「暑さ」を修飾すると意味が逆になる。", "非常だろう": "「非常だろう」は推量の形で、名詞「暑さ」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
