INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45194, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものとインターネットをつなぐしくみのことです。", "primary_collocate": null, "pronunciation": "あいおーてぃー", "ipa": "aioːtiː", "syllable_count": 6, "sentences": [{"text": "IoT のおかげで、外出先からも家のエアコンを動かせる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT のおかげで、外出先[がいしゅつさき]からも家[いえ]のエアコンを動[うご]かせる。", "sentence_source": "generated"}, {"text": "この町では、IoT を使って道路のようすを調べている。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "この町[まち]では、IoT を使[つか]って道路[どうろ]のようすを調[しら]べている。", "sentence_source": "generated"}, {"text": "IoT は、ものをインターネットにつなぐしくみだ。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT は、ものをインターネットにつなぐしくみだ。", "sentence_source": "generated"}, {"text": "農家は IoT で畑の水の量を確認している。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "農家[のうか]は IoT で畑[はたけ]の水[みず]の量[りょう]を確認[かくにん]している。", "sentence_source": "generated"}, {"text": "IoT が広がると、くらしがもっと便利になる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT が広[ひろ]がると、くらしがもっと便利[べんり]になる。", "sentence_source": "generated"}, {"text": "祖父は IoT がよく分からないので、孫に説明してもらった。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "祖父[そふ]は IoT がよく分[わ]からないので、孫[まご]に説明[せつめい]してもらった。", "sentence_source": "generated"}, {"text": "工場では IoT を入れて、機械の故障を早く見つけられるようになった。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "工場[こうじょう]では IoT を入[い]れて、機械[きかい]の故障[こしょう]を早[はや]く見[み]つけられるようになった。", "sentence_source": "generated"}, {"text": "IoT のしくみを学ぶために、小さなセンサーを買った。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT のしくみを学[まな]ぶために、小[ちい]さなセンサーを買[か]った。", "sentence_source": "generated"}, {"text": "IoT を使えば、遠くにいる家族の見守りもできる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT を使[つか]えば、遠[とお]くにいる家族[かぞく]の見守[みまも]りもできる。", "sentence_source": "generated"}, {"text": "新しい冷蔵庫は IoT につながっていて、スマホで中身が見られる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "新[あたら]しい冷蔵庫[れいぞうこ]は IoT につながっていて、スマホで中身[なかみ]が見[み]られる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "IoT", "label": "基本形"}], "register": "常体（中立）", "sense_fingerprint": "身の回りのものをインターネットにつなぐしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45194, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "IoT", "is_correct": true, "explanation": "ものをネットにつなぐ仕組みを指し、外出先から家電を動かせる理由として文が成り立つ。"}, {"text": "電子書籍", "is_correct": false, "explanation": "本のデータ形式を指すので、家のエアコンを遠隔で動かす理由にはならない。"}, {"text": "動画配信", "is_correct": false, "explanation": "動画を届けるサービスで、エアコンの遠隔操作とは関係がなく文が成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "言語を置き換える行為で、家電を動かす理由として文が成り立たない。"}], "explanations": {"IoT": "ものをネットにつなぐ仕組みを指し、外出先から家電を動かせる理由として文が成り立つ。", "電子書籍": "本のデータ形式を指すので、家のエアコンを遠隔で動かす理由にはならない。", "動画配信": "動画を届けるサービスで、エアコンの遠隔操作とは関係がなく文が成り立たない。", "翻訳": "言語を置き換える行為で、家電を動かす理由として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "IoT"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工場では、IoT が重い部品を運んでいる。", "explanation": "ここは〈ロボット〉の意味。IoT は物をネットにつなぐ仕組みで、部品を運ぶ機械ではないので合わない。"}, {"text": "IoT は、動画を一瞬で届ける通信規格だ。", "explanation": "ここは〈5G（通信規格）〉の意味。IoT は物をネットにつなぐ仕組みで、動画を速く届ける通信規格ではないので合わない。"}, {"text": "毎朝、IoT を開いて天気を確認する。", "explanation": "ここは〈アプリ〉の意味。IoT は仕組みを指す言葉で、スマホで開いて使うソフトではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45194, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "IoT", "is_correct": true, "explanation": "機器をネットにつなぐ仕組みを指し、故障を早く見つけられるようになる文脈に合う。"}, {"text": "雑草", "is_correct": false, "explanation": "工場の機械に入れるものではなく、故障発見の文脈に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "機械に入れて故障を見つけるという文にはならない。"}, {"text": "カーテン", "is_correct": false, "explanation": "機械の故障を見つける道具とは言えず、文が不自然になる。"}], "explanations": {"IoT": "機器をネットにつなぐ仕組みを指し、故障を早く見つけられるようになる文脈に合う。", "雑草": "工場の機械に入れるものではなく、故障発見の文脈に合わない。", "砂糖": "機械に入れて故障を見つけるという文にはならない。", "カーテン": "機械の故障を見つける道具とは言えず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "IoT"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は旅行の写真を IoT に保存した。", "explanation": "ここは〈クラウド〉の意味。IoT は物をネットにつなぐ仕組みで、データを保存する場所ではないので合わない。"}, {"text": "IoT は、友達が毎日投稿する場所だ。", "explanation": "ここは〈SNS〉の意味。IoT は物をつなぐ仕組みで、人が投稿して交流する場所ではないので合わない。"}, {"text": "IoT は、写真の人の顔を見分ける。", "explanation": "ここは〈AI〉の意味。IoT は機器をネットにつなぐ仕組みで、画像の人物を判断する機能ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45194, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場では、IoT を機械の温度を確かめている。", "corrected_sentence": "この工場では、IoT で機械の温度を確かめている。", "error_description": "手段を表す「で」が正しい。「を」は目的語に付くため、IoT に続けるのは誤り（誤：を／正：で）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45194, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "IoT を使うば、家の鍵の状態をスマホで確かめられる。", "corrected_sentence": "IoT を使えば、家の鍵の状態をスマホで確かめられる。", "error_description": "「使う」の仮定形は「使えば」が正しい（誤：使うば／正：使えば）。IoT を受ける動詞の活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
