INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45195, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「モノのインターネット」と呼ばれ、家電や機械などがネットに接続して情報をやりとりする技術です。", "primary_collocate": null, "pronunciation": "あいおーてぃー", "ipa": "aioːtiː", "syllable_count": 6, "sentences": [{"text": "家電や機械が情報をやりとりする技術を、IoT と呼ぶ。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "家電[かでん]や機械[きかい]が情報[じょうほう]をやりとりする技術[ぎじゅつ]を、IoT と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "IoT の時計は、歩いた数をスマホに自動で送る。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT の時計[とけい]は、歩[ある]いた数[かず]をスマホに自動[じどう]で送[おく]る。", "sentence_source": "generated"}, {"text": "この会社は、IoT の機械を作って海外に売っている。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、IoT の機械[きかい]を作[つく]って海外[かいがい]に売[う]っている。", "sentence_source": "generated"}, {"text": "IoT では、たくさんの機械が同時にネットにつながる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT では、たくさんの機械[きかい]が同時[どうじ]にネットにつながる。", "sentence_source": "generated"}, {"text": "IoT の電球は、声で明るさを変えられる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT の電球[でんきゅう]は、声[こえ]で明[あか]るさを変[か]えられる。", "sentence_source": "generated"}, {"text": "IoT が進んだので、ビルの電気の使い方を細かく調べられる。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT が進[すす]んだので、ビルの電気[でんき]の使[つか]い方[かた]を細[こま]かく調[しら]べられる。", "sentence_source": "generated"}, {"text": "病院でも IoT の機械が患者の心拍数を記録している。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "病院[びょういん]でも IoT の機械[きかい]が患者[かんじゃ]の心拍数[しんぱくすう]を記録[きろく]している。", "sentence_source": "generated"}, {"text": "IoT は便利だが、ネットから情報がもれる心配もある。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT は便利[べんり]だが、ネットから情報[じょうほう]がもれる心配[しんぱい]もある。", "sentence_source": "generated"}, {"text": "私は大学で IoT の研究をしている。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "私[わたし]は大学[だいがく]で IoT の研究[けんきゅう]をしている。", "sentence_source": "generated"}, {"text": "IoT の機器が増えるにつれて、安全対策が大切になった。", "target_word": "IoT", "complexity_tier": "T3", "furigana": "IoT の機器[きき]が増[ふ]えるにつれて、安全[あんぜん]対策[たいさく]が大切[たいせつ]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "IoT", "label": "基本形"}], "register": "常体（中立）", "sense_fingerprint": "家電や機械がネットにつながり情報を交換する技術", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45195, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "IoT", "is_correct": true, "explanation": "家電や機械をネットにつないで情報を交換する技術の名称なので、ここに入る。"}, {"text": "VR", "is_correct": false, "explanation": "仮想現実の技術名で、この説明の技術とは別なので合わない。"}, {"text": "通販サイト", "is_correct": false, "explanation": "商品を売るウェブサービスで、この技術の名称ではないので合わない。"}, {"text": "翻訳アプリ", "is_correct": false, "explanation": "言語を訳すアプリの名称で、この技術の名前とは違うので合わない。"}], "explanations": {"IoT": "家電や機械をネットにつないで情報を交換する技術の名称なので、ここに入る。", "VR": "仮想現実の技術名で、この説明の技術とは別なので合わない。", "通販サイト": "商品を売るウェブサービスで、この技術の名称ではないので合わない。", "翻訳アプリ": "言語を訳すアプリの名称で、この技術の名前とは違うので合わない。"}, "sentence_index": 0, "correct_answer": "IoT"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "IoT は、友達と近況を共有するサービスだ。", "explanation": "ここは〈SNS〉の意味。IoT は機器をつなぐ技術で、人が近況を共有するサービスではないので合わない。"}, {"text": "IoT は、対戦相手と遊べるゲームだ。", "explanation": "ここは〈ゲーム〉の意味。IoT は機器をつなぐ技術で、遊ぶためのソフトではないので合わない。"}, {"text": "IoT は、大量の画像から顔を見分ける。", "explanation": "ここは〈AI〉の意味。IoT は機器をつなぐ仕組みで、画像を判断する機能ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45195, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "IoT", "is_correct": true, "explanation": "機械をネットにつなぐ仕組みを指し、患者の心拍数を記録する機械に当てはまる。"}, {"text": "動画編集", "is_correct": false, "explanation": "映像を加工する作業で、心拍数を記録する機械の名称にはならない。"}, {"text": "書店", "is_correct": false, "explanation": "本を売る店で、医療機器の名称にはならないので文が成り立たない。"}, {"text": "地図アプリ", "is_correct": false, "explanation": "道案内のアプリで、患者の心拍数を記録する機械の名称にならない。"}], "explanations": {"IoT": "機械をネットにつなぐ仕組みを指し、患者の心拍数を記録する機械に当てはまる。", "動画編集": "映像を加工する作業で、心拍数を記録する機械の名称にはならない。", "書店": "本を売る店で、医療機器の名称にはならないので文が成り立たない。", "地図アプリ": "道案内のアプリで、患者の心拍数を記録する機械の名称にならない。"}, "sentence_index": 6, "correct_answer": "IoT"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "IoT は、好きな映画を見られる配信サービスだ。", "explanation": "ここは〈動画配信〉の意味。IoT は機器をつなぐ技術で、映画を見せるサービスではないので合わない。"}, {"text": "IoT は、取引の記録を改ざんしにくくする。", "explanation": "ここは〈ブロックチェーン〉の意味。IoT は機器をネットにつなぐ仕組みで、記録の改ざんを防ぐ技術ではないので合わない。"}, {"text": "IoT は、小説を読むための本だ。", "explanation": "ここは〈電子書籍〉の意味。IoT は機器をネットにつなぐ技術で、本の内容を読むものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45195, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "IoT で体温計は、家族の体温をスマホに送る。", "corrected_sentence": "IoT の体温計は、家族の体温をスマホに送る。", "error_description": "「IoT の体温計」と所属を表す「の」が正しい（誤：で／正：の）。「で」は手段を表すため、ここでは体温計の説明に合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45195, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "IoT を使うば、家の水道の使用量を毎日確認できる。", "corrected_sentence": "IoT を使えば、家の水道の使用量を毎日確認できる。", "error_description": "仮定形は「使えば」が正しい（誤：使うば／正：使えば）。IoT に付く動詞の活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45199, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "収益が出る、と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞で、「収益を出て」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「収益へ出て」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「収益と出て」は意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "収益が出る、と主語を示す。", "を": "「出る」は自動詞で、「収益を出て」は合わない。", "へ": "「収益へ出て」は文として成り立たない。", "と": "「収益と出て」は意味が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "損失", "is_correct": true, "explanation": "お金がもうかる収益と反対に、お金を失うこと。"}, {"text": "利益", "is_correct": false, "explanation": "もうけの意味で、収益に近い。"}, {"text": "売上", "is_correct": false, "explanation": "入ってくるお金で、反対ではない。"}, {"text": "収入", "is_correct": false, "explanation": "入ってくるお金で、反対ではない。"}], "correct_answer": "損失", "explanations": {"損失": "お金がもうかる収益と反対に、お金を失うこと。", "利益": "もうけの意味で、収益に近い。", "売上": "入ってくるお金で、反対ではない。", "収入": "入ってくるお金で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45199, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "収益は、と話題を示す受身文の主題。"}, {"text": "を", "is_correct": false, "explanation": "受身の「送られた」に「収益を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「収益へ」は方向で、主題にならない。"}, {"text": "と", "is_correct": false, "explanation": "「収益と学校に送られた」は意味が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "収益は、と話題を示す受身文の主題。", "を": "受身の「送られた」に「収益を」は合わない。", "へ": "「収益へ」は方向で、主題にならない。", "と": "「収益と学校に送られた」は意味が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "損失", "is_correct": true, "explanation": "お金がもうかる収益と反対に、お金を失うこと。"}, {"text": "黒字", "is_correct": false, "explanation": "利益が出る状態で、収益に近い。"}, {"text": "儲け", "is_correct": false, "explanation": "もうけの意味で、収益に近い。"}, {"text": "利潤", "is_correct": false, "explanation": "もうけの意味で、収益に近い。"}], "correct_answer": "損失", "explanations": {"損失": "お金がもうかる収益と反対に、お金を失うこと。", "黒字": "利益が出る状態で、収益に近い。", "儲け": "もうけの意味で、収益に近い。", "利潤": "もうけの意味で、収益に近い。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
