INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (45200, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "収益", "is_correct": true, "explanation": "しゅうえき。見出し語そのもの。"}, {"text": "集積", "is_correct": false, "explanation": "しゅうせき。「え」が「せ」に変わる別の語。"}, {"text": "襲撃", "is_correct": false, "explanation": "しゅうげき。「え」が「げ」に変わる別の語。"}, {"text": "終演", "is_correct": false, "explanation": "しゅうえん。「き」が「ん」に変わる別の語。"}], "explanations": {"収益": "しゅうえき。見出し語そのもの。", "集積": "しゅうせき。「え」が「せ」に変わる別の語。", "襲撃": "しゅうげき。「え」が「げ」に変わる別の語。", "終演": "しゅうえん。「き」が「ん」に変わる別の語。"}, "sentence_index": null, "correct_answer": "収益"}, "level_3": {"options": [{"text": "収益", "is_correct": true, "explanation": "機械の導入で工場の利益がよくなる意味で合う。"}, {"text": "方言", "is_correct": false, "explanation": "形は合うが、「工場の方言が改善する」は意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「工場の地震が改善する」は意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「工場の偶然が改善する」は意味が合わない。"}], "explanations": {"収益": "機械の導入で工場の利益がよくなる意味で合う。", "方言": "形は合うが、「工場の方言が改善する」は意味が合わない。", "地震": "形は合うが、「工場の地震が改善する」は意味が合わない。", "偶然": "形は合うが、「工場の偶然が改善する」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "収益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ご飯に収益を食べて学校へ行った。", "explanation": "「収益」は事業で得る利益で、食べるものではない。"}, {"text": "収益を割って、床にこぼれてしまった。", "explanation": "「収益」は割れる物ではなく、お金の利益を表す語。"}, {"text": "雨の収益が強くて、傘をさした。", "explanation": "「収益」は雨の強さを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
