INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51416, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「手伝い」は、他人の仕事や作業を助けること、またはその行為を指します。", "primary_collocate": null, "pronunciation": "てつだい", "ipa": "tetsɯdai", "syllable_count": 4, "sentences": [{"text": "あたらしいロボットは、おうちでいろいろなてつだいをします。", "target_word": "てつだい", "complexity_tier": "T4", "furigana": "あたらしいロボットは、おうちでいろいろなてつだいをします。", "sentence_source": "mined"}, {"text": "手伝いが必要だ。", "target_word": "手伝い", "complexity_tier": "T1", "furigana": "手伝[てつだ]いが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "毎日、母の手伝いをします。", "target_word": "手伝い", "complexity_tier": "T2", "furigana": "毎日[まいにち]、母[はは]の手伝[てつだ]いをします。", "sentence_source": "generated"}, {"text": "手伝いに来てくれて、ありがとう。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "手伝[てつだ]いに来[き]てくれて、ありがとう。", "sentence_source": "generated"}, {"text": "弟は料理の手伝いが好きだ。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "弟[おとうと]は料理[りょうり]の手伝[てつだ]いが好[す]きだ。", "sentence_source": "generated"}, {"text": "夏休みは、店の手伝いをして過ごした。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは、店[みせ]の手伝[てつだ]いをして過[す]ごした。", "sentence_source": "generated"}, {"text": "これはだれの手伝いもいらない仕事だ。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "これはだれの手伝[てつだ]いもいらない仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "ひとりでできるので、手伝いは大丈夫です。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "ひとりでできるので、手伝[てつだ]いは大丈夫[だいじょうぶ]です。", "sentence_source": "generated"}, {"text": "忙しいときは、子どもたちも家の手伝いをして、助けてくれます。", "target_word": "手伝い", "complexity_tier": "T4", "furigana": "忙[いそが]しいときは、子[こ]どもたちも家[いえ]の手伝[てつだ]いをして、助[たす]けてくれます。", "sentence_source": "generated"}, {"text": "手伝いのつもりで始めたが、いつの間にか自分の仕事のようになっていた。", "target_word": "手伝い", "complexity_tier": "T5", "furigana": "手伝[てつだ]いのつもりで始[はじ]めたが、いつの間[ま]にか自分[じぶん]の仕事[しごと]のようになっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手伝う", "label": "派生"}, {"form": "お手伝い", "label": "敬語形"}, {"form": "手伝える", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 他人の仕事や作業を助けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "てつだい", "is_correct": true, "explanation": "家でロボットが「てつだいをする」は自然な表現です。"}, {"text": "おもちゃ", "is_correct": false, "explanation": "形は合うが意味が合わない。「おもちゃをする」とは言いません。"}, {"text": "おかし", "is_correct": false, "explanation": "形は合うが意味が合わない。「おかしをする」とは言いません。"}, {"text": "えほん", "is_correct": false, "explanation": "形は合うが意味が合わない。「えほんをする」とは言いません。"}], "explanations": {"てつだい": "家でロボットが「てつだいをする」は自然な表現です。", "おもちゃ": "形は合うが意味が合わない。「おもちゃをする」とは言いません。", "おかし": "形は合うが意味が合わない。「おかしをする」とは言いません。", "えほん": "形は合うが意味が合わない。「えほんをする」とは言いません。"}, "sentence_index": 0, "correct_answer": "てつだい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母の手伝いを食べて、とてもおいしかった。", "explanation": "「手伝い」は行為で、食べ物ではありません。"}, {"text": "手伝いが高いので、電車で行きます。", "explanation": "「手伝い」に値段が高いという性質は当てはまりません。"}, {"text": "空に大きな手伝いが出ていた。", "explanation": "「手伝い」は空に出る物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手伝い", "is_correct": true, "explanation": "「だれの手伝いもいらない仕事」は自然な表現です。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが意味が合わない。「だれの約束もいらない仕事」は文意が通りません。"}, {"text": "質問", "is_correct": false, "explanation": "形は合うが意味が合わない。「だれの質問もいらない仕事」は文意が通りません。"}, {"text": "写真", "is_correct": false, "explanation": "形は合うが意味が合わない。「だれの写真もいらない仕事」は文意が通りません。"}], "explanations": {"手伝い": "「だれの手伝いもいらない仕事」は自然な表現です。", "約束": "形は合うが意味が合わない。「だれの約束もいらない仕事」は文意が通りません。", "質問": "形は合うが意味が合わない。「だれの質問もいらない仕事」は文意が通りません。", "写真": "形は合うが意味が合わない。「だれの写真もいらない仕事」は文意が通りません。"}, "sentence_index": 6, "correct_answer": "手伝い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の手伝いは風が強くて寒かった。", "explanation": "「手伝い」は天気を表す語ではありません。"}, {"text": "手伝いを飲みながら、本を読んだ。", "explanation": "「手伝い」は飲み物ではありません。"}, {"text": "公園で大きな手伝いが走っている。", "explanation": "「手伝い」は走る生き物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51416, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日、母の手伝いにします。", "corrected_sentence": "毎日、母の手伝いをします。", "error_description": "「手伝いをする」と言い、「手伝いにする」は不自然です。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51416, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越しの手伝いを行きます。", "corrected_sentence": "引っ越しの手伝いに行きます。", "error_description": "目的を表すときは「手伝いに行く」で、「を」は使えません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
