INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51418, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "色の名前で、空や海の色を表す形容詞。", "primary_collocate": null, "pronunciation": "あおい", "ipa": "aoi", "syllable_count": 3, "sentences": [{"text": "わたしは、うちで青いTシャツをきています。", "target_word": "青い", "complexity_tier": "T3", "furigana": "わたしは、うちで青[あお]いTシャツをきています。", "sentence_source": "mined"}, {"text": "夏の空は高くて、とても青いです。", "target_word": "青い", "complexity_tier": "T3", "furigana": "夏[なつ]の空[そら]は高[たか]くて、とても青[あお]いです。", "sentence_source": "generated"}, {"text": "海が青いので、みんなでおよぎに行きました。", "target_word": "青い", "complexity_tier": "T3", "furigana": "海[うみ]が青[あお]いので、みんなでおよぎに行[い]きました。", "sentence_source": "generated"}, {"text": "青い車が家の前にとまっています。", "target_word": "青い", "complexity_tier": "T3", "furigana": "青[あお]い車[くるま]が家[いえ]の前[まえ]にとまっています。", "sentence_source": "generated"}, {"text": "青い花をテーブルにかざりました。", "target_word": "青い", "complexity_tier": "T3", "furigana": "青[あお]い花[はな]をテーブルにかざりました。", "sentence_source": "generated"}, {"text": "兄は青いかばんを持って学校へ行きます。", "target_word": "青い", "complexity_tier": "T3", "furigana": "兄[あに]は青[あお]いかばんを持[も]って学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "晴れた日、青い空にしろい雲がうかんでいた。", "target_word": "青い", "complexity_tier": "T3", "furigana": "晴[は]れた日[ひ]、青[あお]い空[そら]にしろい雲[くも]がうかんでいた。", "sentence_source": "generated"}, {"text": "青いペンで、ノートに名前を書きました。", "target_word": "青い", "complexity_tier": "T3", "furigana": "青[あお]いペンで、ノートに名前[なまえ]を書[か]きました。", "sentence_source": "generated"}, {"text": "プールの水は青いので、見ていてすずしい気分になります。", "target_word": "青い", "complexity_tier": "T3", "furigana": "プールの水[みず]は青[あお]いので、見[み]ていてすずしい気分[きぶん]になります。", "sentence_source": "generated"}, {"text": "青いセーターは、弟によくにあいます。", "target_word": "青い", "complexity_tier": "T3", "furigana": "青[あお]いセーターは、弟[おとうと]によくにあいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "青い", "label": "基本形"}, {"form": "青く", "label": "連用形"}, {"form": "青くて", "label": "て形"}, {"form": "青かった", "label": "過去形"}, {"form": "青くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "空や海のような色を表す色の形容詞(あおい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: およぎ (Zipf 1.58)','sentence 4 above tier T2: contains vocabulary far above tier T2: かざり (Zipf 2.34)','sentence 6 above tier T2: contains vocabulary far above tier T2: うかん (Zipf 1.44)','sentence 8 above tier T2: contains vocabulary far above tier T2: すずしい (Zipf 2.04)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51418, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。「Tシャツ」を修飾する色の形容詞の形で、空欄に入る。"}, {"text": "甘い", "is_correct": false, "explanation": "「甘いTシャツ」は意味が通らず、空欄に入らない。"}, {"text": "苦い", "is_correct": false, "explanation": "「苦いTシャツ」は意味が通らず、この文には入らない。"}, {"text": "眠い", "is_correct": false, "explanation": "「眠いTシャツ」は意味が通らず、空欄に入らない。"}], "explanations": {"青い": "正解。「Tシャツ」を修飾する色の形容詞の形で、空欄に入る。", "甘い": "「甘いTシャツ」は意味が通らず、空欄に入らない。", "苦い": "「苦いTシャツ」は意味が通らず、この文には入らない。", "眠い": "「眠いTシャツ」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "青い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この果物はまだ青いので、もう少し待ちましょう。", "explanation": "ここは〈未熟〉（熟していない）の意味。色ではなく、果物の熟し具合を表す。"}, {"text": "熱が出て、顔が青いので先生は心配した。", "explanation": "ここは〈顔色が悪い〉の意味。色ではなく、体調による顔色を表す。"}, {"text": "彼はまだ青いので、大事な仕事は任せられない。", "explanation": "ここは〈経験が浅く未熟〉の意味。色ではなく、人の経験不足を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51418, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。「空」を修飾する色の形容詞の形で、空欄に入る。"}, {"text": "辛い", "is_correct": false, "explanation": "「辛い空」は意味が通らず、空欄に入らない。"}, {"text": "熱い", "is_correct": false, "explanation": "「熱い空」は意味が通らず、この文には入らない。"}, {"text": "硬い", "is_correct": false, "explanation": "「硬い空」は意味が通らず、空欄に入らない。"}], "explanations": {"青い": "正解。「空」を修飾する色の形容詞の形で、空欄に入る。", "辛い": "「辛い空」は意味が通らず、空欄に入らない。", "熱い": "「熱い空」は意味が通らず、この文には入らない。", "硬い": "「硬い空」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "青い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このメロンはまだ青いので、食べごろは来週です。", "explanation": "ここは〈未熟〉の意味。色ではなく、熟していない状態を表す。"}, {"text": "寝不足で、彼の顔はずっと青かった。", "explanation": "ここは〈顔色が悪い〉の意味。色ではなく、体調による顔色を表す。"}, {"text": "あの若い選手はまだ青いので、大舞台には出せない。", "explanation": "ここは〈経験が浅い〉の意味。色ではなく、人の経験不足を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51418, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海の水が青いくて、きれいです。", "corrected_sentence": "海の水が青くて、きれいです。", "error_description": "形容詞「青い」のて形は「青くて」。「青いくて」は誤った活用形なので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。文末「青いです」で使われる基本形。"}, {"text": "青く", "is_correct": false, "explanation": "連用形の「青く」は「です」の前に来られず、文が成り立たない。"}, {"text": "青くて", "is_correct": false, "explanation": "て形の「青くて」は文をつなぐ形で、文末を終えられない。"}, {"text": "青ければ", "is_correct": false, "explanation": "仮定形の「青ければ」は「とても青ければです」となり、文が成り立たない。"}], "correct_form": "青い", "base_form": "青い", "form_label": "基本形", "sentence_index": 1, "explanations": {"青い": "正解。文末「青いです」で使われる基本形。", "青く": "連用形の「青く」は「です」の前に来られず、文が成り立たない。", "青くて": "て形の「青くて」は文をつなぐ形で、文末を終えられない。", "青ければ": "仮定形の「青ければ」は「とても青ければです」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51418, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "青くかさをさして、学校へ行きました。", "corrected_sentence": "青いかさをさして、学校へ行きました。", "error_description": "名詞の前では「青い」の形を使う。「青く」は名詞を修飾できないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "青い", "is_correct": true, "explanation": "正解。「ペン」を直接修飾する連体形。"}, {"text": "青そう", "is_correct": false, "explanation": "様子を表す形で、「青そうペンで」は名詞を修飾できず文が成り立たない。"}, {"text": "青さ", "is_correct": false, "explanation": "名詞形の「青さ」は「ペン」を直接修飾できず、「青さペンで」は文が成り立たない。"}, {"text": "青かろう", "is_correct": false, "explanation": "推量の形で、名詞を修飾すると「青かろうペンで」は成り立たない。"}], "correct_form": "青い", "base_form": "青い", "form_label": "連体形", "sentence_index": 7, "explanations": {"青い": "正解。「ペン」を直接修飾する連体形。", "青そう": "様子を表す形で、「青そうペンで」は名詞を修飾できず文が成り立たない。", "青さ": "名詞形の「青さ」は「ペン」を直接修飾できず、「青さペンで」は文が成り立たない。", "青かろう": "推量の形で、名詞を修飾すると「青かろうペンで」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
