INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解（熊がすむ：主語）"}, {"text": "を", "is_correct": false, "explanation": "対象（熊をすむは不自然）"}, {"text": "で", "is_correct": false, "explanation": "場所（熊ですむは不自然）"}, {"text": "の", "is_correct": false, "explanation": "所属（熊のすむは不自然）"}], "correct_answer": "が", "explanations": {"が": "正解（熊がすむ：主語）", "を": "対象（熊をすむは不自然）", "で": "場所（熊ですむは不自然）", "の": "所属（熊のすむは不自然）"}, "error_tags": {"が": "正解（熊がすむ：主語）", "を": "対象（熊をすむは不自然）", "で": "場所（熊ですむは不自然）", "の": "所属（熊のすむは不自然）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "クマ科の哺乳類。体が大きく、毛がふさふさしていて、冬に冬眠する。", "primary_collocate": null, "pronunciation": "くま", "ipa": "kɯma", "syllable_count": 2, "sentences": [{"text": "くまの絵がすきです。", "target_word": "くま", "complexity_tier": "T3", "furigana": "くまの絵[え]がすきです。", "sentence_source": "mined"}, {"text": "山で熊を見たら、さわがずにしずかに離れます。", "target_word": "熊", "complexity_tier": "T3", "furigana": "山[やま]で熊[くま]を見[み]たら、さわがずにしずかに離[はな]れます。", "sentence_source": "generated"}, {"text": "熊は冬になると、あなの中でねむります。", "target_word": "熊", "complexity_tier": "T3", "furigana": "熊[くま]は冬[ふゆ]になると、あなの中[なか]でねむります。", "sentence_source": "generated"}, {"text": "動物園の熊が、大きな口でりんごを食べた。", "target_word": "熊", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]の熊[くま]が、大[おお]きな口[くち]でりんごを食[た]べた。", "sentence_source": "generated"}, {"text": "熊は体が大きくて、力がとても強いです。", "target_word": "熊", "complexity_tier": "T3", "furigana": "熊[くま]は体[からだ]が大[おお]きくて、力[ちから]がとても強[つよ]いです。", "sentence_source": "generated"}, {"text": "森に熊がいるので、一人で山に入ってはいけません。", "target_word": "熊", "complexity_tier": "T3", "furigana": "森[もり]に熊[くま]がいるので、一人[ひとり]で山[やま]に入[はい]ってはいけません。", "sentence_source": "generated"}, {"text": "熊は魚をとるのが上手で、川でさけをつかまえます。", "target_word": "熊", "complexity_tier": "T3", "furigana": "熊[くま]は魚[さかな]をとるのが上手[じょうず]で、川[かわ]でさけをつかまえます。", "sentence_source": "generated"}, {"text": "北海道の山には、熊がすんでいます。", "target_word": "熊", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]の山[やま]には、熊[くま]がすんでいます。", "sentence_source": "generated"}, {"text": "熊の毛はふさふさしていて、冬でもあたたかそうです。", "target_word": "熊", "complexity_tier": "T3", "furigana": "熊[くま]の毛[け]はふさふさしていて、冬[ふゆ]でもあたたかそうです。", "sentence_source": "generated"}, {"text": "子どもの熊が、母親の後ろをついて歩いていた。", "target_word": "熊", "complexity_tier": "T3", "furigana": "子[こ]どもの熊[くま]が、母親[ははおや]の後[うし]ろをついて歩[ある]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熊", "label": "基本形"}, {"form": "くま", "label": "ひらがな表記"}], "register": "neutral", "sense_fingerprint": "体が大きく冬眠する動物、クマ科の哺乳類(くま)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: さわが (Zipf 1.11)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "くま", "is_correct": true, "explanation": "正解。「絵」の対象になる動物の熊を指し、空欄に入る。"}, {"text": "試験", "is_correct": false, "explanation": "「試験の絵」は意味が通らず、この文には入らない。"}, {"text": "会議", "is_correct": false, "explanation": "「会議の絵」は意味が通らず、空欄に入らない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題の絵」は意味が通らず、空欄に入らない。"}], "explanations": {"くま": "正解。「絵」の対象になる動物の熊を指し、空欄に入る。", "試験": "「試験の絵」は意味が通らず、この文には入らない。", "会議": "「会議の絵」は意味が通らず、空欄に入らない。", "宿題": "「宿題の絵」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "くま"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "熊は人間のよい友だちで、家の番をします。", "explanation": "ここは〈犬〉の意味。熊は家の番をする動物ではないので、熊には合わない。"}, {"text": "熊は、ひざの上でのどを鳴らして甘えます。", "explanation": "ここは〈猫〉の意味。熊はのどを鳴らして甘える動物ではないので、熊には合わない。"}, {"text": "熊は群れで狩りをして、大きな獲物を追います。", "explanation": "ここは〈狼〉の意味。熊は群れで狩りをしないので、熊には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熊", "is_correct": true, "explanation": "正解。「上手で、川でさけをつかまえる」主語になる動物の熊を指す。"}, {"text": "雨", "is_correct": false, "explanation": "雨は魚をとるわけではないので、この文の主語にならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は魚をとるわけではないので、空欄に入らない。"}, {"text": "病気", "is_correct": false, "explanation": "病気は魚をとるわけではないので、この文には入らない。"}], "explanations": {"熊": "正解。「上手で、川でさけをつかまえる」主語になる動物の熊を指す。", "雨": "雨は魚をとるわけではないので、この文の主語にならない。", "天気": "天気は魚をとるわけではないので、空欄に入らない。", "病気": "病気は魚をとるわけではないので、この文には入らない。"}, "sentence_index": 6, "correct_answer": "熊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熊は木の上で、群れになって遊びます。", "explanation": "ここは〈猿〉の意味。熊は群れで木の上で遊ぶ動物ではないので、熊には合わない。"}, {"text": "熊は牧場で、毎朝乳をしぼられています。", "explanation": "ここは〈牛〉の意味。熊は乳をしぼられる家畜ではないので、熊には合わない。"}, {"text": "熊は枝にとまって、朝に歌をうたいます。", "explanation": "ここは〈鳥〉の意味。熊は枝にとまって歌う動物ではないので、熊には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森で熊を出会ったら、大声を出しましょう。", "corrected_sentence": "森で熊に出会ったら、大声を出しましょう。", "error_description": "「出会う」は相手を「に」で示し、「を」は取らない。「熊を出会った」は不自然なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子熊を川で魚をとっていました。", "corrected_sentence": "子熊が川で魚をとっていました。", "error_description": "「とる」の主語は「が」で示す。「子熊を」と目的語にすると、とる主体として不自然なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「外傷は小さいですが」で外傷を話題として示し、後ろの文と続く。"}, {"text": "を", "is_correct": false, "explanation": "「外傷を小さいですが」は形容詞とつながらず、目的語としても合わない。"}, {"text": "に", "is_correct": false, "explanation": "「外傷に小さいですが」は文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「外傷で小さいですが」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「外傷は小さいですが」で外傷を話題として示し、後ろの文と続く。", "を": "「外傷を小さいですが」は形容詞とつながらず、目的語としても合わない。", "に": "「外傷に小さいですが」は文が成り立たない。", "で": "「で」は手段や場所を示すので、「外傷で小さいですが」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
