INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体にできたきず", "primary_collocate": null, "pronunciation": "がいしょう", "ipa": "ɡaiɕoː", "syllable_count": 4, "sentences": [{"text": "犬にかまれて、足に外傷ができました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "犬[いぬ]にかまれて、足[あし]に外傷[がいしょう]ができました。", "sentence_source": "generated"}, {"text": "外傷は小さいですが、血が出ています。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]は小[ちい]さいですが、血[ち]が出[で]ています。", "sentence_source": "generated"}, {"text": "転んだときの外傷が、まだ痛みます。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "転[ころ]んだときの外傷[がいしょう]が、まだ痛[いた]みます。", "sentence_source": "generated"}, {"text": "外傷があるので、今日はプールに入れません。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]があるので、今日[きょう]はプールに入[はい]れません。", "sentence_source": "generated"}, {"text": "先生は、子どもの体に外傷がないか調べました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "先生[せんせい]は、子[こ]どもの体[からだ]に外傷[がいしょう]がないか調[しら]べました。", "sentence_source": "generated"}, {"text": "この薬は、外傷に塗ると血が早く止まります。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "この薬[くすり]は、外傷[がいしょう]に塗[ぬ]ると血[ち]が早[はや]く止[と]まります。", "sentence_source": "generated"}, {"text": "木から落ちましたが、外傷は軽くてすみました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "木[き]から落[お]ちましたが、外傷[がいしょう]は軽[かる]くてすみました。", "sentence_source": "generated"}, {"text": "外傷のない人も、念のため病院で診てもらいました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]のない人[ひと]も、念[ねん]のため病院[びょういん]で診[み]てもらいました。", "sentence_source": "generated"}, {"text": "外傷が治るまで、運動は休みます。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]が治[なお]るまで、運動[うんどう]は休[やす]みます。", "sentence_source": "generated"}, {"text": "登山中に岩で手を切り、外傷の手当てをしました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "登山中[とざんちゅう]に岩[いわ]で手[て]を切[き]り、外傷[がいしょう]の手当[てあ]てをしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外傷", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "体の表面にできた、けがによるきず", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外傷", "is_correct": true, "explanation": "体の表面にできたけがのきずを指し、犬にかまれた足の文に合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は車が進まない状態を指し、足にできるものではない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝ている間に髪が乱れることで、足には合わない。"}, {"text": "行列", "is_correct": false, "explanation": "行列は並んだ人の列で、足にできるものではない。"}], "explanations": {"外傷": "体の表面にできたけがのきずを指し、犬にかまれた足の文に合う。", "渋滞": "渋滞は車が進まない状態を指し、足にできるものではない。", "寝癖": "寝癖は寝ている間に髪が乱れることで、足には合わない。", "行列": "行列は並んだ人の列で、足にできるものではない。"}, "sentence_index": 0, "correct_answer": "外傷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日から熱があり、外傷が続いているので寝ています。", "explanation": "ここは〈病気〉の意味。外傷は外からのけがによる傷で、熱の症状には使わない。"}, {"text": "シャツに外傷がついたので、すぐ洗いました。", "explanation": "ここは〈シミ〉の意味。外傷は体にできたきずで、服につくシミには使わない。"}, {"text": "背中にほくろが増えて、外傷が一つ増えました。", "explanation": "ここは〈ほくろ〉の意味。外傷は外からの力によるきずで、生まれつきの色の斑点には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外傷", "is_correct": true, "explanation": "体のけがのきずを指し、木から落ちて軽くすんだという話に合う。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は言葉を調べる本で、軽くてすんだという被害の話には合わない。"}, {"text": "新聞", "is_correct": false, "explanation": "新聞は読む紙で、木から落ちた被害の話には合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座るための布製品で、木から落ちた被害の話には当てはまらない。"}], "explanations": {"外傷": "体のけがのきずを指し、木から落ちて軽くすんだという話に合う。", "辞書": "辞書は言葉を調べる本で、軽くてすんだという被害の話には合わない。", "新聞": "新聞は読む紙で、木から落ちた被害の話には合わない。", "座布団": "座布団は座るための布製品で、木から落ちた被害の話には当てはまらない。"}, "sentence_index": 6, "correct_answer": "外傷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魚をさばくとき、外傷が台所じゅうに散らばりました。", "explanation": "ここは〈うろこ〉の意味。外傷は体にできたきずで、魚の表面のうろこには使わない。"}, {"text": "服のほころびを縫って、外傷を直しました。", "explanation": "ここは〈ほころび〉の意味。外傷は体のきずを指し、服の破れには使わない。"}, {"text": "顔にしわができて、外傷が増えました。", "explanation": "ここは〈しわ〉の意味。外傷はけがによるきずで、年齢によるしわには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転んだ拍子に、ひざの外傷を深くなりました。", "corrected_sentence": "転んだ拍子に、ひざの外傷が深くなりました。", "error_description": "「なる」は「が」をとるので、「を」は誤り。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51421, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ひざの外傷に、きれいに洗いました。", "corrected_sentence": "ひざの外傷を、きれいに洗いました。", "error_description": "「洗う」は「を」をとるので、「に」は誤り。正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大きな外傷があると」で、外傷の存在を示す主語として文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「外傷を」は目的語になり、「ある」の主語にならないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「大きな外傷に」はつながらず、存在を示す「が」の代わりにはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、存在を示す文には合わない。"}], "correct_answer": "が", "explanations": {"が": "「大きな外傷があると」で、外傷の存在を示す主語として文に合う。", "を": "「外傷を」は目的語になり、「ある」の主語にならないので合わない。", "に": "「大きな外傷に」はつながらず、存在を示す「が」の代わりにはならない。", "へ": "「へ」は方向を表すので、存在を示す文には合わない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「外傷は見つかりませんでした」の「は」。外傷を話題として示し、「見つかりませんでした」と続けられる。"}, {"text": "の", "is_correct": false, "explanation": "「外傷の見つかりませんでした」は「の」で名詞をつなぐだけなので、「見つかる」の主題を示せず文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「外傷より見つかりませんでした」は比較の表現になり、「見つかる」と結びつかず文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「外傷と見つかりませんでした」は並列や引用を示す「と」で、主題の位置には入らず不自然。"}], "correct_answer": "は", "explanations": {"は": "「外傷は見つかりませんでした」の「は」。外傷を話題として示し、「見つかりませんでした」と続けられる。", "の": "「外傷の見つかりませんでした」は「の」で名詞をつなぐだけなので、「見つかる」の主題を示せず文が成り立たない。", "より": "「外傷より見つかりませんでした」は比較の表現になり、「見つかる」と結びつかず文にならない。", "と": "「外傷と見つかりませんでした」は並列や引用を示す「と」で、主題の位置には入らず不自然。"}, "error_tags": {"の": "連体修飾の格", "より": "比較の格", "と": "並列・引用の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "外部からの力によって生じた体の傷や損傷", "primary_collocate": null, "pronunciation": "がいしょう", "ipa": "ɡaiɕoː", "syllable_count": 4, "sentences": [{"text": "事故で頭を打ちましたが、外傷はありませんでした。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "事故[じこ]で頭[あたま]を打[う]ちましたが、外傷[がいしょう]はありませんでした。", "sentence_source": "generated"}, {"text": "医者は、腕に大きな外傷があると言いました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、腕[うで]に大[おお]きな外傷[がいしょう]があると言[い]いました。", "sentence_source": "generated"}, {"text": "外傷がなくても、中の骨が折れていることがあります。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]がなくても、中[なか]の骨[ほね]が折[お]れていることがあります。", "sentence_source": "generated"}, {"text": "転んだ子どもの外傷を、看護師が消毒しました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "転[ころ]んだ子[こ]どもの外傷[がいしょう]を、看護師[かんごし]が消毒[しょうどく]しました。", "sentence_source": "generated"}, {"text": "この病院は、交通事故による外傷の治療が得意です。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、交通[こうつう]事故[じこ]による外傷[がいしょう]の治療[ちりょう]が得意[とくい]です。", "sentence_source": "generated"}, {"text": "外傷の手当てが遅れると、ばい菌が入るおそれがあります。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]の手当[てあ]てが遅[おく]れると、ばい菌[きん]が入[はい]るおそれがあります。", "sentence_source": "generated"}, {"text": "ボクシングの試合のあと、選手の顔には多くの外傷が見られました。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "ボクシングの試合[しあい]のあと、選手[せんしゅ]の顔[かお]には多[おお]くの外傷[がいしょう]が見[み]られました。", "sentence_source": "generated"}, {"text": "事故のあと、体のあちこちを調べましたが、外傷は見つかりませんでした。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "事故のあと、体のあちこちを調べましたが、外傷[がいしょう]は見つかりませんでした。", "sentence_source": "generated"}, {"text": "外傷が深いときは、すぐ病院に行ってください。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]が深[ふか]いときは、すぐ病院[びょういん]に行[い]ってください。", "sentence_source": "generated"}, {"text": "外傷の跡は、半年たってもまだ残っています。", "target_word": "外傷", "complexity_tier": "T3", "furigana": "外傷[がいしょう]の跡[あと]は、半年[はんとし]たってもまだ残[のこ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外傷", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "事故や打撲など外からの力で体にできた傷・損傷（医療的な語）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外傷", "is_correct": true, "explanation": "外からの力による体の傷の意味で、事故で頭を打ったが傷がなかったという文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、事故で体を打った文脈には当てはまらない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座るときに使う布製品で、体の傷の話には合わない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は読み物で、事故で頭を打った話の中には入らない。"}], "explanations": {"外傷": "外からの力による体の傷の意味で、事故で頭を打ったが傷がなかったという文に合う。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、事故で体を打った文脈には当てはまらない。", "座布団": "座布団は座るときに使う布製品で、体の傷の話には合わない。", "雑誌": "雑誌は読み物で、事故で頭を打った話の中には入らない。"}, "sentence_index": 0, "correct_answer": "外傷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪がなかなか治らず、外傷が続いています。", "explanation": "ここは〈病気〉の意味。外傷は外からの力によってできた傷なので、風邪のような病気には使わない。"}, {"text": "彼は外傷がよくて、いつも人気があります。", "explanation": "ここは〈外見〉の意味。外傷は体の傷を指し、見た目の良し悪しには使わない。"}, {"text": "机の角で、ひどい外傷がつきました。", "explanation": "ここは〈傷〉の意味。外傷は体のけがに使い、机のような物の傷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外傷", "is_correct": true, "explanation": "試合で受けた体の傷を指し、顔に傷として見られるという文に合う。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は車が進まない状態を指し、顔に見られるものではない。"}, {"text": "行列", "is_correct": false, "explanation": "行列は人が並んだ列を指し、顔に見られるものではない。"}, {"text": "標識", "is_correct": false, "explanation": "標識は道路の案内板で、顔に見られるものではない。"}], "explanations": {"外傷": "試合で受けた体の傷を指し、顔に傷として見られるという文に合う。", "渋滞": "渋滞は車が進まない状態を指し、顔に見られるものではない。", "行列": "行列は人が並んだ列を指し、顔に見られるものではない。", "標識": "標識は道路の案内板で、顔に見られるものではない。"}, "sentence_index": 6, "correct_answer": "外傷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の魚で外傷が起きて、おなかを壊しました。", "explanation": "ここは〈食中毒〉の意味。外傷は外からの力による傷なので、食べ物による病気には使わない。"}, {"text": "大雨で道路の外傷がひどいので、修理を頼みました。", "explanation": "ここは〈損傷〉の意味。外傷は人の体のけがを指し、道路の損傷には使わない。"}, {"text": "服の外傷は、洗っても落ちませんでした。", "explanation": "ここは〈汚れ〉の意味。外傷は体のけがを指し、服の汚れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転倒の際、ひざに外傷が負いました。", "corrected_sentence": "転倒の際、ひざに外傷を負いました。", "error_description": "「負う」は「を」をとるので、「が」は誤り。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救急隊は、事故で倒れた人の外傷に手当てしました。", "corrected_sentence": "救急隊は、事故で倒れた人の外傷を手当てしました。", "error_description": "「手当てする」は「を」をとるので、「に」は誤り。正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スポーツが好きです」で、「好きです」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「好き」は「が」で主語を示す形容動詞なので、「スポーツを好きです」は誤り。"}, {"text": "に", "is_correct": false, "explanation": "「スポーツに好きです」は成り立たない。「に」は相手や場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「好きです」とはつながらない。"}], "correct_answer": "が", "explanations": {"が": "「スポーツが好きです」で、「好きです」の主語を示す「が」。", "を": "「好き」は「が」で主語を示す形容動詞なので、「スポーツを好きです」は誤り。", "に": "「スポーツに好きです」は成り立たない。「に」は相手や場所を示す。", "へ": "「へ」は方向を示すので、「好きです」とはつながらない。"}, "error_tags": {"を": "目的語の助詞", "に": "相手・場所の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「して遊ぶ」の対象を示す「を」。「スポーツをして遊びました」の形。"}, {"text": "が", "is_correct": false, "explanation": "「スポーツがして」は成り立たない。「が」は主語を示すが、ここでは対象が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「スポーツへして遊ぶ」は不自然。「へ」は方向を示す。"}, {"text": "の", "is_correct": false, "explanation": "「スポーツのして」は成り立たない。「の」は所属や修飾を示す。"}], "correct_answer": "を", "explanations": {"を": "「して遊ぶ」の対象を示す「を」。「スポーツをして遊びました」の形。", "が": "「スポーツがして」は成り立たない。「が」は主語を示すが、ここでは対象が必要。", "へ": "「スポーツへして遊ぶ」は不自然。「へ」は方向を示す。", "の": "「スポーツのして」は成り立たない。「の」は所属や修飾を示す。"}, "error_tags": {"が": "主語の助詞", "へ": "方向の助詞", "の": "所属・修飾の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体を動かして遊ぶこと。", "primary_collocate": null, "pronunciation": "すぽーつ", "ipa": "supoːtsɯ", "syllable_count": 4, "sentences": [{"text": "休みの日は、公園で子どもたちとスポーツをして遊びます。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、公園[こうえん]で子[こ]どもたちとスポーツをして遊[あそ]びます。", "sentence_source": "generated"}, {"text": "弟はゲームより、外で体を動かすスポーツが好きです。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "弟[おとうと]はゲームより、外[そと]で体[からだ]を動[うご]かすスポーツが好[す]きです。", "sentence_source": "generated"}, {"text": "友達と海でスポーツをして、一日中遊びました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "友達[ともだち]と海[うみ]でスポーツをして、一日中[いちにちじゅう]遊[あそ]びました。", "sentence_source": "generated"}, {"text": "勝ち負けは気にせず、みんなでスポーツを楽しみましょう。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "勝[か]ち負[ま]けは気[き]にせず、みんなでスポーツを楽[たの]しみましょう。", "sentence_source": "generated"}, {"text": "運動場で、家族と軽いスポーツをしました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "運動場[うんどうじょう]で、家族[かぞく]と軽[かる]いスポーツをしました。", "sentence_source": "generated"}, {"text": "雨がやんだので、友達とスポーツをしに外へ出ました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "雨[あめ]がやんだので、友達[ともだち]とスポーツをしに外[そと]へ出[で]ました。", "sentence_source": "generated"}, {"text": "仕事のあと、仲間とスポーツをして気分を変えます。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "仕事[しごと]のあと、仲間[なかま]とスポーツをして気分[きぶん]を変[か]えます。", "sentence_source": "generated"}, {"text": "夏休みに、いとこたちと川の近くでスポーツをして遊びました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、いとこたちと川[かわ]の近[ちか]くでスポーツをして遊[あそ]びました。", "sentence_source": "generated"}, {"text": "大人になっても、友達とスポーツで遊ぶ時間は大切です。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "大人[おとな]になっても、友達[ともだち]とスポーツで遊[あそ]ぶ時間[じかん]は大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "日曜日の朝、近所の人たちと広場でスポーツをします。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]、近所[きんじょ]の人[ひと]たちと広場[ひろば]でスポーツをします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポーツ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "勝ち負けよりも楽しみとして、体を動かして遊ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポーツ", "is_correct": true, "explanation": "「スポーツをして遊びます」は、体を動かして遊ぶという意味で自然。"}, {"text": "ケーキ", "is_correct": false, "explanation": "「ケーキをして遊ぶ」とは言わない。ケーキは食べる物で、遊びの対象にならない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "「ピアノをして遊ぶ」は不自然。楽器は弾くもので、「をして遊ぶ」とは続かない。"}, {"text": "アルバイト", "is_correct": false, "explanation": "アルバイトは仕事であり、「をして遊ぶ」とは意味が合わない。"}], "explanations": {"スポーツ": "「スポーツをして遊びます」は、体を動かして遊ぶという意味で自然。", "ケーキ": "「ケーキをして遊ぶ」とは言わない。ケーキは食べる物で、遊びの対象にならない。", "ピアノ": "「ピアノをして遊ぶ」は不自然。楽器は弾くもので、「をして遊ぶ」とは続かない。", "アルバイト": "アルバイトは仕事であり、「をして遊ぶ」とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "スポーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は、部屋のスポーツをします。", "explanation": "ここは〈掃除〉の意味。部屋を片付ける作業で、体を動かして遊ぶスポーツとは違う。"}, {"text": "毎朝、スポーツで学校へ行きます。", "explanation": "ここは〈電車〉（乗り物）の意味。スポーツは移動の手段ではないので、通学には使えない。"}, {"text": "重力の下での物体のスポーツを計算する。", "explanation": "ここは〈運動〉（物の動き）の意味。遊びとしての体の動きを指すスポーツは、物の動きには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポーツ", "is_correct": true, "explanation": "「仲間とスポーツをして気分を変えます」は、体を動かして気分転換するという意味で自然。"}, {"text": "見積もり", "is_correct": false, "explanation": "見積もりは仕事の作業で、気分転換の遊びにはならない。"}, {"text": "税金", "is_correct": false, "explanation": "「税金をして」とは言わない。税金は納める物。"}, {"text": "会計", "is_correct": false, "explanation": "「会計をして気分を変える」は不自然。会計は仕事の処理で、気分転換にならない。"}], "explanations": {"スポーツ": "「仲間とスポーツをして気分を変えます」は、体を動かして気分転換するという意味で自然。", "見積もり": "見積もりは仕事の作業で、気分転換の遊びにはならない。", "税金": "「税金をして」とは言わない。税金は納める物。", "会計": "「会計をして気分を変える」は不自然。会計は仕事の処理で、気分転換にならない。"}, "sentence_index": 6, "correct_answer": "スポーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題の答えをスポーツに聞きました。", "explanation": "ここは〈先生〉（人）の意味。スポーツは人ではないので、質問の相手にはならない。"}, {"text": "駅前のスポーツで待ち合わせました。", "explanation": "ここは〈喫茶店〉（場所）の意味。スポーツは場所ではないので、待ち合わせの場所にはならない。"}, {"text": "工場で、機械の組み立てスポーツをしました。", "explanation": "ここは〈作業〉の意味。組み立ての仕事は競技や遊びではないので、スポーツとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日曜日は、河原で友達とスポーツを遊びます。", "corrected_sentence": "日曜日は、河原で友達とスポーツをして遊びます。", "error_description": "「スポーツを遊びます」は不自然。「遊ぶ」の前は「スポーツをして」か「スポーツで」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は、友達と海辺でスポーツに楽しみます。", "corrected_sentence": "週末は、友達と海辺でスポーツを楽しみます。", "error_description": "「楽しむ」の対象は「を」で示す。「に」は誤りで、正しくは「スポーツを楽しみます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スポーツが人気です」で、「人気です」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「人気です」は目的語を取らないので、「を」では文が成立しない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、ここでは主語になる語が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「人気です」の文では使えない。"}], "correct_answer": "が", "explanations": {"が": "「スポーツが人気です」で、「人気です」の主語を示す「が」。", "を": "「人気です」は目的語を取らないので、「を」では文が成立しない。", "に": "「に」は相手や場所を示すが、ここでは主語になる語が必要。", "へ": "「へ」は方向を示すので、「人気です」の文では使えない。"}, "error_tags": {"を": "目的語の助詞", "に": "相手・場所の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語を示す「を」。「スポーツを見る」の形。"}, {"text": "が", "is_correct": false, "explanation": "「スポーツが見る」ではスポーツが見る主体になり、文の意味が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「スポーツに見る」とは言わない。「に」は相手や場所を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「見る」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語を示す「を」。「スポーツを見る」の形。", "が": "「スポーツが見る」ではスポーツが見る主体になり、文の意味が成り立たない。", "に": "「スポーツに見る」とは言わない。「に」は相手や場所を示す。", "へ": "「へ」は方向を示すので、「見る」の対象にはならない。"}, "error_tags": {"が": "主語の助詞", "に": "相手・場所の助詞", "へ": "方向の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "体を動かして行う競技や運動の総称。", "primary_collocate": null, "pronunciation": "すぽーつ", "ipa": "supoːtsɯ", "syllable_count": 4, "sentences": [{"text": "高校生は学校でスポーツをします。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "高校生[こうこうせい]は学校[がっこう]でスポーツをします。", "sentence_source": "mined"}, {"text": "日本では、野球やサッカーなどのスポーツが人気です。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "日本[にほん]では、野球[やきゅう]やサッカーなどのスポーツが人気[にんき]です。", "sentence_source": "generated"}, {"text": "運動が苦手でも、スポーツのルールを知ると試合が楽しくなります。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "運動[うんどう]が苦手[にがて]でも、スポーツのルールを知[し]ると試合[しあい]が楽[たの]しくなります。", "sentence_source": "generated"}, {"text": "兄は毎週末、友達とスポーツの大会に出ます。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "兄[あに]は毎週末[まいしゅうまつ]、友達[ともだち]とスポーツの大会[たいかい]に出[で]ます。", "sentence_source": "generated"}, {"text": "冬はスキーなどのスポーツを楽しむ人が多いです。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "冬[ふゆ]はスキーなどのスポーツを楽[たの]しむ人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "健康のために、毎朝スポーツを続けています。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "健康[けんこう]のために、毎朝[まいあさ]スポーツを続[つづ]けています。", "sentence_source": "generated"}, {"text": "好きなスポーツは何ですかと先生に聞かれました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "好[す]きなスポーツは何[なん]ですかと先生[せんせい]に聞[き]かれました。", "sentence_source": "generated"}, {"text": "テレビでスポーツを見るより、自分でやるほうが楽しいです。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "テレビでスポーツを見[み]るより、自分[じぶん]でやるほうが楽[たの]しいです。", "sentence_source": "generated"}, {"text": "スポーツの試合を見るために、駅の近くの競技場へ行きました。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "スポーツの試合[しあい]を見[み]るために、駅[えき]の近[ちか]くの競技場[きょうぎじょう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "雨の日は、体育館でできるスポーツを選びます。", "target_word": "スポーツ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、体育館[たいいくかん]でできるスポーツを選[えら]びます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スポーツ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "体を動かして行う競技や運動の総称としてのスポーツ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スポーツ", "is_correct": true, "explanation": "「学校でスポーツをします」は自然な文で、体を動かす競技や運動を指す。"}, {"text": "ボール", "is_correct": false, "explanation": "「ボールをします」とは言わない。ボールは使って遊ぶ道具で、「をします」の対象にはならない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "ユニフォームは着る物で、「〜をします」の対象にならない。"}, {"text": "ルール", "is_correct": false, "explanation": "ルールは守る・決めるもので、「ルールをします」とは言えない。"}], "explanations": {"スポーツ": "「学校でスポーツをします」は自然な文で、体を動かす競技や運動を指す。", "ボール": "「ボールをします」とは言わない。ボールは使って遊ぶ道具で、「をします」の対象にはならない。", "ユニフォーム": "ユニフォームは着る物で、「〜をします」の対象にならない。", "ルール": "ルールは守る・決めるもので、「ルールをします」とは言えない。"}, "sentence_index": 0, "correct_answer": "スポーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重力の下での物体のスポーツを計算した。", "explanation": "ここは〈運動〉（物の動き）の意味。スポーツは体を動かして行う競技や運動を指すので、物体の動きには使えない。"}, {"text": "毎晩、英語のスポーツをしています。", "explanation": "ここは〈勉強〉の意味。英語の学習は競技や運動ではないので、スポーツとは言わない。"}, {"text": "週末は、工場で機械の組み立てスポーツをしました。", "explanation": "ここは〈作業〉の意味。組み立ての仕事は競技や運動ではないので、スポーツとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スポーツ", "is_correct": true, "explanation": "「好きなスポーツは何ですか」は自然な問いの形で、空欄に入る語はこれだけ。"}, {"text": "ゴミ", "is_correct": false, "explanation": "「好きなゴミ」は意味をなさず、好みの対象として言わない。"}, {"text": "コンセント", "is_correct": false, "explanation": "コンセントは好みを尋ねる対象にならない。「好きなコンセント」は不自然。"}, {"text": "ブレーキ", "is_correct": false, "explanation": "ブレーキは好む対象として言わない。「好きなブレーキは何ですか」は不自然。"}], "explanations": {"スポーツ": "「好きなスポーツは何ですか」は自然な問いの形で、空欄に入る語はこれだけ。", "ゴミ": "「好きなゴミ」は意味をなさず、好みの対象として言わない。", "コンセント": "コンセントは好みを尋ねる対象にならない。「好きなコンセント」は不自然。", "ブレーキ": "ブレーキは好む対象として言わない。「好きなブレーキは何ですか」は不自然。"}, "sentence_index": 6, "correct_answer": "スポーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "悩みをスポーツに相談しました。", "explanation": "ここは〈先生〉（人）の意味。スポーツは人ではないので、相談の相手にはならない。"}, {"text": "駅前のスポーツで待ち合わせました。", "explanation": "ここは〈喫茶店〉（場所）の意味。スポーツは場所ではないので、待ち合わせの場所にはならない。"}, {"text": "毎朝、スポーツで学校へ行きます。", "explanation": "ここは〈電車〉（乗り物）の意味。スポーツは乗り物ではないので、通学の手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、公園でスポーツが続けています。", "corrected_sentence": "毎朝、公園でスポーツを続けています。", "error_description": "「続ける」の対象は「を」で示す。「が」は誤りで、正しくは「スポーツを続けています」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末は、友達と公園でスポーツに楽しみます。", "corrected_sentence": "週末は、友達と公園でスポーツを楽しみます。", "error_description": "「楽しむ」の対象は「を」で示す。「に」は誤りで、正しくは「スポーツを楽しみます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「鞄の底」で、鞄の一部であることを示す「の」。"}, {"text": "に", "is_correct": false, "explanation": "「古い鞄に底に」は成り立たない。「に」は相手や場所を示す。"}, {"text": "を", "is_correct": false, "explanation": "「鞄を底に」は不自然。「を」は目的語を示すので、ここでは使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「鞄へ底に」は成り立たない。「へ」は方向を示す。"}], "correct_answer": "の", "explanations": {"の": "「鞄の底」で、鞄の一部であることを示す「の」。", "に": "「古い鞄に底に」は成り立たない。「に」は相手や場所を示す。", "を": "「鞄を底に」は不自然。「を」は目的語を示すので、ここでは使えない。", "へ": "「鞄へ底に」は成り立たない。「へ」は方向を示す。"}, "error_tags": {"に": "相手・場所の助詞", "を": "目的語の助詞", "へ": "方向の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「鞄がぬれた」で、ぬれた主体を示す「が」。"}, {"text": "で", "is_correct": false, "explanation": "「鞄でぬれた」は成り立たない。「で」は手段や場所を示すため、鞄の状態を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「鞄からぬれた」は不自然。「から」は起点を示すため、鞄がぬれる主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「鞄よりぬれた」は比較を示すため、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「鞄がぬれた」で、ぬれた主体を示す「が」。", "で": "「鞄でぬれた」は成り立たない。「で」は手段や場所を示すため、鞄の状態を表せない。", "から": "「鞄からぬれた」は不自然。「から」は起点を示すため、鞄がぬれる主語にはならない。", "より": "「鞄よりぬれた」は比較を示すため、文が成り立たない。"}, "error_tags": {"で": "手段・場所の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものを入れて持ち運ぶための袋。", "primary_collocate": null, "pronunciation": "かばん", "ipa": "kabaɴ", "syllable_count": 3, "sentences": [{"text": "毎朝、鞄に本と弁当を入れて学校へ行きます。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、鞄[かばん]に本[ほん]と弁当[べんとう]を入[い]れて学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "古い鞄の底に穴が開いて、財布を落としました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "古[ふる]い鞄[かばん]の底[そこ]に穴[あな]が開[あ]いて、財布[さいふ]を落[お]としました。", "sentence_source": "generated"}, {"text": "妹は赤い鞄を肩にかけて歩いています。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "妹[いもうと]は赤[あか]い鞄[かばん]を肩[かた]にかけて歩[ある]いています。", "sentence_source": "generated"}, {"text": "出かける前に、鞄の中を確かめました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "出[で]かける前[まえ]に、鞄[かばん]の中[なか]を確[たし]かめました。", "sentence_source": "generated"}, {"text": "重い荷物で、鞄の持ち手が切れてしまいました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]で、鞄[かばん]の持[も]ち手[て]が切[き]れてしまいました。", "sentence_source": "generated"}, {"text": "鞄を電車に忘れて、駅に電話しました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "鞄[かばん]を電車[でんしゃ]に忘[わす]れて、駅[えき]に電話[でんわ]しました。", "sentence_source": "generated"}, {"text": "父は仕事に黒い鞄を持っていきます。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]に黒[くろ]い鞄[かばん]を持[も]っていきます。", "sentence_source": "generated"}, {"text": "雨で鞄がぬれたので、タオルでふきました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "雨[あめ]で鞄[かばん]がぬれたので、タオルでふきました。", "sentence_source": "generated"}, {"text": "新しい鞄を買うために、デパートへ行きました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "新[あたら]しい鞄[かばん]を買[か]うために、デパートへ行[い]きました。", "sentence_source": "generated"}, {"text": "鞄からノートを出して、先生の話をメモしました。", "target_word": "鞄", "complexity_tier": "T3", "furigana": "鞄[かばん]からノートを出[だ]して、先生[せんせい]の話[はなし]をメモしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鞄", "label": "基本形"}, {"form": "カバン", "label": "カタカナ表記"}], "register": "polite", "sense_fingerprint": "ものを入れて持ち運ぶための袋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鞄", "is_correct": true, "explanation": "「毎朝、鞄に本と弁当を入れて学校へ行きます」は、通学用の袋に物を入れる意味で自然。"}, {"text": "天井", "is_correct": false, "explanation": "「天井に本と弁当を入れて」は不自然。天井は物を入れる容器ではない。"}, {"text": "電話", "is_correct": false, "explanation": "「電話に本と弁当を入れて」は成り立たない。電話は物を入れる場所ではない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓に本と弁当を入れて」は不自然。窓は物を入れる容器ではない。"}], "explanations": {"鞄": "「毎朝、鞄に本と弁当を入れて学校へ行きます」は、通学用の袋に物を入れる意味で自然。", "天井": "「天井に本と弁当を入れて」は不自然。天井は物を入れる容器ではない。", "電話": "「電話に本と弁当を入れて」は成り立たない。電話は物を入れる場所ではない。", "窓": "「窓に本と弁当を入れて」は不自然。窓は物を入れる容器ではない。"}, "sentence_index": 0, "correct_answer": "鞄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出かける前に、鞄の宛先を確かめました。", "explanation": "ここは〈手紙〉の意味。手紙には宛先があるが、鞄は宛先を持たないので合わない。"}, {"text": "庭の鞄に水をやるのを忘れた。", "explanation": "ここは〈花〉の意味。鞄は植物ではないので、水やりの対象にならない。"}, {"text": "出かける前に、鞄の時刻を確かめました。", "explanation": "ここは〈時計〉の意味。時刻は時計が示すもので、鞄には時刻がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鞄", "is_correct": true, "explanation": "「父は仕事に黒い鞄を持っていきます」は、仕事用の袋を持って行く意味で自然。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を持っていきます」は成り立たない。天気は持ち運べない。"}, {"text": "電柱", "is_correct": false, "explanation": "「黒い電柱を持っていきます」は成り立たない。電柱は持ち運べない。"}, {"text": "階段", "is_correct": false, "explanation": "「黒い階段を持っていきます」は成り立たない。階段は持ち運べない。"}], "explanations": {"鞄": "「父は仕事に黒い鞄を持っていきます」は、仕事用の袋を持って行く意味で自然。", "天気": "「天気を持っていきます」は成り立たない。天気は持ち運べない。", "電柱": "「黒い電柱を持っていきます」は成り立たない。電柱は持ち運べない。", "階段": "「黒い階段を持っていきます」は成り立たない。階段は持ち運べない。"}, "sentence_index": 6, "correct_answer": "鞄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鞄に料理を盛りつけました。", "explanation": "ここは〈皿〉の意味。料理を盛りつけるのは皿で、鞄は器ではないので合わない。"}, {"text": "鞄で先生に連絡しました。", "explanation": "ここは〈電話〉（連絡の手段）の意味。鞄は連絡の手段にならないので合わない。"}, {"text": "鞄で道を確かめました。", "explanation": "ここは〈地図〉の意味。鞄は道順を示す物ではないので、確かめる手段にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、鞄を傘を入れて登校します。", "corrected_sentence": "雨の日は、鞄に傘を入れて登校します。", "error_description": "「入れる」の入る先は「に」で示す。「を」は誤りで、正しくは「鞄に傘を入れて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51427, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は、鞄から折りたたみ傘を入れます。", "corrected_sentence": "雨の日は、鞄に折りたたみ傘を入れます。", "error_description": "「入れる」の入る先は「に」で示す。「から」は誤りで、正しくは「鞄に折りたたみ傘を入れます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
