INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51429, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「処置をしました」の「を」。「する」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「処置へしました」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、「処置からしました」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「処置よりしました」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「処置をしました」の「を」。「する」の目的語を示す。", "へ": "「へ」は方向を表すため、「処置へしました」は文が成り立たない。", "から": "「から」は起点を表すため、「処置からしました」は不自然。", "より": "「より」は比較を表すため、「処置よりしました」は文が成り立たない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "わるいところをなおすために、何かをすることを「しょち」といいます。", "primary_collocate": null, "pronunciation": "しょち", "ipa": "ɕot͡ɕi", "syllable_count": 2, "sentences": [{"text": "足にけがをして、病院で処置してもらいました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "足[あし]にけがをして、病院[びょういん]で処置[しょち]してもらいました。", "sentence_source": "generated"}, {"text": "先生は私の指の傷に薬をぬって、処置をしてくれました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の指[ゆび]の傷[きず]に薬[くすり]をぬって、処置[しょち]をしてくれました。", "sentence_source": "generated"}, {"text": "虫歯がひどいので、歯医者さんが処置をしました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "虫歯[むしば]がひどいので、歯医者[はいしゃ]さんが処置[しょち]をしました。", "sentence_source": "generated"}, {"text": "熱が高かったので、すぐに処置が必要でした。", "target_word": "処置", "complexity_tier": "T3", "furigana": "熱[ねつ]が高[たか]かったので、すぐに処置[しょち]が必要[ひつよう]でした。", "sentence_source": "generated"}, {"text": "転んで血が出たとき、保健室で処置を受けました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "転[ころ]んで血[ち]が出[で]たとき、保健室[ほけんしつ]で処置[しょち]を受[う]けました。", "sentence_source": "generated"}, {"text": "看護師さんが、やけどの処置を丁寧にしてくれました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "看護師[かんごし]さんが、やけどの処置[しょち]を丁寧[ていねい]にしてくれました。", "sentence_source": "generated"}, {"text": "処置が早かったおかげで、けがは早く治りました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "処置[しょち]が早[はや]かったおかげで、けがは早[はや]く治[なお]りました。", "sentence_source": "generated"}, {"text": "犬の耳が悪くなったので、獣医さんが処置をしました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "犬[いぬ]の耳[みみ]が悪[わる]くなったので、獣医[じゅうい]さんが処置[しょち]をしました。", "sentence_source": "generated"}, {"text": "鼻血が止まらず、保健の先生に処置をお願いしました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "鼻血[はなぢ]が止[と]まらず、保健[ほけん]の先生[せんせい]に処置[しょち]をお願[ねが]いしました。", "sentence_source": "generated"}, {"text": "けがの処置が終わって、やっと安心しました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "けがの処置[しょち]が終[お]わって、やっと安心[あんしん]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "処置", "label": "基本形"}, {"form": "処置する", "label": "サ変動詞の辞書形"}, {"form": "処置した", "label": "サ変動詞の過去形"}], "register": "polite", "sense_fingerprint": "けがや病気など、わるいところをなおすために手当てをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "処置", "is_correct": true, "explanation": "「病院で処置してもらう」は、けがの手当てを受けたという意味になり文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「病院で散歩してもらう」は意味が通らない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「病院で洗濯してもらう」は文脈に合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "「病院で掃除してもらう」は、けがの手当てとは関係がない。"}], "explanations": {"処置": "「病院で処置してもらう」は、けがの手当てを受けたという意味になり文に合う。", "散歩": "「病院で散歩してもらう」は意味が通らない。", "洗濯": "「病院で洗濯してもらう」は文脈に合わない。", "掃除": "「病院で掃除してもらう」は、けがの手当てとは関係がない。"}, "sentence_index": 0, "correct_answer": "処置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい企画を、先生が一人で処置しました。", "explanation": "処置は事態への手当てを指すので、企画を考える場面には合わない。"}, {"text": "古い書類の処置を、昨日すべて終えました。", "explanation": "処置は傷や事態への手当てを指すので、書類の事務処理には使わない。"}, {"text": "会場の処置は、もう先生が済ませてくれました。", "explanation": "処置は傷や事態への対応を指すので、会場の準備には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "処置", "is_correct": true, "explanation": "「処置が早かった」は手当ての速さを表し、けがが早く治った文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が早かった」は意味が通らない。"}, {"text": "音楽", "is_correct": false, "explanation": "「音楽が早かった」は文脈に合わない。"}, {"text": "紙", "is_correct": false, "explanation": "「紙が早かった」は意味が通らず、治りの早さとは関係がない。"}], "explanations": {"処置": "「処置が早かった」は手当ての速さを表し、けがが早く治った文脈に合う。", "天気": "「天気が早かった」は意味が通らない。", "音楽": "「音楽が早かった」は文脈に合わない。", "紙": "「紙が早かった」は意味が通らず、治りの早さとは関係がない。"}, "sentence_index": 6, "correct_answer": "処置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "修学旅行の処置を、クラス全員で進めています。", "explanation": "処置は傷や事態への手当てを指すので、旅行の段取りには使わない。"}, {"text": "作文の処置を、先生が一人で終えました。", "explanation": "処置は手当てや対応を指すので、作文の評価には使わない。"}, {"text": "ギターの処置を毎晩続けています。", "explanation": "処置は傷や事態への手当てを指すので、楽器の練習には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "獣医さんが犬の耳の処置がしました。", "corrected_sentence": "獣医さんが犬の耳の処置をしました。", "error_description": "「処置をする」の「を」が正しい。「が」は主語を表すため、「処置がしました」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
