INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「処置をしてください」の「を」。「する」の目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、「処置へしてください」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、「処置からしてください」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「処置よりしてください」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「処置をしてください」の「を」。「する」の目的語を示す。", "へ": "「へ」は方向を表すため、「処置へしてください」は文が成り立たない。", "から": "「から」は起点を表すため、「処置からしてください」は不自然。", "より": "「より」は比較を表すため、「処置よりしてください」は文が成り立たない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある事態に対して、必要な対応や手当てをすること。", "primary_collocate": null, "pronunciation": "しょち", "ipa": "ɕot͡ɕi", "syllable_count": 2, "sentences": [{"text": "救急処置のキットをカバンに入れます。", "target_word": "処置", "complexity_tier": "T3", "furigana": "救急処置[きゅうきゅうしょち]のキットをカバンに入[い]れます。", "sentence_source": "mined"}, {"text": "医者はけがをした男性にすぐ処置をしました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "医者[いしゃ]はけがをした男性[だんせい]にすぐ処置[しょち]をしました。", "sentence_source": "generated"}, {"text": "早く処置をしたので、傷はひどくなりませんでした。", "target_word": "処置", "complexity_tier": "T3", "furigana": "早[はや]く処置[しょち]をしたので、傷[きず]はひどくなりませんでした。", "sentence_source": "generated"}, {"text": "事故の現場で、救急隊員が正しい処置を行いました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "事故[じこ]の現場[げんば]で、救急隊員[きゅうきゅうたいいん]が正[ただ]しい処置[しょち]を行[おこな]いました。", "sentence_source": "generated"}, {"text": "問題が起きたとき、会社は迅速な処置をとりました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "問題[もんだい]が起[お]きたとき、会社[かいしゃ]は迅速[じんそく]な処置[しょち]をとりました。", "sentence_source": "generated"}, {"text": "犬が足をけがしたので、病院で処置を受けました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "犬[いぬ]が足[あし]をけがしたので、病院[びょういん]で処置[しょち]を受[う]けました。", "sentence_source": "generated"}, {"text": "応急の処置が遅れると、命にかかわることがあります。", "target_word": "処置", "complexity_tier": "T3", "furigana": "応急[おうきゅう]の処置[しょち]が遅[おく]れると、命[いのち]にかかわることがあります。", "sentence_source": "generated"}, {"text": "ガス漏れが起きたので、すぐに適切な処置をしてください。", "target_word": "処置", "complexity_tier": "T3", "furigana": "ガス[がす]漏[も]れが起[お]きたので、すぐに適切[てきせつ]な処置[しょち]をしてください。", "sentence_source": "generated"}, {"text": "看護師は落ち着いて、傷の処置を進めました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "看護師[かんごし]は落[お]ち着[つ]いて、傷[きず]の処置[しょち]を進[すす]めました。", "sentence_source": "generated"}, {"text": "担当者の処置が適切だったので、被害は小さくすみました。", "target_word": "処置", "complexity_tier": "T3", "furigana": "担当者[たんとうしゃ]の処置[しょち]が適切[てきせつ]だったので、被害[ひがい]は小[ちい]さくすみました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "処置", "label": "基本形"}, {"form": "処置する", "label": "サ変動詞の辞書形"}, {"form": "処置した", "label": "サ変動詞の過去形"}], "register": "polite", "sense_fingerprint": "事故や問題などの事態に対して、必要な対応や手当てをすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "処置", "is_correct": true, "explanation": "「救急処置」は応急の手当てを表す語で、キットの名前として文に合う。"}, {"text": "電話", "is_correct": false, "explanation": "「救急電話のキット」は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "「救急手紙のキット」は不自然で、キットの中身を表さない。"}, {"text": "散歩", "is_correct": false, "explanation": "「救急散歩のキット」は文脈に合わない。"}], "explanations": {"処置": "「救急処置」は応急の手当てを表す語で、キットの名前として文に合う。", "電話": "「救急電話のキット」は意味が通らない。", "手紙": "「救急手紙のキット」は不自然で、キットの中身を表さない。", "散歩": "「救急散歩のキット」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "処置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいアイデアを、みんなで処置しました。", "explanation": "処置は事態への手当てを指すので、アイデアを考える場面には合わない。"}, {"text": "提出する書類の処置を、明日までに終えてください。", "explanation": "処置は傷や事態への手当てを指すので、書類の事務処理には使わない。"}, {"text": "会議室の処置を、先生が前日に頼みました。", "explanation": "処置は傷や事態への対応を指すので、会議室の準備には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "処置", "is_correct": true, "explanation": "「応急の処置」は応急の手当てを指し、遅れると命に関わるという文脈に合う。"}, {"text": "食事", "is_correct": false, "explanation": "「応急の食事」は文脈に合わず、遅れると命に関わるとは言えない。"}, {"text": "試合", "is_correct": false, "explanation": "「応急の試合」は意味が通らない。"}, {"text": "買い物", "is_correct": false, "explanation": "「応急の買い物」は不自然で、命に関わる文脈と合わない。"}], "explanations": {"処置": "「応急の処置」は応急の手当てを指し、遅れると命に関わるという文脈に合う。", "食事": "「応急の食事」は文脈に合わず、遅れると命に関わるとは言えない。", "試合": "「応急の試合」は意味が通らない。", "買い物": "「応急の買い物」は不自然で、命に関わる文脈と合わない。"}, "sentence_index": 6, "correct_answer": "処置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の遠足の処置を、母と一緒に進めました。", "explanation": "処置は傷や事態への手当てを指すので、遠足の段取りには使わない。"}, {"text": "テストの答案の処置は、先生が一人でしました。", "explanation": "処置は手当てや対応を指すので、答案の評価には使わない。"}, {"text": "ピアノの処置を、毎晩一時間続けています。", "explanation": "処置は傷や事態への手当てを指すので、楽器の練習には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救急隊員が傷の処置に行いました。", "corrected_sentence": "救急隊員が傷の処置を行いました。", "error_description": "「処置を行う」が正しい。目的語を示す「を」が必要で、「処置に行いました」の「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "担当の人が、すぐに処置を行きました。", "corrected_sentence": "担当の人が、すぐに処置を行いました。", "error_description": "「処置を行う」が正しい。「行く」は移動を表す動詞で、「処置を行きました」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「救急に連絡しました」の「に」。連絡の相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「救急を連絡しました」は、連絡の相手を「に」で示すため不自然。"}, {"text": "が", "is_correct": false, "explanation": "「救急が連絡しました」は救急が主語になり、連絡の相手が示されず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「救急で連絡しました」は手段を表すが、相手を示す文としては不自然。"}], "correct_answer": "に", "explanations": {"に": "「救急に連絡しました」の「に」。連絡の相手を示す。", "を": "「救急を連絡しました」は、連絡の相手を「に」で示すため不自然。", "が": "「救急が連絡しました」は救急が主語になり、連絡の相手が示されず不自然。", "で": "「救急で連絡しました」は手段を表すが、相手を示す文としては不自然。"}, "error_tags": {"を": "対象の格", "が": "主語の格", "で": "手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
