INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "急に病気やけがをしたときに、すぐに助けること。", "primary_collocate": null, "pronunciation": "きゅうきゅう", "ipa": "kʲɯːkʲɯː", "syllable_count": 4, "sentences": [{"text": "救急の電話番号は119です。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の電話[でんわ]番号[ばんごう]は119です。", "sentence_source": "generated"}, {"text": "道で人が倒れたので、通りかかった人が救急に連絡しました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "道[みち]で人[ひと]が倒[たお]れたので、通[とお]りかかった人[ひと]が救急[きゅうきゅう]に連絡[れんらく]しました。", "sentence_source": "generated"}, {"text": "彼は救急の現場で十年働いています。", "target_word": "救急", "complexity_tier": "T3", "furigana": "彼[かれ]は救急[きゅうきゅう]の現場[げんば]で十年[じゅうねん]働[はたら]いています。", "sentence_source": "generated"}, {"text": "夜中に高い熱が出て、救急で病院に運ばれました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "夜中[よなか]に高[たか]い熱[ねつ]が出[で]て、救急[きゅうきゅう]で病院[びょういん]に運[はこ]ばれました。", "sentence_source": "generated"}, {"text": "この病院は、二十四時間救急を受け付けています。", "target_word": "救急", "complexity_tier": "T3", "furigana": "この病院[びょういん]は、二十四[にじゅうよ]時間[じかん]救急[きゅうきゅう]を受[う]け付[つ]けています。", "sentence_source": "generated"}, {"text": "救急の患者が多くて、医者は昼ご飯を食べる時間もありませんでした。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の患者[かんじゃ]が多[おお]くて、医者[いしゃ]は昼[ひる]ご飯[はん]を食[た]べる時間[じかん]もありませんでした。", "sentence_source": "generated"}, {"text": "救急の医師は、けが人を見てすぐに手当てを始めました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の医師[いし]は、けが人[にん]を見[み]てすぐに手当[てあ]てを始[はじ]めました。", "sentence_source": "generated"}, {"text": "町の消防署では、救急の訓練が毎月あります。", "target_word": "救急", "complexity_tier": "T3", "furigana": "町[まち]の消防署[しょうぼうしょ]では、救急[きゅうきゅう]の訓練[くんれん]が毎月[まいつき]あります。", "sentence_source": "generated"}, {"text": "救急の仕事は大変ですが、人を助けられるのでやりがいがあります。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の仕事[しごと]は大変[たいへん]ですが、人[ひと]を助[たす]けられるのでやりがいがあります。", "sentence_source": "generated"}, {"text": "けがをした子どもは、救急で手当てを受けてから家に帰りました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "けがをした子[こ]どもは、救急[きゅうきゅう]で手当[てあ]てを受[う]けてから家[いえ]に帰[かえ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "救急", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "急病やけがの人をすぐに助ける活動や体制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "救急", "is_correct": true, "explanation": "「救急の電話番号」は急病やけがの通報先を表し、119という番号と結びつく。"}, {"text": "海底", "is_correct": false, "explanation": "「海底の電話番号」は意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖の電話番号」は文脈に合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室の電話番号」は119と結びつかない。"}], "explanations": {"救急": "「救急の電話番号」は急病やけがの通報先を表し、119という番号と結びつく。", "海底": "「海底の電話番号」は意味が通らない。", "砂糖": "「砂糖の電話番号」は文脈に合わない。", "寝室": "「寝室の電話番号」は119と結びつかない。"}, "sentence_index": 0, "correct_answer": "救急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救急の用品を、かばんに入れて持ち歩きました。", "explanation": "ここは別の語義〈用品〉の意味。救急は人を助ける活動を指すので、道具の場面には使わない。"}, {"text": "救急の知識を、子どもに教えました。", "explanation": "ここは別の語義〈知識〉の意味。救急は人を助ける活動を指すので、知識の内容には使わない。"}, {"text": "救急の用意を、家にそろえておきました。", "explanation": "ここは別の語義〈用意〉の意味。救急は人を助ける活動を指すので、備えの場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "救急", "is_correct": true, "explanation": "「救急の医師」は急病やけがを診る医師を表し、けが人の手当てをする文脈に合う。"}, {"text": "電話", "is_correct": false, "explanation": "「電話の医師」は意味が通らない。"}, {"text": "植物", "is_correct": false, "explanation": "「植物の医師」は意味が通らない。"}, {"text": "本棚", "is_correct": false, "explanation": "「本棚の医師」は意味が通らない。"}], "explanations": {"救急": "「救急の医師」は急病やけがを診る医師を表し、けが人の手当てをする文脈に合う。", "電話": "「電話の医師」は意味が通らない。", "植物": "「植物の医師」は意味が通らない。", "本棚": "「本棚の医師」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "救急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "救急の用意を、みんなで点検しました。", "explanation": "ここは別の語義〈用意〉の意味。救急は人を助ける活動を指すので、点検の対象には使わない。"}, {"text": "救急の包帯を、かばんにしまいました。", "explanation": "ここは別の語義〈用品〉の意味。救急は人を助ける活動を指すので、道具には使わない。"}, {"text": "救急の用品を、台所の棚に置きました。", "explanation": "ここは別の語義〈用品〉の意味。救急は人を助ける活動を指すので、棚の物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな事故があったら、すぐに救急を連絡しましょう。", "corrected_sentence": "大きな事故があったら、すぐに救急に連絡しましょう。", "error_description": "「連絡する」は相手を「に」で示す。「救急を連絡」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51431, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町の救急な活動を応援します。", "corrected_sentence": "町の救急の活動を応援します。", "error_description": "「救急」は名詞なので「救急の活動」と「の」で続ける。「救急な」は形容動詞の形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「救急の道具」の「の」。名詞「救急」と「道具」をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "「救急が道具」は救急が主語になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「救急で道具」は手段や場所を表し、道具を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「救急を道具をそろえ」は「を」が重なり不自然。"}], "correct_answer": "の", "explanations": {"の": "「救急の道具」の「の」。名詞「救急」と「道具」をつなぐ。", "が": "「救急が道具」は救急が主語になり、文が成り立たない。", "で": "「救急で道具」は手段や場所を表し、道具を示せない。", "を": "「救急を道具をそろえ」は「を」が重なり不自然。"}, "error_tags": {"が": "主語の格", "で": "手段・場所の格", "を": "対象の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "急な病気やけがのときに、すぐに手当をすること。また、そのためのもの。", "primary_collocate": null, "pronunciation": "きゅうきゅう", "ipa": "kʲɯːkʲɯː", "syllable_count": 4, "sentences": [{"text": "救急処置のキットをカバンに入れます。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]処置[しょち]のキットをカバンに入[い]れます。", "sentence_source": "mined"}, {"text": "家に救急の道具をそろえておくと、けがをしたときに安心です。", "target_word": "救急", "complexity_tier": "T3", "furigana": "家[いえ]に救急[きゅうきゅう]の道具[どうぐ]をそろえておくと、けがをしたときに安心[あんしん]です。", "sentence_source": "generated"}, {"text": "この棚には、救急のための薬や包帯が入っています。", "target_word": "救急", "complexity_tier": "T3", "furigana": "この棚[たな]には、救急[きゅうきゅう]のための薬[くすり]や包帯[ほうたい]が入[はい]っています。", "sentence_source": "generated"}, {"text": "山登りでは、救急の用意を忘れないようにしています。", "target_word": "救急", "complexity_tier": "T3", "furigana": "山登[やまのぼ]りでは、救急[きゅうきゅう]の用意[ようい]を忘[わす]れないようにしています。", "sentence_source": "generated"}, {"text": "先生は救急の知識があるので、すぐに手当てをしてくれました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "先生[せんせい]は救急[きゅうきゅう]の知識[ちしき]があるので、すぐに手当[てあ]てをしてくれました。", "sentence_source": "generated"}, {"text": "夜に子どもが熱を出したので、救急で診てもらいました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "夜[よる]に子[こ]どもが熱[ねつ]を出[だ]したので、救急[きゅうきゅう]で診[み]てもらいました。", "sentence_source": "generated"}, {"text": "救急の講習を受けて、包帯の巻き方を習いました。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の講習[こうしゅう]を受[う]けて、包帯[ほうたい]の巻[ま]き方[かた]を習[なら]いました。", "sentence_source": "generated"}, {"text": "会社の入口に救急の用品が置いてあります。", "target_word": "救急", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の入口[いりぐち]に救急[きゅうきゅう]の用品[ようひん]が置[お]いてあります。", "sentence_source": "generated"}, {"text": "救急の手当てが早かったので、傷は大きくなりませんでした。", "target_word": "救急", "complexity_tier": "T3", "furigana": "救急[きゅうきゅう]の手当[てあ]てが早[はや]かったので、傷[きず]は大[おお]きくなりませんでした。", "sentence_source": "generated"}, {"text": "学校の保健室には、救急の道具がひと通りそろっています。", "target_word": "救急", "complexity_tier": "T3", "furigana": "学校[がっこう]の保健室[ほけんしつ]には、救急[きゅうきゅう]の道具[どうぐ]がひと通[とお]りそろっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "救急", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "急な病気やけがの手当て、またはそのための用品や用意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "救急", "is_correct": true, "explanation": "「救急処置」は急な病気やけがの応急手当を表し、キットの名前として文に合う。"}, {"text": "病院", "is_correct": false, "explanation": "「病院処置のキット」は意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙処置のキット」は不自然で、キットの用途と合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩処置」は文脈に合わない。"}], "explanations": {"救急": "「救急処置」は急な病気やけがの応急手当を表し、キットの名前として文に合う。", "病院": "「病院処置のキット」は意味が通らない。", "手紙": "「手紙処置のキット」は不自然で、キットの用途と合わない。", "散歩": "「散歩処置」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "救急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は救急の仕事があるので、会議を途中で抜けました。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、仕事の場面には使わない。"}, {"text": "救急の患者を、病院でみました。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、患者には使わない。"}, {"text": "救急の医師は、夜も病院にいます。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、医師の所属には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "救急", "is_correct": true, "explanation": "「救急の講習」は応急手当の講習を表し、包帯の巻き方を習う文脈に合う。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室の講習」は文脈に合わない。"}, {"text": "海底", "is_correct": false, "explanation": "「海底の講習」は意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖の講習」は不自然で、包帯の巻き方と関係がない。"}], "explanations": {"救急": "「救急の講習」は応急手当の講習を表し、包帯の巻き方を習う文脈に合う。", "寝室": "「寝室の講習」は文脈に合わない。", "海底": "「海底の講習」は意味が通らない。", "砂糖": "「砂糖の講習」は不自然で、包帯の巻き方と関係がない。"}, "sentence_index": 6, "correct_answer": "救急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "救急の現場で、十年働きました。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、現場の仕事には使わない。"}, {"text": "救急の患者が、病院に運ばれました。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、患者の状況には使わない。"}, {"text": "救急の隊員が、現場に走りました。", "explanation": "ここは別の語義〈活動〉の意味。救急は手当ての用品や用意を指すので、隊員の行動には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "けがをしたら、すぐに救急を連絡してください。", "corrected_sentence": "けがをしたら、すぐに救急に連絡してください。", "error_description": "「連絡する」は相手を「に」で示す。「救急を連絡」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "けがをした人に、救急な手当てをしました。", "corrected_sentence": "けがをした人に、救急の手当てをしました。", "error_description": "「救急」は名詞なので「救急の手当て」と「の」で続ける。「救急な」は形容動詞の形で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「病院へ行きました」の「へ」。移動の方向を表し、ここで自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「病院を行きました」は目的語の「を」では文が成り立たない。行くは移動で、対象を取らない。"}, {"text": "で", "is_correct": false, "explanation": "「病院で行きました」は場所・手段の「で」で、移動の行き先を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「病院が行きました」は主語になるが、病院が行くという意味になり不自然。"}], "correct_answer": "へ", "explanations": {"へ": "「病院へ行きました」の「へ」。移動の方向を表し、ここで自然に成り立つ。", "を": "「病院を行きました」は目的語の「を」では文が成り立たない。行くは移動で、対象を取らない。", "で": "「病院で行きました」は場所・手段の「で」で、移動の行き先を示せない。", "が": "「病院が行きました」は主語になるが、病院が行くという意味になり不自然。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「病院で看護師として働いています」の「で」。働く場所を示し、文が自然に成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "「病院と看護師として働いています」は並列や相手を示す「と」で、場所を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「病院から看護師として働いています」は起点の「から」で、働く場所の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「病院へ看護師として働いています」は方向の「へ」で、働く場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "「病院で看護師として働いています」の「で」。働く場所を示し、文が自然に成り立つ。", "と": "「病院と看護師として働いています」は並列や相手を示す「と」で、場所を表せない。", "から": "「病院から看護師として働いています」は起点の「から」で、働く場所の意味にならない。", "へ": "「病院へ看護師として働いています」は方向の「へ」で、働く場所を示せない。"}, "error_tags": {"と": "並列・相手", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気やけがの治療や診察を受けるための施設。", "primary_collocate": null, "pronunciation": "びょういん", "ipa": "bjoːiɴ", "syllable_count": 4, "sentences": [{"text": "病院での薬の選び方は、昔と今で違います。", "target_word": "病院", "complexity_tier": "T3", "furigana": "病院(びょういん)での薬(くすり)の選(えら)び方(かた)は、昔(むかし)と今(いま)で違(ちが)います。", "sentence_source": "mined"}, {"text": "熱が出たので、母と一緒に病院へ行きました。", "target_word": "病院", "complexity_tier": "T3", "furigana": "熱(ねつ)が出(で)たので、母(はは)と一緒(いっしょ)に病院(びょういん)へ行(い)きました。", "sentence_source": "generated"}, {"text": "この病院には、子どものための専門の医者がいます。", "target_word": "病院", "complexity_tier": "T3", "furigana": "この病院(びょういん)には、子(こ)どものための専門(せんもん)の医者(いしゃ)がいます。", "sentence_source": "generated"}, {"text": "駅の近くに新しい病院ができて、通うのが楽になりました。", "target_word": "病院", "complexity_tier": "T3", "furigana": "駅(えき)の近(ちか)くに新(あたら)しい病院(びょういん)ができて、通(かよ)うのが楽(らく)になりました。", "sentence_source": "generated"}, {"text": "祖父は足の骨を折って、病院で治療を受けています。", "target_word": "病院", "complexity_tier": "T3", "furigana": "祖父(そふ)は足(あし)の骨(ほね)を折(お)って、病院(びょういん)で治療(ちりょう)を受(う)けています。", "sentence_source": "generated"}, {"text": "病院では、静かに話さなければなりません。", "target_word": "病院", "complexity_tier": "T3", "furigana": "病院(びょういん)では、静(しず)かに話(はな)さなければなりません。", "sentence_source": "generated"}, {"text": "夜に急に腹が痛くなって、救急車で病院に運ばれました。", "target_word": "病院", "complexity_tier": "T3", "furigana": "夜(よる)に急(きゅう)に腹(はら)が痛(いた)くなって、救急車(きゅうきゅうしゃ)で病院(びょういん)に運(はこ)ばれました。", "sentence_source": "generated"}, {"text": "姉は病院で看護師として働いています。", "target_word": "病院", "complexity_tier": "T3", "furigana": "姉(あね)は病院(びょういん)で看護師(かんごし)として働(はたら)いています。", "sentence_source": "generated"}, {"text": "病院の待合室で、一時間も名前を呼ばれるのを待ちました。", "target_word": "病院", "complexity_tier": "T3", "furigana": "病院(びょういん)の待合室(まちあいしつ)で、一時間(いちじかん)も名前(なまえ)を呼(よ)ばれるのを待(ま)ちました。", "sentence_source": "generated"}, {"text": "風邪が治らないので、あした病院で検査をしてもらいます。", "target_word": "病院", "complexity_tier": "T3", "furigana": "風邪(かぜ)が治(なお)らないので、あした病院(びょういん)で検査(けんさ)をしてもらいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "病院", "label": "基本形"}], "register": "polite", "sense_fingerprint": "病気やけがの診察・治療を受ける施設", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病院", "is_correct": true, "explanation": "「病院での薬の選び方」の「病院」。医療の場での薬の選び方という意味になり、自然に成り立つ。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題での薬の選び方」は意味が通らない。宿題は学習の課題で、薬の場所にならない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気での薬の選び方」は成り立たない。天気は場所を表さず、薬の選び方の場にならない。"}, {"text": "大根", "is_correct": false, "explanation": "「大根での薬の選び方」は不自然で意味が通らない。大根は野菜で、場所を表さない。"}], "explanations": {"病院": "「病院での薬の選び方」の「病院」。医療の場での薬の選び方という意味になり、自然に成り立つ。", "宿題": "「宿題での薬の選び方」は意味が通らない。宿題は学習の課題で、薬の場所にならない。", "天気": "「天気での薬の選び方」は成り立たない。天気は場所を表さず、薬の選び方の場にならない。", "大根": "「大根での薬の選び方」は不自然で意味が通らない。大根は野菜で、場所を表さない。"}, "sentence_index": 0, "correct_answer": "病院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この病院は昨日から風邪をひいています。", "explanation": "ここは〈病院〉の意味。病院は施設で、風邪をひくのは人なので、病院を人のように扱うのは誤り。"}, {"text": "友だちの誕生日パーティーを病院で開きました。", "explanation": "ここは〈病院〉の意味。病院は診療のための施設で、お祝いの会場の意味にはならない。お祝いの場所は〈会場〉などで言う。"}, {"text": "病院のコーチが、サッカーの練習を教えています。", "explanation": "ここは〈病院〉の意味。病院は医療機関で、スポーツを教える〈クラブ〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病院", "is_correct": true, "explanation": "「救急車で病院に運ばれました」の「病院」。救急車で搬送される先として自然に成り立つ。"}, {"text": "薬", "is_correct": false, "explanation": "「救急車で薬に運ばれました」は意味が通らない。薬は搬送先になる施設ではない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「救急車で鉛筆に運ばれました」は成り立たない。鉛筆は搬送先にならない。"}, {"text": "音", "is_correct": false, "explanation": "「救急車で音に運ばれました」は不自然で、搬送先の場所を表さない。"}], "explanations": {"病院": "「救急車で病院に運ばれました」の「病院」。救急車で搬送される先として自然に成り立つ。", "薬": "「救急車で薬に運ばれました」は意味が通らない。薬は搬送先になる施設ではない。", "鉛筆": "「救急車で鉛筆に運ばれました」は成り立たない。鉛筆は搬送先にならない。", "音": "「救急車で音に運ばれました」は不自然で、搬送先の場所を表さない。"}, "sentence_index": 6, "correct_answer": "病院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あしたは勉強をしに、病院へ行きます。", "explanation": "ここは〈病院〉の意味。病院は診療の施設で、学ぶ場所の意味にはならない。学ぶ場所は〈図書館〉などで言う。"}, {"text": "あしたは病院で銀行のお金を振り込みます。", "explanation": "ここは〈病院〉の意味。病院は医療機関で、金融の手続きを行う場所の意味にはならない。手続きは〈窓口〉などで行う。"}, {"text": "私の病院は祖母と一緒に暮らしています。", "explanation": "ここは〈病院〉の意味。病院は人が住む場所ではないので、暮らしの場の意味にはならない。住まいは〈家〉などで言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は足の骨を折って、病院を行きました。", "corrected_sentence": "祖父は足の骨を折って、病院に行きました。", "error_description": "「病院を行きました」の「を」が誤り。行く先を表すには「に」を使う。正しくは「病院に行きました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51436, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は昔、病院に掃除をしていました。", "corrected_sentence": "祖母は昔、病院で掃除をしていました。", "error_description": "「病院に掃除をしていました」の「に」が誤り。掃除をする場所を表すには「で」を使う。正しくは「病院で掃除をしていました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「薬の選び方」の「の」。薬と選び方を結び、薬の選び方という名詞句を作る。"}, {"text": "が", "is_correct": false, "explanation": "「薬が選び方」は主語の「が」だが、名詞同士の結びつきとして不自然。"}, {"text": "を", "is_correct": false, "explanation": "「薬を選び方」は目的語の「を」で、名詞句を作れない。"}, {"text": "に", "is_correct": false, "explanation": "「薬に選び方」は方向や対象の「に」で、名詞句を作れない。"}], "correct_answer": "の", "explanations": {"の": "「薬の選び方」の「の」。薬と選び方を結び、薬の選び方という名詞句を作る。", "が": "「薬が選び方」は主語の「が」だが、名詞同士の結びつきとして不自然。", "を": "「薬を選び方」は目的語の「を」で、名詞句を作れない。", "に": "「薬に選び方」は方向や対象の「に」で、名詞句を作れない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "場所・相手"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「薬を飲むのを忘れないでください」の「を」。飲む対象を示し、自然に成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "「薬と飲むのを忘れないでください」は並列の「と」で、飲む対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「薬へ飲むのを忘れないでください」は方向の「へ」で、飲む動作の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "「薬から飲むのを忘れないでください」は起点の「から」で、飲む対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「薬を飲むのを忘れないでください」の「を」。飲む対象を示し、自然に成り立つ。", "と": "「薬と飲むのを忘れないでください」は並列の「と」で、飲む対象を示せない。", "へ": "「薬へ飲むのを忘れないでください」は方向の「へ」で、飲む動作の対象にならない。", "から": "「薬から飲むのを忘れないでください」は起点の「から」で、飲む対象を示せない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気やけがを治すために使うもの。飲み薬や塗り薬などがある。", "primary_collocate": null, "pronunciation": "くすり", "ipa": "kɯsɯɾi", "syllable_count": 3, "sentences": [{"text": "病院での薬の選び方は、昔と今で違います。", "target_word": "薬", "complexity_tier": "T3", "furigana": "病院[びょういん]での薬[くすり]の選[えら]び方[かた]は、昔[むかし]と今[いま]で違[ちが]います。", "sentence_source": "mined"}, {"text": "昔はみんな同じ薬です。", "target_word": "薬", "complexity_tier": "T2", "furigana": "昔[むかし]はみんな同[おな]じ薬[くすり]です。", "sentence_source": "mined"}, {"text": "今は一人一人の体に合う薬です。", "target_word": "薬", "complexity_tier": "T3", "furigana": "今[いま]は一人一人[ひとりひとり]の体[からだ]に合[あ]う薬[くすり]です。", "sentence_source": "mined"}, {"text": "医者は体を調べて薬を決めます。", "target_word": "薬", "complexity_tier": "T3", "furigana": "医者[いしゃ]は体[からだ]を調[しら]べて薬[くすり]を決[き]めます。", "sentence_source": "mined"}, {"text": "熱が出たので、薬を飲んで早く寝ました。", "target_word": "薬", "complexity_tier": "T3", "furigana": "熱[ねつ]が出[で]たので、薬[くすり]を飲[の]んで早[はや]く寝[ね]ました。", "sentence_source": "generated"}, {"text": "子どもは苦い薬が嫌いで、なかなか飲みません。", "target_word": "薬", "complexity_tier": "T3", "furigana": "子[こ]どもは苦[にが]い薬[くすり]が嫌[きら]いで、なかなか飲[の]みません。", "sentence_source": "generated"}, {"text": "薬局で医者にもらった紙を見せて、薬を受け取りました。", "target_word": "薬", "complexity_tier": "T4", "furigana": "薬局[やっきょく]で医者[いしゃ]にもらった紙[かみ]を見[み]せて、薬[くすり]を受[う]け取[と]りました。", "sentence_source": "generated"}, {"text": "食事のあとに薬を飲むのを忘れないでください。", "target_word": "薬", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあとに薬[くすり]を飲[の]むのを忘[わす]れないでください。", "sentence_source": "generated"}, {"text": "足をけがしたので、毎朝薬を塗っています。", "target_word": "薬", "complexity_tier": "T3", "furigana": "足[あし]をけがしたので、毎朝[まいあさ]薬[くすり]を塗[ぬ]っています。", "sentence_source": "generated"}, {"text": "この薬は眠くなるので、運転の前には飲めません。", "target_word": "薬", "complexity_tier": "T4", "furigana": "この薬[くすり]は眠[ねむ]くなるので、運転[うんてん]の前[まえ]には飲[の]めません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "薬", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "病気やけがを治すための飲み薬・塗り薬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: けがし (Zipf 2.18)']::text[], 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "薬", "is_correct": true, "explanation": "「病院での薬の選び方」の「薬」。薬の選び方という意味になり、文として自然。"}, {"text": "手紙", "is_correct": false, "explanation": "「病院での手紙の選び方」は意味が通らない。手紙は薬の選び方の対象にならない。"}, {"text": "地図", "is_correct": false, "explanation": "「病院での地図の選び方」は不自然で、薬の文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「病院での鉛筆の選び方」は成り立たない。鉛筆は薬の選び方の対象ではない。"}], "explanations": {"薬": "「病院での薬の選び方」の「薬」。薬の選び方という意味になり、文として自然。", "手紙": "「病院での手紙の選び方」は意味が通らない。手紙は薬の選び方の対象にならない。", "地図": "「病院での地図の選び方」は不自然で、薬の文脈に合わない。", "鉛筆": "「病院での鉛筆の選び方」は成り立たない。鉛筆は薬の選び方の対象ではない。"}, "sentence_index": 0, "correct_answer": "薬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "薬が治るまで、一週間休みます。", "explanation": "ここは〈薬〉の意味。〈薬〉は病気を取り除く手段で、回復するのは〈病気〉の方。"}, {"text": "そばに薬を入れて食べます。", "explanation": "〈薬〉に香辛料の意味はない。「薬味」の略として使った誤用で、薬味は別の語。"}, {"text": "この薬は毎朝、野菜として食べています。", "explanation": "ここは〈薬〉の意味。薬は食品ではないので、〈食材〉として食べるものにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "薬", "is_correct": true, "explanation": "「薬を受け取りました」の「薬」。薬局で薬を受け取るという意味になり、自然に成り立つ。"}, {"text": "電車", "is_correct": false, "explanation": "「電車を受け取りました」は意味が通らない。電車は受け取る対象にならない。"}, {"text": "階段", "is_correct": false, "explanation": "「階段を受け取りました」は成り立たない。階段は受け取る物ではない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を受け取りました」は不自然。天気は受け取る対象にならない。"}], "explanations": {"薬": "「薬を受け取りました」の「薬」。薬局で薬を受け取るという意味になり、自然に成り立つ。", "電車": "「電車を受け取りました」は意味が通らない。電車は受け取る対象にならない。", "階段": "「階段を受け取りました」は成り立たない。階段は受け取る物ではない。", "天気": "「天気を受け取りました」は不自然。天気は受け取る対象にならない。"}, "sentence_index": 6, "correct_answer": "薬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬をつけて、ケーキを焼きました。", "explanation": "ここは〈薬〉の意味。薬は材料として料理に使うものではない。材料には〈砂糖〉などを使う。"}, {"text": "子どもは薬のおもちゃで遊ぶのが好きです。", "explanation": "ここは〈薬〉の意味。薬は遊び道具ではないので、遊ぶ道具の意味にはならない。遊び道具は〈人形〉などで言う。"}, {"text": "母はこの薬で、かぎを作りました。", "explanation": "ここは〈薬〉の意味。薬は物を作る材料にはならない。金属で作るものには〈鉄〉などを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱が出たので、薬が飲みました。", "corrected_sentence": "熱が出たので、薬を飲みました。", "error_description": "「薬が飲みました」の「が」が誤り。飲む対象は「を」で示す。正しくは「薬を飲みました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51438, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は毎晩、薬に飲んでから寝ます。", "corrected_sentence": "祖母は毎晩、薬を飲んでから寝ます。", "error_description": "「薬に飲んで」の「に」が誤り。飲む対象は「を」で示す。正しくは「薬を飲んでから」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「馬は」で馬を話題の主語として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、走る動作は目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や場所を示すが、ここでは主語の位置に入らず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、主語の位置に入ると文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「馬は」で馬を話題の主語として示す。正解。", "を": "「を」は目的語を示すが、走る動作は目的語を取らないので合わない。", "に": "「に」は方向や場所を示すが、ここでは主語の位置に入らず文が成り立たない。", "へ": "「へ」は方向を示すが、主語の位置に入ると文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「馬は」で、馬を外で立っている主語として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、立つ動作は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、主語の位置に入ると文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、馬を起点とする文は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「馬は」で、馬を外で立っている主語として示す。正解。", "を": "「を」は目的語を示すが、立つ動作は目的語を取らないので合わない。", "へ": "「へ」は方向を示すが、主語の位置に入ると文が成り立たない。", "から": "「から」は起点を示すが、馬を起点とする文は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "哺乳類の一種。ウマ科。体が大きく、たてがみと尾があり、人が乗ったり荷物を運んだりするのに使われる。", "primary_collocate": null, "pronunciation": "うま", "ipa": "ɯma", "syllable_count": 2, "sentences": [{"text": "ローマの子供は、木の馬のおもちゃで楽しい遊びをします。", "target_word": "馬", "complexity_tier": "T3", "furigana": "ローマの子供[こども]は、木[き]の馬[うま]のおもちゃで楽[たの]しい遊[あそ]びをします。", "sentence_source": "mined"}, {"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "馬", "complexity_tier": "T3", "furigana": "長[なが]い紐[ひも]を引[ひ]くと、馬[うま]は元気[げんき]に走[はし]ります。", "sentence_source": "mined"}, {"text": "牧場で白い馬が草を食べています。", "target_word": "馬", "complexity_tier": "T2", "furigana": "牧場[ぼくじょう]で白[しろ]い馬[うま]が草[くさ]を食[た]べています。", "sentence_source": "generated"}, {"text": "彼は毎週末、馬に乗る練習をしています。", "target_word": "馬", "complexity_tier": "T3", "furigana": "彼[かれ]は毎週末[まいしゅうまつ]、馬[うま]に乗[の]る練習[れんしゅう]をしています。", "sentence_source": "generated"}, {"text": "昔は、馬が荷物を運ぶ大切な仕事をしていました。", "target_word": "馬", "complexity_tier": "T3", "furigana": "昔[むかし]は、馬[うま]が荷物[にもつ]を運[はこ]ぶ大切[たいせつ]な仕事[しごと]をしていました。", "sentence_source": "generated"}, {"text": "馬は足が速いので、短い時間で遠くまで行けます。", "target_word": "馬", "complexity_tier": "T3", "furigana": "馬[うま]は足[あし]が速[はや]いので、短[みじか]い時間[じかん]で遠[とお]くまで行[い]けます。", "sentence_source": "generated"}, {"text": "子供のころ、祖父の馬にえさをやりました。", "target_word": "馬", "complexity_tier": "T3", "furigana": "子供[こども]のころ、祖父[そふ]の馬[うま]にえさをやりました。", "sentence_source": "generated"}, {"text": "雨の日でも、馬は外で静かに立っていました。", "target_word": "馬", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]でも、馬[うま]は外[そと]で静[しず]かに立[た]っていました。", "sentence_source": "generated"}, {"text": "この馬は人になれていて、おとなしいです。", "target_word": "馬", "complexity_tier": "T2", "furigana": "この馬[うま]は人[ひと]になれていて、おとなしいです。", "sentence_source": "generated"}, {"text": "馬のたてがみを、ブラシで丁寧にとかしました。", "target_word": "馬", "complexity_tier": "T4", "furigana": "馬[うま]のたてがみを、ブラシで丁寧[ていねい]にとかしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "馬", "label": "基本形"}], "register": "中立", "sense_fingerprint": "動物のウマ。人が乗ったり荷物を運んだりする大きな哺乳類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: たてがみ (Zipf 2.48)']::text[], '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石", "is_correct": false, "explanation": "木の石のおもちゃは材料として成り立たず、文が意味をなさない。"}, {"text": "馬", "is_correct": true, "explanation": "木で作った馬のおもちゃという意味になり、空欄に入る唯一の語。"}, {"text": "紙", "is_correct": false, "explanation": "木の紙のおもちゃは不自然で、木製の動物を表す語が必要な文脈に合わない。"}, {"text": "海", "is_correct": false, "explanation": "木の海のおもちゃは意味が通らない。"}], "explanations": {"石": "木の石のおもちゃは材料として成り立たず、文が意味をなさない。", "馬": "木で作った馬のおもちゃという意味になり、空欄に入る唯一の語。", "紙": "木の紙のおもちゃは不自然で、木製の動物を表す語が必要な文脈に合わない。", "海": "木の海のおもちゃは意味が通らない。"}, "sentence_index": 0, "correct_answer": "馬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牧場で、白い馬を三本数えました。", "explanation": "ここは〈頭〉で数える馬を〈本〉で数えた文。馬は一頭、二頭と数えるので、本では言わない。"}, {"text": "馬が喉をゴロゴロ鳴らして、甘えてきました。", "explanation": "ここは〈猫〉の鳴き方（喉をゴロゴロ鳴らす）の文。馬はいななくので、この言い方は合わない。"}, {"text": "駅まで、馬を運転して行きました。", "explanation": "ここは〈車〉の文。運転するのは車で、馬には乗る動作を使う。馬を運転するとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石", "is_correct": false, "explanation": "祖父の石にえさをやるという文は成り立たない。"}, {"text": "馬", "is_correct": true, "explanation": "えさをやる対象となる動物の馬で、空欄に入る唯一の語。"}, {"text": "雲", "is_correct": false, "explanation": "雲にえさをやるのは意味が通らない。"}, {"text": "鏡", "is_correct": false, "explanation": "鏡にえさをやるのは意味が通らない。"}], "explanations": {"石": "祖父の石にえさをやるという文は成り立たない。", "馬": "えさをやる対象となる動物の馬で、空欄に入る唯一の語。", "雲": "雲にえさをやるのは意味が通らない。", "鏡": "鏡にえさをやるのは意味が通らない。"}, "sentence_index": 6, "correct_answer": "馬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎週末、馬に乗車する練習をしています。", "explanation": "ここは〈乗車〉（電車・バスなどに乗り込むこと）の文。馬には〈乗る〉を使う。"}, {"text": "坂道で、馬を一生懸命こいで登りました。", "explanation": "ここは〈自転車〉の文。こぐのは自転車で、馬にはこの動詞を使わない。"}, {"text": "馬が屋根の上でさえずって、朝を告げました。", "explanation": "ここは鳥の鳴き方〈さえずる〉の文。馬はいななくので、この言い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎朝、馬に牧場へ連れていきます。", "corrected_sentence": "祖父は毎朝、馬を牧場へ連れていきます。", "error_description": "誤りは「馬に」。「連れていく」の対象は直接目的語なので「を」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は毎週、乗馬教室で馬を乗ります。", "corrected_sentence": "姉は毎週、乗馬教室で馬に乗ります。", "error_description": "誤りは「馬を乗ります」。「乗る」の対象は「に」で示すので、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「紐で」で手段を示し、紐を使ってしっかり結ぶ意味になる。正解。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、紐が結ぶ主体になると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や結果を示すが、ここでは結ぶ対象として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、結ぶ動作の対象にはならない。"}], "correct_answer": "で", "explanations": {"で": "「紐で」で手段を示し、紐を使ってしっかり結ぶ意味になる。正解。", "が": "「が」は主語を示すが、紐が結ぶ主体になると文が成り立たない。", "に": "「に」は相手や結果を示すが、ここでは結ぶ対象として合わない。", "へ": "「へ」は方向を示すが、結ぶ動作の対象にはならない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「紐を」で結ぶ対象を示す。正解。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、後ろに動詞「結ぶ」が続くと文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を示すが、ここには比べる内容がなく文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、紐を起点に結ぶという文にはならず、結ぶ対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「紐を」で結ぶ対象を示す。正解。", "の": "「の」は名詞どうしをつなぐ助詞で、後ろに動詞「結ぶ」が続くと文が成り立たない。", "より": "「より」は比べる基準を示すが、ここには比べる内容がなく文が成り立たない。", "から": "「から」は起点を示すが、紐を起点に結ぶという文にはならず、結ぶ対象を示せない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を結んだり引っ張ったりするための細長いもの。", "primary_collocate": null, "pronunciation": "ひも", "ipa": "çimo", "syllable_count": 2, "sentences": [{"text": "長い紐を引くと、馬は元気に走ります。", "target_word": "紐", "complexity_tier": "T3", "furigana": "長[なが]い紐[ひも]を引[ひ]くと、馬[うま]は元気[げんき]に走[はし]ります。", "sentence_source": "mined"}, {"text": "荷物が落ちないように、紐でしっかり結びました。", "target_word": "紐", "complexity_tier": "T3", "furigana": "荷物[にもつ]が落[お]ちないように、紐[ひも]でしっかり結[むす]びました。", "sentence_source": "generated"}, {"text": "靴の紐がほどけたので、道のはしで結びなおしました。", "target_word": "紐", "complexity_tier": "T3", "furigana": "靴[くつ]の紐[ひも]がほどけたので、道[みち]のはしで結[むす]びなおしました。", "sentence_source": "generated"}, {"text": "この箱は紐がないと、運ぶときに開いてしまいます。", "target_word": "紐", "complexity_tier": "T3", "furigana": "この箱[はこ]は紐[ひも]がないと、運[はこ]ぶときに開[ひら]いてしまいます。", "sentence_source": "generated"}, {"text": "母は古い紐を切って、新しい紐に取りかえました。", "target_word": "紐", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]い紐[ひも]を切[き]って、新[あたら]しい紐[ひも]に取[と]りかえました。", "sentence_source": "generated"}, {"text": "紐が短すぎて、本の束を結べませんでした。", "target_word": "紐", "complexity_tier": "T3", "furigana": "紐[ひも]が短[みじか]すぎて、本[ほん]の束[たば]を結[むす]べませんでした。", "sentence_source": "generated"}, {"text": "犬が走り出して、手から紐が抜けてしまいました。", "target_word": "紐", "complexity_tier": "T3", "furigana": "犬[いぬ]が走[はし]り出[だ]して、手[て]から紐[ひも]が抜[ぬ]けてしまいました。", "sentence_source": "generated"}, {"text": "帽子の紐をあごの下で結ぶと、風でも飛びません。", "target_word": "紐", "complexity_tier": "T4", "furigana": "帽子[ぼうし]の紐[ひも]をあごの下[した]で結[むす]ぶと、風[かぜ]でも飛[と]びません。", "sentence_source": "generated"}, {"text": "細い紐では重い箱を持ち上げられません。", "target_word": "紐", "complexity_tier": "T3", "furigana": "細[ほそ]い紐[ひも]では重[おも]い箱[はこ]を持[も]ち上[あ]げられません。", "sentence_source": "generated"}, {"text": "引き出しの中に、色のきれいな紐が何本も入っていました。", "target_word": "紐", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しの中[なか]に、色[いろ]のきれいな紐[ひも]が何本[なんぼん]も入[はい]っていました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "紐", "label": "基本形"}], "register": "中立", "sense_fingerprint": "結ぶ・縛る・引っ張るために使う細長い糸状のもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: 取りかえ (Zipf 1.48)']::text[], '8a4b8cef-ab8c-4182-8873-0e78b475e8bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紐", "is_correct": true, "explanation": "長い紐を引くという文脈に合う唯一の語。"}, {"text": "花", "is_correct": false, "explanation": "長い花を引く、という動作は成り立たない。"}, {"text": "鍋", "is_correct": false, "explanation": "長い鍋を引くという文は不自然で、意味が通らない。"}, {"text": "窓", "is_correct": false, "explanation": "長い窓を引くという動作は文脈に合わない。"}], "explanations": {"紐": "長い紐を引くという文脈に合う唯一の語。", "花": "長い花を引く、という動作は成り立たない。", "鍋": "長い鍋を引くという文は不自然で、意味が通らない。", "窓": "長い窓を引くという動作は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "紐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紐をコンセントに差し込んで、ドライヤーを使いました。", "explanation": "ここは〈コード〉（電気の線）の文。電源につなぐのはコードで、紐は差し込めない。"}, {"text": "強風で紐が切れて、町中が停電しました。", "explanation": "ここは〈電線〉の文。停電の原因は電線が切れることで、紐では言わない。"}, {"text": "文房具店で、紐を三枚買いました。", "explanation": "ここは紐を〈枚〉で数えた文。紐は〈本〉で数えるので、この言い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紐", "is_correct": true, "explanation": "手から抜けてしまう細長いものとして、空欄に入る唯一の語。"}, {"text": "空", "is_correct": false, "explanation": "手から空が抜けるという表現は成り立たない。"}, {"text": "雲", "is_correct": false, "explanation": "手から雲が抜けるという表現は意味が通らない。"}, {"text": "影", "is_correct": false, "explanation": "手から影が抜けるという表現は意味が通らない。"}], "explanations": {"紐": "手から抜けてしまう細長いものとして、空欄に入る唯一の語。", "空": "手から空が抜けるという表現は成り立たない。", "雲": "手から雲が抜けるという表現は意味が通らない。", "影": "手から影が抜けるという表現は意味が通らない。"}, "sentence_index": 6, "correct_answer": "紐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いハンガーを紐で曲げて、洗濯物を干しました。", "explanation": "ここは〈針金〉の文。ハンガーを曲げるのは針金で、紐では曲がらない。"}, {"text": "体育館で紐引きをして、チームに分かれました。", "explanation": "ここは〈綱引き〉の〈綱〉の文。綱引きは綱で、紐では言わない。"}, {"text": "庭の紐で水をまきました。", "explanation": "ここは〈ホース〉の文。水をまくのに使うのはホースで、紐では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小包を紐を縛って、郵便局へ持っていきました。", "corrected_sentence": "小包を紐で縛って、郵便局へ持っていきました。", "error_description": "誤りは「紐を」。紐で縛るときの手段は「で」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ふろしきの紐にほどいて、中の本を出しました。", "corrected_sentence": "ふろしきの紐をほどいて、中の本を出しました。", "error_description": "誤りは「紐に」。ほどく対象は「を」で示すので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58c5ee3d-3c58-46da-bb5e-8220fd724acc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ここは主題を示す〈は〉。『この城壁は』と話題を立てて、後ろで高さを説明する形になる。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すが、『この城壁を高さが十メートル』では文が成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は帰着点などを示すが、『この城壁に高さが』では意味が通らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は場所や手段を示すが、『この城壁で高さが』では説明の文として成り立たないので合わない。"}], "correct_answer": "は", "explanations": {"は": "ここは主題を示す〈は〉。『この城壁は』と話題を立てて、後ろで高さを説明する形になる。", "を": "〈を〉は目的語を示すが、『この城壁を高さが十メートル』では文が成り立たないので合わない。", "に": "〈に〉は帰着点などを示すが、『この城壁に高さが』では意味が通らないので合わない。", "で": "〈で〉は場所や手段を示すが、『この城壁で高さが』では説明の文として成り立たないので合わない。"}, "error_tags": {"を": "目的格", "に": "帰着の格", "で": "場所・手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "ここは主題を示す〈は〉。『城壁は』と話題を立てて、石を積んで作られた様子を述べる形になる。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列を示すが、『城壁と石を積み上げて作られている』では城壁と石が並ぶ形になり、主語が合わないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示すが、『城壁より石を積み上げて』では比べる対象がなく、文が成り立たないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すが、『城壁から石を積み上げて』では城壁が作る主体になり、主語『城壁は』と噛み合わないので合わない。"}], "correct_answer": "は", "explanations": {"は": "ここは主題を示す〈は〉。『城壁は』と話題を立てて、石を積んで作られた様子を述べる形になる。", "と": "〈と〉は並列を示すが、『城壁と石を積み上げて作られている』では城壁と石が並ぶ形になり、主語が合わないので合わない。", "より": "〈より〉は比較を示すが、『城壁より石を積み上げて』では比べる対象がなく、文が成り立たないので合わない。", "から": "〈から〉は起点を示すが、『城壁から石を積み上げて』では城壁が作る主体になり、主語『城壁は』と噛み合わないので合わない。"}, "error_tags": {"と": "並列の格", "より": "比較の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "城のまわりの高いかべ。", "primary_collocate": null, "pronunciation": "じょうへき", "ipa": "dʑoːheki", "syllable_count": 4, "sentences": [{"text": "古い城壁の上を歩いて、町を見下ろした。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "古[ふる]い城壁[じょうへき]の上[うえ]を歩[ある]いて、町[まち]を見下[みお]ろした。", "sentence_source": "generated"}, {"text": "この城壁は高さが十メートルもあり、敵が入れなかった。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "この城壁[じょうへき]は高[たか]さが十[じゅう]メートルもあり、敵[てき]が入[はい]れなかった。", "sentence_source": "generated"}, {"text": "城壁のまわりには深い堀がある。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "城壁[じょうへき]のまわりには深[ふか]い堀[ほり]がある。", "sentence_source": "generated"}, {"text": "地震で城壁の一部がくずれてしまった。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "地震[じしん]で城壁[じょうへき]の一部[いちぶ]がくずれてしまった。", "sentence_source": "generated"}, {"text": "昔の人は、町を守るために城壁を築いた。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、町[まち]を守[まも]るために城壁[じょうへき]を築[きず]いた。", "sentence_source": "generated"}, {"text": "城壁に登ると、遠くの山まで見える。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "城壁[じょうへき]に登[のぼ]ると、遠[とお]くの山[やま]まで見[み]える。", "sentence_source": "generated"}, {"text": "観光客が城壁の前で写真を撮っている。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が城壁[じょうへき]の前[まえ]で写真[しゃしん]を撮[と]っている。", "sentence_source": "generated"}, {"text": "城壁は石を積み上げて作られている。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "城壁[じょうへき]は石[いし]を積[つ]み上[あ]げて作[つく]られている。", "sentence_source": "generated"}, {"text": "夜になると、城壁が明かりで照らされる。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "夜[よる]になると、城壁[じょうへき]が明[あ]かりで照[て]らされる。", "sentence_source": "generated"}, {"text": "兵士たちは城壁の上から敵を見張っていた。", "target_word": "城壁", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは城壁[じょうへき]の上[うえ]から敵[てき]を見張[みは]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "城壁", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "城や町を守るためにまわりに築いた高い石の壁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城壁", "is_correct": true, "explanation": "ここに入るのは〈城壁〉。城や町を囲む高い壁で、その上を歩いて町を見下ろせる。"}, {"text": "堀", "is_correct": false, "explanation": "〈堀〉は城の周りに掘った水路で、その上を歩くことはできないので合わない。"}, {"text": "池", "is_correct": false, "explanation": "〈池〉は水をためたくぼみで、その上を歩いて町を見下ろすことはできないので合わない。"}, {"text": "屋台", "is_correct": false, "explanation": "〈屋台〉は食べ物を売る移動式の店で、その上を歩く対象にはならないので合わない。"}], "explanations": {"城壁": "ここに入るのは〈城壁〉。城や町を囲む高い壁で、その上を歩いて町を見下ろせる。", "堀": "〈堀〉は城の周りに掘った水路で、その上を歩くことはできないので合わない。", "池": "〈池〉は水をためたくぼみで、その上を歩いて町を見下ろすことはできないので合わない。", "屋台": "〈屋台〉は食べ物を売る移動式の店で、その上を歩く対象にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "城壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城壁は夜になると閉じられ、人の出入りを止める。", "explanation": "ここは〈城門〉の意味。城壁は開け閉めする戸のない壁なので、閉じて出入りを止めるのは城門の役割で、城壁には合わない。"}, {"text": "城壁は城の中で最も高い建物で、殿様が暮らしていた。", "explanation": "ここは〈天守〉の意味。殿様が住んだ建物は天守で、城壁は外周を囲む壁なので合わない。"}, {"text": "城壁は水を引き込んで、敵が渡れないようにした。", "explanation": "ここは〈堀〉の意味。水を引いて敵の渡河を防ぐのは堀で、城壁は水を引かないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城壁", "is_correct": true, "explanation": "ここに入るのは〈城壁〉。観光客が城壁の前で写真を撮るのは自然な場面。"}, {"text": "切符", "is_correct": false, "explanation": "〈切符〉は乗車などに使う券で、写真を撮る対象の場所にはならないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "〈天気〉は空模様のことで、写真を撮る場所を表さないので合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "〈教科書〉は学習用の本で、観光地の前で写真を撮る対象にはならないので合わない。"}], "explanations": {"城壁": "ここに入るのは〈城壁〉。観光客が城壁の前で写真を撮るのは自然な場面。", "切符": "〈切符〉は乗車などに使う券で、写真を撮る対象の場所にはならないので合わない。", "天気": "〈天気〉は空模様のことで、写真を撮る場所を表さないので合わない。", "教科書": "〈教科書〉は学習用の本で、観光地の前で写真を撮る対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "城壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "城壁は城の中心にあって、殿様が政治を行った場所だ。", "explanation": "ここは〈本丸〉の意味。城の中心で政治を行う場所は本丸で、城壁は外周の壁なので合わない。"}, {"text": "城壁は屋根のある小屋の形をしていて、中から敵の動きを見張った。", "explanation": "ここは〈櫓〉の意味。屋根のある見張りの建物は櫓で、城壁は小屋ではなく壁なので合わない。"}, {"text": "城壁は、畑に水を引くための細長い溝で、農家が使った。", "explanation": "ここは〈用水路〉の意味。畑に水を引く溝で、敵を防ぐ壁の城壁とは合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高い城壁を上を歩いて、海を見下ろした。", "corrected_sentence": "高い城壁の上を歩いて、海を見下ろした。", "error_description": "『城壁の上』が正しい。『城壁』と『上』をつなぐには『の』が必要で、『を』を使うと『城壁を』と目的語が重なり、場所を示せないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高い城壁に、夕日を眺めた。", "corrected_sentence": "高い城壁で、夕日を眺めた。", "error_description": "『城壁で』が正しい。眺めた場所は『で』で示す。『に』は到達点を示すので、眺めるという動作の場所としては誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「番が回ってくる」の主語を表す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「番を回ってきた」では文の関係が成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」で、「番で回ってきた」は意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」だが、番が回ってくる文には使えない。"}], "correct_answer": "が", "explanations": {"が": "「番が回ってくる」の主語を表す「が」。", "を": "「番を回ってきた」では文の関係が成り立たず、不自然。", "で": "手段や場所を表す「で」で、「番で回ってきた」は意味が合わない。", "へ": "方向を表す「へ」だが、番が回ってくる文には使えない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "順序や順番を表す語。特に、何かをする順番や、順番に割り当てられた役割を指す。", "primary_collocate": null, "pronunciation": "ばん", "ipa": "baɴ", "syllable_count": 2, "sentences": [{"text": "「主権」は私の番です。", "target_word": "番", "complexity_tier": "T3", "furigana": "「主権[しゅけん]」は私[わたし]の番[ばん]です。", "sentence_source": "mined"}, {"text": "次は田中さんの番ですから、ここで待っていてください。", "target_word": "番", "complexity_tier": "T3", "furigana": "次[つぎ]は田中[たなか]さんの番[ばん]ですから、ここで待[ま]っていてください。", "sentence_source": "generated"}, {"text": "ゲームで自分の番が来るまで、静かに待ちました。", "target_word": "番", "complexity_tier": "T3", "furigana": "ゲームで自分[じぶん]の番[ばん]が来[く]るまで、静[しず]かに待[ま]ちました。", "sentence_source": "generated"}, {"text": "今日は私が夕食を作る番なので、早く帰ります。", "target_word": "番", "complexity_tier": "T3", "furigana": "今日[きょう]は私[わたし]が夕食[ゆうしょく]を作[つく]る番[ばん]なので、早[はや]く帰[かえ]ります。", "sentence_source": "generated"}, {"text": "トランプで弟の番になると、みんなが笑い出しました。", "target_word": "番", "complexity_tier": "T3", "furigana": "トランプで弟[おとうと]の番[ばん]になると、みんなが笑[わら]い出[だ]しました。", "sentence_source": "generated"}, {"text": "病院で名前を呼ばれて、やっと私の番が来ました。", "target_word": "番", "complexity_tier": "T3", "furigana": "病院[びょういん]で名前[なまえ]を呼[よ]ばれて、やっと私[わたし]の番[ばん]が来[き]ました。", "sentence_source": "generated"}, {"text": "掃除の番を忘れて、先生に注意されました。", "target_word": "番", "complexity_tier": "T3", "furigana": "掃除[そうじ]の番[ばん]を忘[わす]れて、先生[せんせい]に注意[ちゅうい]されました。", "sentence_source": "generated"}, {"text": "質問する番が回ってきたとき、頭が真っ白になりました。", "target_word": "番", "complexity_tier": "T3", "furigana": "質問[しつもん]する番[ばん]が回[まわ]ってきたとき、頭[あたま]が真[ま]っ白[しろ]になりました。", "sentence_source": "generated"}, {"text": "「今度は君の番ですよ」と友達がサイコロを渡してくれました。", "target_word": "番", "complexity_tier": "T3", "furigana": "「今度[こんど]は君[きみ]の番[ばん]ですよ」と友達[ともだち]がサイコロを渡[わた]してくれました。", "sentence_source": "generated"}, {"text": "先週は兄が皿を洗ったので、今週は私の番です。", "target_word": "番", "complexity_tier": "T3", "furigana": "先週[せんしゅう]は兄[あに]が皿[さら]を洗[あら]ったので、今週[こんしゅう]は私[わたし]の番[ばん]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "番", "label": "基本形"}], "register": "polite", "sense_fingerprint": "順番・役割が回ってくる「番」(turn)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "空欄には「順番」の番が入り、「私の番」（私の順番）として文が通る。"}, {"text": "海", "is_correct": false, "explanation": "「私の海」では意味が通らず、順番を表す文に入らない。"}, {"text": "霧", "is_correct": false, "explanation": "「私の霧」は不自然で、順番の文脈に合わない。"}, {"text": "雷", "is_correct": false, "explanation": "「私の雷」は意味をなさず、順番を表せない。"}], "explanations": {"番": "空欄には「順番」の番が入り、「私の番」（私の順番）として文が通る。", "海": "「私の海」では意味が通らず、順番を表す文に入らない。", "霧": "「私の霧」は不自然で、順番の文脈に合わない。", "雷": "「私の雷」は意味をなさず、順番を表せない。"}, "sentence_index": 0, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美術館の番に沿って、絵を一つずつ見ていきました。", "explanation": "ここは〈順路〉の意味。決まった道筋に沿って進む順路の語で、番を道順の代わりに使うのは合わない。"}, {"text": "一列に並んで、番に部屋へ入ってください。", "explanation": "ここは〈順に〉の副詞の意味。番は名詞なので、順に入るという副詞の使い方では合わない。"}, {"text": "一生に一度の番に恵まれて、夢が叶いました。", "explanation": "ここは〈機会〉の意味。番は順番や役割を表し、機会の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "番", "is_correct": true, "explanation": "空欄には「順番」の番が入り、「掃除の番」として文が通る。"}, {"text": "雪", "is_correct": false, "explanation": "「掃除の雪」は意味をなさず、文に入らない。"}, {"text": "波", "is_correct": false, "explanation": "「掃除の波」は不自然で、掃除の当番を表せない。"}, {"text": "星", "is_correct": false, "explanation": "「掃除の星」は意味が通らず、当番の文脈に合わない。"}], "explanations": {"番": "空欄には「順番」の番が入り、「掃除の番」として文が通る。", "雪": "「掃除の雪」は意味をなさず、文に入らない。", "波": "「掃除の波」は不自然で、掃除の当番を表せない。", "星": "「掃除の星」は意味が通らず、当番の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "番"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空いた番に座ってください。", "explanation": "ここは〈席〉の意味。番は順番や役割で、座る場所の意味では使わない。"}, {"text": "この家は三丁目の番にあります。", "explanation": "ここは〈番地〉の意味。住所の番号を表す場面で番だけでは言わない。"}, {"text": "番を閉めて、家に帰りました。", "explanation": "ここは〈店〉の意味。店は閉めるものだが、番は閉められないので、店の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゲームで私の番を来て、みんなが待っています。", "corrected_sentence": "ゲームで私の番が来て、みんなが待っています。", "error_description": "「番が来る」の主語を表す「が」を「を」にしている。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51452, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ようやく自分の番が回ってこました。", "corrected_sentence": "ようやく自分の番が回ってきました。", "error_description": "「回ってくる」の過去形「きました」を「こました」と誤用している。正しくは「きました」（来る）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「もらったバッジ」を「つける」の対象を示す「を」で、バッジに直接つく格助詞。"}, {"text": "に", "is_correct": false, "explanation": "「バッジに」とすると「つける」の場所や相手を表すことになり、ここでは対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「バッジで」は道具として使う意味になり、つける対象のバッジには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、バッジは方向ではなくつける物なので合わない。"}], "correct_answer": "を", "explanations": {"を": "「もらったバッジ」を「つける」の対象を示す「を」で、バッジに直接つく格助詞。", "に": "「バッジに」とすると「つける」の場所や相手を表すことになり、ここでは対象を示せない。", "で": "「バッジで」は道具として使う意味になり、つける対象のバッジには合わない。", "へ": "「へ」は方向を示すが、バッジは方向ではなくつける物なので合わない。"}, "error_tags": {"に": "場所", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「なくす」の対象を示す「を」で、バッジに直接つく格助詞。"}, {"text": "から", "is_correct": false, "explanation": "「バッジから」では起点を示すことになり、「なくす」の対象にならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「バッジと」では並列になり、「なくして」の対象として文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「バッジより なくして」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「なくす」の対象を示す「を」で、バッジに直接つく格助詞。", "から": "「バッジから」では起点を示すことになり、「なくす」の対象にならないので合わない。", "と": "「バッジと」では並列になり、「なくして」の対象として文が成り立たない。", "より": "「より」は比較を示すので、「バッジより なくして」は意味が通らない。"}, "error_tags": {"から": "起点", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゲームやくらぶなどで、がんばったしるしにもらえる、かざりです。", "primary_collocate": null, "pronunciation": "ばっじ", "ipa": "baddʑi", "syllable_count": 3, "sentences": [{"text": "ゲームでクリアすると、新しいバッジがもらえます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "ゲームでクリアすると、新[あたら]しいバッジがもらえます。", "sentence_source": "generated"}, {"text": "弟はクラブでもらったバッジを、かばんにつけています。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "弟[おとうと]はクラブでもらったバッジを、かばんにつけています。", "sentence_source": "generated"}, {"text": "毎日がんばったので、画面にバッジが三つ増えました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "毎日[まいにち]がんばったので、画面[がめん]にバッジが三[みっ]つ増[ふ]えました。", "sentence_source": "generated"}, {"text": "水泳教室で、泳げた記念に赤いバッジをもらいました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "水泳教室[すいえいきょうしつ]で、泳[およ]げた記念[きねん]に赤[あか]いバッジをもらいました。", "sentence_source": "generated"}, {"text": "バッジを集めるのが楽しくて、毎日アプリを開いています。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "バッジを集[あつ]めるのが楽[たの]しくて、毎日[まいにち]アプリを開[ひら]いています。", "sentence_source": "generated"}, {"text": "友達とおそろいのバッジをつけて、学校へ行きました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "友達[ともだち]とおそろいのバッジをつけて、学校[がっこう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "このゲームでは、むずかしい問題をクリアすると、特別なバッジが出ます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "このゲームでは、むずかしい問題[もんだい]をクリアすると、特別[とくべつ]なバッジが出[で]ます。", "sentence_source": "generated"}, {"text": "妹は、クラブのバッジをなくして、泣いてしまいました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "妹[いもうと]は、クラブのバッジをなくして、泣[な]いてしまいました。", "sentence_source": "generated"}, {"text": "読書クラブでは、本を十冊読むとバッジをもらえます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "読書[どくしょ]クラブでは、本[ほん]を十冊[じゅっさつ]読[よ]むとバッジをもらえます。", "sentence_source": "generated"}, {"text": "先生がバッジをくれたので、うれしくて母に見せました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "先生[せんせい]がバッジをくれたので、うれしくて母[はは]に見[み]せました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バッジ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "ゲームやクラブでもらえるがんばったしるしのかざり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バッジ", "is_correct": true, "explanation": "ゲームの達成に対して「もらえる」しるしの品なので、ここに合う。"}, {"text": "天気", "is_correct": false, "explanation": "「新しい天気がもらえます」は意味が通らない。天気は受け取る物ではない。"}, {"text": "台所", "is_correct": false, "explanation": "「新しい台所がもらえます」はゲームの報酬として成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空の色を指す夕焼けは、もらえるものではないので合わない。"}], "explanations": {"バッジ": "ゲームの達成に対して「もらえる」しるしの品なので、ここに合う。", "天気": "「新しい天気がもらえます」は意味が通らない。天気は受け取る物ではない。", "台所": "「新しい台所がもらえます」はゲームの報酬として成り立たない。", "夕焼け": "空の色を指す夕焼けは、もらえるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "バッジ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レジで商品のバッジを読み取った。", "explanation": "ここは〈バーコード〉の意味。レジで読み取る印の模様はバーコードで、バッジは読み取るための印ではないので合わない。"}, {"text": "旅行に着替えを入れる大きなバッジを買った。", "explanation": "ここは〈バッグ〉の意味。物を入れて持ち運ぶのはバッグで、バッジは身につける飾りなので合わない。"}, {"text": "瓶にバッジを貼って、中身の名前を書いた。", "explanation": "ここは〈ラベル〉の意味。中身を書いて貼る札はラベルで、バッジは書くための面がなく合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バッジ", "is_correct": true, "explanation": "ゲームで問題をクリアした報酬として出てくる品なので、「特別なバッジが出ます」に合う。"}, {"text": "午後", "is_correct": false, "explanation": "「特別な午後が出ます」は時間が出てくるという意味になり、合わない。"}, {"text": "交差点", "is_correct": false, "explanation": "「特別な交差点が出ます」はゲームの報酬として意味が通らない。"}, {"text": "家計", "is_correct": false, "explanation": "家計は家庭の収支のことで、ゲーム中に出てくるものではないので合わない。"}], "explanations": {"バッジ": "ゲームで問題をクリアした報酬として出てくる品なので、「特別なバッジが出ます」に合う。", "午後": "「特別な午後が出ます」は時間が出てくるという意味になり、合わない。", "交差点": "「特別な交差点が出ます」はゲームの報酬として意味が通らない。", "家計": "家計は家庭の収支のことで、ゲーム中に出てくるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "バッジ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スマホのバッジが切れたので、充電した。", "explanation": "ここは〈バッテリー〉の意味。電気をためる装置が切れるのはバッテリーで、バッジは身につける飾りなので合わない。"}, {"text": "汗をバッジでふいた。", "explanation": "ここは〈ハンカチ〉の意味。汗をふく道具はハンカチで、バッジは汗をふくものではないので合わない。"}, {"text": "バッジを強くけって、ゴールに入れた。", "explanation": "ここは〈ボール〉の意味。けって遊ぶ球はボールで、バッジはけることができないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "努力の証しとして、バッジにもらいました。", "corrected_sentence": "努力の証しとして、バッジをもらいました。", "error_description": "正しくは「バッジを（もらう）」。「もらう」の対象を表す「を」を「に」に誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51453, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゲームで百回勝ったので、新しいバッジを着ました。", "corrected_sentence": "ゲームで百回勝ったので、新しいバッジをつけました。", "error_description": "正しくは「バッジをつける」。「着る」は服などに使う動詞で、バッジには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「バッジが渡されます」の主語を表す「が」。"}, {"text": "の", "is_correct": false, "explanation": "「金色のバッジの渡されます」は文が成り立たず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「バッジと渡されます」は文の関係が合わず、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「バッジに渡されます」は受け手の関係が不自然で、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「バッジが渡されます」の主語を表す「が」。", "の": "「金色のバッジの渡されます」は文が成り立たず、不自然。", "と": "「バッジと渡されます」は文の関係が合わず、意味が通らない。", "に": "「バッジに渡されます」は受け手の関係が不自然で、文が成り立たない。"}, "error_tags": {"が": "主語", "の": "所属", "と": "相手", "に": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このバッジは」の主題を表す「は」。"}, {"text": "の", "is_correct": false, "explanation": "「このバッジのもらえます」は文が成り立たず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「このバッジへもらえます」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」で、「このバッジからもらえます」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「このバッジは」の主題を表す「は」。", "の": "「このバッジのもらえます」は文が成り立たず、不自然。", "へ": "方向を表す「へ」で、「このバッジへもらえます」は文が成り立たない。", "から": "起点を表す「から」で、「このバッジからもらえます」は意味が通らない。"}, "error_tags": {"は": "主題", "の": "所属", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あることを成し遂げた証として与えられる、小さな記章や印。", "primary_collocate": null, "pronunciation": "ばっじ", "ipa": "baddʑi", "syllable_count": 3, "sentences": [{"text": "「安全運転」のバッジをつけます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "「安全運転[あんぜんうんてん]」のバッジをつけます。", "sentence_source": "generated"}, {"text": "試験に合格した人には、金色のバッジが渡されます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "試験[しけん]に合格[ごうかく]した人[ひと]には、金色[きんいろ]のバッジが渡[わた]されます。", "sentence_source": "generated"}, {"text": "彼は消防士のバッジを胸につけて、誇らしそうに歩いていました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "彼[かれ]は消防士[しょうぼうし]のバッジを胸[むね]につけて、誇[ほこ]らしそうに歩[ある]いていました。", "sentence_source": "generated"}, {"text": "長年の功績が認められ、会社から記念のバッジをもらいました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "長年[ながねん]の功績[こうせき]が認[みと]められ、会社[かいしゃ]から記念[きねん]のバッジをもらいました。", "sentence_source": "generated"}, {"text": "十年間無事故で運転したので、会社からバッジを受け取りました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "十年間[じゅうねんかん]無事故[むじこ]で運転[うんてん]したので、会社[かいしゃ]からバッジを受[う]け取[と]りました。", "sentence_source": "generated"}, {"text": "頂上に着いた証として、バッジをもらいました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "頂上[ちょうじょう]に着[つ]いた証[あかし]として、バッジをもらいました。", "sentence_source": "generated"}, {"text": "優勝したチームの選手たちは、全員バッジを胸につけて表彰式に出ました。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]したチームの選手[せんしゅ]たちは、全員[ぜんいん]バッジを胸[むね]につけて表彰式[ひょうしょうしき]に出[で]ました。", "sentence_source": "generated"}, {"text": "このバッジは、ボランティアを百時間続けた人だけがもらえます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "このバッジは、ボランティアを百時間[ひゃくじかん]続[つづ]けた人[ひと]だけがもらえます。", "sentence_source": "generated"}, {"text": "入学式で、新入生は学校のバッジを制服につけます。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "入学式[にゅうがくしき]で、新入生[しんにゅうせい]は学校[がっこう]のバッジを制服[せいふく]につけます。", "sentence_source": "generated"}, {"text": "小さなバッジですが、三年間努力した証なので、大切にしています。", "target_word": "バッジ", "complexity_tier": "T3", "furigana": "小[ちい]さなバッジですが、三年間[さんねんかん]努力[どりょく]した証[あかし]なので、大切[たいせつ]にしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "バッジ", "label": "基本形"}], "register": "polite", "sense_fingerprint": "成果や身分の証としての記章バッジ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 誇らし (Zipf 1.79)']::text[], '3dad2fff-697e-44cf-a119-02d31c5b4414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "バッジ", "is_correct": true, "explanation": "空欄にはバッジが入り、「安全運転」のバッジをつけるという文になる。"}, {"text": "雨", "is_correct": false, "explanation": "「雨をつけます」は意味が通らず、バッジの文脈に合わない。"}, {"text": "霧", "is_correct": false, "explanation": "「霧をつけます」は不自然で、身につける物として成り立たない。"}, {"text": "雷", "is_correct": false, "explanation": "「雷をつけます」は意味をなさず、文に入らない。"}], "explanations": {"バッジ": "空欄にはバッジが入り、「安全運転」のバッジをつけるという文になる。", "雨": "「雨をつけます」は意味が通らず、バッジの文脈に合わない。", "霧": "「霧をつけます」は不自然で、身につける物として成り立たない。", "雷": "「雷をつけます」は意味をなさず、文に入らない。"}, "sentence_index": 0, "correct_answer": "バッジ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "契約書にバッジを押して、契約しました。", "explanation": "ここは〈印鑑〉の意味。契約書に押すのは印鑑で、バッジは押す物ではない。"}, {"text": "一晩中バッジを読んで、感想を書きました。", "explanation": "ここは〈本〉の意味。読むのは本で、バッジは読めないので合わない。"}, {"text": "バッジを開けて部屋に入りました。", "explanation": "ここは〈鍵〉の意味。鍵は開けるものだが、バッジは開けられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "バッジ", "is_correct": true, "explanation": "空欄にはバッジが入り、胸につけて表彰式に出るという文になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖を胸につけて」は意味をなさず、表彰式の文に合わない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓を胸につけて」は身につける物として成り立たない。"}, {"text": "鏡", "is_correct": false, "explanation": "「鏡を胸につけて」は不自然で、表彰式の文脈に合わない。"}], "explanations": {"バッジ": "空欄にはバッジが入り、胸につけて表彰式に出るという文になる。", "砂糖": "「砂糖を胸につけて」は意味をなさず、表彰式の文に合わない。", "窓": "「窓を胸につけて」は身につける物として成り立たない。", "鏡": "「鏡を胸につけて」は不自然で、表彰式の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "バッジ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強い日差しを避けるため、バッジを差して外に出ました。", "explanation": "ここは〈傘〉の意味。傘は差すものだが、バッジは差せないので合わない。"}, {"text": "熱が出たので、バッジを飲みました。", "explanation": "ここは〈薬〉の意味。薬は飲むものだが、バッジは飲めないので合わない。"}, {"text": "郵便局でバッジを投函しました。", "explanation": "ここは〈手紙〉の意味。投函するのは手紙で、バッジは投函できないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "記念日に、友達がバッジに渡してくれました。", "corrected_sentence": "記念日に、友達がバッジを渡してくれました。", "error_description": "「バッジを渡す」の目的語を表す「を」を「に」にしている。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51454, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このバッジは、努力した人だけがもらえるます。", "corrected_sentence": "このバッジは、努力した人だけがもらえます。", "error_description": "「もらえます」を「もらえるます」と誤用している。正しくは「もらえます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3098aba-6f6f-4241-b083-88432432dfb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「担当する」の対象を示す「を」で、「外交を担当する」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「外交に担当する」は方向の「に」で、「担当する」の対象にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」で、「外交から担当する」は対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」で、「外交と担当する」は「担当する」と結びつかない。"}], "correct_answer": "を", "explanations": {"を": "「担当する」の対象を示す「を」で、「外交を担当する」が正しい。", "に": "「外交に担当する」は方向の「に」で、「担当する」の対象にならない。", "から": "起点の「から」で、「外交から担当する」は対象を示せない。", "と": "並列や相手を示す「と」で、「外交と担当する」は「担当する」と結びつかない。"}, "error_tags": {"に": "方向・対象", "から": "起点", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「研究する」の対象を示す「を」で、「外交を研究している」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「外交が研究している」は外交を主語にしてしまい、研究する主体にならない。"}, {"text": "に", "is_correct": false, "explanation": "「外交に研究している」は方向や対象の「に」で、「研究する」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「外交へ研究している」は研究の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「研究する」の対象を示す「を」で、「外交を研究している」が正しい。", "が": "「外交が研究している」は外交を主語にしてしまい、研究する主体にならない。", "に": "「外交に研究している」は方向や対象の「に」で、「研究する」の対象にはならない。", "へ": "方向の「へ」で、「外交へ研究している」は研究の対象を示せない。"}, "error_tags": {"が": "主語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国と国との話し合いや付き合いのこと。", "primary_collocate": null, "pronunciation": "がいこう", "ipa": "ɡaikoː", "syllable_count": 4, "sentences": [{"text": "二つの国の外交は、数年前の会談から大きく変わった。", "target_word": "外交", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の外交[がいこう]は、数年前[すうねんまえ]の会談[かいだん]から大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "外務省は、国の外交を担当する役所だ。", "target_word": "外交", "complexity_tier": "T3", "furigana": "外務省[がいむしょう]は、国[くに]の外交[がいこう]を担当[たんとう]する役所[やくしょ]だ。", "sentence_source": "generated"}, {"text": "新しい大統領は、隣の国との外交を大切にすると約束した。", "target_word": "外交", "complexity_tier": "T3", "furigana": "新[あたら]しい大統領[だいとうりょう]は、隣[となり]の国[くに]との外交[がいこう]を大切[たいせつ]にすると約束[やくそく]した。", "sentence_source": "generated"}, {"text": "食料の輸入について、両国は外交の場で話し合った。", "target_word": "外交", "complexity_tier": "T3", "furigana": "食料[しょくりょう]の輸入[ゆにゅう]について、両国[りょうこく]は外交[がいこう]の場[ば]で話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "歴史の授業で、江戸時代の外交について調べた。", "target_word": "外交", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、江戸[えど]時代[じだい]の外交[がいこう]について調[しら]べた。", "sentence_source": "generated"}, {"text": "外交がうまくいかなくなると、両国の貿易にも影響が出る。", "target_word": "外交", "complexity_tier": "T3", "furigana": "外交[がいこう]がうまくいかなくなると、両国[りょうこく]の貿易[ぼうえき]にも影響[えいきょう]が出[で]る。", "sentence_source": "generated"}, {"text": "小さな国でも、外交の工夫で自分たちの立場を守ることができる。", "target_word": "外交", "complexity_tier": "T3", "furigana": "小[ちい]さな国[くに]でも、外交[がいこう]の工夫[くふう]で自分[じぶん]たちの立場[たちば]を守[まも]ることができる。", "sentence_source": "generated"}, {"text": "彼女は大学で、日本の外交を研究している。", "target_word": "外交", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]で、日本[にほん]の外交[がいこう]を研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "国どうしの外交は、お互いの信頼から始まる。", "target_word": "外交", "complexity_tier": "T3", "furigana": "国[くに]どうしの外交[がいこう]は、お互[たが]いの信頼[しんらい]から始[はじ]まる。", "sentence_source": "generated"}, {"text": "ニュースでは、各国の外交の動きが毎日報じられている。", "target_word": "外交", "complexity_tier": "T3", "furigana": "ニュースでは、各国[かっこく]の外交[がいこう]の動[うご]きが毎日[まいにち]報[ほう]じられている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外交", "label": "基本形"}], "register": "中立", "sense_fingerprint": "国と国との話し合い・付き合い(国どうしの関係)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "会談をきっかけに「外交」が変わったという文で、自然に成り立つ。"}, {"text": "月", "is_correct": false, "explanation": "月は会談で変わるものではなく、「二つの国の月」が変わるとは言えない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は国の変化の主語にならず、「二つの国の体重」が会談で変わるとは言えない。"}, {"text": "天気", "is_correct": false, "explanation": "会談と無関係で、「二つの国の天気」が会談で変わるとは言えない。"}], "explanations": {"外交": "会談をきっかけに「外交」が変わったという文で、自然に成り立つ。", "月": "月は会談で変わるものではなく、「二つの国の月」が変わるとは言えない。", "体重": "体重は国の変化の主語にならず、「二つの国の体重」が会談で変わるとは言えない。", "天気": "会談と無関係で、「二つの国の天気」が会談で変わるとは言えない。"}, "sentence_index": 0, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は去年から、同じ部署の女性と外交している。", "explanation": "ここは〈交際〉の意味。外交は国と国との関係を指すので、男女の付き合いには使わない。"}, {"text": "店長は、給料の金額について社員と三時間外交を重ねた。", "explanation": "ここは〈交渉〉の意味。外交は国家どうしの話し合いなので、店長と社員の給料の話には合わない。"}, {"text": "隣の夫婦は、夕食のメニューをめぐって毎晩外交している。", "explanation": "ここは〈口論〉の意味。外交は国と国との話し合いや付き合いを指すので、夫婦の言い争いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外交", "is_correct": true, "explanation": "「外交の工夫」は国どうしの話し合いで立場を守る方法を指し、文の意味と合う。"}, {"text": "野球", "is_correct": false, "explanation": "「野球の工夫」は競技の方法を指し、国の立場を守る手段を表せないので文が通らない。"}, {"text": "切手", "is_correct": false, "explanation": "「切手の工夫」は郵便に使う物を指し、国の立場を守る方法にならない。"}, {"text": "給食", "is_correct": false, "explanation": "「給食の工夫」は学校の食事を指し、国の立場を守る手段として意味が通らない。"}], "explanations": {"外交": "「外交の工夫」は国どうしの話し合いで立場を守る方法を指し、文の意味と合う。", "野球": "「野球の工夫」は競技の方法を指し、国の立場を守る手段を表せないので文が通らない。", "切手": "「切手の工夫」は郵便に使う物を指し、国の立場を守る方法にならない。", "給食": "「給食の工夫」は学校の食事を指し、国の立場を守る手段として意味が通らない。"}, "sentence_index": 6, "correct_answer": "外交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの会社は、新しい商品を作るために外交を重ねた。", "explanation": "ここは〈協力〉の意味。外交は国家どうしの関係を指すので、会社どうしの共同作業には使わない。"}, {"text": "教師と生徒は、毎日の外交で信頼を深めた。", "explanation": "ここは〈対話〉の意味。外交は国家どうしのやり取りなので、教師と生徒の日々のやり取りには使わない。"}, {"text": "記者は、政治家の本音を探るために外交を続けた。", "explanation": "ここは〈偵察〉の意味。外交は国と国との話し合いや付き合いを指すので、人の本音を探る行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大統領は、隣国との外交が大切にすると演説で述べた。", "corrected_sentence": "大統領は、隣国との外交を大切にすると演説で述べた。", "error_description": "誤りは「外交が」。正しくは「外交を」で、「大切にする」は対象を「を」で受ける。「が」にすると外交が主語になり、「大切にする」の主体と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51455, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大統領は、同盟国との外交を新しい協定を結んだ。", "corrected_sentence": "大統領は、同盟国との外交で新しい協定を結んだ。", "error_description": "誤りは「外交を」。正しくは「外交で」で、「で」は手段を示す。「を」を二つ並べると目的語が重なり、「結んだ」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "座る", "is_correct": true, "explanation": "立つの対義語。腰を下ろす姿勢で、まっすぐになる立つの反対になる。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水中で進む動作で、姿勢の反対語ではない。"}, {"text": "跳ぶ", "is_correct": false, "explanation": "空中へ飛び上がる動作で、姿勢の反対語ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作で、姿勢の反対語ではない。"}], "correct_answer": "座る", "explanations": {"座る": "立つの対義語。腰を下ろす姿勢で、まっすぐになる立つの反対になる。", "泳ぐ": "水中で進む動作で、姿勢の反対語ではない。", "跳ぶ": "空中へ飛び上がる動作で、姿勢の反対語ではない。", "歌う": "声を出す動作で、姿勢の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
