INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が足で体を支えて、まっすぐになる。", "primary_collocate": null, "pronunciation": "たつ", "ipa": "tatsɯ", "syllable_count": 2, "sentences": [{"text": "長く座っていたので、立つときに足がしびれた。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "長[なが]く座[すわ]っていたので、立[た]つときに足[あし]がしびれた。", "sentence_source": "generated"}, {"text": "先生に名前を呼ばれると、彼は「はい」と言ってすぐに立った。", "target_word": "立った", "complexity_tier": "T3", "furigana": "先生[せんせい]に名前[なまえ]を呼[よ]ばれると、彼[かれ]は「はい」と言[い]ってすぐに立[た]った。", "sentence_source": "generated"}, {"text": "うちの犬は後ろ足で立つことができる。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "うちの犬[いぬ]は後[うし]ろ足[あし]で立[た]つことができる。", "sentence_source": "generated"}, {"text": "先生が来たら、みんな立って挨拶をする。", "target_word": "立って", "complexity_tier": "T3", "furigana": "先生[せんせい]が来[き]たら、みんな立[た]って挨拶[あいさつ]をする。", "sentence_source": "generated"}, {"text": "足を怪我して、しばらくまっすぐに立つのがつらかった。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "足[あし]を怪我[けが]して、しばらくまっすぐに立[た]つのがつらかった。", "sentence_source": "generated"}, {"text": "小さな子が、机につかまってやっと立った。", "target_word": "立った", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]が、机[つくえ]につかまってやっと立[た]った。", "sentence_source": "generated"}, {"text": "疲れすぎて、もう立つ力も残っていなかった。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "疲[つか]れすぎて、もう立[た]つ力[ちから]も残[のこ]っていなかった。", "sentence_source": "generated"}, {"text": "壁に背をつけて、背筋をのばして立ってください。", "target_word": "立って", "complexity_tier": "T3", "furigana": "壁[かべ]に背[せ]をつけて、背筋[せすじ]をのばして立[た]ってください。", "sentence_source": "generated"}, {"text": "舞台の上で、彼は動かずにじっと立っていた。", "target_word": "立って", "complexity_tier": "T3", "furigana": "舞台[ぶたい]の上[うえ]で、彼[かれ]は動[うご]かずにじっと立[た]っていた。", "sentence_source": "generated"}, {"text": "朝礼では、全員が一列に並んで立っている。", "target_word": "立って", "complexity_tier": "T3", "furigana": "朝礼[ちょうれい]では、全員[ぜんいん]が一列[いちれつ]に並[なら]んで立[た]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "立つ", "label": "終止形"}, {"form": "立ち", "label": "連用形"}, {"form": "立って", "label": "て形"}, {"form": "立った", "label": "過去形"}, {"form": "立たない", "label": "否定形"}, {"form": "立てば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人が足で体を支えて、まっすぐになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立つ", "is_correct": true, "explanation": "「立つときに」で、人が体を支えてまっすぐになる動作に合う。"}, {"text": "借りる", "is_correct": false, "explanation": "「借りるときに足がしびれた」は文脈に合わない。"}, {"text": "煮る", "is_correct": false, "explanation": "「煮るときに足がしびれた」は不自然。"}, {"text": "刻む", "is_correct": false, "explanation": "「刻むときに足がしびれた」は不自然で、体の動作の文脈に合わない。"}], "explanations": {"立つ": "「立つときに」で、人が体を支えてまっすぐになる動作に合う。", "借りる": "「借りるときに足がしびれた」は文脈に合わない。", "煮る": "「煮るときに足がしびれた」は不自然。", "刻む": "「刻むときに足がしびれた」は不自然で、体の動作の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は駅の階段に大の字になって、ずっと立った。", "explanation": "ここは〈寝転ぶ〉の意味。大の字に体を横たえる姿勢に、立つは合わないので誤り。"}, {"text": "椅子に深く立って、考え込んだ。", "explanation": "「深く」は腰を下ろして座る様子を表す。まっすぐ姿勢をとる立つとは合わない。"}, {"text": "ソファで横になり、ぐっすり立った。", "explanation": "ここは〈寝る〉の意味。横になって休む様子に、立つは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立つ", "is_correct": true, "explanation": "「もう立つ力も」で、体を支えて立つ力という意味に合う。"}, {"text": "掘る", "is_correct": false, "explanation": "「もう掘る力も」は疲れた文脈に合わない。"}, {"text": "縫う", "is_correct": false, "explanation": "「もう縫う力も」は布を縫う作業の意味で、文脈に合わない。"}, {"text": "叩く", "is_correct": false, "explanation": "「もう叩く力も」は文脈に合わない。"}], "explanations": {"立つ": "「もう立つ力も」で、体を支えて立つ力という意味に合う。", "掘る": "「もう掘る力も」は疲れた文脈に合わない。", "縫う": "「もう縫う力も」は布を縫う作業の意味で、文脈に合わない。", "叩く": "「もう叩く力も」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "立つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は教室の机を枕にして、しばらく立った。", "explanation": "ここは〈寝る〉の意味。枕にして休む動作は横になることで、立つとは合わない。"}, {"text": "子どもが床にごろりと立って笑った。", "explanation": "ここは〈寝転がる〉の意味。床の上で体を横たえる様子に、立つは合わない。"}, {"text": "彼は畳に深く立って、お茶を飲んだ。", "explanation": "ここは〈正座する〉の意味。膝を折って座る姿勢に、立つは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "授業が終わったら、みんな立てて教室を出る。", "corrected_sentence": "授業が終わったら、みんな立って教室を出る。", "error_description": "自分が体を支えて立つ動作は自動詞「立って」。「立てて」は他動詞で、物を立てる意味になり合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "立った", "is_correct": true, "explanation": "過去形。「すぐに立った」で動作の完了を表す。"}, {"text": "立てば", "is_correct": false, "explanation": "仮定形で、「すぐに」と続けて動作を述べる文には合わない。"}, {"text": "立ち", "is_correct": false, "explanation": "連用形で、文を終える形にはならない。"}, {"text": "立て", "is_correct": false, "explanation": "命令形で、「彼は立った」という過去の出来事を述べる文には合わない。"}], "correct_form": "立った", "base_form": "立つ", "form_label": "過去形", "sentence_index": 1, "explanations": {"立った": "過去形。「すぐに立った」で動作の完了を表す。", "立てば": "仮定形で、「すぐに」と続けて動作を述べる文には合わない。", "立ち": "連用形で、文を終える形にはならない。", "立て": "命令形で、「彼は立った」という過去の出来事を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "列の先頭で、まっすぐに立ている少年がいる。", "corrected_sentence": "列の先頭で、まっすぐに立っている少年がいる。", "error_description": "「立っている」の促音「っ」が抜けている。正しくは「立っている」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "立って", "is_correct": true, "explanation": "て形。「〜てください」で指示を表す形。"}, {"text": "立たない", "is_correct": false, "explanation": "否定形で、「立たないください」は成り立たない。"}, {"text": "立たず", "is_correct": false, "explanation": "否定の連用形で、「立たずください」は成り立たない。"}, {"text": "立ちます", "is_correct": false, "explanation": "丁寧形で、「立ちますください」は成り立たない。"}], "correct_form": "立って", "base_form": "立つ", "form_label": "て形", "sentence_index": 7, "explanations": {"立って": "て形。「〜てください」で指示を表す形。", "立たない": "否定形で、「立たないください」は成り立たない。", "立たず": "否定の連用形で、「立たずください」は成り立たない。", "立ちます": "丁寧形で、「立ちますください」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "座る", "is_correct": true, "explanation": "立つの対義語。体を下ろして腰を据える姿勢で、立つの反対になる。"}, {"text": "歩く", "is_correct": false, "explanation": "足を動かして進む動作で、姿勢の反対語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "速く進む動作で、姿勢の反対語ではない。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水中で進む動作で、姿勢の反対語ではない。"}], "correct_answer": "座る", "explanations": {"座る": "立つの対義語。体を下ろして腰を据える姿勢で、立つの反対になる。", "歩く": "足を動かして進む動作で、姿勢の反対語ではない。", "走る": "速く進む動作で、姿勢の反対語ではない。", "泳ぐ": "水中で進む動作で、姿勢の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "座る", "is_correct": true, "explanation": "立つの対義語。腰を下ろす姿勢で、立つの反対になる。"}, {"text": "掘る", "is_correct": false, "explanation": "地面を削る動作で、姿勢の反対語ではない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "大きな声を出す動作で、姿勢の反対語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情や声を表す動作で、姿勢の反対語ではない。"}], "correct_answer": "座る", "explanations": {"座る": "立つの対義語。腰を下ろす姿勢で、立つの反対になる。", "掘る": "地面を削る動作で、姿勢の反対語ではない。", "叫ぶ": "大きな声を出す動作で、姿勢の反対語ではない。", "笑う": "表情や声を表す動作で、姿勢の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が足で体を支えて垂直の姿勢をとる。また、ある場所に身を置く。", "primary_collocate": null, "pronunciation": "たつ", "ipa": "tatsɯ", "syllable_count": 2, "sentences": [{"text": "十代の人が初めてステージに立ちます。", "target_word": "立ち", "complexity_tier": "T3", "furigana": "十代[じゅうだい]の人[ひと]が初[はじ]めてステージに立[た]ちます。", "sentence_source": "mined"}, {"text": "電車が混んでいたので、駅まで立って行った。", "target_word": "立って", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が混[こ]んでいたので、駅[えき]まで立[た]って行[い]った。", "sentence_source": "generated"}, {"text": "彼は窓のそばに立って、外の雪を見ていた。", "target_word": "立って", "complexity_tier": "T3", "furigana": "彼[かれ]は窓[まど]のそばに立[た]って、外[そと]の雪[ゆき]を見[み]ていた。", "sentence_source": "generated"}, {"text": "先生が教壇に立つと、教室が静かになった。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "先生[せんせい]が教壇[きょうだん]に立[た]つと、教室[きょうしつ]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "赤ちゃんが初めて自分の足で立った。", "target_word": "立った", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが初[はじ]めて自分[じぶん]の足[あし]で立[た]った。", "sentence_source": "generated"}, {"text": "雨の中、彼女は一時間も駅の前に立っていた。", "target_word": "立って", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]、彼女[かのじょ]は一時間[いちじかん]も駅[えき]の前[まえ]に立[た]っていた。", "sentence_source": "generated"}, {"text": "試合で優勝して、表彰台に立つ夢がかなった。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "試合[しあい]で優勝[ゆうしょう]して、表彰台[ひょうしょうだい]に立[た]つ夢[ゆめ]がかなった。", "sentence_source": "generated"}, {"text": "バスの中では、お年寄りに席を譲って立つことにした。", "target_word": "立つ", "complexity_tier": "T3", "furigana": "バスの中[なか]では、お年寄[としよ]りに席[せき]を譲[ゆず]って立[た]つことにした。", "sentence_source": "generated"}, {"text": "台所に立って、母と一緒に夕食を作った。", "target_word": "立って", "complexity_tier": "T3", "furigana": "台所[だいどころ]に立[た]って、母[はは]と一緒[いっしょ]に夕食[ゆうしょく]を作[つく]った。", "sentence_source": "generated"}, {"text": "名前を呼ばれたら、その場で立ってください。", "target_word": "立って", "complexity_tier": "T3", "furigana": "名前[なまえ]を呼[よ]ばれたら、その場[ば]で立[た]ってください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "立つ", "label": "終止形"}, {"form": "立ち", "label": "連用形"}, {"form": "立って", "label": "て形"}, {"form": "立った", "label": "過去形"}, {"form": "立たない", "label": "否定形"}, {"form": "立てば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人が足で体を支えて立つ。また、ある場所に身を置く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立ち", "is_correct": true, "explanation": "「ステージに立ちます」の連用形。ステージに上がる意味で文脈に合う。"}, {"text": "洗い", "is_correct": false, "explanation": "「ステージに洗います」は何を洗うのか文が成り立たない。"}, {"text": "焼き", "is_correct": false, "explanation": "「ステージに焼きます」は焼く動作で、ステージの文脈には合わない。"}, {"text": "縫い", "is_correct": false, "explanation": "布を縫う動作で、「ステージに縫います」は文脈に合わない。"}], "explanations": {"立ち": "「ステージに立ちます」の連用形。ステージに上がる意味で文脈に合う。", "洗い": "「ステージに洗います」は何を洗うのか文が成り立たない。", "焼き": "「ステージに焼きます」は焼く動作で、ステージの文脈には合わない。", "縫い": "布を縫う動作で、「ステージに縫います」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "立ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は畳の上にごろりと立って、そのまま眠った。", "explanation": "ここは〈横になる〉の意味。畳の上で体を横たえて眠る様子に、立つは合わないので誤り。"}, {"text": "彼は靴ひもを結ぶため、深く立った。", "explanation": "ここは〈しゃがむ〉の意味。身を低くして腰を落とす動作に、立つは合わないので誤り。"}, {"text": "彼は椅子にゆったりと立って、本を読んだ。", "explanation": "「ゆったりと」は座っている様子を表す。垂直の姿勢をとる立つとは、ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立つ", "is_correct": true, "explanation": "「表彰台に立つ夢」で、表彰台に上がる意味に合う。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "「表彰台に泳ぐ夢」は文脈に合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「表彰台に眠る夢」は文脈に合わない。"}, {"text": "打つ", "is_correct": false, "explanation": "「表彰台に打つ夢」は意味が通らない。"}], "explanations": {"立つ": "「表彰台に立つ夢」で、表彰台に上がる意味に合う。", "泳ぐ": "「表彰台に泳ぐ夢」は文脈に合わない。", "眠る": "「表彰台に眠る夢」は文脈に合わない。", "打つ": "「表彰台に打つ夢」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "立つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は布団でぐっすり立った。", "explanation": "ここは〈寝る〉の意味。横になって休む様子に、立つは合わない。"}, {"text": "雪道で、彼は仰向けに立って足首を痛めた。", "explanation": "ここは〈転ぶ〉の意味。足を滑らせて仰向けに倒れる動作は、垂直になる立つとは合わない。"}, {"text": "彼は机の下にもぐって、しばらく立った。", "explanation": "ここは〈うずくまる〉の意味。身を低くして丸まる姿勢に、立つは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は舞台の中央に立てた。", "corrected_sentence": "彼女は舞台の中央に立った。", "error_description": "「立てる」は他動詞で別の意味になる。自分が立つ意味では自動詞の「立った」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "立って", "is_correct": true, "explanation": "て形。「〜て行った」と続けて、移動の様子を述べる形。"}, {"text": "立ち", "is_correct": false, "explanation": "連用形。「立ち行く」は別の意味になり、「駅まで」と移動を述べる文には合わない。"}, {"text": "立った", "is_correct": false, "explanation": "過去形で、「〜て行った」の「て」には続かない。"}, {"text": "立たない", "is_correct": false, "explanation": "否定形で、ここでは立たないという意味になり文脈に合わない。"}], "correct_form": "立って", "base_form": "立つ", "form_label": "て形", "sentence_index": 1, "explanations": {"立って": "て形。「〜て行った」と続けて、移動の様子を述べる形。", "立ち": "連用形。「立ち行く」は別の意味になり、「駅まで」と移動を述べる文には合わない。", "立った": "過去形で、「〜て行った」の「て」には続かない。", "立たない": "否定形で、ここでは立たないという意味になり文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51458, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "優勝の日、彼女は表彰台に立ちた夢をかなえた。", "corrected_sentence": "優勝の日、彼女は表彰台に立つ夢をかなえた。", "error_description": "名詞を修飾する形は辞書形「立つ夢」。「立ちた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "立つ", "is_correct": true, "explanation": "辞書形。「〜ことにした」は辞書形に続く。"}, {"text": "立てば", "is_correct": false, "explanation": "仮定形で、「〜ことにした」には続かない。"}, {"text": "立て", "is_correct": false, "explanation": "命令形で、「〜ことにした」には続かない。"}, {"text": "立ちます", "is_correct": false, "explanation": "丁寧形で、「〜ことにした」の前には使わない。"}], "correct_form": "立つ", "base_form": "立つ", "form_label": "終止形", "sentence_index": 7, "explanations": {"立つ": "辞書形。「〜ことにした」は辞書形に続く。", "立てば": "仮定形で、「〜ことにした」には続かない。", "立て": "命令形で、「〜ことにした」には続かない。", "立ちます": "丁寧形で、「〜ことにした」の前には使わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
