INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51459, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "何かを人生や経験の中で一番最初にするさま。", "primary_collocate": null, "pronunciation": "はじめて", "ipa": "hadʑimete", "syllable_count": 4, "sentences": [{"text": "昨日、初めて日本の海を見た。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "昨日[きのう]、初[はじ]めて日本[にほん]の海[うみ]を見[み]た。", "sentence_source": "generated"}, {"text": "初めて会った人なのに、すぐ仲良くなった。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った人[ひと]なのに、すぐ仲良[なかよ]くなった。", "sentence_source": "generated"}, {"text": "初めてこの料理を作ったが、うまくできた。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "初[はじ]めてこの料理[りょうり]を作[つく]ったが、うまくできた。", "sentence_source": "generated"}, {"text": "私は初めて一人で電車に乗った。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "私[わたし]は初[はじ]めて一人[ひとり]で電車[でんしゃ]に乗[の]った。", "sentence_source": "generated"}, {"text": "十歳のとき、初めて自転車に乗れた。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "十歳[じゅっさい]のとき、初[はじ]めて自転車[じてんしゃ]に乗[の]れた。", "sentence_source": "generated"}, {"text": "彼の歌を聞いて、初めて音楽が好きになった。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "彼[かれ]の歌[うた]を聞[き]いて、初[はじ]めて音楽[おんがく]が好[す]きになった。", "sentence_source": "generated"}, {"text": "京都に来たのは初めてなので、道がわからない。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "京都[きょうと]に来[き]たのは初[はじ]めてなので、道[みち]がわからない。", "sentence_source": "generated"}, {"text": "初めて飛行機に乗ったとき、とても緊張した。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "初[はじ]めて飛行機[ひこうき]に乗[の]ったとき、とても緊張[きんちょう]した。", "sentence_source": "generated"}, {"text": "初めて失敗した日、準備の大切さがわかった。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "初[はじ]めて失敗[しっぱい]した日[ひ]、準備[じゅんび]の大切[たいせつ]さがわかった。", "sentence_source": "generated"}, {"text": "初めて書いた手紙を、母は今も持っている。", "target_word": "初めて", "complexity_tier": "T3", "furigana": "初[はじ]めて書[か]いた手紙[てがみ]を、母[はは]は今[いま]も持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "初めて", "label": "副詞形"}, {"form": "初めての", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "ある事を人生や経験の中で一番最初にするさま（初回）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51459, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初めて", "is_correct": true, "explanation": "ここに入るのは〈初めて〉。日本の海を見たのが人生で最初だと示す。"}, {"text": "必ず", "is_correct": false, "explanation": "〈必ず〉は確実さを表すが、昨日の出来事に入れると文脈に合わず、初めての意味にもならないので合わない。"}, {"text": "毎日", "is_correct": false, "explanation": "〈毎日〉は繰り返しを表すので、『昨日』と合わず、初めての経験の意味に反するので合わない。"}, {"text": "大いに", "is_correct": false, "explanation": "〈大いに〉は程度の大きさを表すもので、『大いに日本の海を見た』では意味が通らないので合わない。"}], "explanations": {"初めて": "ここに入るのは〈初めて〉。日本の海を見たのが人生で最初だと示す。", "必ず": "〈必ず〉は確実さを表すが、昨日の出来事に入れると文脈に合わず、初めての意味にもならないので合わない。", "毎日": "〈毎日〉は繰り返しを表すので、『昨日』と合わず、初めての経験の意味に反するので合わない。", "大いに": "〈大いに〉は程度の大きさを表すもので、『大いに日本の海を見た』では意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "初めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "初めて毎朝この道を歩いている。", "explanation": "ここは〈いつも〉の意味。初めては一度きりの最初の経験を表すので、毎朝の繰り返しとは合わない。"}, {"text": "この店には初めて何度も来ている。", "explanation": "ここは〈たびたび〉の意味。初めては最初の一回を指すので、回数を重ねる『たびたび来ている』とは両立しない。"}, {"text": "まず初めて、受付で名前を書いてください。", "explanation": "ここは〈手順の最初〉の意味。手順の始まりを言うのは『最初に』で、初めては一度きりの初体験を表すので、受付の手順の説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51459, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初めて", "is_correct": true, "explanation": "ここに入るのは〈初めて〉。『京都に来たのは初めて』と、来たのが一回目だと示す。"}, {"text": "決して", "is_correct": false, "explanation": "〈決して〉は打ち消しと組む副詞で、ここでは文が成り立たないので合わない。"}, {"text": "まったく", "is_correct": false, "explanation": "〈まったく〉は程度を強める語で、『京都に来たのは』の後に入ると意味が通らないので合わない。"}, {"text": "大して", "is_correct": false, "explanation": "〈大して〉は『大して〜ない』の形で使う語で、ここでは意味が通らないので合わない。"}], "explanations": {"初めて": "ここに入るのは〈初めて〉。『京都に来たのは初めて』と、来たのが一回目だと示す。", "決して": "〈決して〉は打ち消しと組む副詞で、ここでは文が成り立たないので合わない。", "まったく": "〈まったく〉は程度を強める語で、『京都に来たのは』の後に入ると意味が通らないので合わない。", "大して": "〈大して〉は『大して〜ない』の形で使う語で、ここでは意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "初めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どものころから、初めてこの町に住んでいる。", "explanation": "ここは〈ずっと〉の意味。初めては最初の一回を表すので、子どものころから続く状態には合わない。"}, {"text": "彼女は毎回、初めて遅刻してしまう。", "explanation": "ここは〈しばしば〉の意味。初めては一回きりの最初を指すので、くり返し起こる遅刻とは両立しない。"}, {"text": "もう三十年も、初めてこの店で働いている。", "explanation": "ここは〈長年〉の意味。長く続いた期間を表すもので、初めては最初の一回を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51459, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年、初めて海外に行く。", "corrected_sentence": "去年、初めて海外に行った。", "error_description": "『行った』が正しい。去年の一回きりの経験を述べるので過去の形が必要。『行く』は現在の形で、過去の出来事とは合わないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51459, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "初めて海外旅行で、とても緊張した。", "corrected_sentence": "初めての海外旅行で、とても緊張した。", "error_description": "『初めての海外旅行』が正しい。名詞『旅行』を修飾するには『の』を付けた連体形が必要。『初めて』のままでは副詞の形で、名詞を直接修飾できないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「十は九の次の数字です」は正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は「です」の文に合わないので、「十を九の次の数字です」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」は文の主題にならないので、「十で九の次の数字です」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は主題にならないので、「十へ九の次の数字です」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「十は九の次の数字です」は正しい。", "を": "目的語の「を」は「です」の文に合わないので、「十を九の次の数字です」は成り立たない。", "で": "手段や場所の「で」は文の主題にならないので、「十で九の次の数字です」は不自然。", "へ": "方向の「へ」は主題にならないので、「十へ九の次の数字です」は成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "範囲の終点を示す「まで」。「十まで数えられた」は正しい。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「十で数えられた」の形で、範囲の終点を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「十に数えられた」は不自然で、範囲の終点を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は十を主語にして「十が数えられた人」となり、数えられる人の話にならない。"}], "correct_answer": "まで", "explanations": {"まで": "範囲の終点を示す「まで」。「十まで数えられた」は正しい。", "で": "手段の「で」は「十で数えられた」の形で、範囲の終点を示せない。", "に": "「十に数えられた」は不自然で、範囲の終点を示せない。", "が": "「が」は十を主語にして「十が数えられた人」となり、数えられる人の話にならない。"}, "error_tags": {"で": "手段", "に": "結果", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "十は、10という数字のことです。", "primary_collocate": null, "pronunciation": "じゅう", "ipa": "dʑɯː", "syllable_count": 2, "sentences": [{"text": "二に八を足すと、十になります。", "target_word": "十", "complexity_tier": "T2", "furigana": "二[に]に八[はち]を足[た]すと、十[じゅう]になります。", "sentence_source": "generated"}, {"text": "十は九の次の数字です。", "target_word": "十", "complexity_tier": "T2", "furigana": "十[じゅう]は九[きゅう]の次[つぎ]の数字[すうじ]です。", "sentence_source": "generated"}, {"text": "十の半分は五です。", "target_word": "十", "complexity_tier": "T2", "furigana": "十[じゅう]の半分[はんぶん]は五[ご]です。", "sentence_source": "generated"}, {"text": "子どもたちは声をそろえて、一から十まで数えました。", "target_word": "十", "complexity_tier": "T3", "furigana": "子[こ]どもたちは声[こえ]をそろえて、一[いち]から十[じゅう]まで数[かぞ]えました。", "sentence_source": "generated"}, {"text": "この箱には、一から十までの番号がついています。", "target_word": "十", "complexity_tier": "T3", "furigana": "この箱[はこ]には、一[いち]から十[じゅう]までの番号[ばんごう]がついています。", "sentence_source": "generated"}, {"text": "十に二をかけると、二十になります。", "target_word": "十", "complexity_tier": "T3", "furigana": "十[じゅう]に二[に]をかけると、二十[にじゅう]になります。", "sentence_source": "generated"}, {"text": "十を二で割ると、五です。", "target_word": "十", "complexity_tier": "T2", "furigana": "十[じゅう]を二[に]で割[わ]ると、五[ご]です。", "sentence_source": "generated"}, {"text": "先生は「十まで数えられた人は手を上げてください」と言いました。", "target_word": "十", "complexity_tier": "T4", "furigana": "先生[せんせい]は「十[じゅう]まで数[かぞ]えられた人[ひと]は手[て]を上[あ]げてください」と言[い]いました。", "sentence_source": "generated"}, {"text": "十から七を引くと、三になります。", "target_word": "十", "complexity_tier": "T2", "furigana": "十[じゅう]から七[なな]を引[ひ]くと、三[さん]になります。", "sentence_source": "generated"}, {"text": "算数の問題で、答えが十になるように数を選びました。", "target_word": "十", "complexity_tier": "T4", "furigana": "算数[さんすう]の問題[もんだい]で、答[こた]えが十[じゅう]になるように数[かず]を選[えら]びました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "十", "label": "基本形"}], "register": "polite", "sense_fingerprint": "10という数字そのもの(九の次、五の二倍)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "十", "is_correct": true, "explanation": "2と8を足すと10。「二に八を足すと、十になります」は計算として正しい。"}, {"text": "八", "is_correct": false, "explanation": "2と8を足すと10であり、8にはならない。"}, {"text": "二十", "is_correct": false, "explanation": "2と8を足すと10であり、20にはならない。"}, {"text": "百", "is_correct": false, "explanation": "2と8を足すと10であり、100にはならない。"}], "explanations": {"十": "2と8を足すと10。「二に八を足すと、十になります」は計算として正しい。", "八": "2と8を足すと10であり、8にはならない。", "二十": "2と8を足すと10であり、20にはならない。", "百": "2と8を足すと10であり、100にはならない。"}, "sentence_index": 0, "correct_answer": "十"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合で十を取ったので、チームは大喜びした。", "explanation": "点数は「十点」と言う。〈十〉だけでは「点を取る」の対象として使わない。"}, {"text": "子どもたちは声をそろえて、一から十数まで数えました。", "explanation": "「十数」は「十ほど」の概数。順に数える終点は、ぴったり十を示す〈十〉でなければならない。"}, {"text": "雨が十降ったので、傘をさした。", "explanation": "雨の量は「十ミリ」のように単位を付けて言うので、〈十〉だけで「降った量」を表すのは合わない。〈十〉は数字の10を表す語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十", "is_correct": true, "explanation": "10を2で割ると5になる。「十を二で割ると、五です」は正しい。"}, {"text": "六", "is_correct": false, "explanation": "6を2で割ると3になり、5にはならない。"}, {"text": "四", "is_correct": false, "explanation": "4を2で割ると2になり、5にはならない。"}, {"text": "千", "is_correct": false, "explanation": "1000を2で割ると500になり、5にはならない。"}], "explanations": {"十": "10を2で割ると5になる。「十を二で割ると、五です」は正しい。", "六": "6を2で割ると3になり、5にはならない。", "四": "4を2で割ると2になり、5にはならない。", "千": "1000を2で割ると500になり、5にはならない。"}, "sentence_index": 6, "correct_answer": "十"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "算数の問題で、答えが十数になるように数を選びました。", "explanation": "「十数」は「十ほど」の概数。ぴったり十を求める問題では合わない。"}, {"text": "算数の問題で、答えが十分になるように数を選びました。", "explanation": "「十分」は「足りている」の意味。答えの数値を表す〈十〉の意味では合わない。"}, {"text": "算数の問題で、答えが十時になるように数を選びました。", "explanation": "「十時」は時刻を表す語で、計算の答えの数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51461, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "四に六を足すと、十がなります。", "corrected_sentence": "四に六を足すと、十になります。", "error_description": "「なる」は「〜になる」の形で、結果を表す「に」を使う。「十が なります」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
