INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51463, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "声を大きくする道具。", "primary_collocate": null, "pronunciation": "まいく", "ipa": "maikɯ", "syllable_count": 3, "sentences": [{"text": "体育館は広いので、校長先生はマイクを使って話します。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "体育館[たいいくかん]は広[ひろ]いので、校長[こうちょう]先生[せんせい]はマイクを使[つか]って話[はな]します。", "sentence_source": "generated"}, {"text": "マイクを近づけすぎると、声が割れて聞こえます。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "マイクを近[ちか]づけすぎると、声[こえ]が割[わ]れて聞[き]こえます。", "sentence_source": "generated"}, {"text": "ライブ会場で、歌手がマイクに向かって大きな声で歌いました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "ライブ会場[かいじょう]で、歌手[かしゅ]がマイクに向[む]かって大[おお]きな声[こえ]で歌[うた]いました。", "sentence_source": "generated"}, {"text": "マイクのおかげで、後ろの席の人にも声が届きました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "マイクのおかげで、後[うし]ろの席[せき]の人[ひと]にも声[こえ]が届[とど]きました。", "sentence_source": "generated"}, {"text": "会議室の机の上に、マイクが二つ置いてあります。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]の机[つくえ]の上[うえ]に、マイクが二[ふた]つ置[お]いてあります。", "sentence_source": "generated"}, {"text": "スピーチの前に、マイクの音を確かめました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "スピーチの前[まえ]に、マイクの音[おと]を確[たし]かめました。", "sentence_source": "generated"}, {"text": "マイクが壊れて、声が小さくしか聞こえませんでした。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "マイクが壊[こわ]れて、声[こえ]が小[ちい]さくしか聞[き]こえませんでした。", "sentence_source": "generated"}, {"text": "説明会では、係の人がマイクを持って客席を回りました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "説明会[せつめいかい]では、係[かかり]の人[ひと]がマイクを持[も]って客席[きゃくせき]を回[まわ]りました。", "sentence_source": "generated"}, {"text": "駅前で、候補者がマイクを持って演説していました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "駅前[えきまえ]で、候補者[こうほしゃ]がマイクを持[も]って演説[えんぜつ]していました。", "sentence_source": "generated"}, {"text": "マイクを置いたあと、会場から大きな拍手が起こりました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "マイクを置[お]いたあと、会場[かいじょう]から大[おお]きな拍手[はくしゅ]が起[お]こりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マイク", "label": "基本形"}], "register": "polite", "sense_fingerprint": "声を大きくして遠くに届ける道具(スピーチ・歌・演説で使う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51463, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マイク", "is_correct": true, "explanation": "「マイクを使って話します」は、声を大きくして話す道具として自然。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は話すための道具ではないので、「座布団を使って話します」は成り立たない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は話すための道具ではないので、「花瓶を使って話します」は文脈に合わない。"}, {"text": "空", "is_correct": false, "explanation": "空は使う道具ではないので、「空を使って話します」は成り立たない。"}], "explanations": {"マイク": "「マイクを使って話します」は、声を大きくして話す道具として自然。", "座布団": "座布団は話すための道具ではないので、「座布団を使って話します」は成り立たない。", "花瓶": "花瓶は話すための道具ではないので、「花瓶を使って話します」は文脈に合わない。", "空": "空は使う道具ではないので、「空を使って話します」は成り立たない。"}, "sentence_index": 0, "correct_answer": "マイク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "マイクを耳に差して、好きな音楽を聴きました。", "explanation": "耳に差して音楽を聴くのはイヤホンの使い方で、〈マイク〉は声を大きくする道具。ここでは合わない。"}, {"text": "マイクのおかげで、後ろの席の人にも日差しが届きました。", "explanation": "マイクは音を拾う道具で、日差しを届ける役目はない。ここでは意味が通らない。"}, {"text": "マイクのおかげで、後ろの席の人にも服が届きました。", "explanation": "マイクは声を大きくする道具で、服を届けるものではない。ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51463, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マイク", "is_correct": true, "explanation": "「マイクが壊れて、声が小さくしか聞こえませんでした」は、声を伝える装置が壊れた状況として自然。"}, {"text": "雨", "is_correct": false, "explanation": "雨は壊れるものではないので、「雨が壊れて」は成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "空は壊れるものではないので、「空が壊れて」は成り立たない。"}, {"text": "本", "is_correct": false, "explanation": "本が壊れても声が小さく聞こえる理由にはならず、文脈に合わない。"}], "explanations": {"マイク": "「マイクが壊れて、声が小さくしか聞こえませんでした」は、声を伝える装置が壊れた状況として自然。", "雨": "雨は壊れるものではないので、「雨が壊れて」は成り立たない。", "空": "空は壊れるものではないので、「空が壊れて」は成り立たない。", "本": "本が壊れても声が小さく聞こえる理由にはならず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "マイク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "マイクで会場の空気を冷やしたので、涼しくなりました。", "explanation": "空気を冷やすのはエアコンの役割で、〈マイク〉は声を大きくする道具。ここでは合わない。"}, {"text": "マイクを焼いたあと、会場から大きな拍手が起こりました。", "explanation": "マイクは焼いて使う調理器具ではない。ここでは〈マイク〉の使い方として合わない。"}, {"text": "マイクを鍋に入れて、スープを温めました。", "explanation": "鍋で温めるのは調理器具の使い方で、〈マイク〉は声を大きくする道具。ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51463, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "マイクを電源を入れて、声の大きさを確かめました。", "corrected_sentence": "マイクの電源を入れて、声の大きさを確かめました。", "error_description": "「電源を入れる」の対象は「マイクの電源」なので「の」で示す。「マイクを電源を」と「を」を重ねたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51463, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "マイクを電池を交換して、声を確かめました。", "corrected_sentence": "マイクの電池を交換して、声を確かめました。", "error_description": "「マイクの電池」の関係は「の」で示す。「マイクを電池を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使う」の目的語を示す「を」。「マイクを使って話しました」は正しい。"}, {"text": "に", "is_correct": false, "explanation": "「マイクに使う」は不自然で、「使う」の目的語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「使う」の対象にならないので、「マイクへ使って」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「マイクと使って」は不自然で、「使う」の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「使う」の目的語を示す「を」。「マイクを使って話しました」は正しい。", "に": "「マイクに使う」は不自然で、「使う」の目的語を示せない。", "へ": "方向の「へ」は「使う」の対象にならないので、「マイクへ使って」は成り立たない。", "と": "「マイクと使って」は不自然で、「使う」の対象を示せない。"}, "error_tags": {"に": "相手・場所", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「回す」の対象を示す「を」。「マイクを回して歌います」は正しい。"}, {"text": "に", "is_correct": false, "explanation": "「マイクに回す」は「回す」の対象を示せず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」は「マイクで回す」の形で、回す対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「マイクと回す」は不自然で、回す対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「回す」の対象を示す「を」。「マイクを回して歌います」は正しい。", "に": "「マイクに回す」は「回す」の対象を示せず、不自然。", "で": "手段の「で」は「マイクで回す」の形で、回す対象を示せない。", "と": "「マイクと回す」は不自然で、回す対象を示せない。"}, "error_tags": {"に": "相手", "で": "手段", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "マイクロフォン。声を電気信号に変えて拡声する装置。", "primary_collocate": null, "pronunciation": "まいく", "ipa": "maikɯ", "syllable_count": 3, "sentences": [{"text": "マイクを持って詩を読みます。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "マイクを持[も]って詩[し]を読[よ]みます。", "sentence_source": "mined"}, {"text": "小さい声だったので、マイクを使って話しました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "小[ちい]さい声[こえ]だったので、マイクを使[つか]って話[はな]しました。", "sentence_source": "generated"}, {"text": "会場が広いので、マイクがないと後ろの人には聞こえません。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "会場[かいじょう]が広[ひろ]いので、マイクがないと後[うし]ろの人[ひと]には聞[き]こえません。", "sentence_source": "generated"}, {"text": "司会の人は、マイクを口に近づけて話し始めました。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "司会[しかい]の人[ひと]は、マイクを口[くち]に近[ちか]づけて話[はな]し始[はじ]めました。", "sentence_source": "generated"}, {"text": "歌手はマイクを両手で持って、ゆっくり歌いました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "歌手[かしゅ]はマイクを両手[りょうて]で持[も]って、ゆっくり歌[うた]いました。", "sentence_source": "generated"}, {"text": "マイクの音が大きすぎて、耳が痛くなりました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "マイクの音[おと]が大[おお]きすぎて、耳[みみ]が痛[いた]くなりました。", "sentence_source": "generated"}, {"text": "先生は、マイクのスイッチを入れてから話しました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "先生[せんせい]は、マイクのスイッチを入[い]れてから話[はな]しました。", "sentence_source": "generated"}, {"text": "カラオケでは、順番にマイクを回して歌います。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "カラオケでは、順番[じゅんばん]にマイクを回[まわ]して歌[うた]います。", "sentence_source": "generated"}, {"text": "電池が切れて、マイクから声が出なくなりました。", "target_word": "マイク", "complexity_tier": "T3", "furigana": "電池[でんち]が切[き]れて、マイクから声[こえ]が出[で]なくなりました。", "sentence_source": "generated"}, {"text": "質問のある人は、手を上げてマイクを受け取ってください。", "target_word": "マイク", "complexity_tier": "T4", "furigana": "質問[しつもん]のある人[ひと]は、手[て]を上[あ]げてマイクを受[う]け取[と]ってください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マイク", "label": "基本形"}], "register": "polite", "sense_fingerprint": "声を電気信号にして拡声する装置(マイクロフォン)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c32a7421-5115-45dc-a774-604346542668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "マイク", "is_correct": true, "explanation": "「マイクを持って詩を読みます」は、マイクを手に持って話す場面として自然。"}, {"text": "雨", "is_correct": false, "explanation": "雨は持つことができないので、「雨を持って詩を読みます」は成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は持てるが、詩を読むときに持つものではないので文脈に合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は持つことができないので、「天井を持って詩を読みます」は成り立たない。"}], "explanations": {"マイク": "「マイクを持って詩を読みます」は、マイクを手に持って話す場面として自然。", "雨": "雨は持つことができないので、「雨を持って詩を読みます」は成り立たない。", "電池": "電池は持てるが、詩を読むときに持つものではないので文脈に合わない。", "天井": "天井は持つことができないので、「天井を持って詩を読みます」は成り立たない。"}, "sentence_index": 0, "correct_answer": "マイク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司会の人は、マイクを会場の天井に取り付けて、客席へ音を流しました。", "explanation": "マイクは声を拾う装置で、客席へ音を流す役目はスピーカーにある。ここは〈マイク〉の意味として合わない。"}, {"text": "司会の人は、マイクを耳に差し込んで話し始めました。", "explanation": "耳に差すのはイヤホン。マイクは口元で声を拾うものなので、この使い方はしない。"}, {"text": "司会の人は、マイクで会場の電気を消して話し始めました。", "explanation": "マイクは声を拾う道具で、照明を操作する道具ではない。ここでは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "マイク", "is_correct": true, "explanation": "マイクには電源のスイッチがあり、「マイクのスイッチを入れて話す」は自然。"}, {"text": "窓", "is_correct": false, "explanation": "窓にはスイッチを入れて話す文脈がなく、「窓のスイッチを入れてから話しました」は不自然。"}, {"text": "本", "is_correct": false, "explanation": "本にはスイッチがなく、「本のスイッチを入れてから話しました」は成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨にはスイッチがなく、「雨のスイッチを入れてから話しました」は成り立たない。"}], "explanations": {"マイク": "マイクには電源のスイッチがあり、「マイクのスイッチを入れて話す」は自然。", "窓": "窓にはスイッチを入れて話す文脈がなく、「窓のスイッチを入れてから話しました」は不自然。", "本": "本にはスイッチがなく、「本のスイッチを入れてから話しました」は成り立たない。", "雨": "雨にはスイッチがなく、「雨のスイッチを入れてから話しました」は成り立たない。"}, "sentence_index": 6, "correct_answer": "マイク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "質問のある人は、手を上げてマイクにメモを書いてください。", "explanation": "マイクは声を拾う装置で、文字を書く道具ではない。ここでは〈マイク〉の意味として合わない。"}, {"text": "質問のある人は、手を上げてマイクを財布に入れてください。", "explanation": "財布に入れて持つのは小銭入れの使い方で、〈マイク〉は会場で声を拾う装置なので、ここでは合わない。"}, {"text": "質問のある人は、手を上げてマイクに答えてください。", "explanation": "マイクは話を伝える装置で、答える相手ではない。ここでは意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ステージでマイクに握って、大きな声で歌いました。", "corrected_sentence": "ステージでマイクを握って、大きな声で歌いました。", "error_description": "「握る」は対象を「を」で示す。「マイクに握る」は誤りで、「マイクを握る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司会者は、マイクに音量を確かめました。", "corrected_sentence": "司会者は、マイクの音量を確かめました。", "error_description": "「マイクの音量」と「の」で所有関係を示す。「マイクに音量を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '401b40f5-d031-4d88-9d8d-edaa3348f3cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "借りる対象（借りた物）を示す。「小説を借りました」で自然に成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主格を表すため「小説が借りました」になり、小説が借りる主体になってしまう。"}, {"text": "に", "is_correct": false, "explanation": "「に」は借り先（人）に付くので、物を借りる「小説に借りました」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すため、「小説で借りました」では借りる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "借りる対象（借りた物）を示す。「小説を借りました」で自然に成り立つ。", "が": "主格を表すため「小説が借りました」になり、小説が借りる主体になってしまう。", "に": "「に」は借り先（人）に付くので、物を借りる「小説に借りました」は成り立たない。", "で": "場所や手段を表すため、「小説で借りました」では借りる対象を示せない。"}, "error_tags": {"が": "主格", "に": "借り先", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「小説のほう」と名詞をつなぐ「の」で、「ほう」に続く形として自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「小説へほうが」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表すが、「小説とほうが」は文の骨組みに合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため、「小説からほうが好き」は比べる対象として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「小説のほう」と名詞をつなぐ「の」で、「ほう」に続く形として自然。", "へ": "方向を表すため、「小説へほうが」は成り立たない。", "と": "並列や引用を表すが、「小説とほうが」は文の骨組みに合わない。", "から": "起点を表すため、「小説からほうが好き」は比べる対象として意味が通らない。"}, "error_tags": {"へ": "方向", "と": "並列・引用", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物語や出来事を書いた本や文章のこと。", "primary_collocate": null, "pronunciation": "しょうせつ", "ipa": "ɕoːsetsɯ", "syllable_count": 4, "sentences": [{"text": "手紙の書簡体の物語は、おもしろい小説です。", "target_word": "小説", "complexity_tier": "T3", "furigana": "手紙[てがみ]の書簡体[しょかんたい]の物語[ものがたり]は、おもしろい小説[しょうせつ]です。", "sentence_source": "mined"}, {"text": "昨日、図書館で新しい小説を借りました。", "target_word": "小説", "complexity_tier": "T3", "furigana": "昨日[きのう]、図書館[としょかん]で新[あたら]しい小説[しょうせつ]を借[か]りました。", "sentence_source": "generated"}, {"text": "この小説は主人公の気持ちがよく書かれているので、最後まで一気に読んでしまった。", "target_word": "小説", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は主人公[しゅじんこう]の気持[きも]ちがよく書[か]かれているので、最後[さいご]まで一気[いっき]に読[よ]んでしまった。", "sentence_source": "generated"}, {"text": "私は電車の中で小説を読むのが好きです。", "target_word": "小説", "complexity_tier": "T3", "furigana": "私[わたし]は電車[でんしゃ]の中[なか]で小説[しょうせつ]を読[よ]むのが好[す]きです。", "sentence_source": "generated"}, {"text": "彼は仕事のあとで、毎晩少しずつ小説を書いている。", "target_word": "小説", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]のあとで、毎晩[まいばん]少[すこ]しずつ小説[しょうせつ]を書[か]いている。", "sentence_source": "generated"}, {"text": "その小説は映画になって、世界中で有名になりました。", "target_word": "小説", "complexity_tier": "T3", "furigana": "その小説[しょうせつ]は映画[えいが]になって、世界中[せかいじゅう]で有名[ゆうめい]になりました。", "sentence_source": "generated"}, {"text": "小説は長くて難しかったが、結末にはとても感動した。", "target_word": "小説", "complexity_tier": "T3", "furigana": "小説[しょうせつ]は長[なが]くて難[むずか]しかったが、結末[けつまつ]にはとても感動[かんどう]した。", "sentence_source": "generated"}, {"text": "兄はマンガより小説のほうが好きだと言います。", "target_word": "小説", "complexity_tier": "T3", "furigana": "兄[あに]はマンガより小説[しょうせつ]のほうが好[す]きだと言[い]います。", "sentence_source": "generated"}, {"text": "作者は旅の経験をもとに、一つの小説を書き上げた。", "target_word": "小説", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は旅[たび]の経験[けいけん]をもとに、一つの小説[しょうせつ]を書き上げた。", "sentence_source": "generated"}, {"text": "先生にすすめられた小説を、週末に二日で読み終えた。", "target_word": "小説", "complexity_tier": "T3", "furigana": "先生[せんせい]にすすめられた小説[しょうせつ]を、週末[しゅうまつ]に二日[ふつか]で読[よ]み終[お]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小説", "label": "基本形"}, {"form": "小説の", "label": "連体形（の）"}], "register": "neutral", "sense_fingerprint": "作者が物語や出来事を書いた、読み物としての本や文章（フィクションの作品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小説", "is_correct": true, "explanation": "「書簡体の物語」を指す読み物の語で、「おもしろい小説です」と自然につながる。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "台所の家電で、読み物の作品を指さないため「おもしろい冷蔵庫です」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、作品ではないため「おもしろい天気です」は意味が通らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、物語を指さないため「おもしろい砂糖です」は合わない。"}], "explanations": {"小説": "「書簡体の物語」を指す読み物の語で、「おもしろい小説です」と自然につながる。", "冷蔵庫": "台所の家電で、読み物の作品を指さないため「おもしろい冷蔵庫です」は成り立たない。", "天気": "空模様を表す語で、作品ではないため「おもしろい天気です」は意味が通らない。", "砂糖": "食品で、物語を指さないため「おもしろい砂糖です」は合わない。"}, "sentence_index": 0, "correct_answer": "小説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は、料理を作る前に分量を小説で確かめた。", "explanation": "ここは〈レシピ〉の意味。料理の分量や手順を確かめるのはレシピで、小説では分量は確認できない。"}, {"text": "研究の結果を小説にまとめて、学会で発表した。", "explanation": "ここは〈論文〉の意味。研究の報告は論文で、作り話の小説とは合わない。"}, {"text": "店名を書いた小説を、入り口の上に掲げた。", "explanation": "ここは〈看板〉の意味。店の名前を示して掲げるのは看板で、小説を入り口に掲げるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小説", "is_correct": true, "explanation": "長くて難しかったと感じられる読み物を指し、結末に感動したという内容に合う。"}, {"text": "掃除機", "is_correct": false, "explanation": "家電で、結末のある作品ではないため「掃除機は長くて難しかった」は合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家電で、結末に感動する対象にはならないため文が成り立たない。"}, {"text": "味噌", "is_correct": false, "explanation": "食品で、結末に感動するような内容を持たないため合わない。"}], "explanations": {"小説": "長くて難しかったと感じられる読み物を指し、結末に感動したという内容に合う。", "掃除機": "家電で、結末のある作品ではないため「掃除機は長くて難しかった」は合わない。", "洗濯機": "家電で、結末に感動する対象にはならないため文が成り立たない。", "味噌": "食品で、結末に感動するような内容を持たないため合わない。"}, "sentence_index": 6, "correct_answer": "小説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "言葉の意味がわからないとき、小説を引く。", "explanation": "ここは〈辞書〉の意味。言葉の意味を調べる本は辞書で、小説は引いて調べるものではない。"}, {"text": "妹は毎朝、小説を弾いて家族を起こす。", "explanation": "ここは〈楽器〉の意味。楽器は弾くもので、小説は弾けないので合わない。"}, {"text": "会議の内容は小説に記録する。", "explanation": "ここは〈議事録〉の意味。会議の記録は議事録に残すもので、小説に記録するとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達が書いた小説が、夏休みに全部読んだ。", "corrected_sentence": "友達が書いた小説を、夏休みに全部読んだ。", "error_description": "誤りは「小説が」の「が」。「読んだ」の目的語なので、対象を表す「を」が正しい。「が」だと小説が読む主体になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51466, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人が勧めてくれた小説を、とても感動した。", "corrected_sentence": "友人が勧めてくれた小説に、とても感動した。", "error_description": "誤りは「小説を」の「を」。「感動した」は原因を「に」で示すので、「を」は誤り。正しくは「小説に感動した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題を示す「は」。「技法は、今も弟子に伝えられています」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、受身の文では「技法を」が主語にならず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すので、「技法に、今も伝えられています」は不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、「技法から、今も伝えられています」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "話題を示す「は」。「技法は、今も弟子に伝えられています」と自然につながる。", "を": "「を」は目的語を示すが、受身の文では「技法を」が主語にならず成り立たない。", "に": "「に」は相手や方向を示すので、「技法に、今も伝えられています」は不自然になる。", "から": "「から」は起点を表すので、「技法から、今も伝えられています」は意味が通らない。"}, "error_tags": {"に": "相手・方向", "から": "起点・理由", "を": "対象"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするときの、特別なやり方や方法のことです。", "primary_collocate": null, "pronunciation": "ぎほう", "ipa": "ɡihoː", "syllable_count": 3, "sentences": [{"text": "この画家は、独特の技法で光を表現しています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "この画家(がか)は、独特(どくとく)の技法(ぎほう)で光(ひかり)を表現(ひょうげん)しています。", "sentence_source": "generated"}, {"text": "昔の職人の技法は、今も弟子に伝えられています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "昔(むかし)の職人(しょくにん)の技法(ぎほう)は、今(いま)も弟子(でし)に伝(つた)えられています。", "sentence_source": "generated"}, {"text": "水彩画の技法を学ぶために、教室に通っています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "水彩画(すいさいが)の技法(ぎほう)を学(まな)ぶために、教室(きょうしつ)に通(かよ)っています。", "sentence_source": "generated"}, {"text": "新しい技法を取り入れて、料理の味が変わりました。", "target_word": "技法", "complexity_tier": "T3", "furigana": "新(あたら)しい技法(ぎほう)を取(と)り入(い)れて、料理(りょうり)の味(あじ)が変(か)わりました。", "sentence_source": "generated"}, {"text": "彼は、さまざまな技法を使い分けて物語を書きます。", "target_word": "技法", "complexity_tier": "T3", "furigana": "彼(かれ)は、さまざまな技法(ぎほう)を使(つか)い分(わ)けて物語(ものがたり)を書(か)きます。", "sentence_source": "generated"}, {"text": "写真の技法を学ぶと、光の使い方がわかります。", "target_word": "技法", "complexity_tier": "T3", "furigana": "写真(しゃしん)の技法(ぎほう)を学(まな)ぶと、光(ひかり)の使(つか)い方(かた)がわかります。", "sentence_source": "generated"}, {"text": "この陶器は、江戸時代から続く技法で作られています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "この陶器(とうき)は、江戸時代(えどじだい)から続(つづ)く技法(ぎほう)で作(つく)られています。", "sentence_source": "generated"}, {"text": "先生は、絵の具を重ねる技法を実際に見せてくれました。", "target_word": "技法", "complexity_tier": "T3", "furigana": "先生(せんせい)は、絵(え)の具(ぐ)を重(かさ)ねる技法(ぎほう)を実際(じっさい)に見(み)せてくれました。", "sentence_source": "generated"}, {"text": "この映画では、古い技法と新しい技法が組み合わされています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "この映画(えいが)では、古(ふる)い技法(ぎほう)と新(あたら)しい技法(ぎほう)が組(く)み合(あ)わされています。", "sentence_source": "generated"}, {"text": "伝統的な技法を守りながら、新しい作品を生み出しています。", "target_word": "技法", "complexity_tier": "T3", "furigana": "伝統的(でんとうてき)な技法(ぎほう)を守(まも)りながら、新(あたら)しい作品(さくひん)を生(う)み出(だ)しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "技法", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "芸術や工芸などで使う専門的な表現・制作の方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab72206-6277-420c-88d0-f9c8f74db76f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技法", "is_correct": true, "explanation": "独特のやり方や方法を表し、「独特の技法で光を表現しています」と合う。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いの性質で、光を表すやり方にはならない。"}, {"text": "感触", "is_correct": false, "explanation": "感触は触ったときの感じで、光を表す方法の意味には合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は食べ物の性質で、絵で光を表す手段にはならない。"}], "explanations": {"技法": "独特のやり方や方法を表し、「独特の技法で光を表現しています」と合う。", "香り": "香りは匂いの性質で、光を表すやり方にはならない。", "感触": "感触は触ったときの感じで、光を表す方法の意味には合わない。", "味": "味は食べ物の性質で、絵で光を表す手段にはならない。"}, "sentence_index": 0, "correct_answer": "技法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店には、腕のいい技法が三人います。", "explanation": "ここは〈職人〉（その仕事をする人）の意味。技法は方法を指すので、人を数える言い方には合わない。"}, {"text": "この教室の技法は、月に二万円です。", "explanation": "ここは〈料金〉（払うお金）の意味。技法は方法なので、払う金額にはならない。"}, {"text": "次の技法の日時を確認してください。", "explanation": "ここは〈予約〉（日時を決めて取っておくこと）の意味。技法には日時がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技法", "is_correct": true, "explanation": "物の作り方を表し、「江戸時代から続く技法で作られています」と自然につながる。"}, {"text": "日付", "is_correct": false, "explanation": "日付は暦の上の日のことで、物の作り方を表す語ではない。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、作り方を表す語ではない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は呼び名で、物の作り方として使えない。"}], "explanations": {"技法": "物の作り方を表し、「江戸時代から続く技法で作られています」と自然につながる。", "日付": "日付は暦の上の日のことで、物の作り方を表す語ではない。", "値段": "値段は価格で、作り方を表す語ではない。", "名前": "名前は呼び名で、物の作り方として使えない。"}, "sentence_index": 6, "correct_answer": "技法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この料理には、新鮮な技法を使います。", "explanation": "ここは〈材料〉（料理に使う食材）の意味。技法は作り方なので、「新鮮な」と合わない。"}, {"text": "大会の技法は、明日発表します。", "explanation": "ここは〈大会の結果〉の意味。技法は方法なので、発表する内容にはならない。"}, {"text": "この地域は、技法が温暖です。", "explanation": "ここは〈気候〉（天候の傾向）の意味。技法は温暖になるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この職人は、古い技法を器を作ります。", "corrected_sentence": "この職人は、古い技法で器を作ります。", "error_description": "「古い技法で」（手段の「で」）が正しい。「技法を」にすると「器を」と目的語が二つ並び、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その彫刻家は、珍しい技法を使いこなすています。", "corrected_sentence": "その彫刻家は、珍しい技法を使いこなしています。", "error_description": "「使いこなしています」が正しい。「使いこなすています」は動詞「使いこなす」の活用が誤りで、「使いこなして」に「いる」をつける必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd726b0d-35a3-4f22-b835-653a682508c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「書簡のように」の形で名詞に付く「の」。「のように」として自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "対象を表すが、「書簡をように」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や相手を表すが、「書簡にように」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主格を表すが、「書簡がように」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「書簡のように」の形で名詞に付く「の」。「のように」として自然に成り立つ。", "を": "対象を表すが、「書簡をように」は成り立たない。", "に": "帰着点や相手を表すが、「書簡にように」は成り立たない。", "が": "主格を表すが、「書簡がように」では文が成り立たない。"}, "error_tags": {"を": "対象", "に": "帰着・相手", "が": "主格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「書簡の形式」と名詞をつなぐ「の」で、文の意味に合い自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すため、「書簡で形式は」は文の骨組みに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「書簡へ形式は」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すため、「書簡より形式は」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「書簡の形式」と名詞をつなぐ「の」で、文の意味に合い自然。", "で": "手段を表すため、「書簡で形式は」は文の骨組みに合わない。", "へ": "方向を表すため、「書簡へ形式は」は成り立たない。", "より": "比較を表すため、「書簡より形式は」では意味が通らない。"}, "error_tags": {"で": "手段", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「書簡」は、手紙の形式や文体を指す言葉で、特に改まった場面で使われる、簡潔で正式な書き方を意味します。", "primary_collocate": null, "pronunciation": "しょかん", "ipa": "ɕokaɴ", "syllable_count": 3, "sentences": [{"text": "部長は、取引先への連絡を書簡の形式で行うことが多い。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は、取引先[とりひきさき]への連絡[れんらく]を書簡[しょかん]の形式[けいしき]で行[おこな]うことが多[おお]い。", "sentence_source": "generated"}, {"text": "改まった場面では、書簡のように簡潔で正式な書き方をすることが望ましい。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "改[あらた]まった場面[ばめん]では、書簡[しょかん]のように簡潔[かんけつ]で正式[せいしき]な書き方[かきかた]をすることが望ましい。", "sentence_source": "generated"}, {"text": "昔の人は、遠くの友人に近況を伝えるとき、書簡の形式で書いていた。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、遠[とお]くの友人[ゆうじん]に近況[きんきょう]を伝[つた]えるとき、書簡[しょかん]の形式[けいしき]で書[か]いていた。", "sentence_source": "generated"}, {"text": "公式な場面では、メールより書簡の形式のほうが正式だと考えられている。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "公式[こうしき]な場面[ばめん]では、メールより書簡[しょかん]の形式[けいしき]のほうが正式[せいしき]だと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "この作家は、友人への便りでも必ず書簡の形式を守っていた。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "この作家[さっか]は、友人[ゆうじん]への便[たよ]りでも必[かなら]ず書簡[しょかん]の形式[けいしき]を守[まも]っていた。", "sentence_source": "generated"}, {"text": "社長は取引先へのお礼を、簡潔な書簡の形式で書いた。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は取引先[とりひきさき]へのお礼[おれい]を、簡潔[かんけつ]な書簡[しょかん]の形式[けいしき]で書[か]いた。", "sentence_source": "generated"}, {"text": "書簡の形式では、季節のあいさつと相手を気づかう言葉を入れるのが普通だった。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "書簡[しょかん]の形式[けいしき]では、季節[きせつ]のあいさつと相手[あいて]を気[き]づかう言葉[ことば]を入[い]れるのが普通[ふつう]だった。", "sentence_source": "generated"}, {"text": "祖父が手紙を書いたときの書簡の形式は、相手への敬意がよく表れている。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "祖父[そふ]が手紙[てがみ]を書[か]いたときの書簡[しょかん]の形式[けいしき]は、相手[あいて]への敬意[けいい]がよく表[あらわ]れている。", "sentence_source": "generated"}, {"text": "改まったお願いなので、電話ではなく書簡の形式でお伝えします。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "改[あらた]まったお願[ねが]いなので、電話[でんわ]ではなく書簡[しょかん]の形式[けいしき]でお伝[つた]えします。", "sentence_source": "generated"}, {"text": "その書簡の形式は簡潔だったが、感謝の気持ちがしっかり伝わった。", "target_word": "書簡", "complexity_tier": "T3", "furigana": "その書簡[しょかん]の形式[けいしき]は簡潔[かんけつ]だったが、感謝[かんしゃ]の気持[きも]ちがしっかり伝[つた]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書簡", "label": "基本形"}, {"form": "書簡で", "label": "手段（で）"}], "register": "formal", "sense_fingerprint": "改まった場面で使う、簡潔で正式な手紙（の書き方・文体）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T4: contains vocabulary far above tier T4: 気づかう (Zipf 1.39)']::text[], 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書簡", "is_correct": true, "explanation": "手紙の形式を表す語で、「書簡の形式で行う」として自然につながる。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "台所の家電で、連絡の形式を表さないため「冷蔵庫の形式で行う」は成り立たない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除の道具で、連絡の形式とは言えない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食品で、連絡の形式を表さないため合わない。"}], "explanations": {"書簡": "手紙の形式を表す語で、「書簡の形式で行う」として自然につながる。", "冷蔵庫": "台所の家電で、連絡の形式を表さないため「冷蔵庫の形式で行う」は成り立たない。", "掃除機": "掃除の道具で、連絡の形式とは言えない。", "砂糖": "食品で、連絡の形式を表さないため合わない。"}, "sentence_index": 0, "correct_answer": "書簡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本の大事な箇所に、書簡を小さく切って貼った。", "explanation": "ここは〈付箋〉の意味。本の目印として小さく貼るのは付箋で、書簡は手紙の形式を指すので本に貼る物ではない。"}, {"text": "画家は、風景を書簡に描いた。", "explanation": "ここは〈絵〉の意味。風景を描くのは絵で、書簡は文章の形式なので描くことはできない。"}, {"text": "この書簡は冷蔵庫で冷やして飲むものだ。", "explanation": "ここは〈飲料〉の意味。冷やして飲むのは飲料で、書簡は読む文章の形式なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書簡", "is_correct": true, "explanation": "手紙の形式を表し、「書簡の形式では」として季節のあいさつを入れる文に自然につながる。"}, {"text": "掃除機", "is_correct": false, "explanation": "家電で、文の形式を表さないため「掃除機の形式では」は合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家電で、手紙の書き方とは関係がないため文が成り立たない。"}, {"text": "味噌", "is_correct": false, "explanation": "食品で、手紙の形式とは関係がないため合わない。"}], "explanations": {"書簡": "手紙の形式を表し、「書簡の形式では」として季節のあいさつを入れる文に自然につながる。", "掃除機": "家電で、文の形式を表さないため「掃除機の形式では」は合わない。", "洗濯機": "家電で、手紙の書き方とは関係がないため文が成り立たない。", "味噌": "食品で、手紙の形式とは関係がないため合わない。"}, "sentence_index": 6, "correct_answer": "書簡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究の結果を書簡にまとめて、学会で発表した。", "explanation": "ここは〈論文〉の意味。研究の成果を学術的にまとめたものは論文で、書簡とは言わない。"}, {"text": "新商品の広告を、書簡に載せた。", "explanation": "ここは〈広告〉の意味。商品を宣伝する文は広告で、新聞や雑誌に載せるものを書簡とは呼ばない。"}, {"text": "言葉の意味は、書簡で調べるのが一番早い。", "explanation": "ここは〈辞書〉の意味。言葉の意味を調べる本は辞書で、相手に送る書簡では調べられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、遠くに住む家族に書簡が送った。", "corrected_sentence": "祖母は、遠くに住む家族に書簡を送った。", "error_description": "誤りは「書簡が」の「が」。「送った」の目的語は書簡なので、対象の「を」が正しい。「が」では書簡が送る主体になり、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51470, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "社長は、取引先に感謝の書簡を立てた。", "corrected_sentence": "社長は、取引先に感謝の書簡を書いた。", "error_description": "誤りは「立てた」。書簡は書く・送るものなので、「立てる」とは続かない。正しくは「書いた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
