INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51471, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "細かいところまで気を配り、しっかりと作られているさま。", "primary_collocate": null, "pronunciation": "ちみつ", "ipa": "tɕimitsɯ", "syllable_count": 3, "sentences": [{"text": "この時計は緻密な部品でできている。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "この時計[とけい]は緻密[ちみつ]な部品[ぶひん]でできている。", "sentence_source": "generated"}, {"text": "この緻密な計画は、ミスが少ない。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "この緻密[ちみつ]な計画[けいかく]は、ミスが少[すく]ない。", "sentence_source": "generated"}, {"text": "緻密に作られた模型に、みんなおどろいた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "緻密[ちみつ]に作[つく]られた模型[もけい]に、みんなおどろいた。", "sentence_source": "generated"}, {"text": "この絵は緻密に描かれていて、葉の一枚一枚まで見える。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "この絵[え]は緻密[ちみつ]に描[えが]かれていて、葉[は]の一枚[いちまい]一枚[いちまい]まで見[み]える。", "sentence_source": "generated"}, {"text": "先生は緻密に調べて、小さな間違いも見つけた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "先生[せんせい]は緻密[ちみつ]に調[しら]べて、小[ちい]さな間違[まちが]いも見[み]つけた。", "sentence_source": "generated"}, {"text": "緻密な作業が続いて、目がとても疲れた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "緻密[ちみつ]な作業[さぎょう]が続[つづ]いて、目[め]がとても疲[つか]れた。", "sentence_source": "generated"}, {"text": "建築家は緻密な図面を何枚もかいた。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "建築家[けんちくか]は緻密[ちみつ]な図面[ずめん]を何枚[なんまい]もかいた。", "sentence_source": "generated"}, {"text": "実験は緻密に行わないと、正しい結果が出ない。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "実験[じっけん]は緻密[ちみつ]に行[おこな]わないと、正[ただ]しい結果[けっか]が出[で]ない。", "sentence_source": "generated"}, {"text": "緻密に織られた布は、水を通しにくい。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "緻密[ちみつ]に織[お]られた布[ぬの]は、水[みず]を通[とお]しにくい。", "sentence_source": "generated"}, {"text": "彼女の緻密な説明のおかげで、問題がよくわかった。", "target_word": "緻密", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の緻密[ちみつ]な説明[せつめい]のおかげで、問題[もんだい]がよくわかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緻密だ", "label": "終止形"}, {"form": "緻密な", "label": "連体形"}, {"form": "緻密に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "細部まで注意が行き届き、精巧で隙がないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de7ed79c-919b-44ee-a142-5d1255fc3aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51471, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緻密", "is_correct": true, "explanation": "ここに入るのは〈緻密〉。部品が細部まで作り込まれていることを表す。"}, {"text": "陽気", "is_correct": false, "explanation": "〈陽気〉は人の性格を表す語で、部品には使わないので合わない。"}, {"text": "賑やか", "is_correct": false, "explanation": "〈賑やか〉は人や場所のにぎわいを表す語で、部品の様子には合わないので合わない。"}, {"text": "穏やか", "is_correct": false, "explanation": "〈穏やか〉は気候や性格に使う語で、部品の様子には合わないので合わない。"}], "explanations": {"緻密": "ここに入るのは〈緻密〉。部品が細部まで作り込まれていることを表す。", "陽気": "〈陽気〉は人の性格を表す語で、部品には使わないので合わない。", "賑やか": "〈賑やか〉は人や場所のにぎわいを表す語で、部品の様子には合わないので合わない。", "穏やか": "〈穏やか〉は気候や性格に使う語で、部品の様子には合わないので合わない。"}, "sentence_index": 0, "correct_answer": "緻密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "緻密な雨が朝から降り続いた。", "explanation": "ここは〈細かい〉の意味。雨粒が細かいことを言うもので、緻密は細部の作り込みを表すので合わない。"}, {"text": "このコーヒーはとても緻密だ。", "explanation": "ここは〈濃い〉の意味。味や色の濃さを言うもので、緻密は細部の作り込みなので合わない。"}, {"text": "緻密な風が、帽子を飛ばした。", "explanation": "ここは〈気まぐれ〉の意味。『気まぐれな風』のように移り変わりの予測しにくさを表すもので、緻密は作り込みの細かさなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51471, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緻密", "is_correct": true, "explanation": "ここに入るのは〈緻密〉。図面を細部まで丁寧に描いたことを表す。"}, {"text": "元気", "is_correct": false, "explanation": "〈元気〉は人の活力を表す語で、図面には使わないので合わない。"}, {"text": "静か", "is_correct": false, "explanation": "〈静か〉は音や様子を表す語で、図面の細かさを言う場面には合わないので合わない。"}, {"text": "健康", "is_correct": false, "explanation": "〈健康〉は体の状態を表す語で、図面には使わないので合わない。"}], "explanations": {"緻密": "ここに入るのは〈緻密〉。図面を細部まで丁寧に描いたことを表す。", "元気": "〈元気〉は人の活力を表す語で、図面には使わないので合わない。", "静か": "〈静か〉は音や様子を表す語で、図面の細かさを言う場面には合わないので合わない。", "健康": "〈健康〉は体の状態を表す語で、図面には使わないので合わない。"}, "sentence_index": 6, "correct_answer": "緻密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緻密な祭りで、町中が盛り上がった。", "explanation": "ここは〈にぎやか〉の意味。人が集まって騒がしい様子を言うもので、緻密は細部の作り込みなので合わない。"}, {"text": "緻密な声で、みんなを励ました。", "explanation": "ここは〈力強い〉の意味。声の迫力を言うもので、緻密は細部の精密さを表すので合わない。"}, {"text": "緻密な色の花が咲いた。", "explanation": "ここは〈淡い〉の意味。色の薄さを言うもので、緻密は細部の作り込みなので色には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51471, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この時計は緻密の作りで、ほとんど狂わない。", "corrected_sentence": "この時計は緻密な作りで、ほとんど狂わない。", "error_description": "『緻密な作り』が正しい。『緻密』は名詞を修飾するとき『な』が必要で、『の』では名詞を修飾できないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "緻密な", "is_correct": true, "explanation": "連体形で、後ろの名詞『計画』を修飾するここに入る形。"}, {"text": "緻密だ", "is_correct": false, "explanation": "終止形で、名詞『計画』の前には置けないので合わない。"}, {"text": "緻密に", "is_correct": false, "explanation": "連用形で、動詞を修飾する形。名詞『計画』を直接修飾できないので合わない。"}, {"text": "緻密で", "is_correct": false, "explanation": "『で』で続く形で、名詞『計画』を直接修飾できないので合わない。"}], "correct_form": "緻密な", "base_form": "緻密だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"緻密な": "連体形で、後ろの名詞『計画』を修飾するここに入る形。", "緻密だ": "終止形で、名詞『計画』の前には置けないので合わない。", "緻密に": "連用形で、動詞を修飾する形。名詞『計画』を直接修飾できないので合わない。", "緻密で": "『で』で続く形で、名詞『計画』を直接修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51471, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、ミスの原因を緻密なまとめた。", "corrected_sentence": "先生は、ミスの原因を緻密にまとめた。", "error_description": "『緻密にまとめた』が正しい。動詞『まとめた』を修飾するには連用形『に』が必要。『な』は名詞を修飾する形なので、動詞の前では誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "緻密に", "is_correct": true, "explanation": "連用形で、動詞『行う』を修飾するここに入る形。"}, {"text": "緻密である", "is_correct": false, "explanation": "『である』の形で、動詞『行う』を修飾できないので合わない。"}, {"text": "緻密だった", "is_correct": false, "explanation": "過去の形で、動詞の直前に置くと文が成り立たないので合わない。"}, {"text": "緻密ではない", "is_correct": false, "explanation": "否定の形で、後ろの動詞を修飾する形にはならないので合わない。"}], "correct_form": "緻密に", "base_form": "緻密だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"緻密に": "連用形で、動詞『行う』を修飾するここに入る形。", "緻密である": "『である』の形で、動詞『行う』を修飾できないので合わない。", "緻密だった": "過去の形で、動詞の直前に置くと文が成り立たないので合わない。", "緻密ではない": "否定の形で、後ろの動詞を修飾する形にはならないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a83fa6f-9a1e-47be-9db8-bfb3c21e75d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「報告書を仕上げた」の目的語を示す格助詞で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「報告書が仕上げた」では報告書が主語になり、徹夜で仕上げた文と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「報告書に仕上げた」では対象を示せず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「報告書と仕上げた」は共同の意味になり、対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「報告書を仕上げた」の目的語を示す格助詞で、正解。", "が": "「報告書が仕上げた」では報告書が主語になり、徹夜で仕上げた文と合わない。", "に": "「報告書に仕上げた」では対象を示せず、不自然。", "と": "「報告書と仕上げた」は共同の意味になり、対象を表せない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「スライドを仕上げ」の目的語を示す格助詞で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「スライドが完璧に仕上げておいた」は主語を示すが、他動詞「仕上げる」は目的語を必要とし、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「スライドへ完璧に仕上げ」と結べず、対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は「スライドから完璧に仕上げ」と結ぶと対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「スライドを仕上げ」の目的語を示す格助詞で、正解。", "が": "「スライドが完璧に仕上げておいた」は主語を示すが、他動詞「仕上げる」は目的語を必要とし、文が成立しない。", "へ": "方向を表す「へ」は「スライドへ完璧に仕上げ」と結べず、対象を示せない。", "から": "起点を表す「から」は「スライドから完璧に仕上げ」と結ぶと対象を示せず、不自然。"}, "error_tags": {"が": "主格", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事を完成させること。特に、最後の細かい部分を整えて完全な状態にすること。", "primary_collocate": null, "pronunciation": "しあげる", "ipa": "ɕiaɡeɾɯ", "syllable_count": 4, "sentences": [{"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "酵母[こうぼ]の活動[かつどう]を観察[かんさつ]しながら生地[きじ]を仕上[しあ]げ、いよいよ焼成[しょうせい]へと進[すす]みます。", "sentence_source": "mined"}, {"text": "締め切りに間に合うように、徹夜で報告書を仕上げた。", "target_word": "仕上げた", "complexity_tier": "T3", "furigana": "締[し]め切[き]りに間[ま]に合[あ]うように、徹夜[てつや]で報告書[ほうこくしょ]を仕上[しあ]げた。", "sentence_source": "generated"}, {"text": "明日までにこのレポートを仕上げなければならない。", "target_word": "仕上げ", "complexity_tier": "T3", "furigana": "明日[あした]までにこのレポートを仕上[しあ]げなければならない。", "sentence_source": "generated"}, {"text": "職人は丁寧にやすりをかけて、木の箱を仕上げている。", "target_word": "仕上げている", "complexity_tier": "T3", "furigana": "職人[しょくにん]は丁寧[ていねい]にやすりをかけて、木[き]の箱[はこ]を仕上[しあ]げている。", "sentence_source": "generated"}, {"text": "母は編んでいたセーターをやっと仕上げて、孫に送った。", "target_word": "仕上げて", "complexity_tier": "T3", "furigana": "母[はは]は編[あ]んでいたセーターをやっと仕上[しあ]げて、孫[まご]に送[おく]った。", "sentence_source": "generated"}, {"text": "宿題を早く仕上げれば、夕方から友達と遊べる。", "target_word": "仕上げれば", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を早[はや]く仕上[しあ]げれば、夕方[ゆうがた]から友達[ともだち]と遊[あそ]べる。", "sentence_source": "generated"}, {"text": "最後に塗装をして家具を仕上げると、新品のように光った。", "target_word": "仕上げる", "complexity_tier": "T3", "furigana": "最後[さいご]に塗装[とそう]をして家具[かぐ]を仕上[しあ]げると、新品[しんぴん]のように光[ひか]った。", "sentence_source": "generated"}, {"text": "発表の前の晩に、スライドを完璧に仕上げておいた。", "target_word": "仕上げて", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の前[まえ]の晩[ばん]に、スライドを完璧[かんぺき]に仕上[しあ]げておいた。", "sentence_source": "generated"}, {"text": "彼は三日で小説を仕上げたが、見直す時間がなかった。", "target_word": "仕上げた", "complexity_tier": "T3", "furigana": "彼[かれ]は三日[みっか]で小説[しょうせつ]を仕上[しあ]げたが、見直[みなお]す時間[じかん]がなかった。", "sentence_source": "generated"}, {"text": "生クリームを塗り、いちごを飾ってケーキを仕上げます。", "target_word": "仕上げます", "complexity_tier": "T3", "furigana": "生[なま]クリームを塗[ぬ]り、いちごを飾[かざ]ってケーキを仕上[しあ]げます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仕上げる", "label": "終止形"}, {"form": "仕上げ", "label": "連用形"}, {"form": "仕上げて", "label": "て形"}, {"form": "仕上げた", "label": "た形"}, {"form": "仕上げない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "最後の細かい部分を整えて物事を完成させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仕上げ", "is_correct": true, "explanation": "「生地を〜、」と続く連用形で、この空欄に入る唯一の形。文の流れにも合う。"}, {"text": "仕上がり", "is_correct": false, "explanation": "名詞の「仕上がり」は「生地を」の後に置けず、文が成立しない。"}, {"text": "仕上がる", "is_correct": false, "explanation": "自動詞「仕上がる」は目的語の「生地を」と結びつかないため不自然。"}, {"text": "仕上げられ", "is_correct": false, "explanation": "受け身の連用形は「生地を」と合わず、文の意味が崩れる。"}], "explanations": {"仕上げ": "「生地を〜、」と続く連用形で、この空欄に入る唯一の形。文の流れにも合う。", "仕上がり": "名詞の「仕上がり」は「生地を」の後に置けず、文が成立しない。", "仕上がる": "自動詞「仕上がる」は目的語の「生地を」と結びつかないため不自然。", "仕上げられ": "受け身の連用形は「生地を」と合わず、文の意味が崩れる。"}, "sentence_index": 0, "correct_answer": "仕上げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に蛇口を仕上げて、台所を出た。", "explanation": "ここは〈締める〉の意味。仕上げるは作業や作品を完成させることで、蛇口を閉める動作には使わない。"}, {"text": "彼は先輩にけんかを仕上げた。", "explanation": "ここは〈仕掛ける〉の意味。仕上げるは完成させることで、けんかを始める意味にはならない。"}, {"text": "彼は長年の夢を仕上げた。", "explanation": "ここは〈成し遂げる〉の意味。仕上げるは作業や作品の最後の仕上げを指し、夢には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仕上げる", "is_correct": true, "explanation": "終止形で「と」に続き、家具を完成させる文として正解。"}, {"text": "光る", "is_correct": false, "explanation": "自動詞なので目的語の「家具を」と結べず、「家具を光ると」は文が成立しない。"}, {"text": "乾く", "is_correct": false, "explanation": "自動詞なので「家具を」と結べず、塗装が乾く意味にもならず不自然。"}, {"text": "届く", "is_correct": false, "explanation": "自動詞なので「家具を」と結べず、届く意味になって仕上げる行為を表せない。"}], "explanations": {"仕上げる": "終止形で「と」に続き、家具を完成させる文として正解。", "光る": "自動詞なので目的語の「家具を」と結べず、「家具を光ると」は文が成立しない。", "乾く": "自動詞なので「家具を」と結べず、塗装が乾く意味にもならず不自然。", "届く": "自動詞なので「家具を」と結べず、届く意味になって仕上げる行為を表せない。"}, "sentence_index": 6, "correct_answer": "仕上げる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猟師は一発で獲物を仕上げた。", "explanation": "ここは〈仕留める〉の意味。仕上げるは作業や作品の完成を指し、獲物を捕らえる意味では使わない。"}, {"text": "廊下の明かりを仕上げてから、寝室に入った。", "explanation": "ここは〈消す〉の意味。仕上げるは完成させることで、明かりを消す動作には使わない。"}, {"text": "雨を仕上げて、ようやく外へ出た。", "explanation": "ここは〈止める〉の意味。仕上げるは完成させることで、雨や動きを止める意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "締め切りまでに論文を仕上がらなければならない。", "corrected_sentence": "締め切りまでに論文を仕上げなければならない。", "error_description": "「論文を」の後には他動詞「仕上げる」が必要だが、自動詞「仕上がる」になっている。正しくは「仕上げなければならない」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "仕上げた", "is_correct": true, "explanation": "過去の「た形」で、文末に置いて事実を述べる正解。"}, {"text": "仕上げ", "is_correct": false, "explanation": "連用形だけでは文が終わらず、述語として成立しない。"}, {"text": "仕上げない", "is_correct": false, "explanation": "否定形なので、徹夜で完成させた事実と合わない。"}, {"text": "仕上げられた", "is_correct": false, "explanation": "受け身になり、「報告書を」と結ぶと文が成立しない。"}], "correct_form": "仕上げた", "base_form": "仕上げる", "form_label": "た形", "sentence_index": 1, "explanations": {"仕上げた": "過去の「た形」で、文末に置いて事実を述べる正解。", "仕上げ": "連用形だけでは文が終わらず、述語として成立しない。", "仕上げない": "否定形なので、徹夜で完成させた事実と合わない。", "仕上げられた": "受け身になり、「報告書を」と結ぶと文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51474, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの宿題に仕上げて、ようやく遊びに行けた。", "corrected_sentence": "夏休みの宿題を仕上げて、ようやく遊びに行けた。", "error_description": "「仕上げる」の目的語には「を」を使う。「に」にすると対象が示せず不自然になるので、「宿題を」に直す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "仕上げて", "is_correct": true, "explanation": "て形で「おいた」に続き、完成させておいた意味になる正解。"}, {"text": "仕上げよう", "is_correct": false, "explanation": "意向形で「これから完成させよう」という意思を表し、「おいた」と続かず、完成済みの事実と合わない。"}, {"text": "仕上げれば", "is_correct": false, "explanation": "仮定形で「〜ば」の条件節になり、「おいた」で文を終える形にはならず、文が成立しない。"}, {"text": "仕上げられて", "is_correct": false, "explanation": "受け身になり、「スライドを」と結ぶと文が成立しない。"}], "correct_form": "仕上げて", "base_form": "仕上げる", "form_label": "て形", "sentence_index": 7, "explanations": {"仕上げて": "て形で「おいた」に続き、完成させておいた意味になる正解。", "仕上げよう": "意向形で「これから完成させよう」という意思を表し、「おいた」と続かず、完成済みの事実と合わない。", "仕上げれば": "仮定形で「〜ば」の条件節になり、「おいた」で文を終える形にはならず、文が成立しない。", "仕上げられて": "受け身になり、「スライドを」と結ぶと文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
