INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「愈」は、物事がついにその段階に達する様子や、程度がさらに進むことを表す副詞です。", "primary_collocate": null, "pronunciation": "いよいよ", "ipa": "ijoji", "syllable_count": 4, "sentences": [{"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "酵母[こうぼ]の活動[かつどう]を観察[かんさつ]しながら生地[きじ]を仕上[しあ]げ、いよいよ焼成[しょうせい]へと進[すす]みます。", "sentence_source": "mined"}, {"text": "長い準備を終えて、明日はいよいよ試合の日だ。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "長[なが]い準備[じゅんび]を終[お]えて、明日[あした]はいよいよ試合[しあい]の日[ひ]だ。", "sentence_source": "generated"}, {"text": "三年間の留学を終えて、いよいよ来週帰国します。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "三年間[さんねんかん]の留学[りゅうがく]を終[お]えて、いよいよ来週[らいしゅう]帰国[きこく]します。", "sentence_source": "generated"}, {"text": "雨が強くなり、川の水がいよいよ危険な高さになってきた。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]くなり、川[かわ]の水[みず]がいよいよ危険[きけん]な高[たか]さになってきた。", "sentence_source": "generated"}, {"text": "夜が更けるにつれて、寒さはいよいよ厳しくなった。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "夜[よる]が更[ふ]けるにつれて、寒[さむ]さはいよいよ厳[きび]しくなった。", "sentence_source": "generated"}, {"text": "発表の順番が来て、私はいよいよ緊張してきた。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の順番[じゅんばん]が来[き]て、私[わたし]はいよいよ緊張[きんちょう]してきた。", "sentence_source": "generated"}, {"text": "長く待っていた新しい店が、今日いよいよ開店する。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "長[なが]く待[ま]っていた新[あたら]しい店[みせ]が、今日[きょう]いよいよ開店[かいてん]する。", "sentence_source": "generated"}, {"text": "試験まであと一日で、いよいよ本番だと思うと眠れなかった。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "試験[しけん]まであと一日[いちにち]で、いよいよ本番[ほんばん]だと思[おも]うと眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "病気が悪化して、彼の体力はいよいよ弱っていった。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "病気[びょうき]が悪化[あっか]して、彼[かれ]の体力[たいりょく]はいよいよ弱[よわ]っていった。", "sentence_source": "generated"}, {"text": "工事が終わり、いよいよ新しい橋が使われはじめる。", "target_word": "いよいよ", "complexity_tier": "T3", "furigana": "工事[こうじ]が終[お]わり、いよいよ新[あたら]しい橋[はし]が使[つか]われはじめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "いよいよ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "待っていた段階についに達する、または程度がさらに進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "いよいよ", "is_correct": true, "explanation": "待っていた段階に進むことを表す副詞で、「焼成へと進みます」に自然につながる正解。"}, {"text": "まったく", "is_correct": false, "explanation": "「まったく」は否定を伴う副詞で、肯定の「進みます」には続かない。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は打ち消しと呼応する副詞で、肯定文では使えない。"}, {"text": "なかなか", "is_correct": false, "explanation": "「なかなか」は否定と一緒に使うため、「進みます」の肯定文とは合わない。"}], "explanations": {"いよいよ": "待っていた段階に進むことを表す副詞で、「焼成へと進みます」に自然につながる正解。", "まったく": "「まったく」は否定を伴う副詞で、肯定の「進みます」には続かない。", "決して": "「決して」は打ち消しと呼応する副詞で、肯定文では使えない。", "なかなか": "「なかなか」は否定と一緒に使うため、「進みます」の肯定文とは合わない。"}, "sentence_index": 0, "correct_answer": "いよいよ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は雨の日でも、いよいよ傘は使わない。", "explanation": "ここは〈決して〉の意味。いよいよは段階の到達を表すので、否定を強める使い方には合わない。"}, {"text": "甘いものは全部好きだが、いよいよ果物が一番好きだ。", "explanation": "ここは〈とりわけ〉の意味。いよいよは段階の到達を表すので、好みの中から特に選ぶ意味にはならない。"}, {"text": "私は毎朝、いよいよ六時に起きる。", "explanation": "ここは〈いつも〉の意味。いよいよは一度きりの段階について言うので、毎日の習慣には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "いよいよ", "is_correct": true, "explanation": "待っていた店が開く段階に達することを表す正解。「今日」に続けて自然。"}, {"text": "めったに", "is_correct": false, "explanation": "「めったに」は否定と呼応する副詞で、肯定の「開店する」とは合わない。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "「ぜんぜん」は打ち消しを伴うため、肯定文の「開店する」には続かない。"}, {"text": "あまり", "is_correct": false, "explanation": "「あまり」は通常否定と使うため、肯定の文脈では不自然になる。"}], "explanations": {"いよいよ": "待っていた店が開く段階に達することを表す正解。「今日」に続けて自然。", "めったに": "「めったに」は否定と呼応する副詞で、肯定の「開店する」とは合わない。", "ぜんぜん": "「ぜんぜん」は打ち消しを伴うため、肯定文の「開店する」には続かない。", "あまり": "「あまり」は通常否定と使うため、肯定の文脈では不自然になる。"}, "sentence_index": 6, "correct_answer": "いよいよ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "メールを受け取ると、いよいよすぐに返事をした。", "explanation": "ここは〈即座〉の意味。いよいよは期待していた段階に達する場面に使い、反射的な素早い反応には合わない。"}, {"text": "いよいよゆっくり歩いて、駅へ向かった。", "explanation": "ここは〈緩慢に〉の意味。いよいよは段階の到達を表すので、ゆっくりした動作の様子には使わない。"}, {"text": "うっかりいよいよ傘を忘れた。", "explanation": "ここは〈不注意にも〉の意味。いよいよは期待された段階に達することを表し、不注意による忘れ物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日はいよいよに大会の日だ。", "corrected_sentence": "明日はいよいよ大会の日だ。", "error_description": "副詞「いよいよ」に格助詞「に」を付けている。「いよいよ」はそのまま「大会の日」にかかるので、「に」は不要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51476, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒さがいよいよに厳しくなった。", "corrected_sentence": "寒さがいよいよ厳しくなった。", "error_description": "副詞の「いよいよ」に格助詞「に」を付けている。「いよいよ」はそのまま「厳しく」にかかるので、「に」は不要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「窯で焼成して」の手段や場所を表す格助詞で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「窯が焼成して」では窯が行為者になり、文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「窯に焼成して」は場所への方向として不自然で、焼成の手段を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「窯へ焼成して」と結べず、文が成立しない。"}], "correct_answer": "で", "explanations": {"で": "「窯で焼成して」の手段や場所を表す格助詞で、正解。", "が": "「窯が焼成して」では窯が行為者になり、文の意味が合わない。", "に": "「窯に焼成して」は場所への方向として不自然で、焼成の手段を表せない。", "へ": "方向を表す「へ」は「窯へ焼成して」と結べず、文が成立しない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「焼成を終えた」の目的語を示す格助詞で、正解。"}, {"text": "と", "is_correct": false, "explanation": "「焼成と終えた」は並列や引用の意味になり、目的語を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は「焼成より終えた」と結べず、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」は「焼成から終えた」と結ぶと対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「焼成を終えた」の目的語を示す格助詞で、正解。", "と": "「焼成と終えた」は並列や引用の意味になり、目的語を表せない。", "より": "比較を表す「より」は「焼成より終えた」と結べず、意味が通らない。", "から": "起点を表す「から」は「焼成から終えた」と結ぶと対象を示せず、不自然。"}, "error_tags": {"と": "共同・引用", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "材料を加熱して、食品や陶器などを仕上げる工程。", "primary_collocate": null, "pronunciation": "しょうせい", "ipa": "ɕoːseː", "syllable_count": 4, "sentences": [{"text": "酵母の活動を観察しながら生地を仕上げ、いよいよ焼成へと進みます。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "酵母[こうぼ]の活動[かつどう]を観察[かんさつ]しながら生地[きじ]を仕上[しあ]げ、いよいよ焼成[しょうせい]へと進[すす]みます。", "sentence_source": "mined"}, {"text": "陶器は成形した後、窯で焼成して初めて硬くなる。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "陶器[とうき]は成形[せいけい]した後[あと]、窯[かま]で焼成[しょうせい]して初[はじ]めて硬[かた]くなる。", "sentence_source": "generated"}, {"text": "この工房では、焼成に約十二時間かかります。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "この工房[こうぼう]では、焼成[しょうせい]に約[やく]十二時間[じゅうにじかん]かかります。", "sentence_source": "generated"}, {"text": "焼成の温度が低すぎると、器がもろくなってしまう。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "焼成[しょうせい]の温度[おんど]が低[ひく]すぎると、器[うつわ]がもろくなってしまう。", "sentence_source": "generated"}, {"text": "窯で焼成した陶板を、冷めるまで待ってから取り出した。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "窯(かま)で焼成(しょうせい)した陶板(とうばん)を、冷(さ)めるまで待(ま)ってから取(と)り出(だ)した。", "sentence_source": "generated"}, {"text": "レンガは粘土を高温で焼成して作られる。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "レンガは粘土[ねんど]を高温[こうおん]で焼成[しょうせい]して作[つく]られる。", "sentence_source": "generated"}, {"text": "焼成の途中で窯の扉を開けると、器がひび割れることがある。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "焼成(しょうせい)の途中(とちゅう)で窯(かま)の扉(とびら)を開(あ)けると、器(うつわ)がひび割(わ)れることがある。", "sentence_source": "generated"}, {"text": "彼は焼成を終えた皿を一枚ずつ丁寧に確かめた。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "彼[かれ]は焼成[しょうせい]を終[お]えた皿[さら]を一枚[いちまい]ずつ丁寧[ていねい]に確[たし]かめた。", "sentence_source": "generated"}, {"text": "窯の火加減が難しく、焼成には熟練の技が必要だ。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "窯[かま]の火加減[ひかげん]が難[むずか]しく、焼成[しょうせい]には熟練[じゅくれん]の技[わざ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "粘土の厚さによって、焼成の時間は変わる。", "target_word": "焼成", "complexity_tier": "T3", "furigana": "粘土(ねんど)の厚(あつ)さによって、焼成(しょうせい)の時間(じかん)は変(か)わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焼成", "label": "基本形"}, {"form": "焼成する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "材料を高温で加熱して食品や陶器に仕上げる工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焼成", "is_correct": true, "explanation": "材料を高温で焼き固める工程で、「いよいよ〜へと進みます」の流れに合う正解。"}, {"text": "採取", "is_correct": false, "explanation": "採取は材料や資料を集める意味で、パン作りの次の工程としては意味が合わない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は客が品物を頼む意味で、製造工程の段階を表せない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作物を取り入れる意味で、生地を焼く段階には当てはまらない。"}], "explanations": {"焼成": "材料を高温で焼き固める工程で、「いよいよ〜へと進みます」の流れに合う正解。", "採取": "採取は材料や資料を集める意味で、パン作りの次の工程としては意味が合わない。", "注文": "注文は客が品物を頼む意味で、製造工程の段階を表せない。", "収穫": "収穫は作物を取り入れる意味で、生地を焼く段階には当てはまらない。"}, "sentence_index": 0, "correct_answer": "焼成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "心の傷を焼成して、やっと忘れられた。", "explanation": "ここは〈消し去る〉の意味。焼成は材料を高温で焼き固める工程で、心の傷を消す意味では使わない。"}, {"text": "会議用の報告書を焼成した。", "explanation": "ここは〈作成〉の意味。焼成は材料を高温で焼き固める工程で、書類を作る意味では使わない。"}, {"text": "雨の日は洗濯物を焼成して乾かす。", "explanation": "ここは〈乾燥〉の意味。焼成は高温で焼き固めることで、洗濯物を乾かす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焼成", "is_correct": true, "explanation": "加熱して仕上げる工程で、窯の扉を開けると割れるという文脈に合う正解。"}, {"text": "面会", "is_correct": false, "explanation": "面会は人と会う意味で、窯の工程を表す語としては合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地中から資源を掘り出す意味で、陶器の焼成とは関係がない。"}, {"text": "送迎", "is_correct": false, "explanation": "送迎は人を送り迎えする意味で、窯の作業の途中とは結びつかない。"}], "explanations": {"焼成": "加熱して仕上げる工程で、窯の扉を開けると割れるという文脈に合う正解。", "面会": "面会は人と会う意味で、窯の工程を表す語としては合わない。", "採掘": "採掘は地中から資源を掘り出す意味で、陶器の焼成とは関係がない。", "送迎": "送迎は人を送り迎えする意味で、窯の作業の途中とは結びつかない。"}, "sentence_index": 6, "correct_answer": "焼成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議で出た議題を焼成して、結論を出した。", "explanation": "ここは〈決定する〉の意味。焼成は材料を高温で焼き固める工程で、議論の結論を出す意味では使わない。"}, {"text": "名刺を焼成して、百枚ほど用意した。", "explanation": "ここは〈印刷〉の意味。焼成は器や陶器を焼く工程で、紙に文字を写す意味にはならない。"}, {"text": "昨日の書類を焼成して、すっかり処分した。", "explanation": "ここは〈燃やして捨てる〉の意味。焼成は材料を高温で焼き固める工程で、書類を処分する意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工房では、焼成を一晩かかります。", "corrected_sentence": "この工房では、焼成に一晩かかります。", "error_description": "「焼成に一晩かかる」と時間を表すなら「に」が必要。「を」は目的語を示すため、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は焼成を終わった皿を、すぐに窯から出した。", "corrected_sentence": "彼は焼成を終えた皿を、すぐに窯から出した。", "error_description": "「焼成を」の後には他動詞「終える」が必要。自動詞「終わる」は目的語の「を」と合わないので「終えた」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『よく出る』の主語を示す。スプリングが出来事の主体になる。"}, {"text": "を", "is_correct": false, "explanation": "『出る』は自動詞なので目的語の『を』は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、『よく出た』の主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "『〜と一緒に』の意味になり、ここでは主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "『よく出る』の主語を示す。スプリングが出来事の主体になる。", "を": "『出る』は自動詞なので目的語の『を』は取れない。", "へ": "方向を示すが、『よく出た』の主語にはならない。", "と": "『〜と一緒に』の意味になり、ここでは主語を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段・原因を示す。スプリングの膨らむ勢いで生地が裂ける、という意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「スプリングへ生地が横に裂けて」と結べず、原因を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、原因を表せず文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、ここでは原因の意味にならず、文脈に合わない。"}], "correct_answer": "で", "explanations": {"で": "手段・原因を示す。スプリングの膨らむ勢いで生地が裂ける、という意味になる。", "へ": "方向を表す「へ」は「スプリングへ生地が横に裂けて」と結べず、原因を示せない。", "より": "比較を示すが、原因を表せず文が成り立たない。", "から": "起点を示すが、ここでは原因の意味にならず、文脈に合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "パンがオーブンの中で急に大きくなることです。", "primary_collocate": null, "pronunciation": "すぷりんぐ", "ipa": "sɯpɯɾiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "オーブンに入れたとたん、スプリングで生地がぐんと伸びた。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "オーブンに入[い]れたとたん、スプリングで生地[きじ]がぐんと伸[の]びた。", "sentence_source": "generated"}, {"text": "スプリングがよく出たので、食パンは型の上まで盛り上がった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングがよく出[で]たので、食[しょく]パンは型[かた]の上[うえ]まで盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "熱い蒸気が生地を押し広げることで、スプリングが起きる。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "熱[あつ]い蒸気[じょうき]が生地[きじ]を押[お]し広[ひろ]げることで、スプリングが起きる。", "sentence_source": "generated"}, {"text": "生地が冷たすぎると、スプリングが遅れることがある。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "生地[きじ]が冷[つめ]たすぎると、スプリングが遅[おく]れることがある。", "sentence_source": "generated"}, {"text": "強力粉のパンは、スプリングが大きくなりやすい。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "強力粉[きょうりきこ]のパンは、スプリングが大[おお]きくなりやすい。", "sentence_source": "generated"}, {"text": "スプリングの途中で扉を開けると、パンがしぼんでしまう。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングの途中[とちゅう]で扉[とびら]を開[あ]けると、パンがしぼんでしまう。", "sentence_source": "generated"}, {"text": "彼女はスプリングを見たくて、毎回オーブンの前で待っている。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はスプリングを見[み]たくて、毎回[まいかい]オーブンの前[まえ]で待[ま]っている。", "sentence_source": "generated"}, {"text": "切り込みが浅いと、スプリングで生地が横に裂けてしまう。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "切[き]り込[こ]みが浅[あさ]いと、スプリングで生地[きじ]が横[よこ]に裂[さ]けてしまう。", "sentence_source": "generated"}, {"text": "焼き上がりの高さは、スプリングの大きさで決まる。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "焼[や]き上[あ]がりの高[たか]さは、スプリングの大[おお]きさで決[き]まる。", "sentence_source": "generated"}, {"text": "スプリングが止まった後は、中までしっかり火を通す。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングが止[と]まった後[あと]は、中[なか]までしっかり火[ひ]を通[とお]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スプリング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "パンがオーブンの中で急に大きく膨らむこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スプリング", "is_correct": true, "explanation": "パンがオーブン内で急に膨らむ現象を表し、「伸びた」という文脈に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "甘みを加える材料で、オーブンの中で生地を伸ばす現象の原因にはならない。"}, {"text": "牛乳", "is_correct": false, "explanation": "生地の水分を調整する材料で、オーブン内で生地を急に伸ばす働きはない。"}, {"text": "塩", "is_correct": false, "explanation": "グルテンの働きを助ける材料だが、オーブン内で生地を急に伸ばす直接の原因ではない。"}], "explanations": {"スプリング": "パンがオーブン内で急に膨らむ現象を表し、「伸びた」という文脈に合う。", "砂糖": "甘みを加える材料で、オーブンの中で生地を伸ばす現象の原因にはならない。", "牛乳": "生地の水分を調整する材料で、オーブン内で生地を急に伸ばす働きはない。", "塩": "グルテンの働きを助ける材料だが、オーブン内で生地を急に伸ばす直接の原因ではない。"}, "sentence_index": 0, "correct_answer": "スプリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パンの皮は、焼きすぎるとスプリングになる。", "explanation": "ここは〈硬くなる〉の意味。皮の状態は硬くなるで言い、スプリングはオーブンで生地が急に膨らむ現象なので、皮には使えない。"}, {"text": "スプリングの季節になると、店先に桜餅が並ぶ。", "explanation": "ここは〈春〉の意味。生地が膨らむ現象の文脈では使えない。"}, {"text": "一次スプリングを一時間行って、生地を二倍にする。", "explanation": "ここは〈発酵〉の意味。スプリングは焼成中に急に膨らむ現象で、焼く前の一次発酵の工程には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スプリング", "is_correct": true, "explanation": "パンがオーブン内で膨らむ様子を見たい、という文脈に合う。"}, {"text": "卵", "is_correct": false, "explanation": "見て待つ対象として不自然で、オーブン内の変化とは関係しない。"}, {"text": "包丁", "is_correct": false, "explanation": "切るための道具で、オーブンの前で見て待つ対象ではなく、文脈に合わない。"}, {"text": "計量カップ", "is_correct": false, "explanation": "材料を量る道具で、オーブン内の膨らむ様子を見る対象にはならない。"}], "explanations": {"スプリング": "パンがオーブン内で膨らむ様子を見たい、という文脈に合う。", "卵": "見て待つ対象として不自然で、オーブン内の変化とは関係しない。", "包丁": "切るための道具で、オーブンの前で見て待つ対象ではなく、文脈に合わない。", "計量カップ": "材料を量る道具で、オーブン内の膨らむ様子を見る対象にはならない。"}, "sentence_index": 6, "correct_answer": "スプリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この服は、袖のスプリングがきれいだ。", "explanation": "ここは〈膨らみ〉の意味。服の袖の形なら膨らみを使い、スプリングはオーブンで生地が急に膨らむ現象なので、服の形には使えない。"}, {"text": "スプリングを逃がすため、扉に小さな穴を開ける。", "explanation": "ここは〈蒸気〉の意味。スプリングは生地が膨らむ現象で、物として逃がすことはできない。"}, {"text": "パンの表面に、スプリングがきれいについた。", "explanation": "ここは〈焼き色〉の意味。表面の色づきは焼き色で言い、スプリングは生地の膨張なので、色の文脈には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "低温では、生地のスプリングをなかなか起きない。", "corrected_sentence": "低温では、生地のスプリングがなかなか起きない。", "error_description": "『起きる』は自動詞なので主語を示す『が』が正しい。『を』は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51485, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強力粉の生地は、スプリングがよく出す。", "corrected_sentence": "強力粉の生地は、スプリングがよく出る。", "error_description": "『出る』は自動詞で主語の『が』と結びつく。『出す』は他動詞で、『スプリングが』と合わないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「スプリングが起こった」の主語を示す格助詞で、正解。"}, {"text": "を", "is_correct": false, "explanation": "「スプリングを起こった」と目的語にすると、自動詞「起こる」と合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「スプリングへ起こった」と結べず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「スプリングと起こった」は共同の意味になり、現象の主体を示せない。"}], "correct_answer": "が", "explanations": {"が": "「スプリングが起こった」の主語を示す格助詞で、正解。", "を": "「スプリングを起こった」と目的語にすると、自動詞「起こる」と合わず不自然。", "へ": "方向を表す「へ」は「スプリングへ起こった」と結べず、意味が通らない。", "と": "「スプリングと起こった」は共同の意味になり、現象の主体を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「スプリングの様子」の所属を示す格助詞で、正解。"}, {"text": "が", "is_correct": false, "explanation": "「スプリングが様子」と主語にすると、名詞同士がつながらず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「スプリングに様子」では位置や相手の意味にならず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「スプリングで様子」は手段の意味になり、「様子」と結べない。"}], "correct_answer": "の", "explanations": {"の": "「スプリングの様子」の所属を示す格助詞で、正解。", "が": "「スプリングが様子」と主語にすると、名詞同士がつながらず不自然。", "に": "「スプリングに様子」では位置や相手の意味にならず、文が成立しない。", "で": "「スプリングで様子」は手段の意味になり、「様子」と結べない。"}, "error_tags": {"が": "主格", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "オーブンの中でパンが焼けるときに、中の空気や水蒸気が熱で膨らんで、パンが急に大きくなる現象のことです。", "primary_collocate": null, "pronunciation": "すぷりんぐ", "ipa": "sɯpɯɾiŋɡɯ", "syllable_count": 5, "sentences": [{"text": "これを「オーブンスプリング」と呼びます。", "target_word": "オーブンスプリング", "complexity_tier": "T3", "furigana": "これを「オーブンスプリング」と呼[よ]びます。", "sentence_source": "mined"}, {"text": "焼き始めて五分ほどで、パンのスプリングが目に見えて起こった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "焼[や]き始[はじ]めて五分[ごふん]ほどで、パンのスプリングが目[め]に見[み]えて起[お]こった。", "sentence_source": "generated"}, {"text": "生地が発酵しすぎると、スプリングが小さくなってしまう。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "生地[きじ]が発酵[はっこう]しすぎると、スプリングが小[ちい]さくなってしまう。", "sentence_source": "generated"}, {"text": "スプリングのおかげで、パンは焼く前より一回り大きくなった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングのおかげで、パンは焼[や]く前[まえ]より一回[ひとまわ]り大[おお]きくなった。", "sentence_source": "generated"}, {"text": "窯の温度が低いと、スプリングが十分に出ない。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "窯[かま]の温度[おんど]が低[ひく]いと、スプリングが十分[じゅうぶん]に出[で]ない。", "sentence_source": "generated"}, {"text": "切れ目を入れておくと、スプリングで生地がきれいに開く。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "切[き]れ目[め]を入[い]れておくと、スプリングで生地[きじ]がきれいに開[ひら]く。", "sentence_source": "generated"}, {"text": "スプリングが終わるころに、パンの表面は固まりはじめる。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "スプリングが終[お]わるころに、パンの表面[ひょうめん]は固[かた]まりはじめる。", "sentence_source": "generated"}, {"text": "先生は、スプリングの様子をオーブンの窓から見せてくれた。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "先生[せんせい]は、スプリングの様子[ようす]をオーブンの窓[まど]から見[み]せてくれた。", "sentence_source": "generated"}, {"text": "蒸気を入れるのは、スプリングをよくするためだ。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "蒸気[じょうき]を入[い]れるのは、スプリングをよくするためだ。", "sentence_source": "generated"}, {"text": "今日のバゲットは、スプリングが弱くて少しつぶれた形になった。", "target_word": "スプリング", "complexity_tier": "T3", "furigana": "今日[きょう]のバゲットは、スプリングが弱[よわ]くて少[すこ]しつぶれた形[かたち]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スプリング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "パンがオーブンの熱で急に膨らむ現象（オーブンスプリング）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d0a981c-3ffd-4367-ac70-36156b437484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オーブンスプリング", "is_correct": true, "explanation": "パンがオーブンの熱で急に膨らむ現象の名称で、「これを〜と呼びます」に入る正解。"}, {"text": "グルテン", "is_correct": false, "explanation": "グルテンは小麦粉のたんぱく質の名前で、膨らむ現象を指す語ではない。"}, {"text": "乳酸発酵", "is_correct": false, "explanation": "乳酸発酵は微生物の働きによる変化で、オーブンでの膨らみを指さない。"}, {"text": "糖化", "is_correct": false, "explanation": "糖化はでんぷんが糖になる変化で、パンが急に膨らむ現象とは別物。"}], "explanations": {"オーブンスプリング": "パンがオーブンの熱で急に膨らむ現象の名称で、「これを〜と呼びます」に入る正解。", "グルテン": "グルテンは小麦粉のたんぱく質の名前で、膨らむ現象を指す語ではない。", "乳酸発酵": "乳酸発酵は微生物の働きによる変化で、オーブンでの膨らみを指さない。", "糖化": "糖化はでんぷんが糖になる変化で、パンが急に膨らむ現象とは別物。"}, "sentence_index": 0, "correct_answer": "オーブンスプリング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜のあいだ、冷蔵庫で生地をスプリングさせておいた。", "explanation": "ここは〈発酵〉の意味。スプリングはオーブンの熱で起こる膨らみで、冷蔵庫での発酵には使わない。"}, {"text": "鍋のお湯がスプリングして、ぐらぐら煮えた。", "explanation": "ここは〈沸騰〉の意味。スプリングはパンが焼ける時の膨らみで、お湯の沸騰には使わない。"}, {"text": "焼き上がったパンがスプリングして、へこんだ。", "explanation": "ここは〈収縮する〉の意味。スプリングは熱で膨らむ現象で、縮む方向の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スプリング", "is_correct": true, "explanation": "パンが膨らむ現象で、「が終わるころに」に入ると表面が固まる流れに合う正解。"}, {"text": "ダイヤル", "is_correct": false, "explanation": "ダイヤルは回して操作する部品で、焼成中の現象の終わりとは結びつかない。"}, {"text": "クラム", "is_correct": false, "explanation": "クラムはパンの内側の部分を指し、終わるという動きとは結びつかない。"}, {"text": "シェイプ", "is_correct": false, "explanation": "シェイプは成形の作業を指し、焼成中の現象の終わりとは関係がない。"}], "explanations": {"スプリング": "パンが膨らむ現象で、「が終わるころに」に入ると表面が固まる流れに合う正解。", "ダイヤル": "ダイヤルは回して操作する部品で、焼成中の現象の終わりとは結びつかない。", "クラム": "クラムはパンの内側の部分を指し、終わるという動きとは結びつかない。", "シェイプ": "シェイプは成形の作業を指し、焼成中の現象の終わりとは関係がない。"}, "sentence_index": 6, "correct_answer": "スプリング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "焼けたパンを網の上でスプリングして、冷ました。", "explanation": "ここは〈冷却〉の意味。スプリングはオーブン内でパンが膨らむ現象で、焼いたあとに冷やす動作には使わない。"}, {"text": "凍ったパンをスプリングして、柔らかくした。", "explanation": "ここは〈解凍〉の意味。スプリングは加熱中に起こる膨らみで、凍ったものを解かす意味にはならない。"}, {"text": "パンがスプリングして真っ黒になった。", "explanation": "ここは〈焦げる〉の意味。スプリングは膨らむ現象で、焦げて黒くなる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窯の火を強くしたら、スプリングをよく出た。", "corrected_sentence": "窯の火を強くしたら、スプリングがよく出た。", "error_description": "「出る」は自動詞なので、主語のスプリングには「が」を使う。「を」にすると文が成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窯の火が弱いと、スプリングが十分に入らない。", "corrected_sentence": "窯の火が弱いと、スプリングが十分に出ない。", "error_description": "オーブンスプリングは「出る」と言う。「入る」にすると現象の意味が通らないので、「出ない」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c6077d-e2cf-408b-a25f-99af80ba644b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "出資する金額を「を」で示す。「百万円を出資した」の形になる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、金額を動詞の対象にできない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すもので、金額の対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示すが、金額の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "出資する金額を「を」で示す。「百万円を出資した」の形になる。", "の": "「の」は名詞どうしをつなぐもので、金額を動詞の対象にできない。", "へ": "「へ」は方向を示すもので、金額の対象には使わない。", "と": "「と」は共同の相手を示すが、金額の対象にはならない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "並列・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "会社や店などの事業に、自分のお金を出すこと。利益目的かどうかは問わない。", "primary_collocate": null, "pronunciation": "しゅっし", "ipa": "ɕɯɕːi", "syllable_count": 3, "sentences": [{"text": "友達の店に出資して、毎月少しずつ配当をもらっている。", "target_word": "出資", "complexity_tier": "T3", "furigana": "友達(ともだち)の店(みせ)に出資(しゅっし)して、毎月(まいつき)少(すこ)しずつ配当(はいとう)をもらっている。", "sentence_source": "generated"}, {"text": "私は父の会社に百万円を出資した。", "target_word": "出資", "complexity_tier": "T3", "furigana": "私(わたし)は父(ちち)の会社(かいしゃ)に百万円(ひゃくまんえん)を出資(しゅっし)した。", "sentence_source": "generated"}, {"text": "この会社は、三つの銀行から出資を受けて作られた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "この会社(かいしゃ)は、三(みっ)つの銀行(ぎんこう)から出資(しゅっし)を受(う)けて作(つく)られた。", "sentence_source": "generated"}, {"text": "新しい店を開くために、親戚に出資をお願いした。", "target_word": "出資", "complexity_tier": "T3", "furigana": "新(あたら)しい店(みせ)を開(ひら)くために、親戚(しんせき)に出資(しゅっし)をお願(ねが)いした。", "sentence_source": "generated"}, {"text": "町の人たちが出資して、小さな映画館を守ることになった。", "target_word": "出資", "complexity_tier": "T3", "furigana": "町(まち)の人(ひと)たちが出資(しゅっし)して、小(ちい)さな映画館(えいがかん)を守(まも)ることになった。", "sentence_source": "generated"}, {"text": "出資はお金に余裕があるときだけにしたほうがいい。", "target_word": "出資", "complexity_tier": "T3", "furigana": "出資(しゅっし)はお金(かね)に余裕(よゆう)があるときだけにしたほうがいい。", "sentence_source": "generated"}, {"text": "社長は、会社を大きくするための出資を受け入れた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "社長(しゃちょう)は、会社(かいしゃ)を大(おお)きくするための出資(しゅっし)を受(う)け入(い)れた。", "sentence_source": "generated"}, {"text": "兄は出資した会社が倒産して、お金が戻ってこなかった。", "target_word": "出資", "complexity_tier": "T3", "furigana": "兄(あに)は出資(しゅっし)した会社(かいしゃ)が倒産(とうさん)して、お金(かね)が戻(もど)ってこなかった。", "sentence_source": "generated"}, {"text": "彼女は農家の新しい事業に出資することを決めた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は農家(のうか)の新(あたら)しい事業(じぎょう)に出資(しゅっし)することを決(き)めた。", "sentence_source": "generated"}, {"text": "出資を断られたので、計画を小さくして始めることにした。", "target_word": "出資", "complexity_tier": "T3", "furigana": "出資(しゅっし)を断(ことわ)られたので、計画(けいかく)を小(ちい)さくして始(はじ)めることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出資する", "label": "終止形"}, {"form": "出資した", "label": "過去形"}, {"form": "出資して", "label": "て形"}, {"form": "出資しない", "label": "否定形"}, {"form": "出資される", "label": "受身形"}], "register": "中立（普通体）", "sense_fingerprint": "会社や店などに自分のお金を出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出資", "is_correct": true, "explanation": "店に資金を出すという意味で、配当をもらう流れに合う。"}, {"text": "湿度", "is_correct": false, "explanation": "気象の数値で、店に対する行為にならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さで、店に対する行為にならない。"}, {"text": "気温", "is_correct": false, "explanation": "気象の数値で、店に対して行う動作にならない。"}], "explanations": {"出資": "店に資金を出すという意味で、配当をもらう流れに合う。", "湿度": "気象の数値で、店に対する行為にならない。", "体重": "体の重さで、店に対する行為にならない。", "気温": "気象の数値で、店に対して行う動作にならない。"}, "sentence_index": 0, "correct_answer": "出資"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "被災地の支援のため、親戚が見返りを求めずに十万円を出資した。", "explanation": "ここは〈寄付〉の場面。被災地への支援金は会社や店に出す資金ではないので、出資とは言わない。"}, {"text": "親戚は英語の契約書を日本語に出資した。", "explanation": "ここは〈翻訳〉の意味。出資は金銭を投じることで、文書の言語を変える意味はない。"}, {"text": "私は週末、庭の花壇に近所から集めた土を出資した。", "explanation": "ここは〈提供〉の場面。出資は会社や店などに金銭を出すことで、土のような物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出資", "is_correct": true, "explanation": "会社に資金を入れてもらう意味で、受け入れる対象になる。"}, {"text": "雨量", "is_correct": false, "explanation": "降水量で、受け入れる対象にならない。"}, {"text": "気圧", "is_correct": false, "explanation": "大気の圧力で、会社を大きくする手段にならない。"}, {"text": "酸素", "is_correct": false, "explanation": "気体で、会社を大きくする手段として受け入れられない。"}], "explanations": {"出資": "会社に資金を入れてもらう意味で、受け入れる対象になる。", "雨量": "降水量で、受け入れる対象にならない。", "気圧": "大気の圧力で、会社を大きくする手段にならない。", "酸素": "気体で、会社を大きくする手段として受け入れられない。"}, "sentence_index": 6, "correct_answer": "出資"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい冷蔵庫を十万円で出資した。", "explanation": "ここは〈購入〉の意味。出資はモノを買う支払いではなく、会社などへ資金を投じること。"}, {"text": "病気に備えて、毎月の保険料を出資している。", "explanation": "ここは〈掛け金〉の場面。病気への備えとして払う費用で、出資は事業に資金を提供すること。"}, {"text": "彼は毎朝八時に出資している。", "explanation": "ここは〈出勤〉の意味。出資は職場へ行くことではなく、金銭を投じること。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は父の店を出資して、経営に口を出している。", "corrected_sentence": "彼女は父の店に出資して、経営に口を出している。", "error_description": "「出資する」は出資先を「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は地元の製菓会社から出資に受けて、事業を広げた。", "corrected_sentence": "兄は地元の製菓会社から出資を受けて、事業を広げた。", "error_description": "「受ける」の目的語は「を」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に出資する」の形で、出資先を示す。"}, {"text": "を", "is_correct": false, "explanation": "出資は出資先を「に」で示すので、「を」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、動詞の相手を示さない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すため、会社から出資したと読むと資金の出し手が逆になり意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「〜に出資する」の形で、出資先を示す。", "を": "出資は出資先を「に」で示すので、「を」は誤り。", "の": "「の」は名詞どうしをつなぐもので、動詞の相手を示さない。", "から": "起点を表すため、会社から出資したと読むと資金の出し手が逆になり意味が通らない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "から": "起点を表すため、ここでは資金の出し手が逆になり意味が通らない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "事業などに資金を提供すること。利益を得る目的で、金銭を投じること。", "primary_collocate": null, "pronunciation": "しゅっし", "ipa": "ɕɯɕːi", "syllable_count": 3, "sentences": [{"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "出資", "complexity_tier": "T4", "furigana": "単(たん)なる出資(しゅっし)にとどまらず、経営(けいえい)戦略(せんりゃく)やネットワークを提供(ていきょう)することで、市場(しじょう)に新(あら)たな価値(かち)を生(う)むイノベーションを加速(かそく)させるのだ。", "sentence_source": "mined"}, {"text": "彼は新しい会社に出資したが、三年たっても利益が出ず、後悔している。", "target_word": "出資", "complexity_tier": "T3", "furigana": "彼(かれ)は新(あたら)しい会社(かいしゃ)に出資(しゅっし)したが、三年(さんねん)たっても利益(りえき)が出(で)ず、後悔(こうかい)している。", "sentence_source": "generated"}, {"text": "投資家たちは、成長が見込める新興企業への出資を増やしている。", "target_word": "出資", "complexity_tier": "T3", "furigana": "投資家(とうしか)たちは、成長(せいちょう)が見込(みこ)める新興(しんこう)企業(きぎょう)への出資(しゅっし)を増(ふ)やしている。", "sentence_source": "generated"}, {"text": "出資の見返りとして、会社の株式の二割を受け取った。", "target_word": "出資", "complexity_tier": "T3", "furigana": "出資(しゅっし)の見返(みかえ)りとして、会社(かいしゃ)の株式(かぶしき)の二割(にわり)を受(う)け取(と)った。", "sentence_source": "generated"}, {"text": "銀行は新工場の建設に出資する代わりに、経営の報告を求めた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "銀行(ぎんこう)は新(しん)工場(こうじょう)の建設(けんせつ)に出資(しゅっし)する代(か)わりに、経営(けいえい)の報告(ほうこく)を求(もと)めた。", "sentence_source": "generated"}, {"text": "起業したばかりの彼女は、知人に出資を頼んで開業資金を集めた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "起業(きぎょう)したばかりの彼女(かのじょ)は、知人(ちじん)に出資(しゅっし)を頼(たの)んで開業(かいぎょう)資金(しきん)を集(あつ)めた。", "sentence_source": "generated"}, {"text": "大手メーカーが出資を決めたため、その研究所は計画を大きく広げることができた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "大手(おおて)メーカーが出資(しゅっし)を決(き)めたため、その研究所(けんきゅうじょ)は計画(けいかく)を大(おお)きく広(ひろ)げることができた。", "sentence_source": "generated"}, {"text": "出資には損をする危険もあるので、よく調べてから決めるべきだ。", "target_word": "出資", "complexity_tier": "T3", "furigana": "出資(しゅっし)には損(そん)をする危険(きけん)もあるので、よく調(しら)べてから決(き)めるべきだ。", "sentence_source": "generated"}, {"text": "彼は利益を期待して、友人の飲食店に出資することにした。", "target_word": "出資", "complexity_tier": "T3", "furigana": "彼(かれ)は利益(りえき)を期待(きたい)して、友人(ゆうじん)の飲食店(いんしょくてん)に出資(しゅっし)することにした。", "sentence_source": "generated"}, {"text": "この映画は複数の企業が出資して作られ、公開後に大きな収益を上げた。", "target_word": "出資", "complexity_tier": "T3", "furigana": "この映画(えいが)は複数(ふくすう)の企業(きぎょう)が出資(しゅっし)して作(つく)られ、公開後(こうかいご)に大(おお)きな収益(しゅうえき)を上(あ)げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出資する", "label": "終止形"}, {"form": "出資した", "label": "過去形"}, {"form": "出資して", "label": "て形"}, {"form": "出資しない", "label": "否定形"}, {"form": "出資される", "label": "受身形"}], "register": "書き言葉（ビジネス）", "sense_fingerprint": "利益を目的に事業や会社へ資金を投じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出資", "is_correct": true, "explanation": "資金を提供する意味の「出資」で、単なる出資と経営支援が対比される。"}, {"text": "湿度", "is_correct": false, "explanation": "気象の数値で、資金提供との対比にならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さで、経営戦略と対比できない。"}, {"text": "気温", "is_correct": false, "explanation": "気象の数値で、「単なる〜にとどまらず」の対象にならない。"}], "explanations": {"出資": "資金を提供する意味の「出資」で、単なる出資と経営支援が対比される。", "湿度": "気象の数値で、資金提供との対比にならない。", "体重": "体の重さで、経営戦略と対比できない。", "気温": "気象の数値で、「単なる〜にとどまらず」の対象にならない。"}, "sentence_index": 0, "correct_answer": "出資"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎月の食費は、家計簿に出資として記録している。", "explanation": "ここは〈支出〉の意味。出資は利益を目的に会社などへ金を投じることで、生活費の出費を指さない。"}, {"text": "父は週末、庭の花壇に近所から集めた土を出資した。", "explanation": "ここは〈提供〉の場面。出資は利益を目的に金銭を投じることで、土のような物には使わない。"}, {"text": "彼は映画の主役として、三か月も出資した。", "explanation": "ここは〈出演〉の意味。出資は金を投じることで、役として画面に出る意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出資", "is_correct": true, "explanation": "事業への資金提供を決めたという意味で、文が通る。"}, {"text": "雨量", "is_correct": false, "explanation": "降水量で、会社が決める対象にならない。"}, {"text": "気圧", "is_correct": false, "explanation": "大気の圧力で、会社が決める対象にならない。"}, {"text": "酸素", "is_correct": false, "explanation": "気体で、会社が決める事業判断の対象にならない。"}], "explanations": {"出資": "事業への資金提供を決めたという意味で、文が通る。", "雨量": "降水量で、会社が決める対象にならない。", "気圧": "大気の圧力で、会社が決める対象にならない。", "酸素": "気体で、会社が決める事業判断の対象にならない。"}, "sentence_index": 6, "correct_answer": "出資"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "被災地の復興のため、この会社は全額を出資し、見返りは求めなかった。", "explanation": "ここは〈寄付〉の場面。見返りを求めない支援には出資は合わない。出資は利益などの見返りを期待して金を投じること。"}, {"text": "新しいパソコンを、十万円で出資した。", "explanation": "ここは〈購入〉の意味。出資はモノを手に入れる支払いではなく、事業に資金を提供すること。"}, {"text": "火事に備えて、毎月の保険料を出資している。", "explanation": "ここは〈掛け金〉の場面。災害への備えとして払う費用で、出資は事業に資金を提供すること。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は地元の工場を出資して、毎月の配当を楽しみにしている。", "corrected_sentence": "彼は地元の工場に出資して、毎月の配当を楽しみにしている。", "error_description": "「出資する」は出資先を「に」で示す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、地元の銀行から出資が受けて開業した。", "corrected_sentence": "その会社は、地元の銀行から出資を受けて開業した。", "error_description": "「受ける」の目的語は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "牽引の目的語を示す「を」。「成長を牽引」と続き、ここで正しい。"}, {"text": "に", "is_correct": false, "explanation": "「成長に牽引」は目的語にならず、牽引の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、牽引の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を表し、牽引の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "牽引の目的語を示す「を」。「成長を牽引」と続き、ここで正しい。", "に": "「成長に牽引」は目的語にならず、牽引の対象を示せない。", "へ": "「へ」は方向を表し、牽引の目的語にはならない。", "と": "「と」は並列や相手を表し、牽引の目的語にはならない。"}, "error_tags": {"に": "対象ではなく位置や相手を表すため、牽引の目的語にならない", "へ": "方向を表すため、牽引の対象には合わない", "と": "並列や相手を表すため、牽引の目的語にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "牽引の目的語を示す「を」。ここで正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、牽引の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表し、牽引の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を表し、動詞の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "牽引の目的語を示す「を」。ここで正しい。", "から": "「から」は起点を表し、牽引の目的語にはならない。", "より": "「より」は比較や起点を表し、牽引の目的語にはならない。", "の": "「の」は連体修飾を表し、動詞の目的語にはならない。"}, "error_tags": {"から": "起点を表すため、牽引の目的語にならない", "より": "比較や起点を表すため、牽引の目的語にならない", "の": "連体修飾を表すため、動詞の目的語にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を引っ張って進めること。特に、先頭に立って全体を動かすこと。", "primary_collocate": null, "pronunciation": "けんいん", "ipa": "keɴiɴ", "syllable_count": 4, "sentences": [{"text": "このような活動は、個々の企業利益だけでなく、社会全体の経済発展を牽引する原動力ともなっている。", "target_word": "牽引", "complexity_tier": "T4", "furigana": "このような活動(かつどう)は、個々(ここ)の企業(きぎょう)利益(りえき)だけでなく、社会(しゃかい)全体(ぜんたい)の経済(けいざい)発展(はってん)を牽引(けんいん)する原動力(げんどうりょく)ともなっている。", "sentence_source": "mined"}, {"text": "新しい技術の開発が、この地域の産業の成長を牽引している。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "新(あたら)しい技術(ぎじゅつ)の開発(かいはつ)が、この地域(ちいき)の産業(さんぎょう)の成長(せいちょう)を牽引(けんいん)している。", "sentence_source": "generated"}, {"text": "彼は若手の中心として、チームを牽引する役割を果たした。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "彼(かれ)は若手(わかて)の中心(ちゅうしん)として、チームを牽引(けんいん)する役割(やくわり)を果(は)たした。", "sentence_source": "generated"}, {"text": "輸出の伸びが景気回復を牽引したと、専門家は分析している。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "輸出(ゆしゅつ)の伸(の)びが景気(けいき)回復(かいふく)を牽引(けんいん)したと、専門家(せんもんか)は分析(ぶんせき)している。", "sentence_source": "generated"}, {"text": "創業者の強い指導力が、会社の急速な拡大を牽引した。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "創業者(そうぎょうしゃ)の強(つよ)い指導力(しどうりょく)が、会社(かいしゃ)の急速(きゅうそく)な拡大(かくだい)を牽引(けんいん)した。", "sentence_source": "generated"}, {"text": "観光業が地方の経済を牽引し、雇用も増えた。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "観光業(かんこうぎょう)が地方(ちほう)の経済(けいざい)を牽引(けんいん)し、雇用(こよう)も増(ふ)えた。", "sentence_source": "generated"}, {"text": "彼女は研究会を牽引してきたが、来年で代表を退く。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は研究会(けんきゅうかい)を牽引(けんいん)してきたが、来年(らいねん)で代表(だいひょう)を退(しりぞ)く。", "sentence_source": "generated"}, {"text": "情報技術の分野では、数社の大企業が市場全体を牽引している。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "情報(じょうほう)技術(ぎじゅつ)の分野(ぶんや)では、数社(すうしゃ)の大企業(だいきぎょう)が市場(しじょう)全体(ぜんたい)を牽引(けんいん)している。", "sentence_source": "generated"}, {"text": "一人の優れた選手が、チームの連勝を牽引することもある。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "一人(ひとり)の優(すぐ)れた選手(せんしゅ)が、チームの連勝(れんしょう)を牽引(けんいん)することもある。", "sentence_source": "generated"}, {"text": "若い世代の消費が、新しい流行を牽引している。", "target_word": "牽引", "complexity_tier": "T3", "furigana": "若(わか)い世代(せだい)の消費(しょうひ)が、新(あたら)しい流行(りゅうこう)を牽引(けんいん)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "牽引する", "label": "終止形"}, {"form": "牽引した", "label": "過去形"}, {"form": "牽引して", "label": "て形"}, {"form": "牽引しない", "label": "否定形"}, {"form": "牽引される", "label": "受身形"}], "register": "書き言葉（報道・ビジネス）", "sense_fingerprint": "先頭に立って集団や経済などを動かし進めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866b1129-2e8c-4bbb-8e31-7d683a7aed2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牽引", "is_correct": true, "explanation": "先頭に立って全体を動かす意味で、経済発展を動かす原動力の文脈に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味。経済発展を動かして進める文脈には合わない。"}, {"text": "離反", "is_correct": false, "explanation": "そむき離れる意味。原動力として経済を動かす文脈では使えない。"}, {"text": "漂流", "is_correct": false, "explanation": "あてもなく流される意味。動かして進める働きとは逆の状態を表す。"}], "explanations": {"牽引": "先頭に立って全体を動かす意味で、経済発展を動かす原動力の文脈に合う。", "撤去": "取り除く意味。経済発展を動かして進める文脈には合わない。", "離反": "そむき離れる意味。原動力として経済を動かす文脈では使えない。", "漂流": "あてもなく流される意味。動かして進める働きとは逆の状態を表す。"}, "sentence_index": 0, "correct_answer": "牽引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は先頭に立つのを避け、チームの最後尾で全体を牽引した。", "explanation": "ここは〈後押し〉の意味。先頭に立たず後ろから押す役割は後押しと言い、先頭で全体を動かす牽引とは合わない。"}, {"text": "係員が客を出口へ牽引した。", "explanation": "ここは〈誘導〉の意味。人を案内する場面で牽引を使うと、綱で引くような不自然な語になるので合わない。"}, {"text": "相手チームを牽引するため、守備を固めた。", "explanation": "ここは〈牽制〉の意味。相手の動きを抑える場面で、先頭で引っ張る牽引を使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牽引", "is_correct": true, "explanation": "研究会の先頭に立って全体を動かしてきたという意味で合う。"}, {"text": "停滞", "is_correct": false, "explanation": "自動詞なので『研究会を』と続けられず、文が成り立たない。"}, {"text": "散布", "is_correct": false, "explanation": "まき広げる意味。研究会を対象にすると意味をなさない。"}, {"text": "漂白", "is_correct": false, "explanation": "色を抜く意味。研究会を対象にする文脈では使えない。"}], "explanations": {"牽引": "研究会の先頭に立って全体を動かしてきたという意味で合う。", "停滞": "自動詞なので『研究会を』と続けられず、文が成り立たない。", "散布": "まき広げる意味。研究会を対象にすると意味をなさない。", "漂白": "色を抜く意味。研究会を対象にする文脈では使えない。"}, "sentence_index": 6, "correct_answer": "牽引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この書類の隅に、部長の牽引を押した。", "explanation": "ここは〈検印〉（同音語）の意味。牽引は引っ張って動かす語で、書類に押す印の意味では使わないので合わない。"}, {"text": "強い姿勢が、敵の侵略を牽引した。", "explanation": "ここは〈抑止〉の意味。牽引は先頭で引っ張って動かすことで、敵の動きを止める意味では使わないので合わない。"}, {"text": "友人を牽引して、映画を見に行った。", "explanation": "ここは〈誘う〉の意味。人を誘い出す場面に牽引は使わず、綱などで引く語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい工場の建設が、この地域の雇用の拡大に牽引している。", "corrected_sentence": "新しい工場の建設が、この地域の雇用の拡大を牽引している。", "error_description": "『牽引する』は他動詞で、動かす対象『雇用の拡大』は『を』で示す。『に』は誤りで、『を牽引している』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大手メーカーの新製品が、業界全体の成長を牽引されている。", "corrected_sentence": "大手メーカーの新製品が、業界全体の成長を牽引している。", "error_description": "目的語『成長』を『を』で示す他動詞『牽引する』を受身の『牽引される』にすると、目的語は『が』になり『を』は使えない。能動の『牽引している』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35119729-6016-47b6-be99-6360763a256e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "到着点を示す「オフィスに着く」の「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「着く」は目的語を取らないので、「オフィスを着いて」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するだけで、「着いて」という動詞に続けられない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すが、「着く」は到着点に「に」を取るので誤り。"}], "correct_answer": "に", "explanations": {"に": "到着点を示す「オフィスに着く」の「に」が正しい。", "を": "「着く」は目的語を取らないので、「オフィスを着いて」は成り立たない。", "の": "「の」は名詞を修飾するだけで、「着いて」という動詞に続けられない。", "で": "「で」は動作の場所を示すが、「着く」は到着点に「に」を取るので誤り。"}, "error_tags": {"を": "目的語の助詞。「着く」とは結びつかない", "の": "連体修飾の助詞。動詞に続けられない", "で": "動作の場所の助詞。到着の意味の「着く」には合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が仕事をするための場所のことです。", "primary_collocate": null, "pronunciation": "おふぃす", "ipa": "oɸisɯ", "syllable_count": 3, "sentences": [{"text": "私のオフィスは駅から歩いて五分のところにあります。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "私[わたし]のオフィスは駅[えき]から歩[ある]いて五分[ごふん]のところにあります。", "sentence_source": "generated"}, {"text": "朝八時にオフィスに着いて、メールを読みました。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "朝[あさ]八時[はちじ]にオフィスに着[つ]いて、メールを読[よ]みました。", "sentence_source": "generated"}, {"text": "このビルの三階に、新しいオフィスができた。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "このビルの三階[さんがい]に、新[あたら]しいオフィスができた。", "sentence_source": "generated"}, {"text": "オフィスの電気を消して、みんなで帰りました。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "オフィスの電気[でんき]を消[け]して、みんなで帰[かえ]りました。", "sentence_source": "generated"}, {"text": "在宅勤務の日は、オフィスへ行かなくてもいいです。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "在宅勤務[ざいたくきんむ]の日[ひ]は、オフィスへ行[い]かなくてもいいです。", "sentence_source": "generated"}, {"text": "広いオフィスなので、会議室がいくつもあります。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "広[ひろ]いオフィスなので、会議室[かいぎしつ]がいくつもあります。", "sentence_source": "generated"}, {"text": "雨がひどかったので、オフィスから出られなかった。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "雨[あめ]がひどかったので、オフィスから出[で]られなかった。", "sentence_source": "generated"}, {"text": "引っ越しのため、古いオフィスの荷物を箱につめた。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのため、古[ふる]いオフィスの荷物[にもつ]を箱[はこ]につめた。", "sentence_source": "generated"}, {"text": "来週からオフィスの席が自由に選べるようになる。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "来週[らいしゅう]からオフィスの席[せき]が自由[じゆう]に選[えら]べるようになる。", "sentence_source": "generated"}, {"text": "駅前のオフィスで、父は毎日働いています。", "target_word": "オフィス", "complexity_tier": "T3", "furigana": "駅前[えきまえ]のオフィスで、父[ちち]は毎日[まいにち]働[はたら]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オフィス", "label": "dictionary form"}, {"form": "オフィスの", "label": "attributive form"}, {"form": "オフィスで", "label": "location form"}, {"form": "オフィスに", "label": "destination form"}], "register": "neutral", "sense_fingerprint": "会社などで人が事務の仕事をする部屋や建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce891cbc-2525-4fa3-868e-3c2cf3f81b11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オフィス", "is_correct": true, "explanation": "場所を表す「オフィス」が入り、「駅から歩いて五分のところにある」と合う。"}, {"text": "趣味", "is_correct": false, "explanation": "趣味は場所ではないので、「駅から歩いて五分のところにある」とは結びつかない。"}, {"text": "意見", "is_correct": false, "explanation": "意見は場所ではないので、「ところにあります」とは合わない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は場所ではないので、「駅から歩いて五分のところにある」とは意味が通らない。"}], "explanations": {"オフィス": "場所を表す「オフィス」が入り、「駅から歩いて五分のところにある」と合う。", "趣味": "趣味は場所ではないので、「駅から歩いて五分のところにある」とは結びつかない。", "意見": "意見は場所ではないので、「ところにあります」とは合わない。", "夢": "夢は場所ではないので、「駅から歩いて五分のところにある」とは意味が通らない。"}, "sentence_index": 0, "correct_answer": "オフィス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに、オフィスで泳いだ。", "explanation": "ここは〈プール〉の意味。泳ぐ場所のプールは水のある施設で、仕事をする場所のオフィスでは泳がないので合わない。"}, {"text": "オフィスを一時間延長した。", "explanation": "ここは〈会議〉の意味。時間を延ばすのは会議や打ち合わせで、場所のオフィスは時間を延長できない。"}, {"text": "オフィスを三品作った。", "explanation": "ここは〈料理〉の意味。三品と数える食べ物を指すので、場所のオフィスは作る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オフィス", "is_correct": true, "explanation": "「雨がひどかったので、オフィスから出られなかった」の場所として、「オフィス」が入る。"}, {"text": "予定", "is_correct": false, "explanation": "予定は出ていく場所ではないので、「から出られなかった」とは合わない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は出ていく場所ではないので、「から出られなかった」とは意味が通らない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は出ていく場所ではないので、「から出られなかった」とは合わない。"}], "explanations": {"オフィス": "「雨がひどかったので、オフィスから出られなかった」の場所として、「オフィス」が入る。", "予定": "予定は出ていく場所ではないので、「から出られなかった」とは合わない。", "言葉": "言葉は出ていく場所ではないので、「から出られなかった」とは意味が通らない。", "宿題": "宿題は出ていく場所ではないので、「から出られなかった」とは合わない。"}, "sentence_index": 6, "correct_answer": "オフィス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "オフィスを受けて、結果を待った。", "explanation": "ここは〈試験〉の意味。受けるのは試験や面接で、場所のオフィスは受けられない。"}, {"text": "オフィスを一気に書き上げた。", "explanation": "ここは〈作文〉の意味。書き上げるのは文章で、場所のオフィスは書けない。"}, {"text": "オフィスをたくさん食べた。", "explanation": "ここは〈お菓子〉の意味。食べるのは食品で、場所のオフィスは食べられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51491, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月からオフィスに会議をすることになった。", "corrected_sentence": "来月からオフィスで会議をすることになった。", "error_description": "会議をする場所を示すのは「で」が正しい。「に」は到着点や存在の場所を示すので、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e815395-38fb-44bd-a5d9-4f260295d4be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
