INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「定型のため」は名詞「定型」に「の」が付き、理由を示す形として成立する。"}, {"text": "を", "is_correct": false, "explanation": "「定型をため」は成立せず、理由を示す形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「定型にため」は成立せず、理由を示す形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「定型でため」は成立せず、理由を示す形にならない。"}], "correct_answer": "の", "explanations": {"の": "「定型のため」は名詞「定型」に「の」が付き、理由を示す形として成立する。", "を": "「定型をため」は成立せず、理由を示す形にならない。", "に": "「定型にため」は成立せず、理由を示す形にならない。", "で": "「定型でため」は成立せず、理由を示す形にならない。"}, "error_tags": {"を": "目的語", "に": "方向", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
