INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まった形のこと。", "primary_collocate": null, "pronunciation": "ていけい", "ipa": "teːkeː", "syllable_count": 4, "sentences": [{"text": "契約書は定型があるので、それに合わせて書けばよい。", "target_word": "定型", "complexity_tier": "T3", "furigana": "契約書[けいやくしょ]は定型[ていけい]があるので、それに合[あ]わせて書[か]けばよい。", "sentence_source": "generated"}, {"text": "この申込用紙は定型のため、書く項目がすべて決まっている。", "target_word": "定型", "complexity_tier": "T3", "furigana": "この申込用紙[もうしこみようし]は定型[ていけい]のため、書[か]く項目[こうもく]がすべて決[き]まっている。", "sentence_source": "generated"}, {"text": "メールの返事が定型ばかりだと、冷たい印象を与えてしまう。", "target_word": "定型", "complexity_tier": "T3", "furigana": "メールの返事[へんじ]が定型[ていけい]ばかりだと、冷[つめ]たい印象[いんしょう]を与[あた]えてしまう。", "sentence_source": "generated"}, {"text": "川柳は五七五の定型で作る短い詩だ。", "target_word": "定型", "complexity_tier": "T3", "furigana": "川柳[せんりゅう]は五七五[ごしちご]の定型[ていけい]で作[つく]る短[みじか]い詩[し]だ。", "sentence_source": "generated"}, {"text": "彼の発表は定型から外れていて、聞く人を驚かせた。", "target_word": "定型", "complexity_tier": "T3", "furigana": "彼[かれ]の発表[はっぴょう]は定型[ていけい]から外[はず]れていて、聞[き]く人[ひと]を驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "学校の作文には定型があり、最初に結論を書くよう教えられた。", "target_word": "定型", "complexity_tier": "T3", "furigana": "学校[がっこう]の作文[さくぶん]には定型[ていけい]があり、最初[さいしょ]に結論[けつろん]を書[か]くよう教[おし]えられた。", "sentence_source": "generated"}, {"text": "お礼状は定型を知っていれば、短時間で書ける。", "target_word": "定型", "complexity_tier": "T3", "furigana": "お礼状[れいじょう]は定型[ていけい]を知[し]っていれば、短時間[たんじかん]で書[か]ける。", "sentence_source": "generated"}, {"text": "この店の接客は定型になっていて、どの店員も同じ言葉を言う。", "target_word": "定型", "complexity_tier": "T3", "furigana": "この店[みせ]の接客[せっきゃく]は定型[ていけい]になっていて、どの店員[てんいん]も同[おな]じ言葉[ことば]を言[い]う。", "sentence_source": "generated"}, {"text": "定型のない自由な作文のほうが、子どもは楽しそうに書く。", "target_word": "定型", "complexity_tier": "T3", "furigana": "定型[ていけい]のない自由[じゆう]な作文[さくぶん]のほうが、子[こ]どもは楽[たの]しそうに書[か]く。", "sentence_source": "generated"}, {"text": "年賀状の挨拶文は定型が多く、自分で考える人は少ない。", "target_word": "定型", "complexity_tier": "T3", "furigana": "年賀状[ねんがじょう]の挨拶文[あいさつぶん]は定型[ていけい]が多[おお]く、自分[じぶん]で考[かんが]える人[ひと]は少[すく]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "定型", "label": "基本形"}], "register": "中立", "sense_fingerprint": "決まった形・型そのものを指す定型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定型", "is_correct": true, "explanation": "「定型がある」は決まった形式があるという意味で、契約書に合わせて書く文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「契約書は天気があるので」は意味をなさず、文の論理が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "「契約書は体温があるので」は不自然で、契約書の説明として成立しない。"}, {"text": "気温", "is_correct": false, "explanation": "「契約書は気温があるので」は意味をなさず、合わせて書く理由にならない。"}], "explanations": {"定型": "「定型がある」は決まった形式があるという意味で、契約書に合わせて書く文脈に合う。", "天気": "「契約書は天気があるので」は意味をなさず、文の論理が通らない。", "体温": "「契約書は体温があるので」は不自然で、契約書の説明として成立しない。", "気温": "「契約書は気温があるので」は意味をなさず、合わせて書く理由にならない。"}, "sentence_index": 0, "correct_answer": "定型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この電車は定型の時間に出発するので、乗り遅れないように早めに着いた。", "explanation": "ここは〈定刻〉の意味。定刻は決まった時刻のことで、定型は形式を指すので合わない。"}, {"text": "この定型券は三か月ごとに更新すればよい。", "explanation": "ここは〈定期〉の意味。定期券は決まった期間の乗車券で、定型は形式を指すので合わない。"}, {"text": "このバスは定型が二十人なので、満員になりやすい。", "explanation": "ここは〈定員〉の意味。定員は決まった人数のことで、定型は形式を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定型", "is_correct": true, "explanation": "「定型を知っていれば」は決まった形を知っているという意味で、お礼状の文脈に合う。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音を知っていれば」は意味をなさず、お礼状の文脈と合わない。"}, {"text": "酷評", "is_correct": false, "explanation": "「酷評を知っていれば」は不自然で、短時間で書ける理由にならない。"}, {"text": "寝癖", "is_correct": false, "explanation": "「寝癖を知っていれば」は意味をなさず、お礼状の文脈に合わない。"}], "explanations": {"定型": "「定型を知っていれば」は決まった形を知っているという意味で、お礼状の文脈に合う。", "騒音": "「騒音を知っていれば」は意味をなさず、お礼状の文脈と合わない。", "酷評": "「酷評を知っていれば」は不自然で、短時間で書ける理由にならない。", "寝癖": "「寝癖を知っていれば」は意味をなさず、お礼状の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "定型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お昼は定型で、ご飯と味噌汁がつく。", "explanation": "ここは〈定食〉の意味。定型は形式を指し、料理の組み合わせは表さないので合わない。"}, {"text": "この店は毎週水曜が定型なので、事前に確認する。", "explanation": "ここは〈定休〉の意味。定休は決まった休業日のことで、定型は形式を指すので合わない。"}, {"text": "彼は定型で会社を退職した。", "explanation": "ここは〈定年〉の意味。定年は決まった退職の年齢のことで、定型は形式を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "定型に沿うば、年賀状は見栄えがよくなる。", "corrected_sentence": "定型に沿えば、年賀状は見栄えがよくなる。", "error_description": "誤りは動詞の活用形。「沿う」の仮定形は「沿えば」なので、「沿うば」は誤り。正しくは「沿えば」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51493, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "企業の申込書には定型を多く、記入に時間がかかる。", "corrected_sentence": "企業の申込書には定型が多く、記入に時間がかかる。", "error_description": "誤りは助詞。「多い」は主語に「が」を取るので、「定型を多く」は誤り。正しくは「定型が多く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『業務の内容』の『の』。業務に関する、の意味。"}, {"text": "を", "is_correct": false, "explanation": "『業務を内容』は名詞が並ばず、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『業務に内容』は不自然で、名詞を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "『業務へ内容』は方向を示すので、名詞の修飾にはならない。"}], "correct_answer": "の", "explanations": {"の": "『業務の内容』の『の』。業務に関する、の意味。", "を": "『業務を内容』は名詞が並ばず、文として成り立たない。", "に": "『業務に内容』は不自然で、名詞を修飾できない。", "へ": "『業務へ内容』は方向を示すので、名詞の修飾にはならない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『業務の間』の『の』。業務の時間、の意味。"}, {"text": "が", "is_correct": false, "explanation": "『業務が間』は主語を示すが、名詞『間』に直接つながらず、『業務の間』の意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "『業務から間』は起点を示す形で、名詞を修飾できない。"}, {"text": "より", "is_correct": false, "explanation": "『業務より間』は比較を示す形で、名詞『間』を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "『業務の間』の『の』。業務の時間、の意味。", "が": "『業務が間』は主語を示すが、名詞『間』に直接つながらず、『業務の間』の意味にならない。", "から": "『業務から間』は起点を示す形で、名詞を修飾できない。", "より": "『業務より間』は比較を示す形で、名詞『間』を修飾できない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事のこと。会社などでする、決まったしごと。", "primary_collocate": null, "pronunciation": "ぎょうむ", "ipa": "ɡʲoːmɯ", "syllable_count": 3, "sentences": [{"text": "私の会社では、午前九時から業務が始まる。", "target_word": "業務", "complexity_tier": "T3", "furigana": "私[わたし]の会社[かいしゃ]では、午前[ごぜん]九時[くじ]から業務[ぎょうむ]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "業務の内容は、入社してから先輩が教えてくれた。", "target_word": "業務", "complexity_tier": "T3", "furigana": "業務[ぎょうむ]の内容[ないよう]は、入社[にゅうしゃ]してから先輩[せんぱい]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "今週は業務が忙しくて、家に帰るのが遅くなった。", "target_word": "業務", "complexity_tier": "T3", "furigana": "今週[こんしゅう]は業務[ぎょうむ]が忙[いそが]しくて、家[いえ]に帰[かえ]るのが遅[おそ]くなった。", "sentence_source": "generated"}, {"text": "彼は業務に慣れるまで、毎日メモを取っていた。", "target_word": "業務", "complexity_tier": "T3", "furigana": "彼[かれ]は業務[ぎょうむ]に慣[な]れるまで、毎日[まいにち]メモを取[と]っていた。", "sentence_source": "generated"}, {"text": "業務のやり方を変えたら、残業が減った。", "target_word": "業務", "complexity_tier": "T3", "furigana": "業務[ぎょうむ]のやり方[かた]を変[か]えたら、残業[ざんぎょう]が減[へ]った。", "sentence_source": "generated"}, {"text": "病院の業務は、患者の命に関わるので責任が重い。", "target_word": "業務", "complexity_tier": "T3", "furigana": "病院[びょういん]の業務[ぎょうむ]は、患者[かんじゃ]の命[いのち]に関[かか]わるので責任[せきにん]が重[おも]い。", "sentence_source": "generated"}, {"text": "社長は社員に、業務の報告を毎週出すように言った。", "target_word": "業務", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は社員[しゃいん]に、業務[ぎょうむ]の報告[ほうこく]を毎週[まいしゅう]出[だ]すように言[い]った。", "sentence_source": "generated"}, {"text": "業務の間は私用の電話をしてはいけない決まりだ。", "target_word": "業務", "complexity_tier": "T3", "furigana": "業務[ぎょうむ]の間[あいだ]は私用[しよう]の電話[でんわ]をしてはいけない決[き]まりだ。", "sentence_source": "generated"}, {"text": "休みの日は、業務のことを忘れて家族と過ごす。", "target_word": "業務", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、業務[ぎょうむ]のことを忘[わす]れて家族[かぞく]と過[す]ごす。", "sentence_source": "generated"}, {"text": "父は長年、工場の管理の業務を担当してきた。", "target_word": "業務", "complexity_tier": "T3", "furigana": "父[ちち]は長年[ながねん]、工場[こうじょう]の管理[かんり]の業務[ぎょうむ]を担当[たんとう]してきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "業務", "label": "基本形"}], "register": "ビジネス・やや硬い", "sense_fingerprint": "会社などで行う決まった仕事一般としての業務", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "業務", "is_correct": true, "explanation": "〈業務〉（会社の仕事）。会社で午前九時に始まるものとして合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は調味料で、始まるものではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、始まるものではない。"}, {"text": "石油", "is_correct": false, "explanation": "石油は燃料で、始まる対象にはならない。"}], "explanations": {"業務": "〈業務〉（会社の仕事）。会社で午前九時に始まるものとして合う。", "砂糖": "砂糖は調味料で、始まるものではない。", "冷蔵庫": "冷蔵庫は家電で、始まるものではない。", "石油": "石油は燃料で、始まる対象にはならない。"}, "sentence_index": 0, "correct_answer": "業務"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は趣味の業務で、毎週絵を描いている。", "explanation": "ここは〈趣味〉（個人の楽しみ）の意味。業務は会社などの仕事を指すので、個人の楽しみには使わない。"}, {"text": "彼は約束の業務に遅れた。", "explanation": "ここは〈約束〉（会う約束）の意味。業務は会社などの仕事を指すので、私的な約束の意味では使わない。"}, {"text": "彼は夏休みの業務を終えるため、毎日勉強した。", "explanation": "ここは〈課題〉の意味。学生の宿題は業務ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "業務", "is_correct": true, "explanation": "〈業務〉（会社の仕事）。社長が求める会社の仕事の報告に合う。"}, {"text": "味噌", "is_correct": false, "explanation": "味噌は調味料で、報告の対象にはならない。"}, {"text": "雷", "is_correct": false, "explanation": "雷は自然現象で、報告の対象ではない。"}, {"text": "絨毯", "is_correct": false, "explanation": "絨毯は床に敷く布で、報告の対象ではない。"}], "explanations": {"業務": "〈業務〉（会社の仕事）。社長が求める会社の仕事の報告に合う。", "味噌": "味噌は調味料で、報告の対象にはならない。", "雷": "雷は自然現象で、報告の対象ではない。", "絨毯": "絨毯は床に敷く布で、報告の対象ではない。"}, "sentence_index": 6, "correct_answer": "業務"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一時間目の業務が、チャイムで始まった。", "explanation": "ここは〈授業〉の意味。学校の授業は業務とは言わないので合わない。"}, {"text": "遊びの業務で、週末は友達と映画を見る。", "explanation": "ここは〈遊び〉の意味。業務は会社などの仕事を指すので、娯楽の遊びには使わない。"}, {"text": "毎朝の業務として、公園を十周走っている。", "explanation": "ここは〈運動〉（体を動かすこと）の意味。業務は会社などの仕事を指すので、個人の運動には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新入社員は業務に覚えるため、先輩に質問した。", "corrected_sentence": "新入社員は業務を覚えるため、先輩に質問した。", "error_description": "『覚える』は『を』で目的語を取る。『に』は誤りで、『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "業務に教えるため、先輩は毎日隣に座った。", "corrected_sentence": "業務を教えるため、先輩は毎日隣に座った。", "error_description": "『教える』は『を』で目的語を取る。『に』は誤りで、『を』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "出どころを示す「から」で、社内外からの参加者という意味が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では参加の対象にならず、「社内外を多くの人が参加」は続かない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると社内外自体が参加する主体になり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では出どころを表せず、「社内外へ参加」は不自然になる。"}], "correct_answer": "から", "explanations": {"から": "出どころを示す「から」で、社内外からの参加者という意味が成り立つ。", "を": "目的語の「を」では参加の対象にならず、「社内外を多くの人が参加」は続かない。", "が": "主語の「が」にすると社内外自体が参加する主体になり、意味が通らない。", "へ": "方向を示す「へ」では出どころを表せず、「社内外へ参加」は不自然になる。"}, "error_tags": {"を": "目的語の「を」だが、参加の対象にはならない", "が": "主語を示すが、社内外が参加の主体にはならない", "へ": "方向を示すが、ここは出どころを表す意味"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
