INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会社という組織の内部と、それ以外の外部の人や場所を指す言葉。", "primary_collocate": null, "pronunciation": "しゃないがい", "ipa": "ɕanaiɡai", "syllable_count": 5, "sentences": [{"text": "そのため、社内外で新しい知識や技術を学び直すリスキリングが不可欠である。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "そのため、社内外[しゃないがい]で新[あたら]しい知識[ちしき]や技術[ぎじゅつ]を学[まな]び直[なお]すリスキリングが不可欠[ふかけつ]である。", "sentence_source": "mined"}, {"text": "このイベントには社内外から多くの人が参加した。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "このイベントには社内外[しゃないがい]から多[おお]くの人[ひと]が参加[さんか]した。", "sentence_source": "generated"}, {"text": "新製品の情報は、社内外に向けて同時に発表される。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の情報[じょうほう]は、社内外[しゃないがい]に向[む]けて同時[どうじ]に発表[はっぴょう]される。", "sentence_source": "generated"}, {"text": "社内外の関係者に連絡する前に、まず上司の許可を取った。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "社内外[しゃないがい]の関係者[かんけいしゃ]に連絡[れんらく]する前[まえ]に、まず上司[じょうし]の許可[きょか]を取[と]った。", "sentence_source": "generated"}, {"text": "彼は社内外を問わず、誰とでもすぐに親しくなれる人だ。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "彼[かれ]は社内外[しゃないがい]を問[と]わず、誰[だれ]とでもすぐに親[した]しくなれる人[ひと]だ。", "sentence_source": "generated"}, {"text": "社内外の評価が高い社員ほど、大きな仕事を任されやすい。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "社内外[しゃないがい]の評価[ひょうか]が高[たか]い社員[しゃいん]ほど、大[おお]きな仕事[しごと]を任[まか]されやすい。", "sentence_source": "generated"}, {"text": "個人情報の扱いには、社内外の別なく細心の注意が必要だ。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "個人情報[こじんじょうほう]の扱[あつか]いには、社内外[しゃないがい]の別[べつ]なく細心[さいしん]の注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "問い合わせの窓口を一本にして、社内外からの連絡を整理した。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "問[と]い合[あ]わせの窓口[まどぐち]を一本[いっぽん]にして、社内外[しゃないがい]からの連絡[れんらく]を整理[せいり]した。", "sentence_source": "generated"}, {"text": "社内外の協力があったからこそ、この計画は成功した。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "社内外[しゃないがい]の協力[きょうりょく]があったからこそ、この計画[けいかく]は成功[せいこう]した。", "sentence_source": "generated"}, {"text": "社内外の人が気軽に集まれる場所として、一階に広い談話室を設けた。", "target_word": "社内外", "complexity_tier": "T3", "furigana": "社内外[しゃないがい]の人[ひと]が気軽[きがる]に集[あつ]まれる場所[ばしょ]として、一階[いっかい]に広[ひろ]い談話室[だんわしつ]を設[もう]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "社内外", "label": "基本形"}], "register": "formal written", "sense_fingerprint": "会社の内部と外部をまとめて指す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社内外", "is_correct": true, "explanation": "「〜で学び直す」の範囲を表し、社内と社外の両方を指す語として自然に入る。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを表す語で、学ぶ範囲や場を示せず文が成り立たない。"}, {"text": "深海", "is_correct": false, "explanation": "海の深い場所で、学び直しの場としては文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、学習の場や範囲にはならず文が成り立たない。"}], "explanations": {"社内外": "「〜で学び直す」の範囲を表し、社内と社外の両方を指す語として自然に入る。", "感情": "心の動きを表す語で、学ぶ範囲や場を示せず文が成り立たない。", "深海": "海の深い場所で、学び直しの場としては文脈に合わない。", "天気": "空模様を表す語で、学習の場や範囲にはならず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "社内外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今月は社内外を大きく伸ばした。", "explanation": "ここは〈売上〉の意味。社内外は範囲を表す語で、伸ばす対象にはならない。"}, {"text": "この社内外は登場人物の心理が丁寧に描かれている。", "explanation": "ここは〈小説〉の意味。小説は登場人物の心理を描くが、社内外は範囲の語で描写の対象にはならない。"}, {"text": "この社内外は毛並みがよく、人懐っこい。", "explanation": "ここは〈犬〉の意味。毛並みや人懐っこさは生き物の特徴で、社内外には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社内外", "is_correct": true, "explanation": "「社内外の別なく」という言い方で、社内と社外の区別を指す語として自然に入る。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、個人情報の扱いの区別を示す言い方にはならない。"}, {"text": "社内", "is_correct": false, "explanation": "社の内部だけを指し、「の別なく」と対になる区別の形を作れず不自然。"}, {"text": "景色", "is_correct": false, "explanation": "眺めを表す語で、扱いの区別の言い方には当てはまらない。"}], "explanations": {"社内外": "「社内外の別なく」という言い方で、社内と社外の区別を指す語として自然に入る。", "季節": "時期を表す語で、個人情報の扱いの区別を示す言い方にはならない。", "社内": "社の内部だけを指し、「の別なく」と対になる区別の形を作れず不自然。", "景色": "眺めを表す語で、扱いの区別の言い方には当てはまらない。"}, "sentence_index": 6, "correct_answer": "社内外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は休日に、社内外のクッキーを焼いた。", "explanation": "ここは〈菓子〉の意味。焼くのはクッキーなどの菓子で、範囲を表す社内外は焼けないので合わない。"}, {"text": "この社内外は春になると咲く。", "explanation": "ここは〈花〉の意味。花は季節に咲く植物を指すが、社内外は範囲を表すので咲く対象にはならない。"}, {"text": "社内外を履いて外に出た。", "explanation": "ここは〈靴〉の意味。靴は足に履く物だが、社内外は範囲を表す語なので履く対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このセミナーには社内外が多くの人が参加した。", "corrected_sentence": "このセミナーには社内外から多くの人が参加した。", "error_description": "「社内外から」は出どころを示す「から」が正しい。「が」にすると社内外自体が主語になり、参加者の出どころを表せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51498, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その計画は社内外を協力を得て成功した。", "corrected_sentence": "その計画は社内外からの協力を得て成功した。", "error_description": "「社内外から」は出どころを示す「からの協力」が正しい。「を」は動作の対象につく助詞で、協力の出どころを表せない。文中に「を」が二つあり、不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "を marks 時代 as the object of 過ごした: a person spends a period of life."}, {"text": "が", "is_correct": false, "explanation": "が would make 時代 the subject of 過ごした, but the verb needs a person as the one spending time."}, {"text": "で", "is_correct": false, "explanation": "で marks place or means. 子どもの時代で is not a place, and the sentence already has a で phrase."}, {"text": "へ", "is_correct": false, "explanation": "へ marks direction. 子どもの時代へ implies moving toward a time, which 過ごした does not express."}], "correct_answer": "を", "explanations": {"を": "を marks 時代 as the object of 過ごした: a person spends a period of life.", "が": "が would make 時代 the subject of 過ごした, but the verb needs a person as the one spending time.", "で": "で marks place or means. 子どもの時代で is not a place, and the sentence already has a で phrase.", "へ": "へ marks direction. 子どもの時代へ implies moving toward a time, which 過ごした does not express."}, "error_tags": {"が": "subject", "で": "location or means", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "に marks the time frame: 〜の時代にも, in every era."}, {"text": "と", "is_correct": false, "explanation": "と links nouns or quotes. 時代と leaves no partner for it to connect with."}, {"text": "を", "is_correct": false, "explanation": "を would make 時代 an object, but no verb in the sentence acts on 時代."}, {"text": "より", "is_correct": false, "explanation": "より is a comparison marker, and the sentence has no comparison term."}], "correct_answer": "に", "explanations": {"に": "に marks the time frame: 〜の時代にも, in every era.", "と": "と links nouns or quotes. 時代と leaves no partner for it to connect with.", "を": "を would make 時代 an object, but no verb in the sentence acts on 時代.", "より": "より is a comparison marker, and the sentence has no comparison term."}, "error_tags": {"と": "companion", "を": "object", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるときの期間のこと。昔や今のときのこと。", "primary_collocate": null, "pronunciation": "じだい", "ipa": "d͡ʑidai", "syllable_count": 3, "sentences": [{"text": "電気がなかった時代、人々は夜になるとろうそくを使った。", "target_word": "時代", "complexity_tier": "T3", "furigana": "電気[でんき]がなかった時代[じだい]、人々[ひとびと]は夜[よる]になるとろうそくを使[つか]った。", "sentence_source": "generated"}, {"text": "母は子どもの時代を、海の近くの町で過ごしたそうだ。", "target_word": "時代", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもの時代[じだい]を、海[うみ]の近[ちか]くの町[まち]で過[す]ごしたそうだ。", "sentence_source": "generated"}, {"text": "私が小学生だった時代には、携帯電話を持つ子はほとんどいなかった。", "target_word": "時代", "complexity_tier": "T3", "furigana": "私[わたし]が小学生[しょうがくせい]だった時代[じだい]には、携帯電話[けいたいでんわ]を持[も]つ子[こ]はほとんどいなかった。", "sentence_source": "generated"}, {"text": "今の時代は、どこにいても友だちと顔を見て話せる。", "target_word": "時代", "complexity_tier": "T3", "furigana": "今[いま]の時代[じだい]は、どこにいても友[とも]だちと顔[かお]を見[み]て話[はな]せる。", "sentence_source": "generated"}, {"text": "時代によって、人気のある遊びはずいぶん違う。", "target_word": "時代", "complexity_tier": "T3", "furigana": "時代[じだい]によって、人気[にんき]のある遊[あそ]びはずいぶん違[ちが]う。", "sentence_source": "generated"}, {"text": "恐竜がいた時代の地球は、今よりずっと暖かかったと言われる。", "target_word": "時代", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]がいた時代[じだい]の地球[ちきゅう]は、今[いま]よりずっと暖[あたた]かかったと言[い]われる。", "sentence_source": "generated"}, {"text": "祖母は、食べ物が少なかった時代の苦労を話してくれた。", "target_word": "時代", "complexity_tier": "T3", "furigana": "祖母[そぼ]は、食[た]べ物[もの]が少[すく]なかった時代[じだい]の苦労[くろう]を話[はな]してくれた。", "sentence_source": "generated"}, {"text": "どの時代にも、新しいものを作り出す人がいる。", "target_word": "時代", "complexity_tier": "T3", "furigana": "どの時代[じだい]にも、新[あたら]しいものを作[つく]り出[だ]す人[ひと]がいる。", "sentence_source": "generated"}, {"text": "この写真は、父がまだ若かった時代のものだ。", "target_word": "時代", "complexity_tier": "T3", "furigana": "この写真[しゃしん]は、父[ちち]がまだ若[わか]かった時代[じだい]のものだ。", "sentence_source": "generated"}, {"text": "時代が違うので、祖父の常識は私たちには不思議に思える。", "target_word": "時代", "complexity_tier": "T3", "furigana": "時代[じだい]が違[ちが]うので、祖父[そふ]の常識[じょうしき]は私[わたし]たちには不思議[ふしぎ]に思[おも]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時代", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "昔や今など、ひとまとまりの期間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時代", "is_correct": true, "explanation": "Fits: 「電気がなかった時代」 names an extended era, the only option that works in this blank."}, {"text": "年齢", "is_correct": false, "explanation": "Means a person''s age. 電気がなかった年齢 does not describe a period when society lacked electricity."}, {"text": "時刻", "is_correct": false, "explanation": "Means a clock time or single moment, not an extended era, so 電気がなかった時刻 does not work."}, {"text": "天気", "is_correct": false, "explanation": "Means weather. 電気がなかった天気 has no referent in a sentence about people using candles."}], "explanations": {"時代": "Fits: 「電気がなかった時代」 names an extended era, the only option that works in this blank.", "年齢": "Means a person''s age. 電気がなかった年齢 does not describe a period when society lacked electricity.", "時刻": "Means a clock time or single moment, not an extended era, so 電気がなかった時刻 does not work.", "天気": "Means weather. 電気がなかった天気 has no referent in a sentence about people using candles."}, "sentence_index": 0, "correct_answer": "時代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の時代に引っ越す予定だ。", "explanation": "Here 〈時期〉 (a specific point in time) is meant. 時代 names a long historical period, so it cannot describe next month."}, {"text": "レポートの時代は来週の金曜日だ。", "explanation": "Here 〈期限〉 (deadline) is meant. A due date is expressed with 期限; 時代 does not mean a deadline."}, {"text": "このファイルは時代が大きすぎて、メールに添付できない。", "explanation": "Here 〈容量〉 (file size) is meant. The size of a file is 容量; 時代 does not express size."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時代", "is_correct": true, "explanation": "Fits: 食べ物が少なかった時代の苦労 means hardships of an era of food shortage."}, {"text": "財布", "is_correct": false, "explanation": "A wallet is an object and cannot be a period of food scarcity."}, {"text": "試験", "is_correct": false, "explanation": "An exam is an event, so 食べ物が少なかった試験の苦労 does not describe a shortage."}, {"text": "手紙", "is_correct": false, "explanation": "A letter is an object and does not describe a time when food was scarce."}], "explanations": {"時代": "Fits: 食べ物が少なかった時代の苦労 means hardships of an era of food shortage.", "財布": "A wallet is an object and cannot be a period of food scarcity.", "試験": "An exam is an event, so 食べ物が少なかった試験の苦労 does not describe a shortage.", "手紙": "A letter is an object and does not describe a time when food was scarce."}, "sentence_index": 6, "correct_answer": "時代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みの時代は図書館が休みになる。", "explanation": "Here 〈期間〉 (period of time) is meant. 時代 means a historical era, not a vacation span like summer break."}, {"text": "このバイトは時代が千二百円だ。", "explanation": "Here 〈時給〉 (hourly wage) is meant. Pay per hour is 時給; 時代 does not express an amount of money."}, {"text": "この電池は時代が三年もつ。", "explanation": "Here 〈寿命〉 (service life) is meant. The lifespan of an object is 寿命; 時代 does not measure durability."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昔の時代を、家に電話が一台しかなかった。", "corrected_sentence": "昔の時代には、家に電話が一台しかなかった。", "error_description": "Wrong particle on 時代. を makes 時代 an object, but a time frame needs には. Right form: 時代には.", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51499, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は新しい時代の切り開いた。", "corrected_sentence": "彼は新しい時代を切り開いた。", "error_description": "Wrong particle on 時代. の cannot mark 時代 as the object of 切り開く, so the sentence breaks. Right form: 時代を切り開いた (opened up a new era).", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「当たり前になった時代に」と時点を表す「に」。時代に直接付く正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「時代を、紙の地図を使う人」では時代が目的語にならず、文が続かない。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」だが、「時代や紙の地図を使う人」では並べる相手が揃わず文が続かない。"}, {"text": "の", "is_correct": false, "explanation": "「時代の、紙の地図」と続けると名詞の関係が成り立たず、文が切れてしまう。"}], "correct_answer": "に", "explanations": {"に": "「当たり前になった時代に」と時点を表す「に」。時代に直接付く正しい助詞。", "を": "「時代を、紙の地図を使う人」では時代が目的語にならず、文が続かない。", "や": "並列の「や」だが、「時代や紙の地図を使う人」では並べる相手が揃わず文が続かない。", "の": "「時代の、紙の地図」と続けると名詞の関係が成り立たず、文が切れてしまう。"}, "error_tags": {"を": "対象を示すが、ここは時点を示す場面", "や": "並列を示すが、並べる相手が揃わない", "の": "所属を示すが、ここは時点を示す場面"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "比較の基準を表す「より」で、「時代より何十年も先」の比較として合う。"}, {"text": "と", "is_correct": false, "explanation": "「時代と何十年も先を行っていた」では一緒に並ぶ相手のように読め、比べる基準にならない。"}, {"text": "を", "is_correct": false, "explanation": "「時代を何十年も先を行っていた」では「を」が二つ続き、対象が二重になって誤り。"}, {"text": "で", "is_correct": false, "explanation": "「時代で何十年も先を行っていた」では場所や手段の「で」になり、比べる基準を示せない。"}], "correct_answer": "より", "explanations": {"より": "比較の基準を表す「より」で、「時代より何十年も先」の比較として合う。", "と": "「時代と何十年も先を行っていた」では一緒に並ぶ相手のように読め、比べる基準にならない。", "を": "「時代を何十年も先を行っていた」では「を」が二つ続き、対象が二重になって誤り。", "で": "「時代で何十年も先を行っていた」では場所や手段の「で」になり、比べる基準を示せない。"}, "error_tags": {"と": "並列・相手", "を": "対象が二重になる", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある特徴的な期間。歴史的な区分や、現在の状況を指す。", "primary_collocate": null, "pronunciation": "じだい", "ipa": "d͡ʑidai", "syllable_count": 3, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "時代", "complexity_tier": "T3", "furigana": "現在[げんざい]、オフィスでの定型業務[ていけいぎょうむ]の自動化[じどうか]が進[すす]み、AIがホワイトカラーの雇用[こよう]を代替[だいたい]する時代[じだい]となっている。", "sentence_source": "mined"}, {"text": "スマートフォンが当たり前になった時代に、紙の地図を使う人は少ない。", "target_word": "時代", "complexity_tier": "T3", "furigana": "スマートフォンが当[あ]たり前[まえ]になった時代[じだい]に、紙[かみ]の地図[ちず]を使[つか]う人[ひと]は少[すく]ない。", "sentence_source": "generated"}, {"text": "祖父は自分が若かった時代の話を、よく聞かせてくれる。", "target_word": "時代", "complexity_tier": "T3", "furigana": "祖父[そふ]は自分[じぶん]が若[わか]かった時代[じだい]の話[はなし]を、よく聞[き]かせてくれる。", "sentence_source": "generated"}, {"text": "時代が変われば、人々の考え方も少しずつ変わっていく。", "target_word": "時代", "complexity_tier": "T3", "furigana": "時代[じだい]が変[か]われば、人々[ひとびと]の考[かんが]え方[かた]も少[すこ]しずつ変[か]わっていく。", "sentence_source": "generated"}, {"text": "この小説は、戦争が終わったばかりの時代を舞台にしている。", "target_word": "時代", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、戦争[せんそう]が終[お]わったばかりの時代[じだい]を舞台[ぶたい]にしている。", "sentence_source": "generated"}, {"text": "今は誰もが自由に情報を発信できる時代だ。", "target_word": "時代", "complexity_tier": "T3", "furigana": "今[いま]は誰[だれ]もが自由[じゆう]に情報[じょうほう]を発信[はっしん]できる時代[じだい]だ。", "sentence_source": "generated"}, {"text": "時代の流れに合わせて、その店はネット販売を始めた。", "target_word": "時代", "complexity_tier": "T3", "furigana": "時代[じだい]の流[なが]れに合[あ]わせて、その店[みせ]はネット販売[はんばい]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼の発想は、時代より何十年も先を行っていた。", "target_word": "時代", "complexity_tier": "T3", "furigana": "彼[かれ]の発想[はっそう]は、時代[じだい]より何十年[なんじゅうねん]も先[さき]を行[い]っていた。", "sentence_source": "generated"}, {"text": "あの時代の音楽は、今聞いても少しも古く感じない。", "target_word": "時代", "complexity_tier": "T3", "furigana": "あの時代[じだい]の音楽[おんがく]は、今[いま]聞[き]いても少[すこ]しも古[ふる]く感[かん]じない。", "sentence_source": "generated"}, {"text": "時代に取り残されないよう、父も新しい機械の使い方を覚えている。", "target_word": "時代", "complexity_tier": "T3", "furigana": "時代[じだい]に取[と]り残[のこ]されないよう、父[ちち]も新[あたら]しい機械[きかい]の使[つか]い方[かた]を覚[おぼ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "時代", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特徴で区切られる時期・社会の状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "時代", "is_correct": true, "explanation": "「〜する時代となっている」と現在の状況を述べる文に入り、期間や区分を表す語として自然。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類の一種で、雇用を代替する状況を表す文には入らない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝るための道具で、雇用の状況を表す文には入らない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「〜する天気となっている」とは言えず文脈に合わない。"}], "explanations": {"時代": "「〜する時代となっている」と現在の状況を述べる文に入り、期間や区分を表す語として自然。", "靴下": "衣類の一種で、雇用を代替する状況を表す文には入らない。", "寝具": "寝るための道具で、雇用の状況を表す文には入らない。", "天気": "空模様を表す語で、「〜する天気となっている」とは言えず文脈に合わない。"}, "sentence_index": 0, "correct_answer": "時代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花見に行く時代は、桜が咲く頃だ。", "explanation": "ここは〈時期〉の意味。時期は行事などのタイミングを指すので、長い区分を表す時代では言い換えられない。"}, {"text": "時代の針が正午を指した。", "explanation": "ここは〈時計〉の意味。針が時刻を指すのは時計で、時代には針がないので合わない。"}, {"text": "夏休みの宿題で、時代を毎日書いた。", "explanation": "ここは〈日記〉の意味。毎日書いて残すのは日記で、時代は書き記す対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "時代", "is_correct": true, "explanation": "「時代の流れ」として社会の移り変わりを表し、店がネット販売を始めた判断に合う。"}, {"text": "食器", "is_correct": false, "explanation": "食べ物を盛る道具で、「流れに合わせて」の対象にはならない。"}, {"text": "病気", "is_correct": false, "explanation": "体の不調を指す語で、「の流れ」と結びつかず文が成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "草木の一部で、「の流れ」とは言えず、店の販売の判断とは無関係。"}], "explanations": {"時代": "「時代の流れ」として社会の移り変わりを表し、店がネット販売を始めた判断に合う。", "食器": "食べ物を盛る道具で、「流れに合わせて」の対象にはならない。", "病気": "体の不調を指す語で、「の流れ」と結びつかず文が成り立たない。", "花": "草木の一部で、「の流れ」とは言えず、店の販売の判断とは無関係。"}, "sentence_index": 6, "correct_answer": "時代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "時代を洗って、棚にしまった。", "explanation": "ここは〈食器〉の意味。食器は洗う対象だが、時代は洗えないので合わない。"}, {"text": "時代が治って、会社に戻った。", "explanation": "ここは〈病気〉の意味。病気は治るものだが、時代は治療の対象にならないので合わない。"}, {"text": "時代を着て、出かけた。", "explanation": "ここは〈服〉の意味。服は身につけて着るものだが、時代は着られないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は若かった時代を写真を、よく見せてくれる。", "corrected_sentence": "祖母は若かった時代の写真を、よく見せてくれる。", "error_description": "「時代の写真」のように名詞を修飾するのは「の」。「時代を写真を」では「を」が二つ続き、不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51500, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は時代に取り残し、流行の話題に疎くなった。", "corrected_sentence": "彼女は時代に取り残され、流行の話題に疎くなった。", "error_description": "「取り残し」は他動詞の連用形で、目的語（取り残す相手）を必要とするが、ここでは目的語がなく文が途切れている。「時代に取り残される」の受け身「取り残され」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "で marks the place where the work happens: 港の倉庫で従業し."}, {"text": "が", "is_correct": false, "explanation": "が would make 港の倉庫 the subject, so the warehouse would be the one working."}, {"text": "を", "is_correct": false, "explanation": "を would make 港の倉庫 an object of 従業, which does not make sense."}, {"text": "と", "is_correct": false, "explanation": "と means ''with''; 港の倉庫と従業し would mean working alongside a warehouse."}], "correct_answer": "で", "explanations": {"で": "で marks the place where the work happens: 港の倉庫で従業し.", "が": "が would make 港の倉庫 the subject, so the warehouse would be the one working.", "を": "を would make 港の倉庫 an object of 従業, which does not make sense.", "と": "と means ''with''; 港の倉庫と従業し would mean working alongside a warehouse."}, "error_tags": {"が": "subject", "を": "object", "と": "companion"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "しごとを する こと。", "primary_collocate": null, "pronunciation": "じゅうぎょう", "ipa": "dʑɯːɡʲoː", "syllable_count": 4, "sentences": [{"text": "彼は十年間、小さな工場で従業している。", "target_word": "従業", "complexity_tier": "T3", "furigana": "彼[かれ]は十年間[じゅうねんかん]、小[ちい]さな工場[こうじょう]で従業[じゅうぎょう]している。", "sentence_source": "generated"}, {"text": "祖父は戦後すぐに港の倉庫で従業し、家族を養った。", "target_word": "従業", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦後[せんご]すぐに港[みなと]の倉庫[そうこ]で従業[じゅうぎょう]し、家族[かぞく]を養[やしな]った。", "sentence_source": "generated"}, {"text": "従業するときは安全のため、必ずヘルメットをかぶる。", "target_word": "従業する", "complexity_tier": "T3", "furigana": "じゅうぎょうするときはあんぜんのため、かならずへるめっとをかぶる。", "sentence_source": "generated"}, {"text": "母は病気になるまで、駅前の食堂で従業していた。", "target_word": "従業", "complexity_tier": "T3", "furigana": "母[はは]は病気[びょうき]になるまで、駅前[えきまえ]の食堂[しょくどう]で従業[じゅうぎょう]していた。", "sentence_source": "generated"}, {"text": "この会社では、学生も週に三日だけ従業できる。", "target_word": "従業", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、学生[がくせい]も週[しゅう]に三日[みっか]だけ従業[じゅうぎょう]できる。", "sentence_source": "generated"}, {"text": "彼女は子どもが生まれてからも、同じ店で従業を続けた。", "target_word": "従業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は子[こ]どもが生[う]まれてからも、同[おな]じ店[みせ]で従業[じゅうぎょう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "外国から来た若者が、農場で従業して日本語を学んだ。", "target_word": "従業", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た若者[わかもの]が、農場[のうじょう]で従業[じゅうぎょう]して日本語[にほんご]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "従業している最中にけがをした場合は、すぐに上司に知らせる。", "target_word": "従業している", "complexity_tier": "T3", "furigana": "じゅうぎょうしているさいちゅうにけがをしたばあいは、すぐにじょうしにしらせる。", "sentence_source": "generated"}, {"text": "彼は大学を出ると、父の会社に従業することになった。", "target_word": "従業", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]を出[で]ると、父[ちち]の会社[かいしゃ]に従業[じゅうぎょう]することになった。", "sentence_source": "generated"}, {"text": "雨の日も雪の日も、彼は休まずに店で従業した。", "target_word": "従業", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]も雪[ゆき]の日[ひ]も、彼[かれ]は休[やす]まずに店[みせ]で従業[じゅうぎょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "従業する", "label": "辞書形"}, {"form": "従業した", "label": "過去形"}, {"form": "従業している", "label": "継続形"}, {"form": "従業しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "従業:会社や店などで仕事に就いて働くこと(する名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a842f311-b815-4a39-bf38-8799be70a7cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "従業", "is_correct": true, "explanation": "Fits: 小さな工場で従業している means working at a small factory."}, {"text": "無視", "is_correct": false, "explanation": "Means ''ignoring''. 工場で無視している does not describe a job."}, {"text": "反省", "is_correct": false, "explanation": "Means ''reflecting on one''s conduct''. It is not something one does at a factory as a job."}, {"text": "感謝", "is_correct": false, "explanation": "Means ''gratitude''. 工場で感謝している does not describe employment."}], "explanations": {"従業": "Fits: 小さな工場で従業している means working at a small factory.", "無視": "Means ''ignoring''. 工場で無視している does not describe a job.", "反省": "Means ''reflecting on one''s conduct''. It is not something one does at a factory as a job.", "感謝": "Means ''gratitude''. 工場で感謝している does not describe employment."}, "sentence_index": 0, "correct_answer": "従業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の日、店は一日従業していた。", "explanation": "Here 〈営業〉 (business operating) is meant. A shop''s opening is 営業; 従業 refers to people working."}, {"text": "祖父は戦後、夜の学校で英語の従業を受けた。", "explanation": "ここは〈授業〉の意味。授業（じゅぎょう）とは音が近いが別語で、従業（じゅうぎょう）は働くことを表す。"}, {"text": "彼は大学を出ると、父の会社の社長に従業した。", "explanation": "Here 〈就任〉 (taking up a post) is meant. Becoming president is 就任; 従業 does not mean that."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "従業", "is_correct": true, "explanation": "Fits: 農場で従業して日本語を学んだ means working on a farm while learning Japanese."}, {"text": "叱責", "is_correct": false, "explanation": "Means ''scolding''. 農場で叱責して does not describe working while learning."}, {"text": "罵倒", "is_correct": false, "explanation": "Means ''verbal abuse''. It does not describe a job or a way of learning."}, {"text": "驚愕", "is_correct": false, "explanation": "Means ''being shocked''. It cannot be the activity carried out on the farm."}], "explanations": {"従業": "Fits: 農場で従業して日本語を学んだ means working on a farm while learning Japanese.", "叱責": "Means ''scolding''. 農場で叱責して does not describe working while learning.", "罵倒": "Means ''verbal abuse''. It does not describe a job or a way of learning.", "驚愕": "Means ''being shocked''. It cannot be the activity carried out on the farm."}, "sentence_index": 6, "correct_answer": "従業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は新人の店員を休まずに従業した。", "explanation": "Here 〈指導〉 (training or guiding) is meant. Teaching a new staff member is 指導; 従業 does not mean that."}, {"text": "彼は若い頃、三年間、地元の高校を従業した。", "explanation": "Here 〈卒業〉 (finishing school) is meant. Graduating from high school is 卒業; 従業 means working and does not mean finishing a course."}, {"text": "彼は若い頃、八月に大学の試験を従業した。", "explanation": "Here 〈受験〉 (sitting an entrance exam) is meant. Taking an exam is 受験; 従業 means working, so it cannot be used for an exam."}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は三十年間、この店を従業していた。", "corrected_sentence": "父は三十年間、この店で従業していた。", "error_description": "Wrong particle before 従業. を is used, but the place where work happens takes で. Right form: この店で従業していた.", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51501, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は卒業後、祖父の店で従業されることになった。", "corrected_sentence": "姉は卒業後、祖父の店で従業することになった。", "error_description": "「従業する」は自動詞的に働くことを表すため、受け身の「従業される」は不自然。正しくは「従業することになった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b5b0a21-b332-4005-b7af-6aea1b92b83c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "直接の対象（花壇の土）を示し、『土を耕した』として正しい。"}, {"text": "が", "is_correct": false, "explanation": "『土が耕した』と主語にすると、土が動作主になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "『花壇の土に耕した』では対象が示されず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、『土へ耕した』は動作の対象にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "直接の対象（花壇の土）を示し、『土を耕した』として正しい。", "が": "『土が耕した』と主語にすると、土が動作主になり不自然。", "に": "『花壇の土に耕した』では対象が示されず、文が成り立たない。", "へ": "方向を表すが、『土へ耕した』は動作の対象にならず不自然。"}, "error_tags": {"を": "対象", "が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "直接の対象（庭）を示し、『庭を耕した』として正しい。"}, {"text": "と", "is_correct": false, "explanation": "『庭と耕した』では並列や相手にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、『庭より耕した』は文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "『庭の耕した』と続けると、動作の対象が文中で示されず不自然。"}], "correct_answer": "を", "explanations": {"を": "直接の対象（庭）を示し、『庭を耕した』として正しい。", "と": "『庭と耕した』では並列や相手にならず、文が成り立たない。", "より": "比較の助詞で、『庭より耕した』は文脈に合わない。", "の": "『庭の耕した』と続けると、動作の対象が文中で示されず不自然。"}, "error_tags": {"を": "対象", "と": "並列・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "土を道具でやわらかくすること。", "primary_collocate": null, "pronunciation": "たがやす", "ipa": "taɡajasɯ", "syllable_count": 4, "sentences": [{"text": "農家の人たちは、秋の終わりに田んぼを耕す。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、秋[あき]の終[お]わりに田[た]んぼを耕[たがや]す。", "sentence_source": "generated"}, {"text": "弟は小さなスコップで花壇の土を耕した。", "target_word": "耕した", "complexity_tier": "T3", "furigana": "弟[おとうと]は小[ちい]さなスコップで花壇[かだん]の土[つち]を耕[たがや]した。", "sentence_source": "generated"}, {"text": "土を耕さずに種をまいても、芽はあまり出ない。", "target_word": "耕さ", "complexity_tier": "T3", "furigana": "土[つち]を耕[たがや]さずに種[たね]をまいても、芽[め]はあまり出[で]ない。", "sentence_source": "generated"}, {"text": "祖母は朝早くから畑を耕している。", "target_word": "耕して", "complexity_tier": "T3", "furigana": "祖母[そぼ]は朝早[あさはや]くから畑[はたけ]を耕[たがや]している。", "sentence_source": "generated"}, {"text": "牛にすきを引かせて畑を耕す農家もある。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "牛[うし]にすきを引[ひ]かせて畑[はたけ]を耕[たがや]す農家[のうか]もある。", "sentence_source": "generated"}, {"text": "畑を耕して肥料を混ぜると、土が元気になる。", "target_word": "耕して", "complexity_tier": "T3", "furigana": "畑[はたけ]を耕[たがや]して肥料[ひりょう]を混[ま]ぜると、土[つち]が元気[げんき]になる。", "sentence_source": "generated"}, {"text": "昔は、人が鍬だけで広い土地を耕していた。", "target_word": "耕して", "complexity_tier": "T3", "furigana": "昔[むかし]は、人[ひと]が鍬[くわ]だけで広[ひろ]い土地[とち]を耕[たがや]していた。", "sentence_source": "generated"}, {"text": "日曜日に家族みんなで庭を耕した。", "target_word": "耕した", "complexity_tier": "T3", "furigana": "日曜日[にちようび]に家族[かぞく]みんなで庭[にわ]を耕[たがや]した。", "sentence_source": "generated"}, {"text": "この機械を使えば、半日で畑を耕せる。", "target_word": "耕せる", "complexity_tier": "T3", "furigana": "この機械[きかい]を使[つか]えば、半日[はんにち]で畑[はたけ]を耕[たがや]せる。", "sentence_source": "generated"}, {"text": "雨で土がぬれているときは、耕すのをやめたほうがいい。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "雨[あめ]で土[つち]がぬれているときは、耕[たがや]すのをやめたほうがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耕す", "label": "終止形・連体形"}, {"form": "耕し", "label": "連用形"}, {"form": "耕さ", "label": "未然形"}, {"form": "耕せ", "label": "仮定形・命令形"}, {"form": "耕そ", "label": "意志形語幹"}, {"form": "耕した", "label": "過去形"}, {"form": "耕して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "鍬や機械などの道具で土をやわらかくする五段動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耕す", "is_correct": true, "explanation": "終止形で文を言い切り、『秋の終わりに田んぼを耕す』と習慣を述べる。"}, {"text": "耕し", "is_correct": false, "explanation": "連用形は文末に置けず、言い切りの文が成り立たない。"}, {"text": "耕さ", "is_correct": false, "explanation": "未然形は文末に置けず、文が途中で切れる。"}, {"text": "耕せ", "is_correct": false, "explanation": "命令形は『耕せ』と命じる文になり、農家の習慣を述べる文に合わない。"}], "explanations": {"耕す": "終止形で文を言い切り、『秋の終わりに田んぼを耕す』と習慣を述べる。", "耕し": "連用形は文末に置けず、言い切りの文が成り立たない。", "耕さ": "未然形は文末に置けず、文が途中で切れる。", "耕せ": "命令形は『耕せ』と命じる文になり、農家の習慣を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "耕す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裏庭に井戸を耕すため、業者が来た。", "explanation": "ここは〈掘る〉の意味。耕すは道具で土をやわらかくすることで、深く穴を掘って井戸をつくる作業は指さないので合わない。"}, {"text": "夕方、母は鍋のスープを耕して、味をみた。", "explanation": "ここは〈かき混ぜる〉の意味。耕すは土をやわらかくする意味で、液体をかき混ぜる動作は指さないので合わない。"}, {"text": "プランターに花を耕して、窓辺に置く。", "explanation": "ここは〈植える〉の意味。耕すは土をやわらかくする作業で、花の苗や種を入れて育てることは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕して", "is_correct": true, "explanation": "て形で『耕している』と続き、『いた』で過去の継続動作を表す。"}, {"text": "耕す", "is_correct": false, "explanation": "辞書形は『耕すいた』と続けられず、文が成り立たない。"}, {"text": "耕した", "is_correct": false, "explanation": "過去形は『耕したいた』と続けられず、不自然。"}, {"text": "耕そ", "is_correct": false, "explanation": "意志形語幹は『耕そていた』と続かず、文が成り立たない。"}], "explanations": {"耕して": "て形で『耕している』と続き、『いた』で過去の継続動作を表す。", "耕す": "辞書形は『耕すいた』と続けられず、文が成り立たない。", "耕した": "過去形は『耕したいた』と続けられず、不自然。", "耕そ": "意志形語幹は『耕そていた』と続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "耕して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新築の前に、業者が敷地を耕した。", "explanation": "ここは〈整地〉の意味。耕すは土をやわらかくして植物が育つ状態にすることで、地面を平らにならす作業は指さないので合わない。"}, {"text": "母は洗濯機で靴下を耕した。", "explanation": "ここは〈洗う〉の意味。耕すは土に関する動作で、衣類の汚れを落とす行為は指さないので合わない。"}, {"text": "作業員は硬い岩を耕して、道を作った。", "explanation": "ここは〈砕く〉の意味。耕すは土をやわらかくする意味で、硬い岩を細かく割ることは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農家は、秋の終わりに田んぼに耕した。", "corrected_sentence": "農家は、秋の終わりに田んぼを耕した。", "error_description": "耕す対象は『田んぼを』と『を』で示す。『田んぼに耕した』では対象が示されず、不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "耕した", "is_correct": true, "explanation": "過去形で、弟が実際に行った動作を述べる。"}, {"text": "耕し", "is_correct": false, "explanation": "連用形は文末に置けず、動作を言い切れない。"}, {"text": "耕せ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文に合わない。"}, {"text": "耕そ", "is_correct": false, "explanation": "意志形語幹は文末に置けず、文が成り立たない。"}], "correct_form": "耕した", "base_form": "耕す", "form_label": "過去形", "sentence_index": 1, "explanations": {"耕した": "過去形で、弟が実際に行った動作を述べる。", "耕し": "連用形は文末に置けず、動作を言い切れない。", "耕せ": "命令形で、過去の出来事を述べる文に合わない。", "耕そ": "意志形語幹は文末に置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51503, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、叔父は畑を耕さた。", "corrected_sentence": "昨日、叔父は畑を耕した。", "error_description": "過去形は『耕した』。『耕さた』は未然形に『た』を付けた誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "耕した", "is_correct": true, "explanation": "過去形で、家族が実際に行った動作を述べる。"}, {"text": "耕せる", "is_correct": false, "explanation": "可能形は能力を表し、実際に行った出来事を述べる文に合わない。"}, {"text": "耕させ", "is_correct": false, "explanation": "使役の語幹で文末に置けず、文が成り立たない。"}, {"text": "耕して", "is_correct": false, "explanation": "て形は文を言い切れず、文末に置けない。"}], "correct_form": "耕した", "base_form": "耕す", "form_label": "過去形", "sentence_index": 7, "explanations": {"耕した": "過去形で、家族が実際に行った動作を述べる。", "耕せる": "可能形は能力を表し、実際に行った出来事を述べる文に合わない。", "耕させ": "使役の語幹で文末に置けず、文が成り立たない。", "耕して": "て形は文を言い切れず、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "直接の対象（畑）を示し、『畑を耕す』として正しい。"}, {"text": "が", "is_correct": false, "explanation": "『畑が耕す』と主語にすると、畑が耕す主体になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "『この畑に耕す』では対象が示されず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、『畑へ耕す』は動作の対象にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "直接の対象（畑）を示し、『畑を耕す』として正しい。", "が": "『畑が耕す』と主語にすると、畑が耕す主体になり不自然。", "に": "『この畑に耕す』では対象が示されず、文が成り立たない。", "へ": "方向を表すが、『畑へ耕す』は動作の対象にならず不自然。"}, "error_tags": {"を": "対象", "が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
