INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "土を掘り返して、植物が育ちやすいようにすること。", "primary_collocate": null, "pronunciation": "たがやす", "ipa": "taɡajasɯ", "syllable_count": 4, "sentences": [{"text": "経験豊富な農家は、広大な畑の土壌を丁寧に耕し、野菜の種を植える。", "target_word": "耕し", "complexity_tier": "T4", "furigana": "経験[けいけん]豊富[ほうふ]な農家[のうか]は、広大[こうだい]な畑[はたけ]の土壌[どじょう]を丁寧[ていねい]に耕[たがや]し、野菜[やさい]の種[たね]を植[う]える。", "sentence_source": "mined"}, {"text": "春になると、祖父は毎年この畑を耕す。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "春[はる]になると、祖父[そふ]は毎年[まいとし]この畑[はたけ]を耕[たがや]す。", "sentence_source": "generated"}, {"text": "種をまく前に、鍬で土を深く耕した。", "target_word": "耕した", "complexity_tier": "T3", "furigana": "種[たね]をまく前[まえ]に、鍬[くわ]で土[つち]を深[ふか]く耕[たがや]した。", "sentence_source": "generated"}, {"text": "固い土は、耕さなければ野菜が育たない。", "target_word": "耕さ", "complexity_tier": "T3", "furigana": "固[かた]い土[つち]は、耕[たがや]さなければ野菜[やさい]が育[そだ]たない。", "sentence_source": "generated"}, {"text": "父はトラクターで広い田んぼを耕している。", "target_word": "耕して", "complexity_tier": "T3", "furigana": "父[ちち]はトラクターで広[ひろ]い田[た]んぼを耕[たがや]している。", "sentence_source": "generated"}, {"text": "雨が降る前に、畑を耕してしまいたい。", "target_word": "耕して", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]に、畑[はたけ]を耕[たがや]してしまいたい。", "sentence_source": "generated"}, {"text": "土を耕すと、中から小さな虫が出てきた。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "土[つち]を耕[たがや]すと、中[なか]から小[ちい]さな虫[むし]が出[で]てきた。", "sentence_source": "generated"}, {"text": "彼は退職後、小さな土地を借りて耕し始めた。", "target_word": "耕し", "complexity_tier": "T3", "furigana": "彼[かれ]は退職後[たいしょくご]、小[ちい]さな土地[とち]を借[か]りて耕[たがや]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "この石だらけの土地は、耕すのが大変だ。", "target_word": "耕す", "complexity_tier": "T3", "furigana": "この石[いし]だらけの土地[とち]は、耕[たがや]すのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "花を植えるために、庭の土をやわらかく耕そう。", "target_word": "耕そ", "complexity_tier": "T3", "furigana": "花[はな]を植[う]えるために、庭[にわ]の土[つち]をやわらかく耕[たがや]そう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "耕す", "label": "終止形・連体形"}, {"form": "耕し", "label": "連用形"}, {"form": "耕さ", "label": "未然形"}, {"form": "耕せ", "label": "仮定形・命令形"}, {"form": "耕そ", "label": "意志形語幹"}, {"form": "耕した", "label": "過去形"}, {"form": "耕して", "label": "て形"}], "register": "neutral", "sense_fingerprint": "畑の土を掘り返して作物が育つ状態にする五段動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耕し", "is_correct": true, "explanation": "連用形で『耕し、〜植える』と中止法で続き、並行する動作を表す。"}, {"text": "耕さ", "is_correct": false, "explanation": "未然形は『耕さ、』で文を中止できず、この文の空欄には入らない。"}, {"text": "耕せ", "is_correct": false, "explanation": "命令形は『耕せ、』と続けられず、『農家は』の述語として合わない。"}, {"text": "耕そ", "is_correct": false, "explanation": "意志形語幹は『耕そ、』と中止に使えず、文が成り立たない。"}], "explanations": {"耕し": "連用形で『耕し、〜植える』と中止法で続き、並行する動作を表す。", "耕さ": "未然形は『耕さ、』で文を中止できず、この文の空欄には入らない。", "耕せ": "命令形は『耕せ、』と続けられず、『農家は』の述語として合わない。", "耕そ": "意志形語幹は『耕そ、』と中止に使えず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "耕し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもが砂場で穴を耕して遊んだ。", "explanation": "ここは〈掘る〉の意味。耕すは土をやわらかくして作物を育てる準備で、穴をあける行為は指さないので合わない。"}, {"text": "彼は古い書類の山を耕して、必要な資料を見つけた。", "explanation": "ここは〈探し出す〉の意味。耕すは土をやわらかくして植物を育てる意味で、書類の山を調べて探すことは指さないので合わない。"}, {"text": "週末に庭へ花の苗を耕した。", "explanation": "ここは〈植える〉の意味。耕すは土を掘り返す作業で、苗を植え込むことは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕す", "is_correct": true, "explanation": "辞書形で『と』に続き、『耕すと〜出てきた』と条件を表す。"}, {"text": "耕し", "is_correct": false, "explanation": "連用形は『と』に続けられず、文が成り立たない。"}, {"text": "耕して", "is_correct": false, "explanation": "て形は『と』の前に置けず、この文の条件節として不自然。"}, {"text": "耕そ", "is_correct": false, "explanation": "意志形語幹は『耕そと』と条件を表せず、文が成り立たない。"}], "explanations": {"耕す": "辞書形で『と』に続き、『耕すと〜出てきた』と条件を表す。", "耕し": "連用形は『と』に続けられず、文が成り立たない。", "耕して": "て形は『と』の前に置けず、この文の条件節として不自然。", "耕そ": "意志形語幹は『耕そと』と条件を表せず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "耕す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事の前に、業者が敷地を耕した。", "explanation": "ここは〈整地〉の意味。耕すは土をやわらかくして植物が育つ状態にすることで、地面を平らにならす作業は指さないので合わない。"}, {"text": "母は洗濯機で靴下を耕した。", "explanation": "ここは〈洗う〉の意味。耕すは土に関する動作で、衣類の汚れを落とす行為は指さないので合わない。"}, {"text": "からまった糸を耕して、やっとほどけた。", "explanation": "ここは〈ほぐす〉の意味。耕すは土を掘り返して育ちやすくする意味で、からまりを解くことは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎年、庭の土に耕す。", "corrected_sentence": "祖父は毎年、庭の土を耕す。", "error_description": "耕す対象は『土を』と『を』で示す。『土に耕す』では対象が示されず、不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "耕す", "is_correct": true, "explanation": "終止形で文末に置き、毎年の習慣を述べる。"}, {"text": "耕し", "is_correct": false, "explanation": "連用形は文末に置けず、文が途中で切れる。"}, {"text": "耕さ", "is_correct": false, "explanation": "未然形は文末に置けず、文が途中で切れる。"}, {"text": "耕せ", "is_correct": false, "explanation": "命令形で、祖父の習慣を述べる文に合わない。"}], "correct_form": "耕す", "base_form": "耕す", "form_label": "終止形", "sentence_index": 1, "explanations": {"耕す": "終止形で文末に置き、毎年の習慣を述べる。", "耕し": "連用形は文末に置けず、文が途中で切れる。", "耕さ": "未然形は文末に置けず、文が途中で切れる。", "耕せ": "命令形で、祖父の習慣を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、弟は庭を耕さた。", "corrected_sentence": "昨日、弟は庭を耕した。", "error_description": "過去形は『耕した』。『耕さた』は未然形に『た』を付けた誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "耕し", "is_correct": true, "explanation": "連用形で『始める』と続け、『耕し始めた』となる。"}, {"text": "耕す", "is_correct": false, "explanation": "終止形は『耕す始めた』とならず、文が成り立たない。"}, {"text": "耕さ", "is_correct": false, "explanation": "未然形は『耕さ始めた』と続かず、文が成り立たない。"}, {"text": "耕して", "is_correct": false, "explanation": "て形は『耕して始めた』と続けられない。"}], "correct_form": "耕し", "base_form": "耕す", "form_label": "連用形", "sentence_index": 7, "explanations": {"耕し": "連用形で『始める』と続け、『耕し始めた』となる。", "耕す": "終止形は『耕す始めた』とならず、文が成り立たない。", "耕さ": "未然形は『耕さ始めた』と続かず、文が成り立たない。", "耕して": "て形は『耕して始めた』と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "給食を話題として示す『は』。給食について、毎日同じ時間に食べると述べる文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では『給食が食べる』となり、食べる主体として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の『の』では『給食の、毎日…』と文が続かず、文の骨組みが崩れる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』では『給食へ食べる』となり、食べる対象として合わない。"}], "correct_answer": "は", "explanations": {"は": "給食を話題として示す『は』。給食について、毎日同じ時間に食べると述べる文になる。", "が": "主語の『が』では『給食が食べる』となり、食べる主体として不自然。", "の": "連体修飾の『の』では『給食の、毎日…』と文が続かず、文の骨組みが崩れる。", "へ": "方向の『へ』では『給食へ食べる』となり、食べる対象として合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "へ": "方向", "は": "話題"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "給食と費用をつなぎ、給食の費用という名詞句を作る『の』。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では『給食を費用は』となり、費用と結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "対象を示す『に』では『給食に費用は』となり、つながらない。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』では『給食で費用は』となり、費用の引き落としと結びつかない。"}], "correct_answer": "の", "explanations": {"の": "給食と費用をつなぎ、給食の費用という名詞句を作る『の』。", "を": "目的語の『を』では『給食を費用は』となり、費用と結びつかない。", "に": "対象を示す『に』では『給食に費用は』となり、つながらない。", "で": "手段の『で』では『給食で費用は』となり、費用の引き落としと結びつかない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校や施設で提供される食事。特に、学校給食を指す。", "primary_collocate": null, "pronunciation": "きゅうしょく", "ipa": "kʲɯːɕokɯ", "syllable_count": 4, "sentences": [{"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "給食", "complexity_tier": "T4", "furigana": "彼[かれ]がこれらを大切[たいせつ]に育[そだ]てる理由[りゆう]は、地域[ちいき]の子供[こども]たちに安全[あんぜん]な給食[きゅうしょく]を安定的[あんていてき]に提供[ていきょう]するためだ。", "sentence_source": "mined"}, {"text": "小学校の給食は、毎日みんなで同じ時間に食べる。", "target_word": "給食", "complexity_tier": "T3", "furigana": "小学校[しょうがっこう]の給食[きゅうしょく]は、毎日[まいにち]みんなで同[おな]じ時間[じかん]に食[た]べる。", "sentence_source": "generated"}, {"text": "今日の給食には、大好きなカレーが出た。", "target_word": "給食", "complexity_tier": "T3", "furigana": "今日[きょう]の給食[きゅうしょく]には、大好[だいす]きなカレーが出[で]た。", "sentence_source": "generated"}, {"text": "給食当番の人は、白い服を着て配膳をする。", "target_word": "給食", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]当番[とうばん]の人[ひと]は、白[しろ]い服[ふく]を着[き]て配膳[はいぜん]をする。", "sentence_source": "generated"}, {"text": "姉は牛乳が苦手で、給食の時間が少しつらかった。", "target_word": "給食", "complexity_tier": "T3", "furigana": "姉[あね]は牛乳[ぎゅうにゅう]が苦手[にがて]で、給食[きゅうしょく]の時間[じかん]が少[すこ]しつらかった。", "sentence_source": "generated"}, {"text": "病院の給食は、栄養士が考えた献立で作られる。", "target_word": "給食", "complexity_tier": "T3", "furigana": "病院[びょういん]の給食[きゅうしょく]は、栄養士[えいようし]が考[かんが]えた献立[こんだて]で作[つく]られる。", "sentence_source": "generated"}, {"text": "アレルギーがある子には、給食で別のおかずが用意される。", "target_word": "給食", "complexity_tier": "T3", "furigana": "アレルギーがある子[こ]には、給食[きゅうしょく]で別[べつ]のおかずが用意[ようい]される。", "sentence_source": "generated"}, {"text": "給食の費用は、毎月銀行から引き落とされる。", "target_word": "給食", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]の費用[ひよう]は、毎月[まいつき]銀行[ぎんこう]から引[ひ]き落[お]とされる。", "sentence_source": "generated"}, {"text": "雨の日は、教室で給食を食べてから昼休みを過ごした。", "target_word": "給食", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、教室[きょうしつ]で給食[きゅうしょく]を食[た]べてから昼休[ひるやす]みを過[す]ごした。", "sentence_source": "generated"}, {"text": "給食を残さず食べたので、先生にほめられた。", "target_word": "給食", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]を残[のこ]さず食[た]べたので、先生[せんせい]にほめられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "給食", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "学校や施設がまとめて出す食事、特に学校の昼食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "給食", "is_correct": true, "explanation": "学校などが子どもに出す食事を指し、安全な食事を提供する文脈に合う。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶は提供する物ではないので、食事を提供する文脈に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は出されるもので、食事のように安定的に提供する対象にはならない。"}, {"text": "通学路", "is_correct": false, "explanation": "通学路は道であり、食事として提供する対象ではない。"}], "explanations": {"給食": "学校などが子どもに出す食事を指し、安全な食事を提供する文脈に合う。", "挨拶": "挨拶は提供する物ではないので、食事を提供する文脈に合わない。", "宿題": "宿題は出されるもので、食事のように安定的に提供する対象にはならない。", "通学路": "通学路は道であり、食事として提供する対象ではない。"}, "sentence_index": 0, "correct_answer": "給食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、母が作った給食を持って遠足に行った。", "explanation": "家で作って持たせる食事は〈弁当〉の意味。給食は学校や施設が用意する食事なので、家庭の手作りには使わない。"}, {"text": "雨で外に出られず、店に電話して給食を届けてもらった。", "explanation": "注文して届けてもらう食事は〈出前〉の意味。給食は学校や施設が決まって出すもので、店に注文する場面には使わない。"}, {"text": "車のガス欠に気づき、スタンドで給食を入れてもらった。", "explanation": "燃料を入れることは〈給油〉の意味。給食は食事なので、車に入れるものとしては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "給食", "is_correct": true, "explanation": "学校などが用意する食事で、アレルギーの子の別メニューを出す文脈に合う。"}, {"text": "名簿", "is_correct": false, "explanation": "名簿で別のおかずが用意されるという意味にはならず、手段として合わない。"}, {"text": "上履き", "is_correct": false, "explanation": "上履きは履く物で、おかずを用意する場所や手段にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学習に使う物で、おかずを用意する手段として合わない。"}], "explanations": {"給食": "学校などが用意する食事で、アレルギーの子の別メニューを出す文脈に合う。", "名簿": "名簿で別のおかずが用意されるという意味にはならず、手段として合わない。", "上履き": "上履きは履く物で、おかずを用意する場所や手段にはならない。", "教科書": "教科書は学習に使う物で、おかずを用意する手段として合わない。"}, "sentence_index": 6, "correct_answer": "給食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レストランの人手が足りず、給食を担当して料理を運んだ。", "explanation": "食卓で料理を運び、客のそばで世話をすることは〈給仕〉の意味。給食は学校や施設が出す食事なので、客に料理を運ぶ仕事には使わない。"}, {"text": "仕事から帰ると、家族で給食を囲んだ。", "explanation": "家庭で家族と食べる夕食は〈夕食〉の意味。給食は学校や施設が出す食事なので、家族の食卓には合わない。"}, {"text": "地震に備えて、防災袋に給食を入れておいた。", "explanation": "備えておく食料は〈非常食〉の意味。給食は提供される食事で、備蓄する物としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "給食を時間には、みんなで手を洗ってから席に着く。", "corrected_sentence": "給食の時間には、みんなで手を洗ってから席に着く。", "error_description": "正しくは「給食の時間」で、『の』が時間につながる。「給食を時間」は『を』を使っており、時間には続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "給食を拾う係は、毎日交代で決める。", "corrected_sentence": "給食を配る係は、毎日交代で決める。", "error_description": "正しくは「給食を配る」。「拾う」は落ちた物を集める動作で、配膳の係の仕事には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "予報を話題として示す『は』。今日の予報について、晴れだったと述べる文になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では『予報を晴れだった』となり、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "時点や対象を示す『に』では『予報に晴れだった』となり、つながらない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の『の』では『予報の晴れだった』となり、文の骨組みが崩れる。"}], "correct_answer": "は", "explanations": {"は": "予報を話題として示す『は』。今日の予報について、晴れだったと述べる文になる。", "を": "目的語の『を』では『予報を晴れだった』となり、文として成り立たない。", "に": "時点や対象を示す『に』では『予報に晴れだった』となり、つながらない。", "の": "連体修飾の『の』では『予報の晴れだった』となり、文の骨組みが崩れる。"}, "error_tags": {"を": "目的語", "に": "場所・時点", "の": "連体修飾", "は": "話題"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す『が』。明日の予報が良ければ、という条件の文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』では『予報へ良ければ』となり、条件の文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』では『予報と良ければ』となり、主語が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』では『予報で良ければ』となり、予報の良し悪しを示せない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す『が』。明日の予報が良ければ、という条件の文になる。", "へ": "方向の『へ』では『予報へ良ければ』となり、条件の文が成り立たない。", "と": "並列の『と』では『予報と良ければ』となり、主語が成立しない。", "で": "手段の『で』では『予報で良ければ』となり、予報の良し悪しを示せない。"}, "error_tags": {"へ": "方向", "と": "並列", "で": "手段", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これからどうなるか、天気のことを前もって教えてくれること。", "primary_collocate": null, "pronunciation": "よほう", "ipa": "joho̞ː", "syllable_count": 3, "sentences": [{"text": "予報によると、明日は朝から強い雨が降るそうだ。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]によると、明日[あした]は朝[あさ]から強[つよ]い雨[あめ]が降[ふ]るそうだ。", "sentence_source": "generated"}, {"text": "今日の予報は晴れだったのに、午後になって急に雨が降り出した。", "target_word": "予報", "complexity_tier": "T3", "furigana": "今日[きょう]の予報[よほう]は晴[は]れだったのに、午後[ごご]になって急[きゅう]に雨[あめ]が降[ふ]り出[だ]した。", "sentence_source": "generated"}, {"text": "予報が外れて、傘を持たずに出かけた私はずぶ濡れになった。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]が外[はず]れて、傘[かさ]を持[も]たずに出[で]かけた私[わたし]はずぶ濡[ぬ]れになった。", "sentence_source": "generated"}, {"text": "週末は台風が近づくという予報なので、キャンプは中止にした。", "target_word": "予報", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は台風[たいふう]が近[ちか]づくという予報[よほう]なので、キャンプは中止[ちゅうし]にした。", "sentence_source": "generated"}, {"text": "ラジオの予報で、夜から気温が下がると聞いて、厚いコートを出した。", "target_word": "予報", "complexity_tier": "T3", "furigana": "ラジオの予報[よほう]で、夜[よる]から気温[きおん]が下[さ]がると聞[き]いて、厚[あつ]いコートを出[だ]した。", "sentence_source": "generated"}, {"text": "予報では雪になるはずだったが、実際には一日中曇りだった。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]では雪[ゆき]になるはずだったが、実際[じっさい]には一日中[いちにちじゅう]曇[くも]りだった。", "sentence_source": "generated"}, {"text": "農家の人たちは、毎日の予報を見ながら、種をまく日を決める。", "target_word": "予報", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、毎日[まいにち]の予報[よほう]を見[み]ながら、種[たね]をまく日[ひ]を決[き]める。", "sentence_source": "generated"}, {"text": "明日の予報が良ければ、家族みんなで海へ行くつもりだ。", "target_word": "予報", "complexity_tier": "T3", "furigana": "明日[あした]の予報[よほう]が良[よ]ければ、家族[かぞく]みんなで海[うみ]へ行[い]くつもりだ。", "sentence_source": "generated"}, {"text": "山に登る前に、必ず予報を確認して、天気が崩れそうなら引き返す。", "target_word": "予報", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]る前[まえ]に、必[かなら]ず予報[よほう]を確認[かくにん]して、天気[てんき]が崩[くず]れそうなら引[ひ]き返[かえ]す。", "sentence_source": "generated"}, {"text": "予報は大雪だったので、会社は早めに社員を家に帰した。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]は大雪[おおゆき]だったので、会社[かいしゃ]は早[はや]めに社員[しゃいん]を家[いえ]に帰[かえ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予報", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "weather forecast: advance notice of what the weather will do", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予報", "is_correct": true, "explanation": "情報の出どころを示す『予報によると』に合う、天気の見通しを表す語。"}, {"text": "気温", "is_correct": false, "explanation": "気温によると雨が降るという内容にはならず、文として合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は雨の見通しを示す語ではないので、この文の根拠にはならない。"}, {"text": "気圧", "is_correct": false, "explanation": "気圧は測定値であり、雨が降るという見通しを示す根拠としては合わない。"}], "explanations": {"予報": "情報の出どころを示す『予報によると』に合う、天気の見通しを表す語。", "気温": "気温によると雨が降るという内容にはならず、文として合わない。", "湿度": "湿度は雨の見通しを示す語ではないので、この文の根拠にはならない。", "気圧": "気圧は測定値であり、雨が降るという見通しを示す根拠としては合わない。"}, "sentence_index": 0, "correct_answer": "予報"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大臣の発言がテレビで予報された。", "explanation": "知らせる内容を伝えることは〈報道〉の意味。予報は天気の見通しなので、大臣の発言には使わない。"}, {"text": "試合の勝ち負けは、予報どおりに決まった。", "explanation": "見込みどおりになることは〈予想〉の意味。予報は天気について使うので、試合の勝敗には合わない。"}, {"text": "公演の日程は、予報どおり来月に決まった。", "explanation": "前もって知らせることは〈予告〉の意味。予報は天気の見通しなので、公演の日程には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予報", "is_correct": true, "explanation": "毎日の天気の見通しを見て種まきの日を決める、という文脈に合う『予報』。"}, {"text": "傘", "is_correct": false, "explanation": "傘は見て種まきを決める判断材料にはならず、予報の代わりとして合わない。"}, {"text": "長靴", "is_correct": false, "explanation": "長靴は履く物で、見ながら種まきの日を決める対象にはならない。"}, {"text": "雨具", "is_correct": false, "explanation": "雨具は身につける物で、種まきの日を決める判断材料として合わない。"}], "explanations": {"予報": "毎日の天気の見通しを見て種まきの日を決める、という文脈に合う『予報』。", "傘": "傘は見て種まきを決める判断材料にはならず、予報の代わりとして合わない。", "長靴": "長靴は履く物で、見ながら種まきの日を決める対象にはならない。", "雨具": "雨具は身につける物で、種まきの日を決める判断材料として合わない。"}, "sentence_index": 6, "correct_answer": "予報"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の予報は、もう決まっている。", "explanation": "前もって決めた計画は〈予定〉の意味。予報は天気などの見通しなので、決まるものではない。"}, {"text": "来年度の予報は、会議で決まった。", "explanation": "お金の計画は〈予算〉の意味。予報は天気の見通しで、会議で決める対象ではない。"}, {"text": "風邪を予報するために、うがいを続けている。", "explanation": "病気を前もって防ぐことは〈予防〉の意味。予報は天気などを知らせるもので、病気には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "予報が勝って、夕方には雪が積もった。", "corrected_sentence": "予報が当たって、夕方には雪が積もった。", "error_description": "正しくは「予報が当たる」。「勝つ」は競争の結果に使う動詞で、予報の的中を表す言い方には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "予報を反して、一日中晴れ間が続いた。", "corrected_sentence": "予報に反して、一日中晴れ間が続いた。", "error_description": "正しくは「予報に反して」。『反する』は『〜に反する』と対象を『に』で示すので、『を』は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "情報源を示す『では』の『で』。予報を根拠に話す文になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では『予報が、は』となり、文が続かない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では『予報を、は』となり、予報を対象にする文脈がない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の『の』では『予報の、は』となり、名詞句が途切れる。"}], "correct_answer": "で", "explanations": {"で": "情報源を示す『では』の『で』。予報を根拠に話す文になる。", "が": "主語の『が』では『予報が、は』となり、文が続かない。", "を": "目的語の『を』では『予報を、は』となり、予報を対象にする文脈がない。", "の": "連体修飾の『の』では『予報の、は』となり、名詞句が途切れる。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "天気の状態を予測して知らせること。特に気象庁などが発表するもの。", "primary_collocate": null, "pronunciation": "よほう", "ipa": "johoː", "syllable_count": 3, "sentences": [{"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "予報", "complexity_tier": "T4", "furigana": "毎朝[まいあさ]の天気[てんき]予報[よほう]を確認[かくにん]し、気温[きおん]や湿度[しつど]に合[あ]わせて水[みず]を調整[ちょうせい]する。", "sentence_source": "mined"}, {"text": "明日の予報では、午後から雨が降るそうだ。", "target_word": "予報", "complexity_tier": "T3", "furigana": "明日[あした]の予報[よほう]では、午後[ごご]から雨[あめ]が降[ふ]るそうだ。", "sentence_source": "generated"}, {"text": "予報が外れて、一日中いい天気だった。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]が外[はず]れて、一日中[いちにちじゅう]いい天気[てんき]だった。", "sentence_source": "generated"}, {"text": "台風が近づいているという予報を聞いて、旅行をやめた。", "target_word": "予報", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているという予報[よほう]を聞[き]いて、旅行[りょこう]をやめた。", "sentence_source": "generated"}, {"text": "気象庁は、大雪の予報を朝のうちに発表した。", "target_word": "予報", "complexity_tier": "T3", "furigana": "気象庁[きしょうちょう]は、大雪[おおゆき]の予報[よほう]を朝[あさ]のうちに発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "予報によると、週末は気温がぐっと下がるらしい。", "target_word": "予報", "complexity_tier": "T3", "furigana": "予報[よほう]によると、週末[しゅうまつ]は気温[きおん]がぐっと下[さ]がるらしい。", "sentence_source": "generated"}, {"text": "傘を持たずに出かけたら、予報どおりに雨が降ってきた。", "target_word": "予報", "complexity_tier": "T3", "furigana": "傘[かさ]を持[も]たずに出[で]かけたら、予報[よほう]どおりに雨[あめ]が降[ふ]ってきた。", "sentence_source": "generated"}, {"text": "夜に霜が降りるという予報なので、植木鉢を家の中に入れた。", "target_word": "予報", "complexity_tier": "T3", "furigana": "夜[よる]に霜[しも]が降[お]りるという予報[よほう]なので、植木鉢[うえきばち]を家[いえ]の中[なか]に入[い]れた。", "sentence_source": "generated"}, {"text": "来週の予報を見て、遠足の日を決めた。", "target_word": "予報", "complexity_tier": "T3", "furigana": "来週[らいしゅう]の予報[よほう]を見[み]て、遠足[えんそく]の日[ひ]を決[き]めた。", "sentence_source": "generated"}, {"text": "予報は当たらないことも多いので、傘は念のため持って行くといい。", "target_word": "予報", "complexity_tier": "T3", "furigana": "{予報|よほう}は{当|あ}たらないことも{多|おお}いので、{傘|かさ}は{念|ねん}のため{持|も}って{行|い}くといい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "予報", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "天気の見通しを前もって発表する知らせ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "予報", "is_correct": true, "explanation": "天気の見通しを前もって知らせる『予報』で、毎朝確認する対象として合う。"}, {"text": "予定", "is_correct": false, "explanation": "予定は自分の計画を指し、天気の見通しを確認する対象ではない。"}, {"text": "手帳", "is_correct": false, "explanation": "手帳は書き留める物で、天気の見通しを確認する対象ではない。"}, {"text": "気圧", "is_correct": false, "explanation": "気圧は測定される数値で、『天気＋気圧』は確認する見通しの語として不自然。"}], "explanations": {"予報": "天気の見通しを前もって知らせる『予報』で、毎朝確認する対象として合う。", "予定": "予定は自分の計画を指し、天気の見通しを確認する対象ではない。", "手帳": "手帳は書き留める物で、天気の見通しを確認する対象ではない。", "気圧": "気圧は測定される数値で、『天気＋気圧』は確認する見通しの語として不自然。"}, "sentence_index": 0, "correct_answer": "予報"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の結果は、予報どおり二対一になった。", "explanation": "見込みどおりに進むことは〈予想〉の意味。予報は天気の見通しに使う語なので、試合の結果には合わない。"}, {"text": "新しい店の開店は、予報どおり来月に決まった。", "explanation": "前もって知らせることは〈予告〉の意味。予報は天気について使うので、店の開店には使わない。"}, {"text": "友人の結婚相手を予報して、祝いの品を選んだ。", "explanation": "前もって言い当てることは〈予言〉の意味。予報は天気などの見通しを伝える語なので、人の将来には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "予報", "is_correct": true, "explanation": "予報どおりに雨が降るという、天気の見通しを表す『予報』に合う。"}, {"text": "献立", "is_correct": false, "explanation": "献立は食事の計画で、雨が降る見通しを表す言葉としては合わない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は時間を示す表で、雨の降り方を表す語として合わない。"}, {"text": "台本", "is_correct": false, "explanation": "台本は演技の筋書きで、天気の出来事を表す言葉としては合わない。"}], "explanations": {"予報": "予報どおりに雨が降るという、天気の見通しを表す『予報』に合う。", "献立": "献立は食事の計画で、雨が降る見通しを表す言葉としては合わない。", "時刻表": "時刻表は時間を示す表で、雨の降り方を表す語として合わない。", "台本": "台本は演技の筋書きで、天気の出来事を表す言葉としては合わない。"}, "sentence_index": 6, "correct_answer": "予報"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪を予報するために、手洗いを続けている。", "explanation": "病気を前もって防ぐことは〈予防〉の意味。予報は天気などを知らせるもので、病気には使わない。"}, {"text": "人気の店は、予報がないと入れない。", "explanation": "席や日時を前もって取ることは〈予約〉の意味。予報は天気の見通しなので、店の席には使わない。"}, {"text": "思いがけない展開を、予報できなかった。", "explanation": "前もって思い描くことは〈予期〉の意味。予報は天気などを知らせることで、出来事の見込みには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週間予報を、来週は寒さが続くと言っていた。", "corrected_sentence": "週間予報で、来週は寒さが続くと言っていた。", "error_description": "正しくは「週間予報で〜と言っていた」。『予報を』は言う対象として不自然で、情報源を示す『で』が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雨の予報が食べられて、休校が決まった。", "corrected_sentence": "大雨の予報が出されて、休校が決まった。", "error_description": "正しくは「予報が出される」。「食べられる」は予報と結びつかない動詞で、この文脈では誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
