INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51515, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何も言わずに、ずっと何かをすること。", "primary_collocate": null, "pronunciation": "もくもく", "ipa": "mokɯmokɯ", "syllable_count": 4, "sentences": [{"text": "彼は昼休みも話さず、黙々と作業を続けた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "彼[かれ]は昼休[ひるやす]みも話[はな]さず、黙々[もくもく]と作業[さぎょう]を続[つづ]けた。", "sentence_source": "generated"}, {"text": "生徒たちは黙々と問題を解いている。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "生徒[せいと]たちは黙々[もくもく]と問題[もんだい]を解[と]いている。", "sentence_source": "generated"}, {"text": "朝早く、父は黙々と雪かきをしていた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "朝早[あさはや]く、父[ちち]は黙々[もくもく]と雪[ゆき]かきをしていた。", "sentence_source": "generated"}, {"text": "彼女は文句を言わずに、黙々と皿を洗った。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は文句[もんく]を言[い]わずに、黙々[もくもく]と皿[さら]を洗[あら]った。", "sentence_source": "generated"}, {"text": "試験の前の夜、弟は黙々と勉強していた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]の夜[よる]、弟[おとうと]は黙々[もくもく]と勉強[べんきょう]していた。", "sentence_source": "generated"}, {"text": "職人は黙々と木を削り、美しい箱を作った。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "職人[しょくにん]は黙々[もくもく]と木[き]を削[けず]り、美[うつく]しい箱[はこ]を作[つく]った。", "sentence_source": "generated"}, {"text": "登山者たちは黙々と山道を歩き続けた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]たちは黙々[もくもく]と山道[やまみち]を歩[ある]き続[つづ]けた。", "sentence_source": "generated"}, {"text": "彼は人と話すより、黙々と絵を描くのが好きだ。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]と話[はな]すより、黙々[もくもく]と絵[え]を描[か]くのが好[す]きだ。", "sentence_source": "generated"}, {"text": "みんなが帰ったあとも、黙々と掃除する人がいた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "みんなが帰[かえ]ったあとも、黙々[もくもく]と掃除[そうじ]する人[ひと]がいた。", "sentence_source": "generated"}, {"text": "黙々と走る姿を見て、仲間も力が出てきた。", "target_word": "黙々", "complexity_tier": "T3", "furigana": "黙々[もくもく]と走[はし]る姿[すがた]を見[み]て、仲間[なかま]も力[ちから]が出[で]てきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "黙々", "label": "基本形"}, {"form": "黙々と", "label": "連用形（と）"}], "register": "常体（中立）", "sense_fingerprint": "口をきかず、ひたすら同じことを続けるようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黙々", "is_correct": true, "explanation": "黙って続ける様子を表し、「黙々と作業を続けた」として文が成り立つ。"}, {"text": "活発", "is_correct": false, "explanation": "「活発と作業を続けた」は連用形として不自然で、文が成り立たない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気と作業を続けた」は意味も形も合わず、文が成り立たない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔と作業を続けた」は文の意味が成り立たない。"}], "explanations": {"黙々": "黙って続ける様子を表し、「黙々と作業を続けた」として文が成り立つ。", "活発": "「活発と作業を続けた」は連用形として不自然で、文が成り立たない。", "陽気": "「陽気と作業を続けた」は意味も形も合わず、文が成り立たない。", "清潔": "「清潔と作業を続けた」は文の意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "黙々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事を終えた彼は、黙々と床に倒れ込んだ。", "explanation": "黙々は根気よく続ける様子を表すので、一瞬倒れ込む動作には合わない。"}, {"text": "先生の質問に、彼女は黙々と大きな声で答えた。", "explanation": "黙々は声を出さず続ける様子を表すので、大きな声で答える場面には合わない。"}, {"text": "怖い話を聞いて、彼は黙々と背筋がぞっとした。", "explanation": "黙々は根気よく続ける様子を表すので、一瞬の感覚を表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黙々", "is_correct": true, "explanation": "黙って歩き続ける様子を表し、「黙々と山道を歩き続けた」として文が成り立つ。"}, {"text": "頑固", "is_correct": false, "explanation": "「頑固と歩き続けた」は意味も形も合わず、文が成り立たない。"}, {"text": "厳重", "is_correct": false, "explanation": "「厳重と歩き続けた」は不自然で、文が成り立たない。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽と歩き続けた」は意味が通らず、文が成り立たない。"}], "explanations": {"黙々": "黙って歩き続ける様子を表し、「黙々と山道を歩き続けた」として文が成り立つ。", "頑固": "「頑固と歩き続けた」は意味も形も合わず、文が成り立たない。", "厳重": "「厳重と歩き続けた」は不自然で、文が成り立たない。", "手軽": "「手軽と歩き続けた」は意味が通らず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "黙々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は黙々と時計を見て、すぐに目をそらした。", "explanation": "黙々は長く続ける様子を表すので、一瞬見る動作には合わない。"}, {"text": "床が黙々と光っている。", "explanation": "黙々は人の行動の様子を表すので、物の状態を描く文には合わない。"}, {"text": "彼は布団で黙々と眠り、朝まで目覚めなかった。", "explanation": "黙々は根気よく続ける様子を表すので、深く眠る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は黙々で本を読んでいた。", "corrected_sentence": "彼は黙々と本を読んでいた。", "error_description": "「黙々」は「と」を付けて動詞を修飾する（誤：で／正：と）。「で」は手段や場所を表すため、ここでは様子を表せない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "黙々と", "is_correct": true, "explanation": "「解いている」を修飾する連用形（と）で、文に合う。"}, {"text": "黙々だ", "is_correct": false, "explanation": "断定の形で動詞を修飾できず、「解いている」と続かない。"}, {"text": "黙々な", "is_correct": false, "explanation": "連体形で後ろに名詞が必要なので、「解いている」とは続かない。"}, {"text": "黙々で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、「解いている」を修飾できず不自然。"}], "correct_form": "黙々と", "base_form": "黙々", "form_label": "連用形（と）", "sentence_index": 1, "explanations": {"黙々と": "「解いている」を修飾する連用形（と）で、文に合う。", "黙々だ": "断定の形で動詞を修飾できず、「解いている」と続かない。", "黙々な": "連体形で後ろに名詞が必要なので、「解いている」とは続かない。", "黙々で": "「で」は手段や場所を表すため、「解いている」を修飾できず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は黙々の日記を書いている。", "corrected_sentence": "彼女は黙々と日記を書いている。", "error_description": "「黙々」は「と」を付けて動詞を修飾する（誤：の／正：と）。「の」を付けると名詞修飾になり、不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "黙々と", "is_correct": true, "explanation": "「描く」を修飾する連用形（と）で、文に合う。"}, {"text": "黙々だった", "is_correct": false, "explanation": "過去の断定の形で動詞を修飾できず、「描く」と続かない。"}, {"text": "黙々で", "is_correct": false, "explanation": "「で」は手段や場所を表すため、「描く」を修飾する形として不自然。"}, {"text": "黙々ならば", "is_correct": false, "explanation": "条件の形で後ろに動詞が続かず、文の修飾として不自然。"}], "correct_form": "黙々と", "base_form": "黙々", "form_label": "連用形（と）", "sentence_index": 7, "explanations": {"黙々と": "「描く」を修飾する連用形（と）で、文に合う。", "黙々だった": "過去の断定の形で動詞を修飾できず、「描く」と続かない。", "黙々で": "「で」は手段や場所を表すため、「描く」を修飾する形として不自然。", "黙々ならば": "条件の形で後ろに動詞が続かず、文の修飾として不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "合わせる対象を示す『に』。駅の時計に合わせる、という意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主語の『が』では『時計が合わせて』となり、合わせる主体として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の『の』では『時計の合わせて』となり、文が続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』では『時計より合わせて』となり、比べる文脈がない。"}], "correct_answer": "に", "explanations": {"に": "合わせる対象を示す『に』。駅の時計に合わせる、という意味になる。", "が": "主語の『が』では『時計が合わせて』となり、合わせる主体として不自然。", "の": "連体修飾の『の』では『時計の合わせて』となり、文が続かない。", "より": "比較の『より』では『時計より合わせて』となり、比べる文脈がない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "合わせる対象を示す『に』。友達の予定に合わせる、という意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』では『予定へ合わせる』となり、合わせる対象を示せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点の『から』では『予定から合わせる』となり、基準にする文脈に合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段の『で』では『予定で合わせる』となり、対象を示せない。"}], "correct_answer": "に", "explanations": {"に": "合わせる対象を示す『に』。友達の予定に合わせる、という意味になる。", "へ": "方向の『へ』では『予定へ合わせる』となり、合わせる対象を示せず不自然。", "から": "起点の『から』では『予定から合わせる』となり、基準にする文脈に合わない。", "で": "手段の『で』では『予定で合わせる』となり、対象を示せない。"}, "error_tags": {"へ": "方向", "から": "起点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものを、ぴったりと合うようにすること。", "primary_collocate": null, "pronunciation": "あわせる", "ipa": "awaseɾɯ", "syllable_count": 4, "sentences": [{"text": "毎朝の天気予報を確認し、気温や湿度に合わせて水を調整する。", "target_word": "合わせて", "complexity_tier": "T4", "furigana": "毎朝[まいあさ]の天気[てんき]予報[よほう]を確認[かくにん]し、気温[きおん]や湿度[しつど]に合[あ]わせて水[みず]を調整[ちょうせい]する。", "sentence_source": "mined"}, {"text": "時計を駅の時計に合わせて、時刻のずれを直した。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "時計[とけい]を駅[えき]の時計[とけい]に合[あ]わせて、時刻[じこく]のずれを直[なお]した。", "sentence_source": "generated"}, {"text": "二枚の布の端をきちんと合わせてから、針で縫い始めた。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "二枚[にまい]の布[ぬの]の端[はし]をきちんと合[あ]わせてから、針[はり]で縫[ぬ]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "みんなで歩く速さを合わせないと、列がばらばらになってしまう。", "target_word": "合わせない", "complexity_tier": "T3", "furigana": "みんなで歩[ある]く速[はや]さを合[あ]わせないと、列[れつ]がばらばらになってしまう。", "sentence_source": "generated"}, {"text": "ピアノの音に声を合わせて歌うと、きれいな和音になった。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "ピアノの音[おと]に声[こえ]を合[あ]わせて歌[うた]うと、きれいな和音[わおん]になった。", "sentence_source": "generated"}, {"text": "壁の色に合わせて、カーテンも青いものを選んだ。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "壁[かべ]の色[いろ]に合[あ]わせて、カーテンも青[あお]いものを選[えら]んだ。", "sentence_source": "generated"}, {"text": "切れた紙を合わせてみると、ぴったり元の形に戻った。", "target_word": "合わせて", "complexity_tier": "T3", "furigana": "切[き]れた紙[かみ]を合[あ]わせてみると、ぴったり元[もと]の形[かたち]に戻[もど]った。", "sentence_source": "generated"}, {"text": "友達の予定に合わせるために、会議の時間を一時間遅らせた。", "target_word": "合わせる", "complexity_tier": "T3", "furigana": "友達[ともだち]の予定[よてい]に合[あ]わせるために、会議[かいぎ]の時間[じかん]を一時間[いちじかん]遅[おく]らせた。", "sentence_source": "generated"}, {"text": "彼は相手の話し方に合わせ、ゆっくり話した。", "target_word": "合わせ", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の話[はな]し方[かた]に合[あ]わせ、ゆっくり話[はな]した。", "sentence_source": "generated"}, {"text": "ふたの大きさをびんの口に合わせれば、空気が入らない。", "target_word": "合わせれば", "complexity_tier": "T3", "furigana": "ふたの大[おお]きさをびんの口[くち]に合[あ]わせれば、空気[くうき]が入[はい]らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "合わせる", "label": "基本形"}, {"form": "合わせ", "label": "連用形"}, {"form": "合わせて", "label": "て形"}, {"form": "合わせた", "label": "た形"}, {"form": "合わせない", "label": "ない形"}, {"form": "合わせれば", "label": "仮定形"}, {"form": "合わせよう", "label": "意向形"}, {"form": "合わせられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "to make two or more things fit or match exactly (times, colours, edges, pace)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合わせて", "is_correct": true, "explanation": "気温や湿度にそろえて水を調整する、という意味になり、ここに合う。"}, {"text": "測って", "is_correct": false, "explanation": "測るのは数値を知る動作で、気温や湿度に合わせる働きとは違い、に続く形として不自然。"}, {"text": "数えて", "is_correct": false, "explanation": "数えるのは数量を確かめる動作で、気温や湿度に合わせる文脈に合わない。"}, {"text": "磨いて", "is_correct": false, "explanation": "磨くは表面を整える動作で、気温や湿度に水の量を合わせる文脈には合わない。"}], "explanations": {"合わせて": "気温や湿度にそろえて水を調整する、という意味になり、ここに合う。", "測って": "測るのは数値を知る動作で、気温や湿度に合わせる働きとは違い、に続く形として不自然。", "数えて": "数えるのは数量を確かめる動作で、気温や湿度に合わせる文脈に合わない。", "磨いて": "磨くは表面を整える動作で、気温や湿度に水の量を合わせる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "合わせて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "久しぶりに駅の前で、昔の友人と顔を合わせた。", "explanation": "人と向かい合って会うことは〈対面する〉の意味。ぴったり揃える意味ではないので、ここでは別義。"}, {"text": "食事の前に、両手を合わせた。", "explanation": "食前に手を合わせることは〈感謝を示す〉の意味。二つのものを揃える意味ではない。"}, {"text": "祖母の墓の前で、静かに手を合わせた。", "explanation": "手を重ねて拝むことは〈拝む〉の意味。二つのものを揃える意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合わせて", "is_correct": true, "explanation": "紙を合わせてみて元の形に戻った、という確認の流れに合う。"}, {"text": "煮て", "is_correct": false, "explanation": "煮るのは料理の動作で、切れた紙を元の形に戻す確認には合わない。"}, {"text": "歌って", "is_correct": false, "explanation": "歌うは紙に対して行う動作ではなく、紙を元の形に戻す文脈には合わない。"}, {"text": "眠らせて", "is_correct": false, "explanation": "眠らせるは紙に使わない動作で、元の形に戻す確認の文として不自然。"}], "explanations": {"合わせて": "紙を合わせてみて元の形に戻った、という確認の流れに合う。", "煮て": "煮るのは料理の動作で、切れた紙を元の形に戻す確認には合わない。", "歌って": "歌うは紙に対して行う動作ではなく、紙を元の形に戻す文脈には合わない。", "眠らせて": "眠らせるは紙に使わない動作で、元の形に戻す確認の文として不自然。"}, "sentence_index": 6, "correct_answer": "合わせて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で、昔の同級生と顔を合わせた。", "explanation": "人と向かい合って会うことは〈対面する〉の意味。ぴったり揃える意味ではないので、ここでは別義。"}, {"text": "食事の前に、手を合わせて感謝した。", "explanation": "食前に手を合わせることは〈感謝を示す〉の意味。二つのものを揃える意味ではない。"}, {"text": "墓の前で、静かに手を合わせた。", "explanation": "手を重ねて拝むことは〈拝む〉の意味。二つのものを揃える意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事の終わりの時間の合わせて、待ち合わせを決めた。", "corrected_sentence": "仕事の終わりの時間に合わせて、待ち合わせを決めた。", "error_description": "正しくは「時間に合わせて」。『の』では合わせる対象を示せず、対象を示す『に』が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "合わせて", "is_correct": true, "explanation": "て形で、後ろの『直した』へ続く形。"}, {"text": "合わせた", "is_correct": false, "explanation": "過去の形で、ここでは文が途切れ、後ろの動作と続かない。"}, {"text": "合わせない", "is_correct": false, "explanation": "否定の形で、意味が逆になり『直した』とつながらない。"}, {"text": "合わせれば", "is_correct": false, "explanation": "仮定の形で、『〜れば』となり文の流れに合わない。"}], "correct_form": "合わせて", "base_form": "合わせる", "form_label": "て形", "sentence_index": 1, "explanations": {"合わせて": "て形で、後ろの『直した』へ続く形。", "合わせた": "過去の形で、ここでは文が途切れ、後ろの動作と続かない。", "合わせない": "否定の形で、意味が逆になり『直した』とつながらない。", "合わせれば": "仮定の形で、『〜れば』となり文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の大きさにぴったり合わせる、カーテンを切った。", "corrected_sentence": "窓の大きさにぴったり合わせて、カーテンを切った。", "error_description": "正しくは『合わせて』で後ろの文とつなぐ連用形。『合わせる』と言い切ると、読点の後の文と続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "合わせる", "is_correct": true, "explanation": "辞書形で、『ために』の前に置いて目的を示す形。"}, {"text": "合わせよう", "is_correct": false, "explanation": "意向形では『ために』の前で意味が通らない。"}, {"text": "合わせて", "is_correct": false, "explanation": "て形は『ために』の前に置けず、文が成り立たない。"}, {"text": "合わせ", "is_correct": false, "explanation": "連用形では、『ために』へ続くための語形が足りない。"}], "correct_form": "合わせる", "base_form": "合わせる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"合わせる": "辞書形で、『ために』の前に置いて目的を示す形。", "合わせよう": "意向形では『ために』の前で意味が通らない。", "合わせて": "て形は『ために』の前に置けず、文が成り立たない。", "合わせ": "連用形では、『ために』へ続くための語形が足りない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『心待ちにしていた』の『に』。心待ちを『〜にする』の形で副詞的に使う。"}, {"text": "が", "is_correct": false, "explanation": "『心待ちがしていた』では心待ちが主語になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『心待ちでしていた』は『〜にする』の形にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『心待ちからしていた』は起点の意味になり、待つ気持ちを表せない。"}], "correct_answer": "に", "explanations": {"に": "『心待ちにしていた』の『に』。心待ちを『〜にする』の形で副詞的に使う。", "が": "『心待ちがしていた』では心待ちが主語になり、文が成り立たない。", "で": "『心待ちでしていた』は『〜にする』の形にならず、文が成り立たない。", "から": "『心待ちからしていた』は起点の意味になり、待つ気持ちを表せない。"}, "error_tags": {"が": "subject_marker", "で": "means_or_location", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かいいことが起こるのを、楽しみに待つこと。", "primary_collocate": null, "pronunciation": "こころまち", "ipa": "kokoɾomat͡ɕi", "syllable_count": 5, "sentences": [{"text": "誕生日のプレゼントを、弟は朝から心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]のプレゼントを、弟[おとうと]は朝[あさ]から心待[こころま]ちにしている。", "sentence_source": "generated"}, {"text": "夏休みに祖父母の家へ行く日を、私は心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに祖父母[そふぼ]の家[いえ]へ行[い]く日[ひ]を、私[わたし]は心待[こころま]ちにしている。", "sentence_source": "generated"}, {"text": "彼は新しいゲームが出るのを心待ちにして、毎日店に通った。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しいゲームが出[で]るのを心待[こころま]ちにして、毎日[まいにち]店[みせ]に通[かよ]った。", "sentence_source": "generated"}, {"text": "春の遠足を心待ちにしている子どもたちが、前の晩はなかなか寝られなかった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "春[はる]の遠足[えんそく]を心待[こころま]ちにしている子[こ]どもたちが、前[まえ]の晩[ばん]はなかなか寝[ね]られなかった。", "sentence_source": "generated"}, {"text": "母は、遠くに住む孫が遊びに来るのを心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "母[はは]は、遠[とお]くに住[す]む孫[まご]が遊[あそ]びに来[く]るのを心待[こころま]ちにしている。", "sentence_source": "generated"}, {"text": "友達からの誘いの電話を心待ちにしたが、その日は鳴らなかった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "友達[ともだち]からの誘[さそ]いの電話[でんわ]を心待[こころま]ちにしたが、その日[ひ]は鳴[な]らなかった。", "sentence_source": "generated"}, {"text": "雪が降る日を心待ちにする娘は、毎朝空を見上げている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]る日[ひ]を心待[こころま]ちにする娘[むすめ]は、毎朝[まいあさ]空[そら]を見上[みあ]げている。", "sentence_source": "generated"}, {"text": "ずっと心待ちにしていた旅行の日が、ようやく来週になった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "ずっと心待[こころま]ちにしていた旅行[りょこう]の日[ひ]が、ようやく来週[らいしゅう]になった。", "sentence_source": "generated"}, {"text": "祭りの花火を心待ちにして、みんな川のそばに集まった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "祭[まつ]りの花火[はなび]を心待[こころま]ちにして、みんな川[かわ]のそばに集[あつ]まった。", "sentence_source": "generated"}, {"text": "合格の知らせを心待ちにする兄は、落ち着かず部屋の中を歩き回っていた。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "合格[ごうかく]の知[し]らせを心待[こころま]ちにする兄[あに]は、落[お]ち着[つ]かず部屋[へや]の中[なか]を歩[ある]き回[まわ]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心待ち", "label": "基本形"}, {"form": "心待ちに", "label": "に形（心待ちにする）"}], "register": "neutral", "sense_fingerprint": "looking forward to something good and waiting for it happily", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心待ち", "is_correct": true, "explanation": "楽しみに待つ意味で、『心待ちにしている』の形で入る語。"}, {"text": "心構え", "is_correct": false, "explanation": "物事に備える心の持ち方で、楽しみに待つ意味ではないので合わない。"}, {"text": "心当たり", "is_correct": false, "explanation": "思い当たる見当を表し、楽しみに待つ文脈には合わない。"}, {"text": "心変わり", "is_correct": false, "explanation": "気持ちが変わることを表し、楽しみに待つ文脈とは合わない。"}], "explanations": {"心待ち": "楽しみに待つ意味で、『心待ちにしている』の形で入る語。", "心構え": "物事に備える心の持ち方で、楽しみに待つ意味ではないので合わない。", "心当たり": "思い当たる見当を表し、楽しみに待つ文脈には合わない。", "心変わり": "気持ちが変わることを表し、楽しみに待つ文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "心待ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嫌な検査の結果を、彼は心待ちにしている。", "explanation": "ここは〈不安〉の意味。嫌な結果を心待ちにするのは気がかりな状態で、楽しみに待つ心待ちとは合わない。"}, {"text": "妹の帰りが遅いので、母は心待ちどころか、何度も電話をかけ直した。", "explanation": "ここは〈心配〉の意味。楽しみに待つ気持ちではなく気がかりな状態なので、心待ちの意味では使えない。"}, {"text": "地震を心待ちにして、防災用品を準備した。", "explanation": "ここは〈恐れる〉の意味。地震を楽しみに待つことはなく、心待ちは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心待ち", "is_correct": true, "explanation": "楽しみに待つ意味で、『心待ちにする』の形で入る語。"}, {"text": "心遣い", "is_correct": false, "explanation": "相手を思いやる気持ちを表し、楽しみに待つ意味ではないので合わない。"}, {"text": "心残り", "is_correct": false, "explanation": "果たせなかった未練や気がかりを表し、楽しみに待つ文脈には合わない。"}, {"text": "心得", "is_correct": false, "explanation": "物事の知識や心構えを表し、楽しみに待つ意味ではないので合わない。"}], "explanations": {"心待ち": "楽しみに待つ意味で、『心待ちにする』の形で入る語。", "心遣い": "相手を思いやる気持ちを表し、楽しみに待つ意味ではないので合わない。", "心残り": "果たせなかった未練や気がかりを表し、楽しみに待つ文脈には合わない。", "心得": "物事の知識や心構えを表し、楽しみに待つ意味ではないので合わない。"}, "sentence_index": 6, "correct_answer": "心待ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい店の開店に、近所の人が心待ちを寄せている。", "explanation": "ここは〈期待〉の意味。『期待を寄せる』の名詞として使うが、心待ちは待つ状態を指すので『寄せる』の対象にはならない。"}, {"text": "先生から厳しい心待ちを受けて、彼は反省した。", "explanation": "ここは〈警告〉の意味。心待ちは望んで待つことで、厳しく受けるものではないので合わない。"}, {"text": "来週の心待ちは、まだ決まっていない。", "explanation": "ここは〈予定〉の意味。予定は決めるものだが、心待ちは待つ気持ちを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は、夏休みの旅行を心待ちでしている。", "corrected_sentence": "兄は、夏休みの旅行を心待ちにしている。", "error_description": "誤りは『心待ちで』。心待ちは『に』を付けて『心待ちにする』の形にする必要があり、『で』では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、週末の旅行を心待ちでしている。", "corrected_sentence": "私は、週末の旅行を心待ちにしている。", "error_description": "誤りは『心待ちで』。心待ちは『に』を付けて『心待ちにする』の形にする必要があり、『で』では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『心待ちにしている』の『に』。心待ちを『〜にする』の形で副詞的に使う。"}, {"text": "が", "is_correct": false, "explanation": "『心待ちがしている』では心待ちが主語になり、意味が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『心待ちでしている』は『〜にする』の形にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『心待ちのしている』は修飾になり、続く動詞と合わない。"}], "correct_answer": "に", "explanations": {"に": "『心待ちにしている』の『に』。心待ちを『〜にする』の形で副詞的に使う。", "が": "『心待ちがしている』では心待ちが主語になり、意味が成り立たない。", "で": "『心待ちでしている』は『〜にする』の形にならず、文が成り立たない。", "の": "『心待ちのしている』は修飾になり、続く動詞と合わない。"}, "error_tags": {"が": "subject_marker", "で": "means_or_location", "の": "modifier"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『心待ちにしていた』の『に』。心待ちを『〜にする』の形で副詞的に使う。"}, {"text": "が", "is_correct": false, "explanation": "『心待ちがしていた』では心待ちが主語になり、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『心待ちでしていた』は『〜にする』の形にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『心待ちとしていた』は『〜として』の意味になり、待つ気持ちを表せない。"}], "correct_answer": "に", "explanations": {"に": "『心待ちにしていた』の『に』。心待ちを『〜にする』の形で副詞的に使う。", "が": "『心待ちがしていた』では心待ちが主語になり、文が成り立たない。", "で": "『心待ちでしていた』は『〜にする』の形にならず、文が成り立たない。", "と": "『心待ちとしていた』は『〜として』の意味になり、待つ気持ちを表せない。"}, "error_tags": {"が": "subject_marker", "で": "means_or_location", "と": "companion_or_and"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある出来事や物事が実現するのを、期待しながら待つこと。", "primary_collocate": null, "pronunciation": "こころまち", "ipa": "kokoɾomat͡ɕi", "syllable_count": 5, "sentences": [{"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T4", "furigana": "過酷[かこく]な自然[しぜん]環境[かんきょう]と向[む]き合[あ]いながら、彼[かれ]は今日[きょう]も黙々[もくもく]と作業[さぎょう]を続[つづ]け、やがて訪[おとず]れる豊[ゆた]かな実[みの]りの季節[きせつ]を心待[こころま]ちにしている。", "sentence_source": "mined"}, {"text": "子どもたちは、サンタクロースが来るクリスマスの夜を心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、サンタクロースが来[く]るクリスマスの夜[よる]を心待[こころま]ちにしている。", "sentence_source": "generated"}, {"text": "長い入院を終えた父は、家族との再会を心待ちにしていた。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "長[なが]い入院[にゅういん]を終[お]えた父[ちち]は、家族[かぞく]との再会[さいかい]を心待[こころま]ちにしていた。", "sentence_source": "generated"}, {"text": "彼女からの返事を心待ちにしていたが、一週間たっても連絡は来なかった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "彼女[かのじょ]からの返事[へんじ]を心待[こころま]ちにしていたが、一週間[いっしゅうかん]たっても連絡[れんらく]は来[こ]なかった。", "sentence_source": "generated"}, {"text": "発売日を心待ちにしていたファンが、朝から店の前に並んでいる。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "発売日[はつばいび]を心待[こころま]ちにしていたファンが、朝[あさ]から店[みせ]の前[まえ]に並[なら]んでいる。", "sentence_source": "generated"}, {"text": "桜が咲く季節を心待ちにして、毎日つぼみの様子を見に行く。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "桜[さくら]が咲[さ]く季節[きせつ]を心待[こころま]ちにして、毎日[まいにち]つぼみの様子[ようす]を見[み]に行[い]く。", "sentence_source": "generated"}, {"text": "留学中の姉が帰ってくる日を、家族全員が心待ちにしている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "留学中[りゅうがくちゅう]の姉[あね]が帰[かえ]ってくる日[ひ]を、家族[かぞく]全員[ぜんいん]が心待[こころま]ちにしている。", "sentence_source": "generated"}, {"text": "新しい図書館の開館を、町の人々は長い間心待ちにしてきた。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "新[あたら]しい図書館[としょかん]の開館[かいかん]を、町[まち]の人々[ひとびと]は長[なが]い間[あいだ]心待[こころま]ちにしてきた。", "sentence_source": "generated"}, {"text": "手紙を心待ちにする祖母のために、私は毎週はがきを書いている。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "手紙[てがみ]を心待[こころま]ちにする祖母[そぼ]のために、私[わたし]は毎週[まいしゅう]はがきを書[か]いている。", "sentence_source": "generated"}, {"text": "試合の結果を心待ちにしていたのに、中継が突然終わってしまった。", "target_word": "心待ち", "complexity_tier": "T3", "furigana": "試合[しあい]の結果[けっか]を心待[こころま]ちにしていたのに、中継[ちゅうけい]が突然[とつぜん]終[お]わってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "心待ち", "label": "基本形"}, {"form": "心待ちに", "label": "に形（心待ちにする）"}], "register": "neutral", "sense_fingerprint": "waiting expectantly in one''s heart for an event or thing to come about", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心待ち", "is_correct": true, "explanation": "期待しながら待つ意味で、『心待ちにしている』の形で入る語。"}, {"text": "心構え", "is_correct": false, "explanation": "物事に備える心の持ち方を表し、期待して待つ意味ではないので合わない。"}, {"text": "心当たり", "is_correct": false, "explanation": "思い当たる見当を表すので、期待して待つ文脈には合わない。"}, {"text": "心変わり", "is_correct": false, "explanation": "気持ちが変わることで、待ち望む文脈とは逆になり合わない。"}], "explanations": {"心待ち": "期待しながら待つ意味で、『心待ちにしている』の形で入る語。", "心構え": "物事に備える心の持ち方を表し、期待して待つ意味ではないので合わない。", "心当たり": "思い当たる見当を表すので、期待して待つ文脈には合わない。", "心変わり": "気持ちが変わることで、待ち望む文脈とは逆になり合わない。"}, "sentence_index": 0, "correct_answer": "心待ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新製品の発売に、多くの店が心待ちを寄せている。", "explanation": "ここは〈期待〉の意味。『期待を寄せる』の名詞として使うが、心待ちは待つ状態を指すので『寄せる』の対象にはならない。"}, {"text": "最悪の結果も心待ちにして、彼は会議に臨んだ。", "explanation": "ここは〈覚悟〉の意味。心待ちは望ましい出来事を期待して待つことなので、最悪の結果には使わない。"}, {"text": "不審者を心待ちにして、夜は戸締まりを確かめた。", "explanation": "ここは〈警戒〉の意味。不審者を期待して待つことはないので、心待ちはこの場面では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心待ち", "is_correct": true, "explanation": "期待して待つ意味で、『心待ちにしている』の形で入る語。"}, {"text": "心遣い", "is_correct": false, "explanation": "相手を思いやる気持ちを表し、待つ期待の意味ではないので合わない。"}, {"text": "心残り", "is_correct": false, "explanation": "あとまで気にかかる未練を表し、期待して待つ文脈とは逆になるので合わない。"}, {"text": "心模様", "is_correct": false, "explanation": "心の状態や移り変わりを表し、待つ気持ちを示す語としては合わない。"}], "explanations": {"心待ち": "期待して待つ意味で、『心待ちにしている』の形で入る語。", "心遣い": "相手を思いやる気持ちを表し、待つ期待の意味ではないので合わない。", "心残り": "あとまで気にかかる未練を表し、期待して待つ文脈とは逆になるので合わない。", "心模様": "心の状態や移り変わりを表し、待つ気持ちを示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "心待ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "結果を聞いた彼は、心待ちを一気に吐き出して肩を落とした。", "explanation": "ここは〈不満をぶちまける〉の意味。心待ちは楽しみに待つことで、吐き出すものではないので合わない。"}, {"text": "先生から厳しい心待ちを受けて、彼は反省した。", "explanation": "ここは〈警告〉の意味。心待ちは望んで待つことで、厳しく受けるものではないので合わない。"}, {"text": "新作ゲームの心待ちが、公式サイトで発表された。", "explanation": "ここは〈予告〉の意味。予告は発表されるものだが、心待ちは待つ人の気持ちを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、孫からの電話を心待ちでしている。", "corrected_sentence": "祖母は、孫からの電話を心待ちにしている。", "error_description": "誤りは『心待ちで』。心待ちは『に』を付けて『心待ちにする』の形にする必要があり、『で』では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、雪の降る朝を心待ちがしている。", "corrected_sentence": "私は、雪の降る朝を心待ちにしている。", "error_description": "誤りは『心待ちが』。心待ちは『に』を付けて『心待ちにする』の形にするが、『が』では主語になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「実りを使った」で、使う対象を示す「を」。"}, {"text": "へ", "is_correct": false, "explanation": "「実りへ使った」は方向の形で、使う対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「実りから使った」は起点の意味になり、材料としての対象を示さない。"}, {"text": "より", "is_correct": false, "explanation": "「実りより使った」は比較の形で、この文の意味に合わない。"}], "correct_answer": "を", "explanations": {"を": "「実りを使った」で、使う対象を示す「を」。", "へ": "「実りへ使った」は方向の形で、使う対象を示せない。", "から": "「実りから使った」は起点の意味になり、材料としての対象を示さない。", "より": "「実りより使った」は比較の形で、この文の意味に合わない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「森の実りが少ない」で、少ないという状態の主語を示す「が」。"}, {"text": "に", "is_correct": false, "explanation": "「実りに少ない」は場所や対象の形で、「少ない」の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「実りで少ない」は手段の意味になり、主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「実りと少ない」は並列の形で、状態の主語として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「森の実りが少ない」で、少ないという状態の主語を示す「が」。", "に": "「実りに少ない」は場所や対象の形で、「少ない」の主語にはならない。", "で": "「実りで少ない」は手段の意味になり、主語を示せない。", "と": "「実りと少ない」は並列の形で、状態の主語として成り立たない。"}, "error_tags": {"に": "方向・場所", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物がたくさんできること。", "primary_collocate": null, "pronunciation": "みのり", "ipa": "minoɾi", "syllable_count": 3, "sentences": [{"text": "今年は天候に恵まれて、果物の実りが例年よりも良かった。", "target_word": "実り", "complexity_tier": "T3", "furigana": "今年[ことし]は天候[てんこう]に恵[めぐ]まれて、果物[くだもの]の実[みの]りが例年[れいねん]よりも良[よ]かった。", "sentence_source": "generated"}, {"text": "秋の実りを使った料理が、町の食堂にずらりと並んでいる。", "target_word": "実り", "complexity_tier": "T3", "furigana": "秋[あき]の実[みの]りを使[つか]った料理[りょうり]が、町[まち]の食堂[しょくどう]にずらりと並[なら]んでいる。", "sentence_source": "generated"}, {"text": "山の実りを求めて、子どもたちは毎週森へ出かけた。", "target_word": "実り", "complexity_tier": "T3", "furigana": "山[やま]の実[みの]りを求[もと]めて、子[こ]どもたちは毎週[まいしゅう]森[もり]へ出[で]かけた。", "sentence_source": "generated"}, {"text": "台風で畑が荒れてしまい、今年の実りはほとんど期待できない。", "target_word": "実り", "complexity_tier": "T3", "furigana": "台風[たいふう]で畑[はたけ]が荒[あ]れてしまい、今年[ことし]の実[みの]りはほとんど期待[きたい]できない。", "sentence_source": "generated"}, {"text": "海の幸と山の実りに恵まれた村では、毎年秋に感謝祭が開かれる。", "target_word": "実り", "complexity_tier": "T3", "furigana": "海[うみ]の幸[さち]と山[やま]の実[みの]りに恵[めぐ]まれた村[むら]では、毎年[まいとし]秋[あき]に感謝祭[かんしゃさい]が開[ひら]かれる。", "sentence_source": "generated"}, {"text": "実りの秋になると、スーパーに新米や栗が並び始める。", "target_word": "実り", "complexity_tier": "T3", "furigana": "実[みの]りの秋[あき]になると、スーパーに新米[しんまい]や栗[くり]が並[なら]び始[はじ]める。", "sentence_source": "generated"}, {"text": "日照りが続いたので、田んぼの実りが悪かった。", "target_word": "実り", "complexity_tier": "T3", "furigana": "日照[ひで]りが続[つづ]いたので、田[た]んぼの実[みの]りが悪[わる]かった。", "sentence_source": "generated"}, {"text": "森の実りが少ない年は、クマが人里に下りてくる。", "target_word": "実り", "complexity_tier": "T3", "furigana": "森[もり]の実[みの]りが少[すく]ない年[とし]は、クマが人里[ひとざと]に下[お]りてくる。", "sentence_source": "generated"}, {"text": "農家のおじいさんは、今年の実りの多さに笑顔を見せた。", "target_word": "実り", "complexity_tier": "T3", "furigana": "農家[のうか]のおじいさんは、今年[ことし]の実[みの]りの多[おお]さに笑顔[えがお]を見[み]せた。", "sentence_source": "generated"}, {"text": "畑いっぱいの実りを、家族みんなで収穫した。", "target_word": "実り", "complexity_tier": "T3", "furigana": "畑[はたけ]いっぱいの実[みの]りを、家族[かぞく]みんなで収穫[しゅうかく]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実り", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "実り:作物や木の実などの食べ物が豊かにとれること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実り", "is_correct": true, "explanation": "「果物の実り」は果物がよく実った状態を指し、「例年より良かった」と合う。"}, {"text": "寒さ", "is_correct": false, "explanation": "寒さは果物の出来を表さず、「例年よりも良かった」と比べる対象にならない。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "時間帯を表す語で、果物の出来を述べる文に入らない。"}, {"text": "嵐", "is_correct": false, "explanation": "天候の一種だが、果物の出来を比べる語としては成り立たない。"}], "explanations": {"実り": "「果物の実り」は果物がよく実った状態を指し、「例年より良かった」と合う。", "寒さ": "寒さは果物の出来を表さず、「例年よりも良かった」と比べる対象にならない。", "夕暮れ": "時間帯を表す語で、果物の出来を述べる文に入らない。", "嵐": "天候の一種だが、果物の出来を比べる語としては成り立たない。"}, "sentence_index": 0, "correct_answer": "実り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "災害に備えて、非常用の実りを一年分買っておいた。", "explanation": "ここは〈非常食〉の意味。実りは収穫された作物の出来を指し、保存された食品は指さないので合わない。"}, {"text": "新作が人気で、店の実りがどんどん少なくなった。", "explanation": "ここは〈在庫〉の意味。店の商品の在庫は実りとは言わず、農作物の出来を指す実りには合わない。"}, {"text": "店の経営が好調で、今月は実りが大きく増えた。", "explanation": "ここは〈売上〉の意味。実りは農作物の出来を指すので、商売の売上には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実り", "is_correct": true, "explanation": "「田んぼの実り」は稲などが実った状態を指し、「悪かった」の主語として自然。"}, {"text": "稲妻", "is_correct": false, "explanation": "稲妻は田んぼの出来の良し悪しを表さず、文が成り立たない。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷雨は一時的な天気で、作物の出来を示す語にならない。"}, {"text": "山火事", "is_correct": false, "explanation": "山火事は田んぼの出来と関係がなく、「悪かった」の評価対象として不自然。"}], "explanations": {"実り": "「田んぼの実り」は稲などが実った状態を指し、「悪かった」の主語として自然。", "稲妻": "稲妻は田んぼの出来の良し悪しを表さず、文が成り立たない。", "雷雨": "雷雨は一時的な天気で、作物の出来を示す語にならない。", "山火事": "山火事は田んぼの出来と関係がなく、「悪かった」の評価対象として不自然。"}, "sentence_index": 6, "correct_answer": "実り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑いっぱいの実りを、まだ小さいうちに植え替えた。", "explanation": "ここは〈苗〉の意味。実りは実った作物を指し、まだ育っていない苗には使えない。"}, {"text": "桜の木の実りが、今年は見事に咲き誇った。", "explanation": "ここは〈花〉の意味。実りは実のことで、咲き誇る花には使わない。"}, {"text": "倒れた大木の実りを、家具の材料として切り出した。", "explanation": "ここは〈木材〉の意味。実りは木の実や作物を指し、木そのものの材料には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年は森の実りを少なかった。", "corrected_sentence": "今年は森の実りが少なかった。", "error_description": "形容詞「少ない」は「〜が少ない」の形で主語を示す。「実り」に付く助詞は「が」で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51521, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋になると、畑は豊かな実りを包まれる。", "corrected_sentence": "秋になると、畑は豊かな実りに包まれる。", "error_description": "「包まれる」は「〜に包まれる」の形で、包むものを「に」で示す。「実り」に付く助詞は「に」で、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「実りとして」は〈〜として〉の形で、結果や立場を示す。「と」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "「実りの」と続けると連体修飾になり、「として」と接続しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「実りへとして」では文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」は「実りからとして」と続かず、この文の意味に合わない。"}], "correct_answer": "と", "explanations": {"と": "「実りとして」は〈〜として〉の形で、結果や立場を示す。「と」が正しい。", "の": "「実りの」と続けると連体修飾になり、「として」と接続しない。", "へ": "「へ」は方向を示すが、「実りへとして」では文として成り立たない。", "から": "起点の「から」は「実りからとして」と続かず、この文の意味に合わない。"}, "error_tags": {"の": "連体・所属", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きな実りをもたらす」で、もたらす対象を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「実りがもたらした」では実りが主語になり、もたらす対象が欠ける。"}, {"text": "に", "is_correct": false, "explanation": "「実りに」は受け手の形になり、この文の「もたらす」の対象は「を」で示す必要がある。"}, {"text": "で", "is_correct": false, "explanation": "「実りで」は手段の意味になり、もたらす対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「大きな実りをもたらす」で、もたらす対象を示す「を」。", "が": "「実りがもたらした」では実りが主語になり、もたらす対象が欠ける。", "に": "「実りに」は受け手の形になり、この文の「もたらす」の対象は「を」で示す必要がある。", "で": "「実りで」は手段の意味になり、もたらす対象として成り立たない。"}, "error_tags": {"が": "主語", "に": "受け手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "植物の実がなること。また、その実。転じて、努力の結果として得られるよい成果。", "primary_collocate": null, "pronunciation": "みのり", "ipa": "minoɾi", "syllable_count": 3, "sentences": [{"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "実り", "complexity_tier": "T4", "furigana": "過酷[かこく]な自然[しぜん]環境[かんきょう]と向[む]き合[あ]いながら、彼[かれ]は今日[きょう]も黙々[もくもく]と作業[さぎょう]を続[つづ]け、やがて訪[おとず]れる豊[ゆた]かな実[みの]りの季節[きせつ]を心待[こころま]ちにしている。", "sentence_source": "mined"}, {"text": "長い努力の実りとして、彼女は国家試験に合格した。", "target_word": "実り", "complexity_tier": "T3", "furigana": "長[なが]い努力[どりょく]の実[みの]りとして、彼女[かのじょ]は国家[こっか]試験[しけん]に合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "秋は実りの季節で、柿や栗が店先にたくさん並ぶ。", "target_word": "実り", "complexity_tier": "T3", "furigana": "秋[あき]は実[みの]りの季節[きせつ]で、柿[かき]や栗[くり]が店先[みせさき]にたくさん並[なら]ぶ。", "sentence_source": "generated"}, {"text": "今年は雨が多かったので、畑の実りが心配だ。", "target_word": "実り", "complexity_tier": "T3", "furigana": "今年[ことし]は雨[あめ]が多[おお]かったので、畑[はたけ]の実[みの]りが心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "何年も続けた練習は、大会での優勝という実りをもたらした。", "target_word": "実り", "complexity_tier": "T3", "furigana": "何年[なんねん]も続[つづ]けた練習[れんしゅう]は、大会[たいかい]での優勝[ゆうしょう]という実[みの]りをもたらした。", "sentence_source": "generated"}, {"text": "実りの多い話し合いだったと、全員が満足して会議室を出た。", "target_word": "実り", "complexity_tier": "T3", "furigana": "実[みの]りの多[おお]い話[はな]し合[あ]いだったと、全員[ぜんいん]が満足[まんぞく]して会議室[かいぎしつ]を出[で]た。", "sentence_source": "generated"}, {"text": "農家の人たちは、秋の実りに感謝して、神社で祭りを開く。", "target_word": "実り", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]たちは、秋[あき]の実[みの]りに感謝[かんしゃ]して、神社[じんじゃ]で祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}, {"text": "若いころの苦労は、今になって大きな実りをもたらしてくれた。", "target_word": "実り", "complexity_tier": "T3", "furigana": "若[わか]いころの苦労[くろう]は、今[いま]になって大[おお]きな実[みの]りをもたらしてくれた。", "sentence_source": "generated"}, {"text": "実りの少ない議論が続いて、みんな疲れてしまった。", "target_word": "実り", "complexity_tier": "T3", "furigana": "実[みの]りの少[すく]ない議論[ぎろん]が続[つづ]いて、みんな疲[つか]れてしまった。", "sentence_source": "generated"}, {"text": "稲穂が重く垂れ、田んぼは黄金色の実りに包まれている。", "target_word": "実り", "complexity_tier": "T3", "furigana": "稲穂[いなほ]が重[おも]く垂[た]れ、田[た]んぼは黄金色[こがねいろ]の実[みの]りに包[つつ]まれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実り", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "実り:作物が実ること、転じて努力の末に得られる成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実り", "is_correct": true, "explanation": "「豊かな実りの季節」は作物がよく実る時期を指し、文脈に合う。"}, {"text": "冬枯れ", "is_correct": false, "explanation": "冬に草木が枯れることで、「豊かな」と意味が逆になり合わない。"}, {"text": "嵐", "is_correct": false, "explanation": "嵐の季節は豊かさを表さず、「心待ちにしている」の対象として不自然。"}, {"text": "眠り", "is_correct": false, "explanation": "眠りの季節は「豊かな」と結びつかず、季節を表す語として成り立たない。"}], "explanations": {"実り": "「豊かな実りの季節」は作物がよく実る時期を指し、文脈に合う。", "冬枯れ": "冬に草木が枯れることで、「豊かな」と意味が逆になり合わない。", "嵐": "嵐の季節は豊かさを表さず、「心待ちにしている」の対象として不自然。", "眠り": "眠りの季節は「豊かな」と結びつかず、季節を表す語として成り立たない。"}, "sentence_index": 0, "correct_answer": "実り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この投資の実りは、会社に残った大きな損害だった。", "explanation": "ここは〈損失〉の意味。実りは良い成果を指すので、損失という悪い結果には使えない。"}, {"text": "田植えの日、田んぼに稲の実りを植えた。", "explanation": "ここは〈苗〉の意味。実りは実った作物を指し、まだ育っていない苗を植えるとは言わないので合わない。"}, {"text": "庭のチューリップの実りが、一面に咲き誇った。", "explanation": "ここは〈花〉の意味。実りは実や成果を指し、咲き誇る花には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実り", "is_correct": true, "explanation": "「秋の実り」は秋に作物が実ったことを指し、感謝の対象として自然。"}, {"text": "霜", "is_correct": false, "explanation": "霜は秋の恵みではなく、感謝して祭りを開く対象にならない。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷雨は感謝の対象にならず、「秋の〜に感謝して」の文意に合わない。"}, {"text": "陽炎", "is_correct": false, "explanation": "陽炎は夏の現象で、秋の感謝の対象として不自然。"}], "explanations": {"実り": "「秋の実り」は秋に作物が実ったことを指し、感謝の対象として自然。", "霜": "霜は秋の恵みではなく、感謝して祭りを開く対象にならない。", "雷雨": "雷雨は感謝の対象にならず、「秋の〜に感謝して」の文意に合わない。", "陽炎": "陽炎は夏の現象で、秋の感謝の対象として不自然。"}, "sentence_index": 6, "correct_answer": "実り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は味がよく、いつの間にか実りが広まって客が増えた。", "explanation": "ここは〈評判〉の意味。実りは努力の成果を指し、人づての評判には使わない。"}, {"text": "テストで良い実りを取るため、毎日二時間勉強している。", "explanation": "ここは〈成績〉の意味。試験の点数や評価は成績と言い、実りとは言わない。"}, {"text": "手術の実りで、病状が一気に悪化した。", "explanation": "ここは〈結果〉の意味。実りは良い成果に限られるので、病状の悪化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年は天候に恵まれ、畑の実りを多かった。", "corrected_sentence": "今年は天候に恵まれ、畑の実りが多かった。", "error_description": "形容詞「多い」は「〜が多い」の形で主語を示す。「実り」に付く助詞は「が」で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長年の努力は、ついに実りがもたらした。", "corrected_sentence": "長年の努力は、ついに実りをもたらした。", "error_description": "「もたらす」は目的語に「を」を取る動詞。「実り」に付く助詞は「を」で、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「床に滴った」で、しずくが落ちる着点を示す「に」。"}, {"text": "が", "is_correct": false, "explanation": "「床が滴った」では床が落ちる主語になり、文意に合わない。"}, {"text": "を", "is_correct": false, "explanation": "「床を滴った」は目的語の形で、滴る動きの場所を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「床と滴った」は並列の形で、着点を示せない。"}], "correct_answer": "に", "explanations": {"に": "「床に滴った」で、しずくが落ちる着点を示す「に」。", "が": "「床が滴った」では床が落ちる主語になり、文意に合わない。", "を": "「床を滴った」は目的語の形で、滴る動きの場所を示せない。", "と": "「床と滴った」は並列の形で、着点を示せない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水が滴る」で、しずくになって落ちる主語を示す「が」。"}, {"text": "に", "is_correct": false, "explanation": "「水に滴る」は着点の形で、主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「水と滴る」は並列の形で、主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「水より滴る」は比較の形で、この文の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「水が滴る」で、しずくになって落ちる主語を示す「が」。", "に": "「水に滴る」は着点の形で、主語を示せない。", "と": "「水と滴る」は並列の形で、主語にならない。", "より": "「水より滴る」は比較の形で、この文の主語にならない。"}, "error_tags": {"に": "着点", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水や汗が、ぽたぽたとおちること。", "primary_collocate": null, "pronunciation": "したたる", "ipa": "ɕitatarɯ", "syllable_count": 4, "sentences": [{"text": "走り終えた選手のあごから、汗が滴っていた。", "target_word": "滴っ", "complexity_tier": "T3", "furigana": "走[はし]り終[お]えた選手[せんしゅ]のあごから、汗[あせ]が滴[したた]っていた。", "sentence_source": "generated"}, {"text": "洗ったばかりの傘から、水が玄関の床に滴った。", "target_word": "滴った", "complexity_tier": "T3", "furigana": "洗[あら]ったばかりの傘[かさ]から、水[みず]が玄関[げんかん]の床[ゆか]に滴[したた]った。", "sentence_source": "generated"}, {"text": "夏の暑い日、額から汗が滴るほど歩いた。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]い日[ひ]、額[ひたい]から汗[あせ]が滴[したた]るほど歩[ある]いた。", "sentence_source": "generated"}, {"text": "軒先のつららが溶けて、水が一滴ずつ滴っている。", "target_word": "滴っ", "complexity_tier": "T3", "furigana": "軒先[のきさき]のつららが溶[と]けて、水[みず]が一滴[いってき]ずつ滴[したた]っている。", "sentence_source": "generated"}, {"text": "蛇口をしっかり閉めないと、水が滴る音が気になる。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "蛇口[じゃぐち]をしっかり閉[し]めないと、水[みず]が滴[したた]る音[おと]が気[き]になる。", "sentence_source": "generated"}, {"text": "濡れた犬が体を振ると、毛から水が滴った。", "target_word": "滴った", "complexity_tier": "T3", "furigana": "濡[ぬ]れた犬[いぬ]が体[からだ]を振[ふ]ると、毛[け]から水[みず]が滴[したた]った。", "sentence_source": "generated"}, {"text": "雨上がりの葉先から、露が滴って光っていた。", "target_word": "滴って", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの葉先[はさき]から、露[つゆ]が滴[したた]って光[ひか]っていた。", "sentence_source": "generated"}, {"text": "絞りきれていない雑巾から、まだ水が滴る。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "絞[しぼ]りきれていない雑巾[ぞうきん]から、まだ水[みず]が滴[したた]る。", "sentence_source": "generated"}, {"text": "アイスコーヒーのグラスから水が滴って、机にしみができた。", "target_word": "滴って", "complexity_tier": "T3", "furigana": "アイスコーヒーのグラスから水[みず]が滴[したた]って、机[つくえ]にしみができた。", "sentence_source": "generated"}, {"text": "汗が目に滴らないように、ハチマキを巻いて作業した。", "target_word": "滴ら", "complexity_tier": "T3", "furigana": "汗[あせ]が目[め]に滴[したた]らないように、ハチマキを巻[ま]いて作業[さぎょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴る", "label": "辞書形"}, {"form": "滴らない", "label": "否定形"}, {"form": "滴り", "label": "連用形"}, {"form": "滴って", "label": "て形"}, {"form": "滴った", "label": "た形"}, {"form": "滴れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "滴る:水や汗がぽたぽたと落ちる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滴っ", "is_correct": true, "explanation": "「汗が滴っていた」の「滴っ」で、汗がしたたる様子を表す。"}, {"text": "砕け", "is_correct": false, "explanation": "砕ける系の形で、汗が主語の文として意味が成り立たない。"}, {"text": "眠っ", "is_correct": false, "explanation": "眠るの形で、汗の動きとして使えない。"}, {"text": "歌っ", "is_correct": false, "explanation": "歌うの形で、汗の動きとしては不自然。"}], "explanations": {"滴っ": "「汗が滴っていた」の「滴っ」で、汗がしたたる様子を表す。", "砕け": "砕ける系の形で、汗が主語の文として意味が成り立たない。", "眠っ": "眠るの形で、汗の動きとして使えない。", "歌っ": "歌うの形で、汗の動きとしては不自然。"}, "sentence_index": 0, "correct_answer": "滴っ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "嵐の海で、古いボートが滴った。", "explanation": "ここは〈沈む〉の意味。船が水中に下がる様子は沈むと言い、しずくになって落ちる滴るとは合わない。"}, {"text": "配管のすき間から、ガスが滴っている。", "explanation": "ここは〈漏れる〉の意味。ガスや大量の液体が隙間から出る場合は漏れると言い、滴るとは言わない。"}, {"text": "桜の枝から花びらが滴った。", "explanation": "ここは〈散る〉の意味。花びらは散るもので、水や汗のしずくには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滴って", "is_correct": true, "explanation": "「露が滴って光っていた」で、露がしずくになって落ちて光る様子を表す。"}, {"text": "焦げて", "is_correct": false, "explanation": "焦げるの形で、露とは結びつかず意味が成り立たない。"}, {"text": "萎れて", "is_correct": false, "explanation": "萎れるの形で、露の動きとして不自然。"}, {"text": "咲いて", "is_correct": false, "explanation": "咲くの形で、露が主語では意味が通らない。"}], "explanations": {"滴って": "「露が滴って光っていた」で、露がしずくになって落ちて光る様子を表す。", "焦げて": "焦げるの形で、露とは結びつかず意味が成り立たない。", "萎れて": "萎れるの形で、露の動きとして不自然。", "咲いて": "咲くの形で、露が主語では意味が通らない。"}, "sentence_index": 6, "correct_answer": "滴って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汗で濡れたシャツの袖が、重く滴っていた。", "explanation": "ここは〈垂れ下がる〉の意味。布が下がる様子は垂れると言い、水が落ちる意味ではない。"}, {"text": "割れた瓶から、中身の酒が一気に滴った。", "explanation": "ここは〈こぼれる〉の意味。一気に流れ出す様子はこぼれると言い、少しずつ落ちる滴るとは違う。"}, {"text": "棚の上から花瓶が滴った。", "explanation": "ここは〈落下〉の意味。花瓶は液体ではなく物体なので、滴るは使えず落ちると言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "額から汗を滴った。", "corrected_sentence": "額から汗が滴った。", "error_description": "「滴る」は自動詞で、目的語の「を」は取らない。「汗」が主語なので「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "滴った", "is_correct": true, "explanation": "過去を表す「た形」で、すでに落ちた出来事を述べる文と合う。"}, {"text": "滴れ", "is_correct": false, "explanation": "命令形で、文末に来ると命令になり、事実を述べる文と合わない。"}, {"text": "滴らない", "is_correct": false, "explanation": "否定形で、実際に水が落ちた出来事と逆になる。"}, {"text": "滴れば", "is_correct": false, "explanation": "仮定形で、過去の出来事を表さない。"}], "correct_form": "滴った", "base_form": "滴る", "form_label": "た形", "sentence_index": 1, "explanations": {"滴った": "過去を表す「た形」で、すでに落ちた出来事を述べる文と合う。", "滴れ": "命令形で、文末に来ると命令になり、事実を述べる文と合わない。", "滴らない": "否定形で、実際に水が落ちた出来事と逆になる。", "滴れば": "仮定形で、過去の出来事を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の結露が、枠から滴ってていた。", "corrected_sentence": "窓の結露が、枠から滴っていた。", "error_description": "「滴っている」の「て」を二重にした誤り。「滴っていた」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "滴る", "is_correct": true, "explanation": "文末の終止形で、今まさに水が落ちている状態を述べる。"}, {"text": "滴り", "is_correct": false, "explanation": "連用形は文末に単独では使えず、ここでは文を終わらせられない。"}, {"text": "滴って", "is_correct": false, "explanation": "て形は文を続ける形で、ここでは文末の断定にならない。"}, {"text": "滴った", "is_correct": false, "explanation": "た形は過去の動きを表すため、「まだ」で今の状態を述べる文と合わない。"}], "correct_form": "滴る", "base_form": "滴る", "form_label": "終止形", "sentence_index": 7, "explanations": {"滴る": "文末の終止形で、今まさに水が落ちている状態を述べる。", "滴り": "連用形は文末に単独では使えず、ここでは文を終わらせられない。", "滴って": "て形は文を続ける形で、ここでは文末の断定にならない。", "滴った": "た形は過去の動きを表すため、「まだ」で今の状態を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「水が滴っている」で、しずくになって落ちる主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「水を滴っている」は目的語の形で、滴る動作の主語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「水に滴っている」は着点の形で、水が落ちる主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「水で滴っている」は手段の意味になり、主語の文意に合わない。"}], "correct_answer": "が", "explanations": {"が": "「水が滴っている」で、しずくになって落ちる主語を示す「が」。", "を": "「水を滴っている」は目的語の形で、滴る動作の主語にならない。", "に": "「水に滴っている」は着点の形で、水が落ちる主語を示せない。", "で": "「水で滴っている」は手段の意味になり、主語の文意に合わない。"}, "error_tags": {"を": "目的語", "に": "着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「顔から滴る」で、しずくが出てくる起点を示す「から」。"}, {"text": "と", "is_correct": false, "explanation": "「顔と滴る」は並列の形で、滴る起点を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「顔で滴る」は手段の形で、起点を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「顔より滴る」は比較の形で、起点を示す文意に合わない。"}], "correct_answer": "から", "explanations": {"から": "「顔から滴る」で、しずくが出てくる起点を示す「から」。", "と": "「顔と滴る」は並列の形で、滴る起点を示せない。", "で": "「顔で滴る」は手段の形で、起点を示せない。", "より": "「顔より滴る」は比較の形で、起点を示す文意に合わない。"}, "error_tags": {"と": "並列", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体が、したたり落ちる。しずくとなって落ちる。", "primary_collocate": null, "pronunciation": "したたる", "ipa": "ɕitatarɯ", "syllable_count": 4, "sentences": [{"text": "汗が滴る中でも、その表情は穏やかだ。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "汗[あせ]が滴[したた]る中[なか]でも、その表情[ひょうじょう]は穏[おだ]やかだ。", "sentence_source": "mined"}, {"text": "雨に濡れた髪から、水が滴っている。", "target_word": "滴っ", "complexity_tier": "T3", "furigana": "雨[あめ]に濡[ぬ]れた髪[かみ]から、水[みず]が滴[したた]っている。", "sentence_source": "generated"}, {"text": "切ったばかりのレモンから果汁が滴り落ちた。", "target_word": "滴り落ちた", "complexity_tier": "T3", "furigana": "切[き]ったばかりのレモンから果汁[かじゅう]が滴[したた]り落[お]ちた。", "sentence_source": "generated"}, {"text": "蛇口の水が一晩中ぽたぽたと滴って、眠れなかった。", "target_word": "滴って", "complexity_tier": "T3", "furigana": "蛇口[じゃぐち]の水[みず]が一晩中[ひとばんじゅう]ぽたぽたと滴[したた]って、眠[ねむ]れなかった。", "sentence_source": "generated"}, {"text": "焼きたての肉から脂が滴る様子を、みんなじっと見つめていた。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "焼[や]きたての肉[にく]から脂[あぶら]が滴[したた]る様子[ようす]を、みんなじっと見[み]つめていた。", "sentence_source": "generated"}, {"text": "洞窟の天井から水が滴る音だけが、静かに響いていた。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の天井[てんじょう]から水[みず]が滴[したた]る音[おと]だけが、静[しず]かに響[ひび]いていた。", "sentence_source": "generated"}, {"text": "傷口から血が滴らないように、ガーゼで強く押さえた。", "target_word": "滴ら", "complexity_tier": "T3", "furigana": "傷口[きずぐち]から血[ち]が滴[したた]らないように、ガーゼで強[つよ]く押[お]さえた。", "sentence_source": "generated"}, {"text": "彼は顔から滴る汗を、タオルでぬぐった。", "target_word": "滴る", "complexity_tier": "T3", "furigana": "彼[かれ]は顔[かお]から滴[したた]る汗[あせ]を、タオルでぬぐった。", "sentence_source": "generated"}, {"text": "屋根から雨水が滴ったので、下にバケツを置いた。", "target_word": "滴った", "complexity_tier": "T3", "furigana": "屋根[やね]から雨水[あまみず]が滴[したた]ったので、下[した]にバケツを置[お]いた。", "sentence_source": "generated"}, {"text": "氷が溶けて、手のひらから冷たい水が滴った。", "target_word": "滴った", "complexity_tier": "T3", "furigana": "氷[こおり]が溶[と]けて、手[て]のひらから冷[つめ]たい水[みず]が滴[したた]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴る", "label": "辞書形"}, {"form": "滴らない", "label": "否定形"}, {"form": "滴り", "label": "連用形"}, {"form": "滴って", "label": "て形"}, {"form": "滴った", "label": "た形"}, {"form": "滴れば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "滴る:液体がしずくになって落ちる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滴る", "is_correct": true, "explanation": "「汗が滴る中」で、汗がしずくになって落ちる様子を表し、文に合う。"}, {"text": "沸く", "is_correct": false, "explanation": "沸くは湯などが熱で泡立つ意味で、汗の動きには使わない。"}, {"text": "砕ける", "is_correct": false, "explanation": "砕けるは固いものが割れる意味で、汗の動きに合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは寝ることなので、汗が主語の文として成り立たない。"}], "explanations": {"滴る": "「汗が滴る中」で、汗がしずくになって落ちる様子を表し、文に合う。", "沸く": "沸くは湯などが熱で泡立つ意味で、汗の動きには使わない。", "砕ける": "砕けるは固いものが割れる意味で、汗の動きに合わない。", "眠る": "眠るは寝ることなので、汗が主語の文として成り立たない。"}, "sentence_index": 0, "correct_answer": "滴る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "床一面に、ガラスの破片が滴っている。", "explanation": "ここは〈散らばる〉の意味。ガラスの破片は液体ではなく、しずくとなって落ちないので、滴るとは言わない。"}, {"text": "水道管から水が勢いよく滴った。", "explanation": "ここは〈噴き出す〉の意味。勢いよく出る水は噴き出すと言い、静かにしたたる滴るとは合わない。"}, {"text": "川の水が、ゆっくりと滴っている。", "explanation": "ここは〈流れる〉の意味。川の水は流れるもので、しずくになって落ちるのではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滴ら", "is_correct": true, "explanation": "「血が滴らないように」の未然形で、血が落ちないよう防ぐ文脈に合う。"}, {"text": "眠ら", "is_correct": false, "explanation": "眠るの未然形で、血の動きとして意味が成り立たない。"}, {"text": "歌わ", "is_correct": false, "explanation": "歌うの未然形で、血が主語の文では意味が通らない。"}, {"text": "笑わ", "is_correct": false, "explanation": "笑うの未然形で、血には使えず不自然。"}], "explanations": {"滴ら": "「血が滴らないように」の未然形で、血が落ちないよう防ぐ文脈に合う。", "眠ら": "眠るの未然形で、血の動きとして意味が成り立たない。", "歌わ": "歌うの未然形で、血が主語の文では意味が通らない。", "笑わ": "笑うの未然形で、血には使えず不自然。"}, "sentence_index": 6, "correct_answer": "滴ら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ぬれた布団が、重く滴っている。", "explanation": "ここは〈垂れる〉の意味。布団のような物が重みで下がる様子は垂れると言い、液体が落ちる意味ではない。"}, {"text": "浴槽からお湯がどっと滴った。", "explanation": "ここは〈溢れる〉の意味。大量に流れ出す様子は溢れると言い、少しずつ落ちる滴るとは違う。"}, {"text": "お湯を沸かしていたら、鍋から湯気が滴った。", "explanation": "ここは〈蒸発〉の意味。湯気は液体が気体になったもので、しずくとして落ちるわけではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋根から雨水が滴るている。", "corrected_sentence": "屋根から雨水が滴っている。", "error_description": "「滴る」の て形は「滴って」で、「〜ている」は「滴っている」となる。「滴るている」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "滴っ", "is_correct": true, "explanation": "「滴っている」のて形（促音便）の部分で、文中の形と一致する。"}, {"text": "滴る", "is_correct": false, "explanation": "辞書形で、「〜ている」の進行の形になっていない。"}, {"text": "滴らない", "is_correct": false, "explanation": "否定形で、水が落ちている状態を述べる文と逆になる。"}, {"text": "滴れば", "is_correct": false, "explanation": "仮定形で、現に進行している状態を表さない。"}], "correct_form": "滴っ", "base_form": "滴る", "form_label": "て形", "sentence_index": 1, "explanations": {"滴っ": "「滴っている」のて形（促音便）の部分で、文中の形と一致する。", "滴る": "辞書形で、「〜ている」の進行の形になっていない。", "滴らない": "否定形で、水が落ちている状態を述べる文と逆になる。", "滴れば": "仮定形で、現に進行している状態を表さない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51524, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傷口から血を滴った。", "corrected_sentence": "傷口から血が滴った。", "error_description": "「滴る」は自動詞で、目的語の「を」は取らない。「血」が主語なので「が」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "滴る", "is_correct": true, "explanation": "「滴る汗」と名詞を修飾する連体形で、文中の形と一致する。"}, {"text": "滴れ", "is_correct": false, "explanation": "命令形で、名詞「汗」を修飾できず文が成り立たない。"}, {"text": "滴って", "is_correct": false, "explanation": "て形は文を続ける形で、名詞「汗」を直接修飾できない。"}, {"text": "滴り", "is_correct": false, "explanation": "連用形は名詞「汗」を直接修飾する形ではなく、ここでは文の形が合わない。"}], "correct_form": "滴る", "base_form": "滴る", "form_label": "連体形", "sentence_index": 7, "explanations": {"滴る": "「滴る汗」と名詞を修飾する連体形で、文中の形と一致する。", "滴れ": "命令形で、名詞「汗」を修飾できず文が成り立たない。", "滴って": "て形は文を続ける形で、名詞「汗」を直接修飾できない。", "滴り": "連用形は名詞「汗」を直接修飾する形ではなく、ここでは文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『一人の男』が『割っている』の主語を示し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、割る主体は男なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示し、男を主語にできない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示し、男を主語にできない。"}], "correct_answer": "が", "explanations": {"が": "『一人の男』が『割っている』の主語を示し、文に合う。", "を": "目的語を示すが、割る主体は男なので合わない。", "に": "相手や方向を示し、男を主語にできない。", "で": "場所や手段を示し、男を主語にできない。"}, "error_tags": {"を": "目的語の格助詞", "に": "相手・方向の格助詞", "で": "場所・手段の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おとなの、男の人。", "primary_collocate": null, "pronunciation": "おとこ", "ipa": "otoko", "syllable_count": 3, "sentences": [{"text": "男は朝早く起きて、家族のために朝ごはんを作った。", "target_word": "男", "complexity_tier": "T3", "furigana": "男[おとこ]は朝早[あさはや]く起[お]きて、家族[かぞく]のために朝[あさ]ごはんを作[つく]った。", "sentence_source": "generated"}, {"text": "森の奥で、一人の男が薪を割っている。", "target_word": "男", "complexity_tier": "T3", "furigana": "森[もり]の奥[おく]で、一人[ひとり]の男[おとこ]が薪[まき]を割[わ]っている。", "sentence_source": "generated"}, {"text": "受付に来た男は、社長に会いたいと言った。", "target_word": "男", "complexity_tier": "T3", "furigana": "受付[うけつけ]に来[き]た男[おとこ]は、社長[しゃちょう]に会[あ]いたいと言[い]った。", "sentence_source": "generated"}, {"text": "その男は足を怪我していたので、ゆっくり歩いていた。", "target_word": "男", "complexity_tier": "T3", "furigana": "その男[おとこ]は足[あし]を怪我[けが]していたので、ゆっくり歩[ある]いていた。", "sentence_source": "generated"}, {"text": "先生は、教室の入り口に立っている男に声をかけた。", "target_word": "男", "complexity_tier": "T3", "furigana": "先生[せんせい]は、教室[きょうしつ]の入[い]り口[ぐち]に立[た]っている男[おとこ]に声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "男は長い間働いて、やっと小さな家を買うことができた。", "target_word": "男", "complexity_tier": "T3", "furigana": "男[おとこ]は長[なが]い間[あいだ]働[はたら]いて、やっと小[ちい]さな家[いえ]を買[か]うことができた。", "sentence_source": "generated"}, {"text": "暗い道で知らない男に名前を呼ばれて、私は驚いた。", "target_word": "男", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]で知[し]らない男[おとこ]に名前[なまえ]を呼[よ]ばれて、私[わたし]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "彼は優しい男で、困っている人を見るとすぐに助ける。", "target_word": "男", "complexity_tier": "T3", "furigana": "彼[かれ]は優[やさ]しい男[おとこ]で、困[こま]っている人[ひと]を見[み]るとすぐに助[たす]ける。", "sentence_source": "generated"}, {"text": "年を取った男が、公園のベンチで新聞を読んでいる。", "target_word": "男", "complexity_tier": "T3", "furigana": "年[とし]を取[と]った男[おとこ]が、公園[こうえん]のベンチで新聞[しんぶん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "祭りの日、男は子どもを肩に乗せて花火を見せた。", "target_word": "男", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]、男[おとこ]は子[こ]どもを肩[かた]に乗[の]せて花火[はなび]を見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "男", "label": "base"}, {"form": "男の", "label": "genitive"}, {"form": "男が", "label": "subject"}], "register": "neutral", "sense_fingerprint": "grown man, an adult male person", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "朝早く起きて朝ごはんを作る人物として自然に収まる。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は朝ごはんを作らないので文が成り立たない。"}, {"text": "犬", "is_correct": false, "explanation": "犬は家族のために朝ごはんを作らないので不自然。"}, {"text": "鶏", "is_correct": false, "explanation": "鶏は朝ごはんを作る主体にならない。"}], "explanations": {"男": "朝早く起きて朝ごはんを作る人物として自然に収まる。", "太陽": "太陽は朝ごはんを作らないので文が成り立たない。", "犬": "犬は家族のために朝ごはんを作らないので不自然。", "鶏": "鶏は朝ごはんを作る主体にならない。"}, "sentence_index": 0, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "男は生まれたばかりで、まだ言葉を話せない。", "explanation": "ここは〈赤ちゃん〉の意味。〈男〉は大人の男性を指すので、乳児には使わない。"}, {"text": "彼女は男で、毎朝ピアノの練習をしてから出かける。", "explanation": "ここは〈女性〉の意味。〈男〉は女性を指さないので、この文では使えない。"}, {"text": "この机は男で、毎日教室で使われている。", "explanation": "ここは〈男〉を物に当てた誤用。〈男〉は人の性別を表すので、机には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "知らない男に名前を呼ばれる文として自然に収まる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は人のように名前を呼ばないので文が成り立たない。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は名前を呼ばないので不自然。"}, {"text": "駐車場", "is_correct": false, "explanation": "駐車場は名前を呼ぶ主体にならない。"}], "explanations": {"男": "知らない男に名前を呼ばれる文として自然に収まる。", "窓": "窓は人のように名前を呼ばないので文が成り立たない。", "夕日": "夕日は名前を呼ばないので不自然。", "駐車場": "駐車場は名前を呼ぶ主体にならない。"}, "sentence_index": 6, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この馬は男で、牧場を元気に駆けていく。", "explanation": "ここは〈雄〉の意味。〈男〉は人間にだけ使うので、馬の性別には合わない。"}, {"text": "このロボットは男で、毎朝部屋を掃除している。", "explanation": "ここは〈男〉を機械に当てた誤用。〈男〉は人の性別を表すので、ロボットには使わない。"}, {"text": "その女王は男で、長く国を治めた。", "explanation": "ここは〈女性〉を〈男〉で言い換えた誤用。〈男〉は女性を指さないので、女王には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事帰りの男を、コンビニで弁当を買っている。", "corrected_sentence": "仕事帰りの男が、コンビニで弁当を買っている。", "error_description": "買う動作の主体は男なので『が』が必要。『男を』では『を』が二つ重なり、目的語の扱いも不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51525, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "橋の上で、一匹の男が川を眺めていた。", "corrected_sentence": "橋の上で、一人の男が川を眺めていた。", "error_description": "人を数える『一人』が必要。『一匹』は動物を数えるので、人である男には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『男』が『待っている』の主語を示す格助詞で、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、待つ主体は男なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示し、男を主語にできない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示し、男を主語にできない。"}], "correct_answer": "が", "explanations": {"が": "『男』が『待っている』の主語を示す格助詞で、文に合う。", "を": "目的語を示すが、待つ主体は男なので合わない。", "に": "相手や方向を示し、男を主語にできない。", "で": "場所や手段を示し、男を主語にできない。"}, "error_tags": {"を": "目的語の格助詞", "に": "相手・方向の格助詞", "で": "場所・手段の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『あの男』を主題として示し、文に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示し、約束を守る主体にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示し、この文の主題にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「あの男で約束を守る」は断定・手段の『で』としても文が成り立たず、主題の位置に入らない。"}], "correct_answer": "は", "explanations": {"は": "『あの男』を主題として示し、文に合う。", "へ": "方向を示し、約束を守る主体にはならない。", "から": "起点を示し、この文の主題にはならない。", "で": "「あの男で約束を守る」は断定・手段の『で』としても文が成り立たず、主題の位置に入らない。"}, "error_tags": {"へ": "方向の格助詞", "から": "起点の格助詞", "で": "断定・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間の性別の一つで、女性ではない成人。", "primary_collocate": null, "pronunciation": "おとこ", "ipa": "otoko", "syllable_count": 3, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "男", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "駅の前で、背の高い男が誰かを待っている。", "target_word": "男", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で、背[せ]の高[たか]い男[おとこ]が誰[だれ]かを待[ま]っている。", "sentence_source": "generated"}, {"text": "その男は財布を落としたことに気づかず、そのまま電車に乗ってしまった。", "target_word": "男", "complexity_tier": "T3", "furigana": "その男[おとこ]は財布[さいふ]を落[お]としたことに気[き]づかず、そのまま電車[でんしゃ]に乗[の]ってしまった。", "sentence_source": "generated"}, {"text": "隣に引っ越してきた男は、毎朝公園を走っている。", "target_word": "男", "complexity_tier": "T3", "furigana": "隣[となり]に引[ひ]っ越[こ]してきた男[おとこ]は、毎朝[まいあさ]公園[こうえん]を走[はし]っている。", "sentence_source": "generated"}, {"text": "店に入ってきた男は、メニューも見ずにコーヒーを注文した。", "target_word": "男", "complexity_tier": "T3", "furigana": "店[みせ]に入[はい]ってきた男[おとこ]は、メニューも見[み]ずにコーヒーを注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "男は重い荷物を持ち上げて、トラックの荷台に載せた。", "target_word": "男", "complexity_tier": "T3", "furigana": "男[おとこ]は重[おも]い荷物[にもつ]を持[も]ち上[あ]げて、トラックの荷台[にだい]に載[の]せた。", "sentence_source": "generated"}, {"text": "道に迷っていると、親切な男が駅まで案内してくれた。", "target_word": "男", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]っていると、親切[しんせつ]な男[おとこ]が駅[えき]まで案内[あんない]してくれた。", "sentence_source": "generated"}, {"text": "あの男は約束を守るので、みんなから信頼されている。", "target_word": "男", "complexity_tier": "T3", "furigana": "あの男[おとこ]は約束[やくそく]を守[まも]るので、みんなから信頼[しんらい]されている。", "sentence_source": "generated"}, {"text": "雨の中、傘もささずに歩く男を見て、母は心配した。", "target_word": "男", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]、傘[かさ]もささずに歩[ある]く男[おとこ]を見[み]て、母[はは]は心配[しんぱい]した。", "sentence_source": "generated"}, {"text": "窓の外で、一人の男が犬に話しかけていた。", "target_word": "男", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]で、一人[ひとり]の男[おとこ]が犬[いぬ]に話[はな]しかけていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "男", "label": "base"}, {"form": "男の", "label": "genitive"}, {"form": "男が", "label": "subject"}], "register": "neutral", "sense_fingerprint": "adult human male, as a person (not female)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 鶏舎 (Zipf 2.02)']::text[], '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "農家の男が鶏舎へ足を運ぶ主体として自然に収まる。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は足を運ばないので文が成り立たない。"}, {"text": "農場", "is_correct": false, "explanation": "農場は歩いて鶏舎へ向かう主体にならない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は足を運ぶ主体にならず、文が不自然になる。"}], "explanations": {"男": "農家の男が鶏舎へ足を運ぶ主体として自然に収まる。", "太陽": "太陽は足を運ばないので文が成り立たない。", "農場": "農場は歩いて鶏舎へ向かう主体にならない。", "雨": "雨は足を運ぶ主体にならず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "男は小学二年生で、毎朝ランドセルを背負って学校へ行く。", "explanation": "ここは〈男の子〉の意味。〈男〉は成人の男性を指すので、小学生には使わない。"}, {"text": "この鶏は男で、毎朝鶏舎の前で大きな声で鳴く。", "explanation": "ここは〈雄〉の意味。〈男〉は人間にだけ使うので、鶏の性別には合わない。"}, {"text": "その女性は男で、会社の社長を務めている。", "explanation": "ここは〈女性〉の意味。〈男〉は女性を指さないので、女性には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "親切な男が駅まで案内する主体として自然に収まる。"}, {"text": "電車", "is_correct": false, "explanation": "電車は人を案内しないので文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は人のように案内する主体にならない。"}, {"text": "花", "is_correct": false, "explanation": "花は駅まで案内する主体として不自然。"}], "explanations": {"男": "親切な男が駅まで案内する主体として自然に収まる。", "電車": "電車は人を案内しないので文が成り立たない。", "窓": "窓は人のように案内する主体にならない。", "花": "花は駅まで案内する主体として不自然。"}, "sentence_index": 6, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この人形は男で、着物を着て棚に飾られている。", "explanation": "ここは〈男〉を人形の性別に当てた誤用。〈男〉は人間の性別なので、人形には使わない。"}, {"text": "あのバンドは男で、メンバーは五人だ。", "explanation": "ここは〈男〉を集団に当てた誤用。〈男〉は一人の人の性別を表すので、バンドには使わない。"}, {"text": "その女王は男で、長く国を治めた。", "explanation": "ここは〈女性〉を〈男〉で言い換えた誤用。〈男〉は女性を指さないので、女王には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな荷物を持った男に、駅の階段をゆっくり上っている。", "corrected_sentence": "大きな荷物を持った男が、駅の階段をゆっくり上っている。", "error_description": "階段を上る動作の主体は男なので『が』が必要。『に』では男が主語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51526, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日、一匹の男がタクシーを待っている。", "corrected_sentence": "雨の日、一人の男がタクシーを待っている。", "error_description": "人を数える『一人』が必要。『一匹』は動物を数えるので、人である男には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「夜が明ける瞬間」の「が」で、夜が明ける主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「明ける」は自動詞なので「夜を明ける」とは言えず、目的語の「を」は入らない。"}, {"text": "に", "is_correct": false, "explanation": "「夜に明ける瞬間」は意味が通らず、主語の位置に「に」は入らない。"}, {"text": "で", "is_correct": false, "explanation": "「夜で明ける」は場所や手段として成り立たず、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「夜が明ける瞬間」の「が」で、夜が明ける主語を示す。", "を": "「明ける」は自動詞なので「夜を明ける」とは言えず、目的語の「を」は入らない。", "に": "「夜に明ける瞬間」は意味が通らず、主語の位置に「に」は入らない。", "で": "「夜で明ける」は場所や手段として成り立たず、主語を示せない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "時点", "で": "場所・手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暮れる", "is_correct": true, "explanation": "夜明けと日暮れが対になるため、「明ける」（夜が明ける）の対義語。"}, {"text": "始まる", "is_correct": false, "explanation": "「始まる」は始まることを表し、「明ける」の対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は睡眠の意味で、夜明けの反対概念ではない。"}, {"text": "降る", "is_correct": false, "explanation": "「降る」は雨や雪が落ちる意味で、「明ける」の対義語にはならない。"}], "correct_answer": "暮れる", "explanations": {"暮れる": "夜明けと日暮れが対になるため、「明ける」（夜が明ける）の対義語。", "始まる": "「始まる」は始まることを表し、「明ける」の対義語ではない。", "眠る": "「眠る」は睡眠の意味で、夜明けの反対概念ではない。", "降る": "「降る」は雨や雪が落ちる意味で、「明ける」の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「明けると」の「と」で、空が明けることを条件として示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「明けるへ」とは続かず、この位置に入らない。"}, {"text": "より", "is_correct": false, "explanation": "「明けるより」は比較の文として続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「明けるの、海が…」は名詞化として続かず、不自然な文になる。"}], "correct_answer": "と", "explanations": {"と": "「明けると」の「と」で、空が明けることを条件として示す。", "へ": "方向を表す「へ」は「明けるへ」とは続かず、この位置に入らない。", "より": "「明けるより」は比較の文として続かず、文が成り立たない。", "の": "「明けるの、海が…」は名詞化として続かず、不自然な文になる。"}, "error_tags": {"と": "条件", "へ": "方向", "より": "比較", "の": "名詞化"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暮れる", "is_correct": true, "explanation": "夜明けと日暮れが対になるため、「明ける」（夜が明ける）の対義語。"}, {"text": "来る", "is_correct": false, "explanation": "「来る」は到来する意味で、「明ける」の対義語ではない。"}, {"text": "続く", "is_correct": false, "explanation": "「続く」は継続する意味で、夜が明けることの反対概念ではない。"}, {"text": "冷える", "is_correct": false, "explanation": "「冷える」は温度が下がる意味で、「明ける」の対義語にはならない。"}], "correct_answer": "暮れる", "explanations": {"暮れる": "夜明けと日暮れが対になるため、「明ける」（夜が明ける）の対義語。", "来る": "「来る」は到来する意味で、「明ける」の対義語ではない。", "続く": "「続く」は継続する意味で、夜が明けることの反対概念ではない。", "冷える": "「冷える」は温度が下がる意味で、「明ける」の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "夜が終わって、空が明るくなること。", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "夜が明けると、鳥の声が聞こえてきた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けると、鳥[とり]の声[こえ]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "山の上で、夜が明ける瞬間を見るために早く起きた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で、夜[よる]が明[あ]ける瞬間[しゅんかん]を見[み]るために早[はや]く起[お]きた。", "sentence_source": "generated"}, {"text": "空がだんだん明けて、遠くの町が見えてきた。", "target_word": "明けて", "complexity_tier": "T3", "furigana": "空[そら]がだんだん明[あ]けて、遠[とお]くの町[まち]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "夜が明けたら、すぐに出発しよう。", "target_word": "明けたら", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けたら、すぐに出発[しゅっぱつ]しよう。", "sentence_source": "generated"}, {"text": "一晩中話しているうちに、いつのまにか夜が明けた。", "target_word": "明けた", "complexity_tier": "T3", "furigana": "一晩中[ひとばんじゅう]話[はな]しているうちに、いつのまにか夜[よる]が明[あ]けた。", "sentence_source": "generated"}, {"text": "カーテンの隙間から光がもれて、夜が明けたことに気づいた。", "target_word": "明けた", "complexity_tier": "T3", "furigana": "カーテンの隙間[すきま]から光[ひかり]がもれて、夜[よる]が明[あ]けたことに気[き]づいた。", "sentence_source": "generated"}, {"text": "夜が明けきらないうちに、漁師たちは船を出した。", "target_word": "明け", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けきらないうちに、漁師[りょうし]たちは船[ふね]を出[だ]した。", "sentence_source": "generated"}, {"text": "東の空が明けると、海が金色に光りはじめた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "東[ひがし]の空[そら]が明[あ]けると、海[うみ]が金色[きんいろ]に光[ひか]りはじめた。", "sentence_source": "generated"}, {"text": "夜が明けるのを待ちながら、キャンプの火を見ていた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けるのを待[ま]ちながら、キャンプの火[ひ]を見[み]ていた。", "sentence_source": "generated"}, {"text": "眠れないまま夜が明けてしまい、朝になっていた。", "target_word": "明けて", "complexity_tier": "T3", "furigana": "眠[ねむ]れないまま夜[よる]が明[あ]けてしまい、朝[あさ]になっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明ける", "label": "dictionary"}, {"form": "明け", "label": "continuative"}, {"form": "明けて", "label": "te-form"}, {"form": "明けた", "label": "past"}, {"form": "明けない", "label": "negative"}, {"form": "明ければ", "label": "conditional"}], "register": "neutral", "sense_fingerprint": "night ends and the sky grows light; dawn breaks", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明ける", "is_correct": true, "explanation": "「夜が明けると」の辞書形＋「と」で、夜が終わる条件を表す。"}, {"text": "覚める", "is_correct": false, "explanation": "「覚める」は眠りから目が覚める意味で、夜を主語にできず文に合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は寝る意味で、夜が眠ると言うことはできない。"}, {"text": "降る", "is_correct": false, "explanation": "「降る」は雨や雪が落ちる意味で、夜を主語にすることはできない。"}], "explanations": {"明ける": "「夜が明けると」の辞書形＋「と」で、夜が終わる条件を表す。", "覚める": "「覚める」は眠りから目が覚める意味で、夜を主語にできず文に合わない。", "眠る": "「眠る」は寝る意味で、夜が眠ると言うことはできない。", "降る": "「降る」は雨や雪が落ちる意味で、夜を主語にすることはできない。"}, "sentence_index": 0, "correct_answer": "明ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日が明けると、町に灯りがともった。", "explanation": "ここは〈暮れる〉の意味。夕方の日暮れには「暮れる」を使い、「明ける」は夜が終わる朝に使うので合わない。"}, {"text": "記憶がだんだん明けてきた。", "explanation": "ここは〈薄れる〉の意味。記憶は「薄れる」と言い、「明ける」は夜や季節などの区切りに使うので合わない。"}, {"text": "片付けが明けたので、帰った。", "explanation": "ここは〈終わる〉の意味。作業や片付けは「終わる」と言い、「明ける」は夜や季節など時間の区切りに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明け", "is_correct": true, "explanation": "「明けきらない」の「明け」は連用形で、夜がまだ完全には明けていないことを表す。"}, {"text": "途切れ", "is_correct": false, "explanation": "「途切れる」は続いていたものが切れる意味で、夜には使えず「明けきらない」に続かない。"}, {"text": "泣き", "is_correct": false, "explanation": "夜は泣かないので、「夜が泣ききらないうちに」は文が成り立たない。"}, {"text": "冷め", "is_correct": false, "explanation": "「冷める」は温度が下がる意味で、夜を主語にできず文脈に合わない。"}], "explanations": {"明け": "「明けきらない」の「明け」は連用形で、夜がまだ完全には明けていないことを表す。", "途切れ": "「途切れる」は続いていたものが切れる意味で、夜には使えず「明けきらない」に続かない。", "泣き": "夜は泣かないので、「夜が泣ききらないうちに」は文が成り立たない。", "冷め": "「冷める」は温度が下がる意味で、夜を主語にできず文脈に合わない。"}, "sentence_index": 6, "correct_answer": "明け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "待ち時間が明けてしまい、みんな席を立った。", "explanation": "ここは〈過ぎる〉の意味。待ち時間は「過ぎる」と言い、「明ける」は夜や季節など区切りの終わりに使う。"}, {"text": "電池が明けてしまい、懐中電灯が使えなくなった。", "explanation": "ここは〈切れる〉の意味。電池は「切れる」と言い、「明ける」は夜や梅雨など時期の区切りに使うので合わない。"}, {"text": "熱が明けて、ようやく体が楽になった。", "explanation": "ここは〈引く〉の意味。熱は「引く」と言い、「明ける」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜が明けるたら、鳥が鳴き始めた。", "corrected_sentence": "夜が明けたら、鳥が鳴き始めた。", "error_description": "「たら」は過去形に続ける形なので、「明けるたら」ではなく「明けたら」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明ける", "is_correct": true, "explanation": "「夜が明ける瞬間」と名詞「瞬間」を修飾する基本形。"}, {"text": "明けよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「夜が明けよう瞬間」は文として成り立たない。"}, {"text": "明けて", "is_correct": false, "explanation": "て形は名詞を直接修飾できず、「明けて瞬間」は成り立たない。"}, {"text": "明けろ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、夜に命令する形となり文脈に合わない。"}], "correct_form": "明ける", "base_form": "明ける", "form_label": "基本形", "sentence_index": 1, "explanations": {"明ける": "「夜が明ける瞬間」と名詞「瞬間」を修飾する基本形。", "明けよう": "意志形は名詞を修飾できず、「夜が明けよう瞬間」は文として成り立たない。", "明けて": "て形は名詞を直接修飾できず、「明けて瞬間」は成り立たない。", "明けろ": "命令形は名詞を修飾できず、夜に命令する形となり文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51529, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "東の空が明けが、鳥が一斉に鳴きはじめた。", "corrected_sentence": "東の空が明けると、鳥が一斉に鳴きはじめた。", "error_description": "「明ける」の直後に「が」は続かない。条件を表す「明けると」の「と」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明ける", "is_correct": true, "explanation": "辞書形＋「と」で、「東の空が明けると」と空が明ける条件を示す。"}, {"text": "明けよう", "is_correct": false, "explanation": "意志形になり、空が意志を持つような不自然な文になる。"}, {"text": "明けられる", "is_correct": false, "explanation": "可能形の「明けられると」は意味が通らず、この文脈に合わない。"}, {"text": "明けよ", "is_correct": false, "explanation": "命令形の文語的な形で、「東の空が明けよ」と空に命じる文になり不自然。"}], "correct_form": "明ける", "base_form": "明ける", "form_label": "基本形", "sentence_index": 7, "explanations": {"明ける": "辞書形＋「と」で、「東の空が明けると」と空が明ける条件を示す。", "明けよう": "意志形になり、空が意志を持つような不自然な文になる。", "明けられる": "可能形の「明けられると」は意味が通らず、この文脈に合わない。", "明けよ": "命令形の文語的な形で、「東の空が明けよ」と空に命じる文になり不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「明けると」の「と」で、梅雨が明ける結果として夏が始まるという条件を表す。"}, {"text": "を", "is_correct": false, "explanation": "「明ける」は自動詞なので目的語の「を」は取らず、「明けるを」は続かない。"}, {"text": "に", "is_correct": false, "explanation": "「明けるに」とは続かず、時点や帰着を表す「に」は動詞の直後に置けない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「明けるへ」と続かず、この位置には入らない。"}], "correct_answer": "と", "explanations": {"と": "「明けると」の「と」で、梅雨が明ける結果として夏が始まるという条件を表す。", "を": "「明ける」は自動詞なので目的語の「を」は取らず、「明けるを」は続かない。", "に": "「明けるに」とは続かず、時点や帰着を表す「に」は動詞の直後に置けない。", "へ": "方向を表す「へ」は「明けるへ」と続かず、この位置には入らない。"}, "error_tags": {"と": "条件", "を": "目的語", "に": "時点・帰着", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "夜や季節などの区切りが終わり、新しい状態が始まること。特に、夜が明けて明るくなること。", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "明け", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "梅雨が明けると、一気に暑い夏が始まる。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "梅雨[つゆ]が明[あ]けると、一気[いっき]に暑[あつ]い夏[なつ]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "長かった冬が明けて、庭の木に新しい芽が出てきた。", "target_word": "明けて", "complexity_tier": "T3", "furigana": "長[なが]かった冬[ふゆ]が明[あ]けて、庭[にわ]の木[き]に新[あたら]しい芽[め]が出[で]てきた。", "sentence_source": "generated"}, {"text": "空が明けてきたので、私たちは山の頂上で日の出を待った。", "target_word": "明けて", "complexity_tier": "T3", "furigana": "空[そら]が明[あ]けてきたので、私[わたし]たちは山[やま]の頂上[ちょうじょう]で日[ひ]の出[で]を待[ま]った。", "sentence_source": "generated"}, {"text": "夜が明けるまで、彼は川のそばで釣りを続けた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けるまで、彼[かれ]は川[かわ]のそばで釣[つ]りを続[つづ]けた。", "sentence_source": "generated"}, {"text": "試験期間が明けたら、みんなで食事に行こう。", "target_word": "明けたら", "complexity_tier": "T3", "furigana": "試験期間[しけんきかん]が明[あ]けたら、みんなで食事[しょくじ]に行[い]こう。", "sentence_source": "generated"}, {"text": "夜が明けても、雪はまだ降り続いていた。", "target_word": "明けても", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]けても、雪[ゆき]はまだ降[ふ]り続[つづ]いていた。", "sentence_source": "generated"}, {"text": "東の空が明けはじめ、鳥が鳴き出した。", "target_word": "明け", "complexity_tier": "T3", "furigana": "東[ひがし]の空[そら]が明[あ]けはじめ、鳥[とり]が鳴[な]き出[だ]した。", "sentence_source": "generated"}, {"text": "寒い夜が明けると、窓ガラスに霜がついていた。", "target_word": "明ける", "complexity_tier": "T3", "furigana": "寒[さむ]い夜[よる]が明[あ]けると、窓[まど]ガラスに霜[しも]がついていた。", "sentence_source": "generated"}, {"text": "連休が明けると、街にまた人が戻ってくる。", "target_word": "明けると", "complexity_tier": "T3", "furigana": "連休[れんきゅう]が明[あ]けると、街[まち]にまた人[ひと]が戻[もど]ってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "明ける", "label": "dictionary"}, {"form": "明け", "label": "continuative"}, {"form": "明けて", "label": "te-form"}, {"form": "明けた", "label": "past"}, {"form": "明けない", "label": "negative"}, {"form": "明ければ", "label": "conditional"}], "register": "neutral", "sense_fingerprint": "(night, season, period) comes to an end and a new phase begins; day breaks", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明け", "is_correct": true, "explanation": "「夜が明け、太陽が…」の「明け」は「明ける」の連用形で、夜が終わって朝になることを表す。"}, {"text": "暮れ", "is_correct": false, "explanation": "「暮れる」は日が沈んで夜になる意味で、太陽が農場を照らし始める朝には合わない。"}, {"text": "明かし", "is_correct": false, "explanation": "「明かす」は夜を過ごす意味で、「夜が」を主語にして続けることはできない。"}, {"text": "覚め", "is_correct": false, "explanation": "「覚める」は眠りから目が覚める意味で、夜を主語にできず文脈にも合わない。"}], "explanations": {"明け": "「夜が明け、太陽が…」の「明け」は「明ける」の連用形で、夜が終わって朝になることを表す。", "暮れ": "「暮れる」は日が沈んで夜になる意味で、太陽が農場を照らし始める朝には合わない。", "明かし": "「明かす」は夜を過ごす意味で、「夜が」を主語にして続けることはできない。", "覚め": "「覚める」は眠りから目が覚める意味で、夜を主語にできず文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "明け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "契約の期限が明けたので、更新の手続きをした。", "explanation": "ここは〈切れる〉の意味。期限は「切れる」と言い、「明ける」は夜や季節などの区切りに使うので合わない。"}, {"text": "痛みがだんだん明けてきた。", "explanation": "ここは〈和らぐ〉の意味。痛みは「和らぐ」と言い、「明ける」は夜や季節など時間の区切りに使うので合わない。"}, {"text": "式典が明けたので、みんな会場を出た。", "explanation": "ここは〈終わる〉の意味。式典は「終わる」と言い、「明ける」は季節や夜など時間の区切りに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明けても", "is_correct": true, "explanation": "「夜が明けても」の形で、夜が明けた後も雪が降り続いていたことを表す。"}, {"text": "途切れても", "is_correct": false, "explanation": "「途切れる」は続いていたものが止まる意味で、夜を主語にすると文脈に合わない。"}, {"text": "止んでも", "is_correct": false, "explanation": "「止む」は雪や雨がやむ意味で、夜を主語にして使うことはできない。"}, {"text": "熟しても", "is_correct": false, "explanation": "「熟す」は果実などが熟す意味で、夜を主語にすると不自然で文脈にも合わない。"}], "explanations": {"明けても": "「夜が明けても」の形で、夜が明けた後も雪が降り続いていたことを表す。", "途切れても": "「途切れる」は続いていたものが止まる意味で、夜を主語にすると文脈に合わない。", "止んでも": "「止む」は雪や雨がやむ意味で、夜を主語にして使うことはできない。", "熟しても": "「熟す」は果実などが熟す意味で、夜を主語にすると不自然で文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "明けても"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "騒ぎが明けたので、街にまた人が戻ってきた。", "explanation": "ここは〈収まる〉の意味。騒ぎは「収まる」と言い、「明ける」は夜や季節などの区切りに使うので合わない。"}, {"text": "ボタンが明けたので、シャツを脱いだ。", "explanation": "ここは〈外れる〉の意味。ボタンは「外れる」と言い、「明ける」は夜や季節など時間の区切りに使うので合わない。"}, {"text": "準備が明けたので、すぐに出発した。", "explanation": "ここは〈完了する〉の意味。準備は「完了する・整う」と言い、「明ける」は時期の区切りに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜が明けに、鳥が鳴き始めた。", "corrected_sentence": "夜が明けると、鳥が鳴き始めた。", "error_description": "「明ける」の直後に「に」は続かない。条件を表す「明けると」の「と」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "明ける", "is_correct": true, "explanation": "「梅雨が明けると」の「明ける」は基本形で、「と」を続けて条件を表す。"}, {"text": "明けない", "is_correct": false, "explanation": "否定形では梅雨が明けないことになり、後半の「夏が始まる」と矛盾する。"}, {"text": "明けよう", "is_correct": false, "explanation": "意志形で、梅雨の終わりを話し手が決める意味になり、「と」に続く条件の形として不自然。"}, {"text": "明けられる", "is_correct": false, "explanation": "可能形の「梅雨が明けられる」は意味が通らず、この文脈に合わない。"}], "correct_form": "明ける", "base_form": "明ける", "form_label": "基本形", "sentence_index": 1, "explanations": {"明ける": "「梅雨が明けると」の「明ける」は基本形で、「と」を続けて条件を表す。", "明けない": "否定形では梅雨が明けないことになり、後半の「夏が始まる」と矛盾する。", "明けよう": "意志形で、梅雨の終わりを話し手が決める意味になり、「と」に続く条件の形として不自然。", "明けられる": "可能形の「梅雨が明けられる」は意味が通らず、この文脈に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連休が明けば、街にまた人が戻ってくる。", "corrected_sentence": "連休が明ければ、街にまた人が戻ってくる。", "error_description": "「明ける」の仮定形は「明ければ」で、「明けば」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "明け", "is_correct": true, "explanation": "「明けはじめ」の「明け」は連用形で、動詞「はじめる」の前に置いて使う。"}, {"text": "明ける", "is_correct": false, "explanation": "基本形なので「明けはじめ」の前には使えず、この位置では文が成り立たない。"}, {"text": "明けて", "is_correct": false, "explanation": "て形は「明けてはじめ」とは続かず、「はじめる」に接続する形ではない。"}, {"text": "明けろ", "is_correct": false, "explanation": "命令形で空に命令する形になり、「東の空が明けろはじめ」は文として成り立たない。"}], "correct_form": "明け", "base_form": "明ける", "form_label": "連用形", "sentence_index": 7, "explanations": {"明け": "「明けはじめ」の「明け」は連用形で、動詞「はじめる」の前に置いて使う。", "明ける": "基本形なので「明けはじめ」の前には使えず、この位置では文が成り立たない。", "明けて": "て形は「明けてはじめ」とは続かず、「はじめる」に接続する形ではない。", "明けろ": "命令形で空に命令する形になり、「東の空が明けろはじめ」は文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝の給餌」の「の」で、朝と給餌をつなぐ連体修飾の形を作る。"}, {"text": "へ", "is_correct": false, "explanation": "「朝へ給餌」は方向として成り立たず、この位置に入らない。"}, {"text": "を", "is_correct": false, "explanation": "「朝を給餌が終わると」は目的語と主語が重なり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「朝と給餌が終わると」は並列として不自然で、文が通らない。"}], "correct_answer": "の", "explanations": {"の": "「朝の給餌」の「の」で、朝と給餌をつなぐ連体修飾の形を作る。", "へ": "「朝へ給餌」は方向として成り立たず、この位置に入らない。", "を": "「朝を給餌が終わると」は目的語と主語が重なり、文が成り立たない。", "と": "「朝と給餌が終わると」は並列として不自然で、文が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「朝夕の給餌」の「の」で、朝夕と給餌をつなぐ連体修飾の形を作る。"}, {"text": "へ", "is_correct": false, "explanation": "「朝夕へ給餌のとき」は時間に方向が付き、成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「朝夕を給餌」は目的語として意味が通らず、この位置に入らない。"}, {"text": "で", "is_correct": false, "explanation": "「朝夕で給餌」は手段や場所として成り立たず、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「朝夕の給餌」の「の」で、朝夕と給餌をつなぐ連体修飾の形を作る。", "へ": "「朝夕へ給餌のとき」は時間に方向が付き、成り立たない。", "を": "「朝夕を給餌」は目的語として意味が通らず、この位置に入らない。", "で": "「朝夕で給餌」は手段や場所として成り立たず、意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "動物に食べ物をあげること。", "primary_collocate": null, "pronunciation": "きゅうじ", "ipa": "kʲɯːdʑi", "syllable_count": 3, "sentences": [{"text": "毎日の給餌は、ペットを飼う人の大切な仕事です。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "毎日[まいにち]の給餌[きゅうじ]は、ペットを飼[か]う人[ひと]の大切[たいせつ]な仕事[しごと]です。", "sentence_source": "generated"}, {"text": "朝の給餌が終わると、犬はうれしそうに尻尾を振った。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "朝[あさ]の給餌[きゅうじ]が終[お]わると、犬[いぬ]はうれしそうに尻尾[しっぽ]を振[ふ]った。", "sentence_source": "generated"}, {"text": "水族館では、ダイバーが魚に給餌する様子を見られる。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "水族館[すいぞくかん]では、ダイバーが魚[さかな]に給餌[きゅうじ]する様子[ようす]を見[み]られる。", "sentence_source": "generated"}, {"text": "給餌のあとは、皿をきれいに洗っておきます。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "給餌[きゅうじ]のあとは、皿[さら]をきれいに洗[あら]っておきます。", "sentence_source": "generated"}, {"text": "兄は猫の給餌を忘れて、母に叱られた。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "兄[あに]は猫[ねこ]の給餌[きゅうじ]を忘[わす]れて、母[はは]に叱[しか]られた。", "sentence_source": "generated"}, {"text": "うちの犬は、給餌の回数を一日二回に決めている。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "うちの犬[いぬ]は、給餌[きゅうじ]の回数[かいすう]を一日[いちにち]二回[にかい]に決[き]めている。", "sentence_source": "generated"}, {"text": "ひよこへの給餌は、小さなスプーンで少しずつ行う。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "ひよこへの給餌[きゅうじ]は、小[ちい]さなスプーンで少[すこ]しずつ行[おこな]う。", "sentence_source": "generated"}, {"text": "農家では、朝夕の給餌のときに家畜の様子も確認する。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "農家[のうか]では、朝夕[あさゆう]の給餌[きゅうじ]のときに家畜[かちく]の様子[ようす]も確認[かくにん]する。", "sentence_source": "generated"}, {"text": "休日は私が給餌を担当し、弟は散歩に連れて行く。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "休日[きゅうじつ]は私[わたし]が給餌[きゅうじ]を担当[たんとう]し、弟[おとうと]は散歩[さんぽ]に連[つ]れて行[い]く。", "sentence_source": "generated"}, {"text": "動物園では、午後三時になると給餌が始まる。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、午後[ごご]三時[さんじ]になると給餌[きゅうじ]が始[はじ]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "給餌", "label": "基本形"}, {"form": "給餌する", "label": "する動詞"}], "register": "中立", "sense_fingerprint": "動物に食べ物をあげること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "給餌", "is_correct": true, "explanation": "「毎日の給餌」で、えさを与える仕事を指す。"}, {"text": "給油", "is_correct": false, "explanation": "「給油」は車への燃料補給で、ペットの仕事としては合わない。"}, {"text": "給電", "is_correct": false, "explanation": "「給電」は電力の供給で、ペットを飼う人の仕事としては成り立たない。"}, {"text": "給湯", "is_correct": false, "explanation": "「給湯」は湯の供給で、ペットの世話の仕事としては文脈に合わない。"}], "explanations": {"給餌": "「毎日の給餌」で、えさを与える仕事を指す。", "給油": "「給油」は車への燃料補給で、ペットの仕事としては合わない。", "給電": "「給電」は電力の供給で、ペットを飼う人の仕事としては成り立たない。", "給湯": "「給湯」は湯の供給で、ペットの世話の仕事としては文脈に合わない。"}, "sentence_index": 0, "correct_answer": "給餌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "患者に薬を給餌した。", "explanation": "ここは〈投与〉の意味。薬や治療は「投与」と言い、「給餌」は動物にえさを与えること。"}, {"text": "チラシを給餌した。", "explanation": "ここは〈配布〉の意味。印刷物は「配布」と言い、「給餌」は動物に限る。"}, {"text": "畑に給餌した。", "explanation": "ここは〈灌水〉の意味。畑や植物には「水をやる・灌水」と言い、「給餌」は動物に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "給餌", "is_correct": true, "explanation": "「ひよこへの給餌」で、えさを与える行為を指す。"}, {"text": "給紙", "is_correct": false, "explanation": "「給紙」は紙を供給する意味で、ひよこには合わない。"}, {"text": "給気", "is_correct": false, "explanation": "「給気」は空気を送る意味で、「ひよこへの給気」は成り立たない。"}, {"text": "給炭", "is_correct": false, "explanation": "「給炭」は炭を供給する意味で、ひよこには使わない。"}], "explanations": {"給餌": "「ひよこへの給餌」で、えさを与える行為を指す。", "給紙": "「給紙」は紙を供給する意味で、ひよこには合わない。", "給気": "「給気」は空気を送る意味で、「ひよこへの給気」は成り立たない。", "給炭": "「給炭」は炭を供給する意味で、ひよこには使わない。"}, "sentence_index": 6, "correct_answer": "給餌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後三時から水道の給餌が始まる。", "explanation": "ここは〈供給〉の意味。水道や電気は「供給」と言い、「給餌」は動物にえさを与えること。"}, {"text": "燃料の給餌が午後三時に始まる。", "explanation": "ここは〈補給〉の意味。燃料は「補給」と言い、「給餌」は動物にえさを与えること。"}, {"text": "食料の給餌が午後三時に始まる。", "explanation": "ここは〈配給〉の意味。人に食料を配ることは「配給」と言い、「給餌」は動物に限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の給餌を終わると、猫はうれしそうに鳴いた。", "corrected_sentence": "夕方の給餌が終わると、猫はうれしそうに鳴いた。", "error_description": "「終わる」は自動詞なので、「給餌を」ではなく「給餌が」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎晩、猫の給餌を食べてから寝る。", "corrected_sentence": "毎晩、猫の給餌をしてから寝る。", "error_description": "「給餌」は行為を表す名詞で、「食べる」ではなく「する」と組み合わせる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「牛への給餌」の「の」で、給餌を名詞として修飾するつながりを作る。"}, {"text": "で", "is_correct": false, "explanation": "「牛へで給餌」は場所や手段として成り立たず、つながらない。"}, {"text": "より", "is_correct": false, "explanation": "「牛へより給餌」は比較の文として成り立たず、続かない。"}, {"text": "から", "is_correct": false, "explanation": "「牛へから給餌」は起点として意味が通らず、続かない。"}], "correct_answer": "の", "explanations": {"の": "「牛への給餌」の「の」で、給餌を名詞として修飾するつながりを作る。", "で": "「牛へで給餌」は場所や手段として成り立たず、つながらない。", "より": "「牛へより給餌」は比較の文として成り立たず、続かない。", "から": "「牛へから給餌」は起点として意味が通らず、続かない。"}, "error_tags": {"の": "連体修飾", "で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「給餌の量」の「の」で、給餌と量をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「給餌を量を減らした」と目的語が重なり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「給餌に量を減らした」は成り立たず、時点や帰着を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「給餌へ量を減らした」は方向として意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「給餌の量」の「の」で、給餌と量をつなぐ。", "を": "「給餌を量を減らした」と目的語が重なり、意味が通らない。", "に": "「給餌に量を減らした」は成り立たず、時点や帰着を表せない。", "へ": "「給餌へ量を減らした」は方向として意味が通らない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "に": "時点・帰着", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "動物にえさを与えること。特に、飼育している動物に定期的にえさをやること。", "primary_collocate": null, "pronunciation": "きゅうじ", "ipa": "kʲɯːdʑi", "syllable_count": 3, "sentences": [{"text": "彼が大切にしているのは、動物である鶏たちへの給餌だ。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "彼[かれ]が大切[たいせつ]にしているのは、動物[どうぶつ]である鶏[にわとり]たちへの給餌[きゅうじ]だ。", "sentence_source": "mined"}, {"text": "毎朝六時に、牧場で牛への給餌をします。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]六時[ろくじ]に、牧場[ぼくじょう]で牛[うし]への給餌[きゅうじ]をします。", "sentence_source": "generated"}, {"text": "給餌の時間が遅れると、犬が吠えて催促する。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "給餌[きゅうじ]の時間[じかん]が遅[おく]れると、犬[いぬ]が吠[ほ]えて催促[さいそく]する。", "sentence_source": "generated"}, {"text": "動物園では、飼育員が決まった時刻に給餌を行う。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、飼育員[しいくいん]が決[き]まった時刻[じこく]に給餌[きゅうじ]を行[おこな]う。", "sentence_source": "generated"}, {"text": "魚に給餌しすぎると、水が汚れてしまいます。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "魚[さかな]に給餌[きゅうじ]しすぎると、水[みず]が汚[よご]れてしまいます。", "sentence_source": "generated"}, {"text": "子鳥が大きくなるまで、親鳥は何度も給餌を繰り返す。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "子鳥[こどり]が大[おお]きくなるまで、親鳥[おやどり]は何度[なんど]も給餌[きゅうじ]を繰[く]り返[かえ]す。", "sentence_source": "generated"}, {"text": "旅行中は友人に頼んで、猫の給餌をしてもらった。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "旅行中[りょこうちゅう]は友人[ゆうじん]に頼[たの]んで、猫[ねこ]の給餌[きゅうじ]をしてもらった。", "sentence_source": "generated"}, {"text": "給餌の量を減らしたのは、ペットが太りすぎたからだ。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "給餌[きゅうじ]の量[りょう]を減[へ]らしたのは、ペットが太[ふと]りすぎたからだ。", "sentence_source": "generated"}, {"text": "見学者による給餌は禁止されている。動物の健康を守るためだ。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "見学者[けんがくしゃ]による給餌[きゅうじ]は禁止[きんし]されている。動物[どうぶつ]の健康[けんこう]を守[まも]るためだ。", "sentence_source": "generated"}, {"text": "冬の山では雪で餌が見つからず、鹿への給餌が行われる。", "target_word": "給餌", "complexity_tier": "T3", "furigana": "冬[ふゆ]の山[やま]では雪[ゆき]で餌[えさ]が見[み]つからず、鹿[しか]への給餌[きゅうじ]が行[おこな]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "給餌", "label": "基本形"}, {"form": "給餌する", "label": "する動詞"}], "register": "中立", "sense_fingerprint": "飼育動物に定期的にえさを与える行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "給餌", "is_correct": true, "explanation": "「鶏たちへの給餌」で、えさを与える行為を指す。"}, {"text": "給油", "is_correct": false, "explanation": "「給油」は車などに燃料を入れる意味で、鶏には使わない。"}, {"text": "給電", "is_correct": false, "explanation": "「給電」は電力を供給する意味で、鶏への給電は文として成り立たない。"}, {"text": "給湯", "is_correct": false, "explanation": "「給湯」は湯を供給する意味で、鶏への給湯は不自然で文脈に合わない。"}], "explanations": {"給餌": "「鶏たちへの給餌」で、えさを与える行為を指す。", "給油": "「給油」は車などに燃料を入れる意味で、鶏には使わない。", "給電": "「給電」は電力を供給する意味で、鶏への給電は文として成り立たない。", "給湯": "「給湯」は湯を供給する意味で、鶏への給湯は不自然で文脈に合わない。"}, "sentence_index": 0, "correct_answer": "給餌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "避難所では住民に給餌を行った。", "explanation": "ここは〈炊き出し〉の意味。避難所で食事を作って配ることは「炊き出し」と言い、「給餌」は動物にえさを与える語。"}, {"text": "畑に肥料を給餌した。", "explanation": "ここは〈散布〉の意味。肥料は「散布」や「施す」と言い、「給餌」は動物に食べ物を与える語。"}, {"text": "車に給餌した。", "explanation": "ここは〈給油〉の意味。車には燃料を入れる「給油」を使い、「給餌」は動物に限られる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "給餌", "is_correct": true, "explanation": "「猫の給餌」で、猫にえさを与えることを指す。"}, {"text": "給紙", "is_correct": false, "explanation": "「給紙」は紙を供給する意味で、猫には使えない。"}, {"text": "給気", "is_correct": false, "explanation": "「給気」は空気を送る意味で、「猫の給気」は成り立たない。"}, {"text": "給炭", "is_correct": false, "explanation": "「給炭」は炭を供給する意味で、猫には使わない。"}], "explanations": {"給餌": "「猫の給餌」で、猫にえさを与えることを指す。", "給紙": "「給紙」は紙を供給する意味で、猫には使えない。", "給気": "「給気」は空気を送る意味で、「猫の給気」は成り立たない。", "給炭": "「給炭」は炭を供給する意味で、猫には使わない。"}, "sentence_index": 6, "correct_answer": "給餌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "戦時中は食料の給餌が行われた。", "explanation": "ここは〈配給〉の意味。人に食料を配ることは「配給」と言い、「給餌」は動物に限る。"}, {"text": "燃料を給餌して、車で出発した。", "explanation": "ここは〈補給〉の意味。燃料は「補給」と言い、「給餌」は動物にえさを与えること。"}, {"text": "在庫を給餌しておく。", "explanation": "ここは〈補充〉の意味。在庫や商品は「補充」と言い、「給餌」は動物にしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎朝、牧場の牛に給餌を食べた。", "corrected_sentence": "毎朝、牧場の牛に給餌を行った。", "error_description": "「給餌」は行為を表す名詞で、「食べる」とは組み合わせられない。「行う」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行中は友人に頼んで、猫で給餌をお願いした。", "corrected_sentence": "旅行中は友人に頼んで、猫の給餌をお願いした。", "error_description": "「猫の給餌」の「の」を「で」にした誤り。「給餌」の対象を示す「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「帽子が」で、可能動詞「取れる」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」では「取れる」の主語にも目的語にもならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では「取れる」の主語にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、ここでは文の主語の位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "「帽子が」で、可能動詞「取れる」の主語を示す。", "と": "「と」では「取れる」の主語にも目的語にもならず、文が成り立たない。", "に": "「に」では「取れる」の主語にならず、文が成り立たない。", "で": "手段や場所を表すが、ここでは文の主語の位置に入らない。"}, "error_tags": {"と": "並列・相手", "に": "相手・位置", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
