INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをつかんで、自分のものにすることができるという意味です。", "primary_collocate": null, "pronunciation": "とれる", "ipa": "toɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "棚が高くて、背の低い私には本が取れない。", "target_word": "取れない", "complexity_tier": "T3", "furigana": "棚[たな]が高[たか]くて、背[せ]の低[ひく]い私[わたし]には本[ほん]が取[と]れない。", "sentence_source": "generated"}, {"text": "腕を伸ばせば、窓の外の帽子が取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "腕[うで]を伸[の]ばせば、窓[まど]の外[そと]の帽子[ぼうし]が取[と]れる。", "sentence_source": "generated"}, {"text": "弟は片手でボールが取れるようになった。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "弟[おとうと]は片手[かたて]でボールが取[と]れるようになった。", "sentence_source": "generated"}, {"text": "川の中の石は、手を入れても深くて取れなかった。", "target_word": "取れなかった", "complexity_tier": "T3", "furigana": "川[かわ]の中[なか]の石[いし]は、手[て]を入[い]れても深[ふか]くて取[と]れなかった。", "sentence_source": "generated"}, {"text": "長い棒を使えば、木の上のボールが取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "長[なが]い棒[ぼう]を使[つか]えば、木[き]の上[うえ]のボールが取[と]れる。", "sentence_source": "generated"}, {"text": "手がふるえて、小さなネジがうまく取れない。", "target_word": "取れない", "complexity_tier": "T3", "furigana": "手[て]がふるえて、小[ちい]さなネジがうまく取[と]れない。", "sentence_source": "generated"}, {"text": "危ないので、火の近くの鍋は子どもには取れない場所に置く。", "target_word": "取れない", "complexity_tier": "T3", "furigana": "危[あぶ]ないので、火[ひ]の近[ちか]くの鍋[なべ]は子[こ]どもには取[と]れない場所[ばしょ]に置[お]く。", "sentence_source": "generated"}, {"text": "高い枝の実は、はしごがあれば取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "高[たか]い枝[えだ]の実[み]は、はしごがあれば取[と]れる。", "sentence_source": "generated"}, {"text": "彼女は走ってきたボールが素早く取れた。", "target_word": "取れた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は走[はし]ってきたボールが素早[すばや]く取[と]れた。", "sentence_source": "generated"}, {"text": "手袋をしていると、小さなコインが取れない。", "target_word": "取れない", "complexity_tier": "T3", "furigana": "手袋[てぶくろ]をしていると、小[ちい]さなコインが取[と]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取れる", "label": "終止形"}, {"form": "取れた", "label": "過去形"}, {"form": "取れない", "label": "否定形"}, {"form": "取れて", "label": "て形"}, {"form": "取れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "「取る」の可能。つかんで手に入れることができる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取れない", "is_correct": true, "explanation": "言い切りの否定形で、「高くて届かない」という理由と合う。"}, {"text": "取れて", "is_correct": false, "explanation": "て形なので文末に置けない。"}, {"text": "取れれば", "is_correct": false, "explanation": "仮定形で「〜なら」の節になり、文を終えられない。"}, {"text": "取る", "is_correct": false, "explanation": "「本が取る」とは言えない。取るは「本を取る」と目的語に「を」を使う。"}], "explanations": {"取れない": "言い切りの否定形で、「高くて届かない」という理由と合う。", "取れて": "て形なので文末に置けない。", "取れれば": "仮定形で「〜なら」の節になり、文を終えられない。", "取る": "「本が取る」とは言えない。取るは「本を取る」と目的語に「を」を使う。"}, "sentence_index": 0, "correct_answer": "取れない"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まじめな仕事ぶりで、社員の信頼が取れた。", "explanation": "ここは〈得る〉の意味。信頼には〈得る〉を使い、取れるは物を手でつかむ意味なので、信頼には合わない。"}, {"text": "上着のボタンが取れて、床に落ちた。", "explanation": "ここは〈外れる〉の意味。取れるはつかんで手に入れる意味で、ボタンが外れる場面には合わない。"}, {"text": "その会社では、彼の案が取れた。", "explanation": "ここは〈採用する〉の意味。案には〈採用する〉を使い、取れるは物をつかむ意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取れない", "is_correct": true, "explanation": "「子どもには取れない場所」という否定の形で、「危ないので」という理由と合う。"}, {"text": "取れなく", "is_correct": false, "explanation": "連用形は「場所」を後ろから修飾できない。"}, {"text": "取れなかった", "is_correct": false, "explanation": "過去の否定になり、これから鍋を置く場所の説明として時制が合わない。"}, {"text": "取れ", "is_correct": false, "explanation": "語幹だけでは「場所」を修飾できず、文としても成り立たない。"}], "explanations": {"取れない": "「子どもには取れない場所」という否定の形で、「危ないので」という理由と合う。", "取れなく": "連用形は「場所」を後ろから修飾できない。", "取れなかった": "過去の否定になり、これから鍋を置く場所の説明として時制が合わない。", "取れ": "語幹だけでは「場所」を修飾できず、文としても成り立たない。"}, "sentence_index": 6, "correct_answer": "取れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "逃げた犯人が、ついに取れた。", "explanation": "ここは〈捕まえる〉の意味。取れるは物をつかむ意味で、人には使わない。"}, {"text": "子どもの頃の夢が、ようやく取れた。", "explanation": "ここは〈叶う〉の意味。夢には〈叶う〉を使い、取れるは〈つかんで手に入れる〉意味なので合わない。"}, {"text": "たくさんの経験から、知識が取れた。", "explanation": "ここは〈得る〉の意味。知識には〈得る〉を使い、取れるは物をつかむ意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "脚立に乗れば、高い棚の上の箱が取れられる。", "corrected_sentence": "脚立に乗れば、高い棚の上の箱が取れる。", "error_description": "「取れられる」は可能形に可能の助動詞を重ねた二重の可能で誤り。正しくは「取れる」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取れる", "is_correct": true, "explanation": "終止形。「伸ばせば」の結果を言い切る形として正しい。"}, {"text": "取れるば", "is_correct": false, "explanation": "仮定形は「取れれば」で、「取れるば」は活用として成り立たない。"}, {"text": "取れて", "is_correct": false, "explanation": "て形なので文末に置けず、「ば」の条件文とも続かない。"}, {"text": "取れれば", "is_correct": false, "explanation": "仮定形を重ねると「伸ばせば取れれば」となり、文として成り立たない。"}], "correct_form": "取れる", "base_form": "取れる", "form_label": "終止形", "sentence_index": 1, "explanations": {"取れる": "終止形。「伸ばせば」の結果を言い切る形として正しい。", "取れるば": "仮定形は「取れれば」で、「取れるば」は活用として成り立たない。", "取れて": "て形なので文末に置けず、「ば」の条件文とも続かない。", "取れれば": "仮定形を重ねると「伸ばせば取れれば」となり、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51533, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "はしごを使えば、屋根の上の帽子が取れられる。", "corrected_sentence": "はしごを使えば、屋根の上の帽子が取れる。", "error_description": "「取れられる」は可能形に可能の助動詞を重ねた二重の可能で誤り。正しくは「取れる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取れる", "is_correct": true, "explanation": "終止形。「はしごがあれば」という条件の結果を言い切る形として正しい。"}, {"text": "取れるば", "is_correct": false, "explanation": "仮定形は「取れれば」で、「取れるば」は活用として成り立たない。"}, {"text": "取れなくて", "is_correct": false, "explanation": "て形なので文末に置けず、条件の結果にもならない。"}, {"text": "取れなければ", "is_correct": false, "explanation": "否定の条件になり、「はしごがあれば」と逆の意味になる。"}], "correct_form": "取れる", "base_form": "取れる", "form_label": "終止形", "sentence_index": 7, "explanations": {"取れる": "終止形。「はしごがあれば」という条件の結果を言い切る形として正しい。", "取れるば": "仮定形は「取れれば」で、「取れるば」は活用として成り立たない。", "取れなくて": "て形なので文末に置けず、条件の結果にもならない。", "取れなければ": "否定の条件になり、「はしごがあれば」と逆の意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「休みが」で、可能動詞「取れる」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "可能動詞は対象を「が」で示すので、「休みを取れそう」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「休みに」では「取れる」の主語にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すが、この文では主語の位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "「休みが」で、可能動詞「取れる」の主語を示す。", "を": "可能動詞は対象を「が」で示すので、「休みを取れそう」は不自然。", "に": "「休みに」では「取れる」の主語にならず、文が成り立たない。", "で": "手段や場所を表すが、この文では主語の位置に入らない。"}, "error_tags": {"を": "対象", "に": "位置", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「座席が」で、可能動詞「取れる」の主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表すが、「座席と取れる」では主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「取れる」の主語の位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、この文では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「座席が」で、可能動詞「取れる」の主語を示す。", "と": "並列や相手を表すが、「座席と取れる」では主語にならない。", "へ": "方向を表すが、「取れる」の主語の位置には入らない。", "より": "比較を表すが、この文では文が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や体を使って物をしっかりとつかみ、自分の手元に持ってくること。また、機会や状況をうまく利用すること。", "primary_collocate": null, "pronunciation": "とれる", "ipa": "toɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "背伸びをしたら、棚の上の箱が取れた。", "target_word": "取れた", "complexity_tier": "T3", "furigana": "背伸[せの]びをしたら、棚[たな]の上[うえ]の箱[はこ]が取[と]れた。", "sentence_source": "generated"}, {"text": "忙しくても、来週は三日ほど休みが取れそうだ。", "target_word": "取れ", "complexity_tier": "T3", "furigana": "忙[いそが]しくても、来週[らいしゅう]は三日[みっか]ほど休[やす]みが取[と]れそうだ。", "sentence_source": "generated"}, {"text": "足元に落ちた鍵は、しゃがめばすぐ取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "足元[あしもと]に落[お]ちた鍵[かぎ]は、しゃがめばすぐ取[と]れる。", "sentence_source": "generated"}, {"text": "早く申し込んだので、人気のコンサートの席が取れた。", "target_word": "取れた", "complexity_tier": "T3", "furigana": "早[はや]く申[もう]し込[こ]んだので、人気[にんき]のコンサートの席[せき]が取[と]れた。", "sentence_source": "generated"}, {"text": "授業の合間に、ゆっくり昼ごはんを食べる時間が取れた。", "target_word": "取れた", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の合間[あいま]に、ゆっくり昼[ひる]ごはんを食[た]べる時間[じかん]が取[と]れた。", "sentence_source": "generated"}, {"text": "水に落ちたボールも、長い網を使えば取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "水[みず]に落[お]ちたボールも、長[なが]い網[あみ]を使[つか]えば取[と]れる。", "sentence_source": "generated"}, {"text": "時間がうまく取れれば、毎朝運動を続けられるのに。", "target_word": "取れれば", "complexity_tier": "T3", "furigana": "時間[じかん]がうまく取[と]れれば、毎朝[まいあさ]運動[うんどう]を続[つづ]けられるのに。", "sentence_source": "generated"}, {"text": "早起きした日は、混む前に電車の座席が取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "早起[はやお]きした日[ひ]は、混[こ]む前[まえ]に電車[でんしゃ]の座席[ざせき]が取[と]れる。", "sentence_source": "generated"}, {"text": "窓のそばに立てば、上のカーテンの紐が取れる。", "target_word": "取れる", "complexity_tier": "T3", "furigana": "窓[まど]のそばに立[た]てば、上[うえ]のカーテンの紐[ひも]が取[と]れる。", "sentence_source": "generated"}, {"text": "予定が合ったので、全員で集まる日がやっと取れた。", "target_word": "取れた", "complexity_tier": "T3", "furigana": "予定[よてい]が合[あ]ったので、全員[ぜんいん]で集[あつ]まる日[ひ]がやっと取[と]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取れる", "label": "終止形"}, {"form": "取れた", "label": "過去形"}, {"form": "取れない", "label": "否定形"}, {"form": "取れて", "label": "て形"}, {"form": "取れれば", "label": "仮定形"}], "register": "常体（中立）", "sense_fingerprint": "「取る」の可能。物を手元に持ってこられる、機会や時間を確保できる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: しゃがめ (Zipf 1.71)']::text[], '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取れた", "is_correct": true, "explanation": "過去形で、背伸びをした結果として箱が手元に取れたことを表す。"}, {"text": "取れて", "is_correct": false, "explanation": "て形なので文末に置けない。"}, {"text": "取れません", "is_correct": false, "explanation": "丁寧語で、常体で書かれた文の文体に合わない。"}, {"text": "取れなくて", "is_correct": false, "explanation": "て形で文を言い切れず、「背伸びをしたら」の結果としても続かない。"}], "explanations": {"取れた": "過去形で、背伸びをした結果として箱が手元に取れたことを表す。", "取れて": "て形なので文末に置けない。", "取れません": "丁寧語で、常体で書かれた文の文体に合わない。", "取れなくて": "て形で文を言い切れず、「背伸びをしたら」の結果としても続かない。"}, "sentence_index": 0, "correct_answer": "取れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生からの注意が取れた。", "explanation": "ここは〈受ける〉の意味。注意には〈受ける〉を使い、取れるは手元に持ってくる意味なので合わない。"}, {"text": "子どもの頃の夢が、ようやく取れた。", "explanation": "ここは〈叶う〉の意味。夢には〈叶う〉を使い、取れるは機会や物を手元に得る意味なので合わない。"}, {"text": "会議の内容が、一枚に取れた。", "explanation": "ここは〈まとめる〉の意味。内容には〈まとめる〉を使い、取れるは手元に持ってくる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取れれば", "is_correct": true, "explanation": "仮定形で、「時間がうまく取れれば」という条件と「〜のに」の願いがつながる。"}, {"text": "取れず", "is_correct": false, "explanation": "文語的な否定の形で、「〜のに」と続く文の口語の流れに合わない。"}, {"text": "取れなければ", "is_correct": false, "explanation": "否定の条件になり、続けたいという願いと逆の意味になる。"}, {"text": "取れそう", "is_correct": false, "explanation": "様態の形で、「〜のに」の前提になる条件を表せない。"}], "explanations": {"取れれば": "仮定形で、「時間がうまく取れれば」という条件と「〜のに」の願いがつながる。", "取れず": "文語的な否定の形で、「〜のに」と続く文の口語の流れに合わない。", "取れなければ": "否定の条件になり、続けたいという願いと逆の意味になる。", "取れそう": "様態の形で、「〜のに」の前提になる条件を表せない。"}, "sentence_index": 6, "correct_answer": "取れれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボタンが服から取れた。", "explanation": "ここは〈外れる〉の意味。ボタンが服から離れる意味で、手元に持ってくる語義とは違う。"}, {"text": "誤解が、ようやく取れた。", "explanation": "ここは〈解ける〉の意味。誤解が解ける意味で、手元に持ってくる語義とは違う。"}, {"text": "二人の話を聞いて、結論が取れた。", "explanation": "ここは〈出る・まとまる〉の意味。結論には〈出る〉を使い、取れるは手元に持ってくる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝早く起きれば、ゆっくり朝食の時間を取れる。", "corrected_sentence": "朝早く起きれば、ゆっくり朝食の時間が取れる。", "error_description": "「を」が誤りで、正しくは「が」。可能形の「取れる」は対象を「が」で示すため、「時間を取れる」とは言わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取れ", "is_correct": true, "explanation": "連用形。「そうだ」（様子）は動詞の語幹に続くため、「取れそうだ」の形になる。"}, {"text": "取れた", "is_correct": false, "explanation": "「取れたそうだ」は伝聞の意味になり、様子を表す文に合わない。"}, {"text": "取れない", "is_correct": false, "explanation": "「取れないそうだ」は伝聞の意味になり、様子を表す文に合わない。"}, {"text": "取れて", "is_correct": false, "explanation": "て形は「そうだ」の前に続かず、文が成り立たない。"}], "correct_form": "取れ", "base_form": "取れる", "form_label": "連用形", "sentence_index": 1, "explanations": {"取れ": "連用形。「そうだ」（様子）は動詞の語幹に続くため、「取れそうだ」の形になる。", "取れた": "「取れたそうだ」は伝聞の意味になり、様子を表す文に合わない。", "取れない": "「取れないそうだ」は伝聞の意味になり、様子を表す文に合わない。", "取れて": "て形は「そうだ」の前に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝早く起きれば、駅前の座席が取れられる。", "corrected_sentence": "朝早く起きれば、駅前の座席が取れる。", "error_description": "「取れられる」は可能形に可能の助動詞を重ねた二重の可能で誤り。正しくは「取れる」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取れる", "is_correct": true, "explanation": "終止形。「混む前に座席が取れる」と、早起きの結果を言い切る形として正しい。"}, {"text": "取れよう", "is_correct": false, "explanation": "意志・推量の形で、「座席が」の主語と文末が合わない。"}, {"text": "取れなかった", "is_correct": false, "explanation": "過去の否定になり、早起きした日の習慣的な結果を表す文に合わない。"}, {"text": "取れず", "is_correct": false, "explanation": "文語的な否定の形で、口語の文末には合わない。"}], "correct_form": "取れる", "base_form": "取れる", "form_label": "終止形", "sentence_index": 7, "explanations": {"取れる": "終止形。「混む前に座席が取れる」と、早起きの結果を言い切る形として正しい。", "取れよう": "意志・推量の形で、「座席が」の主語と文末が合わない。", "取れなかった": "過去の否定になり、早起きした日の習慣的な結果を表す文に合わない。", "取れず": "文語的な否定の形で、口語の文末には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穀物を」で、「育てる」の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「育てる」の対象には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「穀物に育てている」は育てる対象を示せず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞で、文の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「穀物を」で、「育てる」の対象を示す。", "が": "主語を示す助詞で、「育てる」の対象には使えない。", "に": "「穀物に育てている」は育てる対象を示せず、文が成り立たない。", "の": "連体修飾の助詞で、文の対象にはならない。"}, "error_tags": {"が": "主語", "に": "位置", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「穀物を」で、「輸入している」の対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表すが、「輸入する」の対象は「を」で示す。"}, {"text": "と", "is_correct": false, "explanation": "並列を表すが、「穀物と輸入している」では対象にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「輸入している」の対象の位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "「穀物を」で、「輸入している」の対象を示す。", "に": "位置や相手を表すが、「輸入する」の対象は「を」で示す。", "と": "並列を表すが、「穀物と輸入している」では対象にならない。", "へ": "方向を表すが、「輸入している」の対象の位置には入らない。"}, "error_tags": {"に": "位置", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たべものになる、むぎやこめなどのたね。", "primary_collocate": null, "pronunciation": "こくもつ", "ipa": "kokɯmotsɯ", "syllable_count": 4, "sentences": [{"text": "米や麦は、世界中で食べられている穀物だ。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "米[こめ]や麦[むぎ]は、世界中[せかいじゅう]で食[た]べられている穀物[こくもつ]だ。", "sentence_source": "generated"}, {"text": "この地方では、寒さに強い穀物を育てている。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "この地方[ちほう]では、寒[さむ]さに強[つよ]い穀物[こくもつ]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "穀物は、パンやめんの原料になる。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "穀物[こくもつ]は、パンやめんの原料[げんりょう]になる。", "sentence_source": "generated"}, {"text": "干ばつのせいで、穀物の値段が上がった。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "干[ひ]ばつのせいで、穀物[こくもつ]の値段[ねだん]が上[あ]がった。", "sentence_source": "generated"}, {"text": "農家は秋に穀物を収穫して、倉庫にしまう。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "農家[のうか]は秋[あき]に穀物[こくもつ]を収穫[しゅうかく]して、倉庫[そうこ]にしまう。", "sentence_source": "generated"}, {"text": "鳥が畑の穀物を食べに来るので、あみをかけた。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "鳥[とり]が畑[はたけ]の穀物[こくもつ]を食[た]べに来[く]るので、あみをかけた。", "sentence_source": "generated"}, {"text": "朝食に、穀物の入ったシリアルを食べる。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "朝食[ちょうしょく]に、穀物[こくもつ]の入[はい]ったシリアルを食[た]べる。", "sentence_source": "generated"}, {"text": "日本は、外国から多くの穀物を輸入している。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "日本[にほん]は、外国[がいこく]から多[おお]くの穀物[こくもつ]を輸入[ゆにゅう]している。", "sentence_source": "generated"}, {"text": "昔の人は、穀物を粉にして団子を作った。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、穀物[こくもつ]を粉[こな]にして団子[だんご]を作[つく]った。", "sentence_source": "generated"}, {"text": "穀物の中でも、とうもろこしは家畜のえさによく使われる。", "target_word": "穀物", "complexity_tier": "T3", "furigana": "穀物[こくもつ]の中[なか]でも、とうもろこしは家畜[かちく]のえさによく使[つか]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "穀物", "label": "基本形"}], "register": "常体（中立）", "sense_fingerprint": "米や麦など、食用にする植物の種", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aba9d36-096d-4db0-9fb9-3346be598cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穀物", "is_correct": true, "explanation": "米や麦などの食用の種子で、世界中で食べられているものとして文に合う。"}, {"text": "食器", "is_correct": false, "explanation": "食べ物ではなく、料理を盛る器なので「食べられている」と合わない。"}, {"text": "レシピ", "is_correct": false, "explanation": "料理の作り方であり、食べられるものではない。"}, {"text": "調理器具", "is_correct": false, "explanation": "料理に使う道具で、食べられるものではない。"}], "explanations": {"穀物": "米や麦などの食用の種子で、世界中で食べられているものとして文に合う。", "食器": "食べ物ではなく、料理を盛る器なので「食べられている」と合わない。", "レシピ": "料理の作り方であり、食べられるものではない。", "調理器具": "料理に使う道具で、食べられるものではない。"}, "sentence_index": 0, "correct_answer": "穀物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は、りんごやもものような穀物がおいしい。", "explanation": "ここは〈果物〉の意味。りんごやももは果物と言い、穀物は米や麦など穀類を指すので合わない。"}, {"text": "キャベツは、畑でていねいに育てる穀物だ。", "explanation": "ここは〈野菜〉の意味。キャベツは野菜で、穀物は米や麦のような穀類を指すので合わない。"}, {"text": "牛肉は、ステーキにすると喜ばれる穀物だ。", "explanation": "ここは〈肉〉の意味。牛肉は肉で、穀物は植物の種子を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穀物", "is_correct": true, "explanation": "「穀物の入ったシリアル」として、朝食に食べる食材の説明に合う。"}, {"text": "包丁", "is_correct": false, "explanation": "料理の道具で、シリアルに入るものではない。"}, {"text": "まな板", "is_correct": false, "explanation": "料理の台で、シリアルに入るものではない。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、入ったシリアルとは合わない。"}], "explanations": {"穀物": "「穀物の入ったシリアル」として、朝食に食べる食材の説明に合う。", "包丁": "料理の道具で、シリアルに入るものではない。", "まな板": "料理の台で、シリアルに入るものではない。", "鍋": "調理器具で、入ったシリアルとは合わない。"}, "sentence_index": 6, "correct_answer": "穀物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ねぎは、夏の冷ややっこに欠かせない穀物だ。", "explanation": "ここは〈野菜〉の意味。ねぎは野菜で、穀物は米や麦などの穀類を指すので合わない。"}, {"text": "穀物は、ホクホクして焼き芋にすると人気だ。", "explanation": "ここは〈芋〉の意味。さつまいもは芋で、穀物は穀類を指すので合わない。"}, {"text": "穀物は、料理に甘みを加える調味料だ。", "explanation": "ここは〈調味料〉の意味。砂糖は調味料だが、穀物は主食になる食材なので、甘みを加える使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "農家は春に穀物で植えて、夏に収穫する。", "corrected_sentence": "農家は春に穀物を植えて、夏に収穫する。", "error_description": "「で」が誤りで、正しくは「を」。「植える」の対象は「を」で示すため、「穀物で植える」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この倉庫には、穀物がたくさん保管されてている。", "corrected_sentence": "この倉庫には、穀物がたくさん保管されている。", "error_description": "「保管されてている」は「ている」を重ねた誤り。正しくは「保管されている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd695bfba-4dc1-4868-b162-0f10f02c2fd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "与える", "is_correct": true, "explanation": "「人から受け取る」の対義で、「人に与える」を表す。"}, {"text": "拾う", "is_correct": false, "explanation": "拾うは落ちた物を取る行為で、貰うの対義語ではない。"}, {"text": "買う", "is_correct": false, "explanation": "買うは代金を払って得る行為で、貰うの対義語ではない。"}, {"text": "受け取る", "is_correct": false, "explanation": "受け取るは貰うの類義語で、対義語ではない。"}], "correct_answer": "与える", "explanations": {"与える": "「人から受け取る」の対義で、「人に与える」を表す。", "拾う": "拾うは落ちた物を取る行為で、貰うの対義語ではない。", "買う": "買うは代金を払って得る行為で、貰うの対義語ではない。", "受け取る": "受け取るは貰うの類義語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "与える", "is_correct": true, "explanation": "「人から受け取る」の対義で、「人に与える」を表す。"}, {"text": "預ける", "is_correct": false, "explanation": "預けるは一時的に託す行為で、貰うの対義語ではない。"}, {"text": "届ける", "is_correct": false, "explanation": "届けるは相手のもとへ運ぶ行為で、貰うの対義語ではない。"}, {"text": "売る", "is_correct": false, "explanation": "売るは買うの対義語で、貰うの対義語ではない。"}], "correct_answer": "与える", "explanations": {"与える": "「人から受け取る」の対義で、「人に与える」を表す。", "預ける": "預けるは一時的に託す行為で、貰うの対義語ではない。", "届ける": "届けるは相手のもとへ運ぶ行為で、貰うの対義語ではない。", "売る": "売るは買うの対義語で、貰うの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人から物やお金をもらうことです。", "primary_collocate": null, "pronunciation": "もらう", "ipa": "moɾaɯ", "syllable_count": 3, "sentences": [{"text": "母からお小遣いをもらって、本を買いに行った。", "target_word": "もらって", "complexity_tier": "T3", "furigana": "母[はは]からお小遣[こづか]いをもらって、本[ほん]を買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "友達に旅行のお土産をもらいました。", "target_word": "もらい", "complexity_tier": "T3", "furigana": "友達[ともだち]に旅行[りょこう]のお土産[みやげ]をもらいました。", "sentence_source": "generated"}, {"text": "会社から給料をもらうと、家族と外食する。", "target_word": "もらう", "complexity_tier": "T3", "furigana": "会社[かいしゃ]から給料[きゅうりょう]をもらうと、家族[かぞく]と外食[がいしょく]する。", "sentence_source": "generated"}, {"text": "兄は大学の入学祝いに、新しい時計をもらった。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]の入学祝[にゅうがくいわ]いに、新[あたら]しい時計[とけい]をもらった。", "sentence_source": "generated"}, {"text": "駅で配っているティッシュを、ついもらってしまった。", "target_word": "もらって", "complexity_tier": "T3", "furigana": "駅[えき]で配[くば]っているティッシュを、ついもらってしまった。", "sentence_source": "generated"}, {"text": "先生に花をもらった生徒は、うれしそうに笑った。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "先生[せんせい]に花[はな]をもらった生徒[せいと]は、うれしそうに笑[わら]った。", "sentence_source": "generated"}, {"text": "誕生日のプレゼントをもらうたび、祖父に電話をかけている。", "target_word": "もらう", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]のプレゼントをもらうたび、祖父[そふ]に電話[でんわ]をかけている。", "sentence_source": "generated"}, {"text": "古い本をもらってくれる人を探している。", "target_word": "もらって", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]をもらってくれる人[ひと]を探[さが]している。", "sentence_source": "generated"}, {"text": "隣の家から野菜をもらったので、お礼にお菓子を渡した。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]から野菜[やさい]をもらったので、お礼[れい]にお菓子[かし]を渡[わた]した。", "sentence_source": "generated"}, {"text": "賞金をもらった彼女は、全額を寄付した。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "賞金[しょうきん]をもらった彼女[かのじょ]は、全額[ぜんがく]を寄付[きふ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貰う", "label": "基本形"}, {"form": "もらった", "label": "過去形"}, {"form": "もらわない", "label": "否定形"}, {"form": "もらって", "label": "て形"}, {"form": "もらえる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "人から物やお金を受け取る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もらって", "is_correct": true, "explanation": "て形で「もらって、本を買いに行った」と前後を続ける。文の意味に合う。"}, {"text": "もらおう", "is_correct": false, "explanation": "意向形は文中で「〜て」と続かず、文が成り立たない。"}, {"text": "もらえ", "is_correct": false, "explanation": "命令形や可能の語幹で、文中で前後をつなげない。"}, {"text": "もらわせ", "is_correct": false, "explanation": "使役の語幹では文が成り立たない。"}], "explanations": {"もらって": "て形で「もらって、本を買いに行った」と前後を続ける。文の意味に合う。", "もらおう": "意向形は文中で「〜て」と続かず、文が成り立たない。", "もらえ": "命令形や可能の語幹で、文中で前後をつなげない。", "もらわせ": "使役の語幹では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "もらって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は大学の入学祝いに、健康診断を貰った。", "explanation": "ここは〈受ける〉の意味。検査や試験を受けるのは〈受ける〉で、物や金銭を受け取る〈貰う〉とは合わない。"}, {"text": "兄は大学の入学祝いに、新しい時計を貰って、お金を払って買った。", "explanation": "ここは〈買う〉の意味。代金を払って買うのは〈買う〉で、無償で受け取る〈貰う〉とは合わない。"}, {"text": "兄は大学の入学祝いに、新しい時計を貰うため、店で値段を下げさせた。", "explanation": "ここは〈値引き〉の意味。値段を下げさせるのは〈値引き〉で、無償で受け取る〈貰う〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もらう", "is_correct": true, "explanation": "「もらうたび」と基本形で続き、何度も受け取る場面に合う。"}, {"text": "もらわず", "is_correct": false, "explanation": "打ち消しの連用形は「もらわずたび」と続かない。"}, {"text": "もらいに", "is_correct": false, "explanation": "目的を表す形は「もらいにたび」と続かない。"}, {"text": "もらいたく", "is_correct": false, "explanation": "希望の語幹は「もらいたくたび」と続かない。"}], "explanations": {"もらう": "「もらうたび」と基本形で続き、何度も受け取る場面に合う。", "もらわず": "打ち消しの連用形は「もらわずたび」と続かない。", "もらいに": "目的を表す形は「もらいにたび」と続かない。", "もらいたく": "希望の語幹は「もらいたくたび」と続かない。"}, "sentence_index": 6, "correct_answer": "もらう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は寄付のため、窓口の係から賞金を貰って、力ずくで持ち去った。", "explanation": "ここは〈奪う〉の意味。力ずくで取るのは〈奪う〉で、相手から与えられる〈貰う〉とは合わない。"}, {"text": "彼女は寄付のため、借金を貰って、施設に返した。", "explanation": "ここは〈借りる〉の意味。借りたお金を返すのは〈借りる〉で、無償で受け取る〈貰う〉とは合わない。"}, {"text": "彼女は寄付のため、オークションで品物を貰い、高値で競り落とした。", "explanation": "ここは〈落札〉の意味。競りで高値を払って買い取るのは〈落札〉で、無償で受け取る〈貰う〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達からお礼にケーキをもらってので、一緒に食べた。", "corrected_sentence": "友達からお礼にケーキをもらったので、一緒に食べた。", "error_description": "「もらったので」の「もらった」が「もらってので」になっている。過去の形「もらった」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "もらい", "is_correct": true, "explanation": "連用形で「もらいました」の形になり、丁寧な過去の文に合う。"}, {"text": "もらう", "is_correct": false, "explanation": "「もらうました」とは続かないので、この文では成り立たない。"}, {"text": "もらおう", "is_correct": false, "explanation": "意向形で、「もらおうました」とは続かず、丁寧な過去の文が成り立たない。"}, {"text": "もらわない", "is_correct": false, "explanation": "否定形は「もらわないました」と続かないので、文が成り立たない。"}], "correct_form": "もらい", "base_form": "貰う", "form_label": "連用形", "sentence_index": 1, "explanations": {"もらい": "連用形で「もらいました」の形になり、丁寧な過去の文に合う。", "もらう": "「もらうました」とは続かないので、この文では成り立たない。", "もらおう": "意向形で、「もらおうました」とは続かず、丁寧な過去の文が成り立たない。", "もらわない": "否定形は「もらわないました」と続かないので、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達から誕生日のケーキを貰わった弟は、すぐに食べた。", "corrected_sentence": "友達から誕生日のケーキを貰った弟は、すぐに食べた。", "error_description": "「貰った」が「貰わった」になっている。「貰う」の過去形は「貰った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "もらって", "is_correct": true, "explanation": "て形で「もらってくれる」と続き、受け取ってもらう意味に合う。"}, {"text": "もらわず", "is_correct": false, "explanation": "打ち消しの連用形は「くれる」に続かない。"}, {"text": "もらいに", "is_correct": false, "explanation": "目的を表す形は「くれる」に続かない。"}, {"text": "もらいたく", "is_correct": false, "explanation": "希望の語幹は「くれる」に続かない。"}], "correct_form": "もらって", "base_form": "貰う", "form_label": "て形", "sentence_index": 7, "explanations": {"もらって": "て形で「もらってくれる」と続き、受け取ってもらう意味に合う。", "もらわず": "打ち消しの連用形は「くれる」に続かない。", "もらいに": "目的を表す形は「くれる」に続かない。", "もらいたく": "希望の語幹は「くれる」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "与える", "is_correct": true, "explanation": "「人から受け取る」の対義で、「人に与える」を表す。"}, {"text": "拾う", "is_correct": false, "explanation": "拾うは落ちた物を取る行為で、貰うの対義語ではない。"}, {"text": "買う", "is_correct": false, "explanation": "買うは代金を払って得る行為で、貰うの対義語ではない。"}, {"text": "受け取る", "is_correct": false, "explanation": "受け取るは貰うの類義語で、対義語ではない。"}], "correct_answer": "与える", "explanations": {"与える": "「人から受け取る」の対義で、「人に与える」を表す。", "拾う": "拾うは落ちた物を取る行為で、貰うの対義語ではない。", "買う": "買うは代金を払って得る行為で、貰うの対義語ではない。", "受け取る": "受け取るは貰うの類義語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「もらうと」と条件を表し、後ろに続く文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「もらうを」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や相手を示すが、「もらうに」では続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「もらうへ」では続かない。"}], "correct_answer": "と", "explanations": {"と": "「もらうと」と条件を表し、後ろに続く文の意味に合う。", "を": "「を」は目的語を示すが、「もらうを」では文が成り立たない。", "に": "「に」は時点や相手を示すが、「もらうに」では続かない。", "へ": "「へ」は方向を示すが、「もらうへ」では続かない。"}, "error_tags": {"を": "目的語", "に": "時点・相手", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "与える", "is_correct": true, "explanation": "「人から受け取る」の対義で、「人に与える」を表す。"}, {"text": "盗む", "is_correct": false, "explanation": "盗むは無断で取る行為で、貰うの対義語ではない。"}, {"text": "預ける", "is_correct": false, "explanation": "預けるは一時的に託す行為で、貰うの対義語ではない。"}, {"text": "届ける", "is_correct": false, "explanation": "届けるは相手のもとへ運ぶ行為で、貰うの対義語ではない。"}], "correct_answer": "与える", "explanations": {"与える": "「人から受け取る」の対義で、「人に与える」を表す。", "盗む": "盗むは無断で取る行為で、貰うの対義語ではない。", "預ける": "預けるは一時的に託す行為で、貰うの対義語ではない。", "届ける": "届けるは相手のもとへ運ぶ行為で、貰うの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "他人から何かを与えられること。受け取る。", "primary_collocate": null, "pronunciation": "もらう", "ipa": "moɾaɯ", "syllable_count": 3, "sentences": [{"text": "先生から推薦状をもらうため、職員室へ行った。", "target_word": "もらう", "complexity_tier": "T3", "furigana": "先生[せんせい]から推薦状[すいせんじょう]をもらうため、職員室[しょくいんしつ]へ行[い]った。", "sentence_source": "generated"}, {"text": "誕生日に、祖母から新しい自転車をもらった。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、祖母[そぼ]から新[あたら]しい自転車[じてんしゃ]をもらった。", "sentence_source": "generated"}, {"text": "先輩に資料をもらって、会議の準備をした。", "target_word": "もらって", "complexity_tier": "T3", "furigana": "先輩[せんぱい]に資料[しりょう]をもらって、会議[かいぎ]の準備[じゅんび]をした。", "sentence_source": "generated"}, {"text": "隣の人からりんごをたくさんもらったので、ジャムを作った。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]からりんごをたくさんもらったので、ジャムを作[つく]った。", "sentence_source": "generated"}, {"text": "結果の連絡をもらったら、すぐに知らせます。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "結果[けっか]の連絡[れんらく]をもらったら、すぐに知[し]らせます。", "sentence_source": "generated"}, {"text": "店員から小さな袋をもらい、買った本を入れた。", "target_word": "もらい", "complexity_tier": "T3", "furigana": "店員[てんいん]から小[ちい]さな袋[ふくろ]をもらい、買[か]った本[ほん]を入[い]れた。", "sentence_source": "generated"}, {"text": "優勝してメダルをもらった選手が、涙を流した。", "target_word": "もらった", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]してメダルをもらった選手[せんしゅ]が、涙[なみだ]を流[なが]した。", "sentence_source": "generated"}, {"text": "お年玉をもらうと、弟はすぐに貯金箱に入れた。", "target_word": "もらう", "complexity_tier": "T3", "furigana": "お年玉[としだま]をもらうと、弟[おとうと]はすぐに貯金箱[ちょきんばこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "先生から励ましの言葉をもらって、やる気が出た。", "target_word": "もらって", "complexity_tier": "T3", "furigana": "先生[せんせい]から励[はげ]ましの言葉[ことば]をもらって、やる気[き]が出[で]た。", "sentence_source": "generated"}, {"text": "無料のサンプルをもらう人で、店の前に列ができている。", "target_word": "もらう", "complexity_tier": "T3", "furigana": "無料[むりょう]のサンプルをもらう人[ひと]で、店[みせ]の前[まえ]に列[れつ]ができている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貰う", "label": "基本形"}, {"form": "もらった", "label": "過去形"}, {"form": "もらわない", "label": "否定形"}, {"form": "もらって", "label": "て形"}, {"form": "もらえる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "他人から物や事柄を与えられて受け取る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a4780bf-a1a7-411d-9aed-2edc926c01bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "もらう", "is_correct": true, "explanation": "「もらうため」と基本形で続き、受け取る目的を表す。文の意味に合う。"}, {"text": "もらおう", "is_correct": false, "explanation": "意向形は「もらおうため」と続かず、文が成り立たない。"}, {"text": "もらえ", "is_correct": false, "explanation": "命令形や可能の語幹で、「もらえため」と続かない。"}, {"text": "もらって", "is_correct": false, "explanation": "て形は「もらってため」と名詞に続けられない。"}], "explanations": {"もらう": "「もらうため」と基本形で続き、受け取る目的を表す。文の意味に合う。", "もらおう": "意向形は「もらおうため」と続かず、文が成り立たない。", "もらえ": "命令形や可能の語幹で、「もらえため」と続かない。", "もらって": "て形は「もらってため」と名詞に続けられない。"}, "sentence_index": 0, "correct_answer": "もらう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "騒いでいた生徒から、先生はりんごを貰って没収した。", "explanation": "ここは〈取り上げる〉の意味。無理に取り上げるのは〈取り上げる〉で、相手から与えられる〈貰う〉とは合わない。"}, {"text": "来年、同じ村の人から借金を貰って、屋根を直すことにした。", "explanation": "ここは〈借りる〉の意味。返す必要のあるお金を借りるのは〈借りる〉で、無償で与えられる〈貰う〉とは合わない。"}, {"text": "お店でりんごを貰って、レジで代金を払った。", "explanation": "ここは〈買う〉の意味。代金を払うのは買う行為で、無償で与えられる〈貰う〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "もらった", "is_correct": true, "explanation": "「メダルをもらった選手」と関係節で選手を修飾する。文の意味に合う。"}, {"text": "もらいに", "is_correct": false, "explanation": "目的を表す形で、「選手が」に続く関係節にならない。"}, {"text": "もらわず", "is_correct": false, "explanation": "打ち消しの連用形で、「選手が」に続かない。"}, {"text": "もらいたく", "is_correct": false, "explanation": "希望の語幹で、名詞を修飾する関係節にならない。"}], "explanations": {"もらった": "「メダルをもらった選手」と関係節で選手を修飾する。文の意味に合う。", "もらいに": "目的を表す形で、「選手が」に続く関係節にならない。", "もらわず": "打ち消しの連用形で、「選手が」に続かない。", "もらいたく": "希望の語幹で、名詞を修飾する関係節にならない。"}, "sentence_index": 6, "correct_answer": "もらった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店員は無料のサンプルを貰い、客に一人ずつ代金を求めた。", "explanation": "ここは〈請求〉の意味。代金を客に求めるのは〈請求〉で、無償で受け取る〈貰う〉とは合わない。"}, {"text": "店は無料のサンプルを貰って、代金を受け取った。", "explanation": "ここは〈売る〉の意味。代金を受け取るのは売る行為で、無償で与えられる〈貰う〉とは合わない。"}, {"text": "店は無料のサンプルを貰い、仕入れ先に代金を払った。", "explanation": "ここは〈仕入れる〉の意味。代金を払って仕入れる行為で、無償で受け取る〈貰う〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母からお菓子をもらうて、お礼を言った。", "corrected_sentence": "祖母からお菓子をもらって、お礼を言った。", "error_description": "「もらって」のて形が「もらうて」になっている。正しくは「もらって」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "もらった", "is_correct": true, "explanation": "過去形で、誕生日の出来事を述べる文に合う。"}, {"text": "もらわず", "is_correct": false, "explanation": "打ち消しの連用形で、文末に立てず、文が成り立たない。"}, {"text": "もらって", "is_correct": false, "explanation": "て形は文末に立てないので、この文では成り立たない。"}, {"text": "もらいに", "is_correct": false, "explanation": "目的を表す形で、文末に立てず、文が成り立たない。"}], "correct_form": "もらった", "base_form": "貰う", "form_label": "過去形", "sentence_index": 1, "explanations": {"もらった": "過去形で、誕生日の出来事を述べる文に合う。", "もらわず": "打ち消しの連用形で、文末に立てず、文が成り立たない。", "もらって": "て形は文末に立てないので、この文では成り立たない。", "もらいに": "目的を表す形で、文末に立てず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生から賞状を貰わった生徒は、みんなの前で笑った。", "corrected_sentence": "先生から賞状を貰った生徒は、みんなの前で笑った。", "error_description": "「貰った」が「貰わった」になっている。「貰う」の過去形は「貰った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "もらう", "is_correct": true, "explanation": "基本形で、「と」を伴い「もらうと」と条件を表す。文の意味に合う。"}, {"text": "もらい", "is_correct": false, "explanation": "連用形は「もらいと」と条件の形にならない。"}, {"text": "もらわず", "is_correct": false, "explanation": "打ち消しの連用形は「もらわずと」と続かない。"}, {"text": "もらいたく", "is_correct": false, "explanation": "希望の語幹は「もらいたくと」と条件の形にならない。"}], "correct_form": "もらう", "base_form": "貰う", "form_label": "基本形", "sentence_index": 7, "explanations": {"もらう": "基本形で、「と」を伴い「もらうと」と条件を表す。文の意味に合う。", "もらい": "連用形は「もらいと」と条件の形にならない。", "もらわず": "打ち消しの連用形は「もらわずと」と続かない。", "もらいたく": "希望の語幹は「もらいたくと」と条件の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab9d4d68-b2f5-4857-ab9b-70cb92607cce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
