INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「参加する」は「〜に参加する」と場所や集まりに「に」を取るので、ここで正しい。"}, {"text": "を", "is_correct": false, "explanation": "「参加する」は目的語に「を」を取らないので、「儀式を参加させてもらった」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「儀式が」と主語にすると、「参加させてもらった」の対象として文がつながらない。"}, {"text": "の", "is_correct": false, "explanation": "「儀式の」と名詞をつなぐと、「参加させてもらった」が続く文の形にならない。"}], "correct_answer": "に", "explanations": {"に": "「参加する」は「〜に参加する」と場所や集まりに「に」を取るので、ここで正しい。", "を": "「参加する」は目的語に「を」を取らないので、「儀式を参加させてもらった」は成り立たない。", "が": "「儀式が」と主語にすると、「参加させてもらった」の対象として文がつながらない。", "の": "「儀式の」と名詞をつなぐと、「参加させてもらった」が続く文の形にならない。"}, "error_tags": {"を": "参加は目的語を取らない", "が": "主語では文が続かない", "の": "名詞をつなぐ形では文が成立しない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "決まったやり方で行う大切な行動のことです。", "primary_collocate": null, "pronunciation": "ぎしき", "ipa": "ɡiɕiki", "syllable_count": 3, "sentences": [{"text": "村では、毎年秋に感謝の儀式を行います。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "村[むら]では、毎年[まいとし]秋[あき]に感謝[かんしゃ]の儀式[ぎしき]を行[おこな]います。", "sentence_source": "generated"}, {"text": "結婚式は、二人が新しい生活を始めるための大切な儀式だ。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]は、二人[ふたり]が新[あたら]しい生活[せいかつ]を始[はじ]めるための大切[たいせつ]な儀式[ぎしき]だ。", "sentence_source": "generated"}, {"text": "その国には、子どもが十歳になると祝う古い儀式がある。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "その国[くに]には、子[こ]どもが十歳[じゅっさい]になると祝[いわ]う古[ふる]い儀式[ぎしき]がある。", "sentence_source": "generated"}, {"text": "儀式が始まると、会場は急に静かになった。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "儀式[ぎしき]が始[はじ]まると、会場[かいじょう]は急[きゅう]に静[しず]かになった。", "sentence_source": "generated"}, {"text": "神社で、新しい年の平和を祈る儀式が行われた。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "神社[じんじゃ]で、新[あたら]しい年[とし]の平和[へいわ]を祈[いの]る儀式[ぎしき]が行[おこな]われた。", "sentence_source": "generated"}, {"text": "王様が冠をかぶる儀式は、何百年も前から変わらない。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "王様[おうさま]が冠[かんむり]をかぶる儀式[ぎしき]は、何百年[なんびゃくねん]も前[まえ]から変[か]わらない。", "sentence_source": "generated"}, {"text": "儀式では、決まった順番で言葉を唱えなければならない。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "儀式[ぎしき]では、決[き]まった順番[じゅんばん]で言葉[ことば]を唱[とな]えなければならない。", "sentence_source": "generated"}, {"text": "外国から来た客も、地元の儀式に参加させてもらった。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た客[きゃく]も、地元[じもと]の儀式[ぎしき]に参加[さんか]させてもらった。", "sentence_source": "generated"}, {"text": "儀式に使う道具は、お寺の倉庫で大切に守られている。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "儀式[ぎしき]に使[つか]う道具[どうぐ]は、お寺[てら]の倉庫[そうこ]で大切[たいせつ]に守[まも]られている。", "sentence_source": "generated"}, {"text": "緊張しながら、私は儀式の最初のあいさつをした。", "target_word": "儀式", "complexity_tier": "T3", "furigana": "緊張[きんちょう]しながら、私[わたし]は儀式[ぎしき]の最初[さいしょ]のあいさつをした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀式", "label": "基本形"}], "register": "中立", "sense_fingerprint": "決まった作法と順序で行う、大切な式や行事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "儀式", "is_correct": true, "explanation": "感謝の気持ちを表す決まった式のことで、「感謝の儀式を行う」と自然につながる。"}, {"text": "予算", "is_correct": false, "explanation": "使えるお金の計画のことで、「感謝の予算を行う」とは言えない。"}, {"text": "信用", "is_correct": false, "explanation": "人を信じて任せる気持ちのことで、「感謝の信用を行う」とは言えない。"}, {"text": "希望", "is_correct": false, "explanation": "望む気持ちのことで、「感謝の希望を行う」とは言えない。"}], "explanations": {"儀式": "感謝の気持ちを表す決まった式のことで、「感謝の儀式を行う」と自然につながる。", "予算": "使えるお金の計画のことで、「感謝の予算を行う」とは言えない。", "信用": "人を信じて任せる気持ちのことで、「感謝の信用を行う」とは言えない。", "希望": "望む気持ちのことで、「感謝の希望を行う」とは言えない。"}, "sentence_index": 0, "correct_answer": "儀式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前の店で、儀式を一つ千円で買った。", "explanation": "ここは〈商品〉の意味。儀式は行う式で、品物として買えるものではないので合わない。"}, {"text": "週末、風邪の儀式にかかって寝込んだ。", "explanation": "ここは〈病気〉の意味。儀式は式を行うことで、病気にかかるものではないので合わない。"}, {"text": "来週、英語の儀式を受けることになった。", "explanation": "ここは〈試験〉の意味。儀式は式を行うことで、試験を受けるという使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "儀式", "is_correct": true, "explanation": "決まった順番で言葉を唱える式のことで、「儀式では」と場面を示す文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、決まった順番で言葉を唱える場面には合わない。"}, {"text": "利益", "is_correct": false, "explanation": "もうけのことで、「利益では、言葉を唱える」とは文がつながらない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さのことで、言葉を唱える場面を示す語としては成り立たない。"}], "explanations": {"儀式": "決まった順番で言葉を唱える式のことで、「儀式では」と場面を示す文に合う。", "天気": "空模様のことで、決まった順番で言葉を唱える場面には合わない。", "利益": "もうけのことで、「利益では、言葉を唱える」とは文がつながらない。", "体重": "体の重さのことで、言葉を唱える場面を示す語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "儀式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "午後は、倉庫の荷物を運ぶ儀式をした。", "explanation": "ここは〈作業〉の意味。儀式は決まった作法で行う式で、荷物を運ぶような実際の作業には使わない。"}, {"text": "朝、先生に会ったら、きちんと儀式をしよう。", "explanation": "ここは〈挨拶〉の意味。日常のあいさつに儀式という語は使わず、決まった式を行う場合に限られる。"}, {"text": "入学の儀式は、来月までに学校へ出してください。", "explanation": "ここは〈手続き〉の意味。書類を提出するという手続きの語で、儀式は提出するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年に一度、村の人たちが集まって大切な儀式が行う。", "corrected_sentence": "年に一度、村の人たちが集まって大切な儀式を行う。", "error_description": "「儀式」は「行う」の対象なので「を」が必要。「儀式が行う」は儀式を主語にしてしまい不自然。正しくは「儀式を行う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51541, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その寺では、毎月の儀式を欠かさず食べている。", "corrected_sentence": "その寺では、毎月の儀式を欠かさず行っている。", "error_description": "「儀式」と結びつく動詞は「行う」。「食べる」は儀式とは結びつかないので不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「日の出の空」の「の」で、日の出と空をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す助詞で、「日の出を空は」では成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や相手を示すが、「日の出に空は」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「日の出へ空は」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「日の出の空」の「の」で、日の出と空をつなぐ。", "を": "動作の対象を示す助詞で、「日の出を空は」では成り立たない。", "に": "帰着点や相手を示すが、「日の出に空は」とつながらない。", "へ": "方向を示すが、「日の出へ空は」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "朝、太陽が空に上がるときのことです。", "primary_collocate": null, "pronunciation": "ひので", "ipa": "çinode", "syllable_count": 3, "sentences": [{"text": "朝早く起きて、公園で日の出を見ました。", "target_word": "日の出", "complexity_tier": "T2", "furigana": "朝[あさ]早[はや]く起[お]きて、公園[こうえん]で日[ひ]の出[で]を見[み]ました。", "sentence_source": "generated"}, {"text": "日の出の空は、赤とオレンジ色でとてもきれいでした。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]の空[そら]は、赤[あか]とオレンジ色[いろ]でとてもきれいでした。", "sentence_source": "generated"}, {"text": "父は毎朝、日の出に合わせて犬の散歩に出かける。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "父[ちち]は毎朝[まいあさ]、日[ひ]の出[で]に合[あ]わせて犬[いぬ]の散歩[さんぽ]に出[で]かける。", "sentence_source": "generated"}, {"text": "天気予報のサイトで日の出の時刻を調べてから出かけた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "天気予報[てんきよほう]のサイトで日[ひ]の出[で]の時刻[じこく]を調[しら]べてから出[で]かけた。", "sentence_source": "generated"}, {"text": "冬の日の出は遅く、七時ごろにやっと空が明るくなる。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "冬[ふゆ]の日[ひ]の出[で]は遅[おそ]く、七時[しちじ]ごろにやっと空[そら]が明[あか]るくなる。", "sentence_source": "generated"}, {"text": "山の上のホテルから、日の出がよく見えると聞いて予約した。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]のホテルから、日[ひ]の出[で]がよく見[み]えると聞[き]いて予約[よやく]した。", "sentence_source": "generated"}, {"text": "日の出を見るために、まだ暗い午前四時に起きた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]を見[み]るために、まだ暗[くら]い午前[ごぜん]四時[よじ]に起[お]きた。", "sentence_source": "generated"}, {"text": "雲が多くて、今朝は日の出がはっきり見えなかった。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "雲[くも]が多[おお]くて、今朝[けさ]は日[ひ]の出[で]がはっきり見[み]えなかった。", "sentence_source": "generated"}, {"text": "日の出の少し前から、鳥たちが一斉に鳴きはじめた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]の少[すこ]し前[まえ]から、鳥[とり]たちが一斉[いっせい]に鳴[な]きはじめた。", "sentence_source": "generated"}, {"text": "旅行の最終日、私たちは船の上で日の出を迎えた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "旅行[りょこう]の最終日[さいしゅうび]、私[わたし]たちは船[ふね]の上[うえ]で日[ひ]の出[で]を迎[むか]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日の出", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "朝、太陽が空に上がってくるとき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日の出", "is_correct": true, "explanation": "「見る」の対象で、朝早く起きて見た太陽の昇りを表す。"}, {"text": "夜景", "is_correct": false, "explanation": "夜の景色を指し、朝早く起きて見たという文脈と合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方の空の色で、朝早くという文脈とは逆になる。"}, {"text": "星空", "is_correct": false, "explanation": "夜の空を指し、朝早くの出来事として合わない。"}], "explanations": {"日の出": "「見る」の対象で、朝早く起きて見た太陽の昇りを表す。", "夜景": "夜の景色を指し、朝早く起きて見たという文脈と合わない。", "夕焼け": "夕方の空の色で、朝早くという文脈とは逆になる。", "星空": "夜の空を指し、朝早くの出来事として合わない。"}, "sentence_index": 0, "correct_answer": "日の出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、西の空に日の出が沈んでいくのを眺めた。", "explanation": "ここは〈日の入り〉の意味。日の出は朝に太陽が昇る現象を指し、沈むことには使わない。"}, {"text": "窓辺で日の出を浴びながら、コーヒーを飲んだ。", "explanation": "ここは〈朝日〉の意味。日の出は太陽が昇るときを指し、光を浴びるという使い方はしない。"}, {"text": "真昼の日の出が肌をじりじりと焼いた。", "explanation": "ここは〈太陽〉の意味。日の出は朝に昇るときを指すので、真昼の強い日差しには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日の出", "is_correct": true, "explanation": "「見るために」の目的語で、早起きして見た太陽の昇りを表す。"}, {"text": "夕日", "is_correct": false, "explanation": "夕方の太陽で、午前四時に起きた理由として合わない。"}, {"text": "夕立", "is_correct": false, "explanation": "夕方の雨で、見るために起きる対象ではない。"}, {"text": "海鳴り", "is_correct": false, "explanation": "音を表す語で、見る対象にはならない。"}], "explanations": {"日の出": "「見るために」の目的語で、早起きして見た太陽の昇りを表す。", "夕日": "夕方の太陽で、午前四時に起きた理由として合わない。", "夕立": "夕方の雨で、見るために起きる対象ではない。", "海鳴り": "音を表す語で、見る対象にはならない。"}, "sentence_index": 6, "correct_answer": "日の出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日の出が明けるころ、空は白くなり始めた。", "explanation": "ここは〈夜明け〉の意味。「夜が明ける」とは言うが、日の出が明けるとは言わない。"}, {"text": "午後の部屋に日の出が差し込んで、蒸し暑くなった。", "explanation": "ここは〈西日〉の意味。日の出は朝の太陽の昇りを指し、午後の日差しには使わない。"}, {"text": "日の出が深まり、部屋の明かりを点けた。", "explanation": "ここは〈夕暮れ〉の意味。日の出は深まっていくものではなく、夕方の時間帯には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちと日の出を合わせて海へ行く約束をした。", "corrected_sentence": "友だちと日の出に合わせて海へ行く約束をした。", "error_description": "「合わせる」は「〜に合わせる」と言うので、「日の出を」は誤り（正しくは「日の出に」）。誤りは日の出に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の寒い朝、私たちは日の出を聞くために駅まで歩いた。", "corrected_sentence": "冬の寒い朝、私たちは日の出を見るために駅まで歩いた。", "error_description": "「日の出」は見るもので、「聞く」とは合わない。誤りは日の出に付く動詞で、正しくは「見る」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「待つ」の対象を示す助詞で、「日の出を待つ」となり正しい。"}, {"text": "で", "is_correct": false, "explanation": "場所を示す助詞で、「山頂で」のように場所に使う。待つ対象には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「待つ」は対象に「に」を取らないので、「日の出に待つ」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、待つ対象には使えない。「日の出へ待つ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「待つ」の対象を示す助詞で、「日の出を待つ」となり正しい。", "で": "場所を示す助詞で、「山頂で」のように場所に使う。待つ対象には使えない。", "に": "「待つ」は対象に「に」を取らないので、「日の出に待つ」は成り立たない。", "へ": "方向を示す助詞で、待つ対象には使えない。「日の出へ待つ」は不自然。"}, "error_tags": {"で": "場所・手段", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「日の出の時刻」の「の」で、日の出と時刻をつなぐ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞だが、「日の出が時刻は」のように名詞を続ける位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「日の出より時刻」は成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「日の出から時刻は」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「日の出の時刻」の「の」で、日の出と時刻をつなぐ。", "が": "主語を示す助詞だが、「日の出が時刻は」のように名詞を続ける位置には入らない。", "より": "比較の助詞で、「日の出より時刻」は成り立たない。", "から": "起点を示す助詞で、「日の出から時刻は」は意味が通らない。"}, "error_tags": {"が": "主語", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "太陽が地平線から昇る現象やその時刻を指す言葉。", "primary_collocate": null, "pronunciation": "ひので", "ipa": "çinode", "syllable_count": 3, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "日の出", "complexity_tier": "T4", "furigana": "日[ひ]の出[で]と共[とも]に目覚[めざ]める鶏[にわとり]の健康[けんこう]こそが、栄養[えいよう]豊富[ほうふ]な卵[たまご]を産[う]んでもらうための条件[じょうけん]だからである。", "sentence_source": "mined"}, {"text": "山頂で日の出を待っていると、空が少しずつ明るくなってきた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "山頂[さんちょう]で日[ひ]の出[で]を待[ま]っていると、空[そら]が少[すこ]しずつ明[あか]るくなってきた。", "sentence_source": "generated"}, {"text": "夏は日の出が早いので、朝五時にはもう外が明るい。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "夏[なつ]は日[ひ]の出[で]が早[はや]いので、朝[あさ]五時[ごじ]にはもう外[そと]が明[あか]るい。", "sentence_source": "generated"}, {"text": "明日の日の出は午前六時ごろなので、五時に家を出ましょう。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "明日[あした]の日[ひ]の出[で]は午前[ごぜん]六時[ろくじ]ごろなので、五時[ごじ]に家[いえ]を出[で]ましょう。", "sentence_source": "generated"}, {"text": "日の出の前は空が暗く、まだ星が見えていた。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]の前[まえ]は空[そら]が暗[くら]く、まだ星[ほし]が見[み]えていた。", "sentence_source": "generated"}, {"text": "冬は日の出が遅いから、朝の散歩は少し暖かくなってからにしている。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "冬[ふゆ]は日[ひ]の出[で]が遅[おそ]いから、朝[あさ]の散歩[さんぽ]は少[すこ]し暖[あたた]かくなってからにしている。", "sentence_source": "generated"}, {"text": "漁師たちは日の出とともに船を出し、夕方まで海で働く。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "漁師[りょうし]たちは日[ひ]の出[で]とともに船[ふね]を出[だ]し、夕方[ゆうがた]まで海[うみ]で働[はたら]く。", "sentence_source": "generated"}, {"text": "日の出の時刻は、地域や季節によって数分から数十分ずつ違う。", "target_word": "日の出", "complexity_tier": "T4", "furigana": "日[ひ]の出[で]の時刻[じこく]は、地域[ちいき]や季節[きせつ]によって数分[すうふん]から数十分[すうじゅっぷん]ずつ違[ちが]う。", "sentence_source": "generated"}, {"text": "窓から日の出の光が差しこんで、部屋が金色に染まった。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "窓[まど]から日[ひ]の出[で]の光[ひかり]が差[さ]しこんで、部屋[へや]が金色[きんいろ]に染[そ]まった。", "sentence_source": "generated"}, {"text": "日の出を見ながら飲んだ温かいお茶の味は、今でも忘れられない。", "target_word": "日の出", "complexity_tier": "T3", "furigana": "日[ひ]の出[で]を見[み]ながら飲[の]んだ温[あたた]かいお茶[ちゃ]の味[あじ]は、今[いま]でも忘[わす]れられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "日の出", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "朝、太陽が地平線から昇る現象、またはその時刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日の出", "is_correct": true, "explanation": "朝に太陽が昇る時刻を表し、鶏が目覚める条件として文脈に合う。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕方に空が赤く染まる現象で、目覚める時刻とは合わない。"}, {"text": "星空", "is_correct": false, "explanation": "夜の空を指すので、朝に目覚める条件として意味が通らない。"}, {"text": "日の入り", "is_correct": false, "explanation": "太陽が沈む時刻で、朝に目覚める文脈と逆になる。"}], "explanations": {"日の出": "朝に太陽が昇る時刻を表し、鶏が目覚める条件として文脈に合う。", "夕焼け": "夕方に空が赤く染まる現象で、目覚める時刻とは合わない。", "星空": "夜の空を指すので、朝に目覚める条件として意味が通らない。", "日の入り": "太陽が沈む時刻で、朝に目覚める文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "日の出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕方、海の向こうへ日の出がゆっくり沈んでいった。", "explanation": "ここは〈日の入り〉の意味。日の出は太陽が昇る現象や時刻を指すので、沈んでいくことには使わない。"}, {"text": "毎朝、日の出を浴びると気持ちが切り替わる。", "explanation": "ここは〈朝日〉の意味。日の出は太陽が昇る時刻を指し、光そのものを浴びるとは言わない。"}, {"text": "真夏の日の出がじりじりと照りつけて、息が苦しい。", "explanation": "ここは〈太陽〉の意味。日の出は朝に昇る時刻を指すので、昼の強い日差しには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日の出", "is_correct": true, "explanation": "漁師が船を出す朝の時刻を表し、文脈に合う。"}, {"text": "夕暮れ", "is_correct": false, "explanation": "夕方の時間帯で、朝に船を出す文脈と合わない。"}, {"text": "月明かり", "is_correct": false, "explanation": "夜の月の光を指し、朝に船を出す時刻を表さない。"}, {"text": "嵐", "is_correct": false, "explanation": "荒天を指し、船を出す時刻を表す語ではない。"}], "explanations": {"日の出": "漁師が船を出す朝の時刻を表し、文脈に合う。", "夕暮れ": "夕方の時間帯で、朝に船を出す文脈と合わない。", "月明かり": "夜の月の光を指し、朝に船を出す時刻を表さない。", "嵐": "荒天を指し、船を出す時刻を表す語ではない。"}, "sentence_index": 6, "correct_answer": "日の出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日の出が明けると、港が少しずつ騒がしくなる。", "explanation": "ここは〈夜明け〉の意味。「夜が明ける」とは言うが、日の出が明けるとは言わない。"}, {"text": "午後の窓から、日の出が差して部屋が蒸し暑くなった。", "explanation": "ここは〈西日〉の意味。日の出は朝に昇る時刻を指し、午後の日差しには使わない。"}, {"text": "日の出が深まって、虫の声が聞こえてきた。", "explanation": "ここは〈夕暮れ〉の意味。夕暮れは時間が深まっていくが、日の出は朝に太陽が昇る時刻を指すので、深まるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏は日の出を早いので、朝四時半にはもう空が白みはじめる。", "corrected_sentence": "夏は日の出が早いので、朝四時半にはもう空が白みはじめる。", "error_description": "「早い」の主語には「日の出が」と「が」を使う。「を」にすると「日の出を早い」となり文が成り立たない。誤りは日の出に付く助詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の朝、私たちは海辺で日の出を出迎えた。", "corrected_sentence": "夏の朝、私たちは海辺で日の出を迎えた。", "error_description": "「出迎える」は人を迎える語で、日の出には使わない。正しくは「迎える」。誤りは日の出に付く動詞。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
