INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51545, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ねむっているときから、めをあけておきること。", "primary_collocate": null, "pronunciation": "めざめる", "ipa": "mezameɾɯ", "syllable_count": 4, "sentences": [{"text": "雨の音で目覚めた。", "target_word": "目覚めた", "complexity_tier": "T2", "furigana": "雨[あめ]の音[おと]で目覚[めざ]めた。", "sentence_source": "generated"}, {"text": "夜中にのどがかわいて、目覚めてしまった。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "夜中[よなか]にのどがかわいて、目覚[めざ]めてしまった。", "sentence_source": "generated"}, {"text": "弟はまだ目覚めていないので、そっとしておこう。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "弟[おとうと]はまだ目覚[めざ]めていないので、そっとしておこう。", "sentence_source": "generated"}, {"text": "電車の中で眠っていたが、駅に着く直前に目覚めた。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で眠[ねむ]っていたが、駅[えき]に着[つ]く直前[ちょくぜん]に目覚[めざ]めた。", "sentence_source": "generated"}, {"text": "目覚めると、部屋の中はもう明るかった。", "target_word": "目覚める", "complexity_tier": "T3", "furigana": "目覚[めざ]めると、部屋[へや]の中[なか]はもう明[あか]るかった。", "sentence_source": "generated"}, {"text": "子どもは、母の声に目覚めて、すぐに起き上がった。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "子[こ]どもは、母[はは]の声[こえ]に目覚[めざ]めて、すぐに起[お]き上[あ]がった。", "sentence_source": "generated"}, {"text": "昨夜は早く寝たので、朝五時に自然に目覚めた。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "昨夜[さくや]は早[はや]く寝[ね]たので、朝[あさ]五時[ごじ]に自然[しぜん]に目覚[めざ]めた。", "sentence_source": "generated"}, {"text": "犬は物音に目覚めて、玄関のほうへ走っていった。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "犬[いぬ]は物音[ものおと]に目覚[めざ]めて、玄関[げんかん]のほうへ走[はし]っていった。", "sentence_source": "generated"}, {"text": "手術のあと、祖父は夕方にやっと目覚めた。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]のあと、祖父[そふ]は夕方[ゆうがた]にやっと目覚[めざ]めた。", "sentence_source": "generated"}, {"text": "目覚めたら、知らない部屋にいて、とても驚いた。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "目覚[めざ]めたら、知[し]らない部屋[へや]にいて、とても驚[おどろ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目覚める", "label": "辞書形"}, {"form": "目覚めます", "label": "ます形"}, {"form": "目覚めて", "label": "て形"}, {"form": "目覚めた", "label": "た形"}, {"form": "目覚めない", "label": "ない形"}], "register": "標準(中立)", "sense_fingerprint": "眠りから覚めて目を開け、起きること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目覚めた", "is_correct": true, "explanation": "雨の音で眠りから覚めたという意味で、この空所に入る。"}, {"text": "濡れた", "is_correct": false, "explanation": "雨に当たる意味で、雨の音で目が覚める文脈には合わないので合わない。"}, {"text": "笑った", "is_correct": false, "explanation": "笑う動作で、雨の音との因果が成り立たないので合わない。"}, {"text": "読んだ", "is_correct": false, "explanation": "本を読む意味で、雨の音で目が覚める文脈と結びつかないので合わない。"}], "explanations": {"目覚めた": "雨の音で眠りから覚めたという意味で、この空所に入る。", "濡れた": "雨に当たる意味で、雨の音で目が覚める文脈には合わないので合わない。", "笑った": "笑う動作で、雨の音との因果が成り立たないので合わない。", "読んだ": "本を読む意味で、雨の音で目が覚める文脈と結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "目覚めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は宿題を目覚めて、夕方までに終わらせた。", "explanation": "ここは〈片付ける〉の意味。目覚めるは眠りから覚める意味で、宿題には使わないので合わない。"}, {"text": "父は車を目覚めて、駐車場まで運んだ。", "explanation": "ここは〈動かす〉の意味。目覚めるは人や動物が眠りから覚める意味で、車を動かす意味にはならないので合わない。"}, {"text": "母は弟を目覚めて、朝ごはんを用意した。", "explanation": "ここは〈起こす〉の意味。目覚めるは自分が覚める意味で、他人を起こす意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目覚めた", "is_correct": true, "explanation": "朝五時に自然に眠りから覚めたという意味で、この空所に入る。"}, {"text": "叫んだ", "is_correct": false, "explanation": "大声を出す意味で、自然に目が覚める文脈には合わないので合わない。"}, {"text": "歩いた", "is_correct": false, "explanation": "移動の意味で、朝の目覚めの説明にならないので合わない。"}, {"text": "怒鳴った", "is_correct": false, "explanation": "大声で叱る意味で、自然な目覚めとは結びつかないので合わない。"}], "explanations": {"目覚めた": "朝五時に自然に眠りから覚めたという意味で、この空所に入る。", "叫んだ": "大声を出す意味で、自然に目が覚める文脈には合わないので合わない。", "歩いた": "移動の意味で、朝の目覚めの説明にならないので合わない。", "怒鳴った": "大声で叱る意味で、自然な目覚めとは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "目覚めた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話が目覚めて、大きな声で鳴った。", "explanation": "ここは〈着信する〉の意味。目覚めるは眠りから覚める意味で、電話の着信には使わないので合わない。"}, {"text": "信号が目覚めて、車が止まった。", "explanation": "ここは〈切り替わる〉の意味。目覚めるは生き物の起床を指し、信号の切り替えには使わないので合わない。"}, {"text": "絵の具が目覚めて、鮮やかな色を出した。", "explanation": "ここは〈発色する〉の意味。目覚めるは眠りから覚める意味で、絵の具の発色には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は五時に目覚めに、すぐに台所へ向かった。", "corrected_sentence": "祖母は五時に目覚めて、すぐに台所へ向かった。", "error_description": "正しくは「目覚めて」。動作を続けて述べる「〜て」が必要で、「目覚めに」は接続の形として誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "目覚めて", "is_correct": true, "explanation": "て形で、「のどがかわいて、目覚めてしまった」と続ける形として正しい。"}, {"text": "目覚めない", "is_correct": false, "explanation": "否定形で、実際に目が覚めた結果を述べる文の意味と逆になるので合わない。"}, {"text": "目覚めます", "is_correct": false, "explanation": "丁寧形で、普通体の文の流れと合わないので合わない。"}, {"text": "目覚めた", "is_correct": false, "explanation": "過去形で、「〜て、〜てしまった」という接続に合わないので合わない。"}], "correct_form": "目覚めて", "base_form": "目覚める", "form_label": "て形", "sentence_index": 1, "explanations": {"目覚めて": "て形で、「のどがかわいて、目覚めてしまった」と続ける形として正しい。", "目覚めない": "否定形で、実際に目が覚めた結果を述べる文の意味と逆になるので合わない。", "目覚めます": "丁寧形で、普通体の文の流れと合わないので合わない。", "目覚めた": "過去形で、「〜て、〜てしまった」という接続に合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は昨夜ずっと目覚めた。", "corrected_sentence": "彼女は昨夜ずっと目覚めていた。", "error_description": "正しくは「目覚めていた」。「ずっと」は継続を表すので、「目覚めた」の一度の動作では意味が合わない（アスペクトの誤り）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "目覚めて", "is_correct": true, "explanation": "て形で、後ろの「走っていった」へ続く形として正しい。"}, {"text": "目覚めよう", "is_correct": false, "explanation": "意志を表す形で、物音で実際に起きて走っていった事実と合わないので合わない。"}, {"text": "目覚めろ", "is_correct": false, "explanation": "命令形で、語りの過去の出来事を述べる文には合わないので合わない。"}, {"text": "目覚めません", "is_correct": false, "explanation": "丁寧な否定形で、普通体の語りと合わず、物音で起きた事実とも逆になるので合わない。"}], "correct_form": "目覚めて", "base_form": "目覚める", "form_label": "て形", "sentence_index": 7, "explanations": {"目覚めて": "て形で、後ろの「走っていった」へ続く形として正しい。", "目覚めよう": "意志を表す形で、物音で実際に起きて走っていった事実と合わないので合わない。", "目覚めろ": "命令形で、語りの過去の出来事を述べる文には合わないので合わない。", "目覚めません": "丁寧な否定形で、普通体の語りと合わず、物音で起きた事実とも逆になるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "眠っている状態から覚めて、意識がはっきりすること。活動を始めること。", "primary_collocate": null, "pronunciation": "めざめる", "ipa": "mezameɾɯ", "syllable_count": 4, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "目覚める", "complexity_tier": "T4", "furigana": "日[ひ]の出[で]と共[とも]に目覚[めざ]める鶏[にわとり]の健康[けんこう]こそが、栄養[えいよう]豊富[ほうふ]な卵[たまご]を産[う]んでもらうための条件[じょうけん]だからである。", "sentence_source": "mined"}, {"text": "春になると、冬眠していたクマが目覚めて、餌を探しに出かける。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "春[はる]になると、冬眠[とうみん]していたクマが目覚[めざ]めて、餌[えさ]を探[さが]しに出[で]かける。", "sentence_source": "generated"}, {"text": "夜中に大きな音がして、驚いて目覚めてしまった。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "夜中[よなか]に大[おお]きな音[おと]がして、驚[おどろ]いて目覚[めざ]めてしまった。", "sentence_source": "generated"}, {"text": "赤ちゃんは、お腹がすくと目覚めて泣き出す。", "target_word": "目覚めて", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは、お腹[なか]がすくと目覚[めざ]めて泣[な]き出[だ]す。", "sentence_source": "generated"}, {"text": "彼は病院のベッドで三日ぶりに目覚めた。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "彼[かれ]は病院[びょういん]のベッドで三日[みっか]ぶりに目覚[めざ]めた。", "sentence_source": "generated"}, {"text": "朝、鳥の声で目覚めると、窓から明るい光が入っていた。", "target_word": "目覚める", "complexity_tier": "T3", "furigana": "朝[あさ]、鳥[とり]の声[こえ]で目覚[めざ]めると、窓[まど]から明[あか]るい光[ひかり]が入[はい]っていた。", "sentence_source": "generated"}, {"text": "旅行の翌日は疲れていたので、昼まで目覚めなかった。", "target_word": "目覚めなかった", "complexity_tier": "T3", "furigana": "旅行[りょこう]の翌日[よくじつ]は疲[つか]れていたので、昼[ひる]まで目覚[めざ]めなかった。", "sentence_source": "generated"}, {"text": "静かな村も、市場が開く時間になると目覚める。", "target_word": "目覚める", "complexity_tier": "T3", "furigana": "静[しず]かな村[むら]も、市場[いちば]が開[ひら]く時間[じかん]になると目覚[めざ]める。", "sentence_source": "generated"}, {"text": "山小屋の朝は早く、客は日の出前に目覚める。", "target_word": "目覚める", "complexity_tier": "T3", "furigana": "山小屋[やまごや]の朝[あさ]は早[はや]く、客[きゃく]は日[ひ]の出[で]前[まえ]に目覚[めざ]める。", "sentence_source": "generated"}, {"text": "目覚めたばかりのときは、頭がぼんやりして何も考えられない。", "target_word": "目覚めた", "complexity_tier": "T3", "furigana": "目覚[めざ]めたばかりのときは、頭[あたま]がぼんやりして何[なに]も考[かんが]えられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目覚める", "label": "辞書形"}, {"form": "目覚めます", "label": "ます形"}, {"form": "目覚めて", "label": "て形"}, {"form": "目覚めた", "label": "た形"}, {"form": "目覚めない", "label": "ない形"}], "register": "標準(中立)", "sense_fingerprint": "眠りから覚めて意識がはっきりする。転じて、町や自然が活動を始める。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f6b1235-7c2d-4e61-9691-9f3fcb3a9405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目覚める", "is_correct": true, "explanation": "朝の日の出とともに鶏が眠りから覚める様子を表し、この空所に入る。"}, {"text": "寝込む", "is_correct": false, "explanation": "病気などで床につく意味で、日の出とともに鶏が活動する文脈には合わないので合わない。"}, {"text": "気付く", "is_correct": false, "explanation": "何かに気がつく意味で、鶏の起床を説明する文脈には合わないので合わない。"}, {"text": "疲れる", "is_correct": false, "explanation": "疲労の意味で、日の出の時刻と結びつかないので合わない。"}], "explanations": {"目覚める": "朝の日の出とともに鶏が眠りから覚める様子を表し、この空所に入る。", "寝込む": "病気などで床につく意味で、日の出とともに鶏が活動する文脈には合わないので合わない。", "気付く": "何かに気がつく意味で、鶏の起床を説明する文脈には合わないので合わない。", "疲れる": "疲労の意味で、日の出の時刻と結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "目覚める"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は医者を目覚めて、毎日勉強している。", "explanation": "ここは〈目指す〉の意味。目覚めるは眠りから覚める意味で、将来の目標には使わないので合わない。"}, {"text": "母は新しい料理を目覚めて、ゆっくり味わった。", "explanation": "ここは〈作り出す〉の意味。目覚めるは眠りから覚める意味で、料理を作り出す意味にはならないので合わない。"}, {"text": "彼は約束を目覚めて、遅刻した。", "explanation": "ここは〈忘れる〉の意味。目覚めるは約束の記憶を指さないので、ここには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目覚めなかった", "is_correct": true, "explanation": "否定の過去形で、昼まで眠り続けていたという文脈に合う。"}, {"text": "目覚めた", "is_correct": false, "explanation": "肯定の過去形で、疲れて昼まで寝ていた文脈と逆になるので合わない。"}, {"text": "目覚めて", "is_correct": false, "explanation": "て形で文が終わらず、ここでは述語にならないので合わない。"}, {"text": "目覚めさせなかった", "is_correct": false, "explanation": "他人を目覚めさせる意味になり、自分が起きなかった文脈には合わないので合わない。"}], "explanations": {"目覚めなかった": "否定の過去形で、昼まで眠り続けていたという文脈に合う。", "目覚めた": "肯定の過去形で、疲れて昼まで寝ていた文脈と逆になるので合わない。", "目覚めて": "て形で文が終わらず、ここでは述語にならないので合わない。", "目覚めさせなかった": "他人を目覚めさせる意味になり、自分が起きなかった文脈には合わないので合わない。"}, "sentence_index": 6, "correct_answer": "目覚めなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボールが目覚めて、ゴールに転がった。", "explanation": "ここは〈動き出す〉の意味。目覚めるは人や動物が眠りから覚める意味で、ボールが動き出す意味には使わないので合わない。"}, {"text": "シャッターが目覚めて、お客を迎えた。", "explanation": "ここは〈開く〉の意味。目覚めるは生き物が眠りから覚めることで、シャッターの開閉には使わないので合わない。"}, {"text": "母は子どもを目覚めて、学校へ送り出した。", "explanation": "ここは〈起こす〉の意味。目覚めるは自分が覚める自動詞で、他人を起こす意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は毎朝六時に目覚めるて、すぐに窓を開ける。", "corrected_sentence": "彼女は毎朝六時に目覚めて、すぐに窓を開ける。", "error_description": "正しくは「目覚めて」。動詞「目覚める」の て形は「目覚めて」で、「目覚めるて」は活用形の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "目覚めて", "is_correct": true, "explanation": "て形で、後ろの「餌を探しに出かける」へ続く形として正しい。"}, {"text": "目覚めない", "is_correct": false, "explanation": "否定形で、覚めて動き出すという文の意味と逆になるので合わない。"}, {"text": "目覚めます", "is_correct": false, "explanation": "丁寧形で、普通体で書かれた文の流れと合わないので合わない。"}, {"text": "目覚めた", "is_correct": false, "explanation": "過去形で、「目覚めた、餌を探しに」と続けられないので合わない。"}], "correct_form": "目覚めて", "base_form": "目覚める", "form_label": "て形", "sentence_index": 1, "explanations": {"目覚めて": "て形で、後ろの「餌を探しに出かける」へ続く形として正しい。", "目覚めない": "否定形で、覚めて動き出すという文の意味と逆になるので合わない。", "目覚めます": "丁寧形で、普通体で書かれた文の流れと合わないので合わない。", "目覚めた": "過去形で、「目覚めた、餌を探しに」と続けられないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51546, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は毎朝五時を目覚めて、庭の花に水をやる。", "corrected_sentence": "祖母は毎朝五時に目覚めて、庭の花に水をやる。", "error_description": "正しくは「五時に目覚めて」。目覚める時点を表す「に」が必要で、「五時を目覚めて」は格助詞の誤り（目覚めるは「〜を」を取らない）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "目覚めよう", "is_correct": false, "explanation": "意志を表す形で、「〜になると」という習慣の文脈には合わないので合わない。"}, {"text": "目覚めない", "is_correct": false, "explanation": "否定形で、市場が開く時間に村が活動を始めるという習慣の文と逆になるので合わない。"}, {"text": "目覚めろ", "is_correct": false, "explanation": "命令形で、村の様子を述べる文の流れには合わないので合わない。"}, {"text": "目覚める", "is_correct": true, "explanation": "辞書形で、「〜になると目覚める」という習慣の文脈で正しい。"}], "correct_form": "目覚める", "base_form": "目覚める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"目覚めよう": "意志を表す形で、「〜になると」という習慣の文脈には合わないので合わない。", "目覚めない": "否定形で、市場が開く時間に村が活動を始めるという習慣の文と逆になるので合わない。", "目覚めろ": "命令形で、村の様子を述べる文の流れには合わないので合わない。", "目覚める": "辞書形で、「〜になると目覚める」という習慣の文脈で正しい。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25737dca-c8b0-466c-9dc6-412a3b29aa59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「卒業の日」と名詞を修飾する「の」で、卒業が日を説明する形になる。"}, {"text": "が", "is_correct": false, "explanation": "「卒業が日に」では卒業が主語になるが、続く「日に」と結びつかず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「卒業を日に」は目的語を示すが、「日」を目的語にとる動詞がなく成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「卒業へ日に」は方向を示すが、卒業は行き先にならないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「卒業の日」と名詞を修飾する「の」で、卒業が日を説明する形になる。", "が": "「卒業が日に」では卒業が主語になるが、続く「日に」と結びつかず不自然。", "を": "「卒業を日に」は目的語を示すが、「日」を目的語にとる動詞がなく成立しない。", "へ": "「卒業へ日に」は方向を示すが、卒業は行き先にならないので合わない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "へ": "方向を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "学校の課程に入ることで、課程を終えて出る卒業と対になる。"}, {"text": "入院", "is_correct": false, "explanation": "病院に入ることを表し、卒業と対になる関係ではない。"}, {"text": "採用", "is_correct": false, "explanation": "人を雇い入れる意味で、学校の課程を終える卒業とは対にならない。"}, {"text": "出版", "is_correct": false, "explanation": "本を世に出す意味で、卒業の対義語にはならない。"}], "correct_answer": "入学", "explanations": {"入学": "学校の課程に入ることで、課程を終えて出る卒業と対になる。", "入院": "病院に入ることを表し、卒業と対になる関係ではない。", "採用": "人を雇い入れる意味で、学校の課程を終える卒業とは対にならない。", "出版": "本を世に出す意味で、卒業の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "学校の課程に入ることで、課程を終えて出る卒業と対になる。"}, {"text": "開業", "is_correct": false, "explanation": "店や事業を始める意味で、卒業と対になる関係ではない。"}, {"text": "入隊", "is_correct": false, "explanation": "軍隊や組織に入る意味で、卒業の対義語にはならない。"}, {"text": "就任", "is_correct": false, "explanation": "役職に就く意味で、学校の課程を終える卒業とは対にならない。"}], "correct_answer": "入学", "explanations": {"入学": "学校の課程に入ることで、課程を終えて出る卒業と対になる。", "開業": "店や事業を始める意味で、卒業と対になる関係ではない。", "入隊": "軍隊や組織に入る意味で、卒業の対義語にはならない。", "就任": "役職に就く意味で、学校の課程を終える卒業とは対にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "学校を全部終わって、出ること。", "primary_collocate": null, "pronunciation": "そつぎょう", "ipa": "sotsɯɡʲoː", "syllable_count": 4, "sentences": [{"text": "姉は去年、大学を卒業して、小さな出版社に入りました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "姉[あね]は去年[きょねん]、大学[だいがく]を卒業[そつぎょう]して、小[ちい]さな出版社[しゅっぱんしゃ]に入[はい]りました。", "sentence_source": "generated"}, {"text": "卒業の日に、先生が一人ひとりに手紙をくれました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]の日[ひ]に、先生[せんせい]が一人[ひとり]ひとりに手紙[てがみ]をくれました。", "sentence_source": "generated"}, {"text": "中学校を卒業したら、私は遠くの高校に通うつもりです。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "中学校[ちゅうがっこう]を卒業[そつぎょう]したら、私[わたし]は遠[とお]くの高校[こうこう]に通[かよ]うつもりです。", "sentence_source": "generated"}, {"text": "兄は単位が足りなくて、予定の春に卒業できませんでした。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "兄[あに]は単位[たんい]が足[た]りなくて、予定[よてい]の春[はる]に卒業[そつぎょう]できませんでした。", "sentence_source": "generated"}, {"text": "卒業した小学校の前を通ると、なつかしい気持ちになります。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]した小学校[しょうがっこう]の前[まえ]を通[とお]ると、なつかしい気持[きも]ちになります。", "sentence_source": "generated"}, {"text": "祖父は戦争のため、小学校を卒業しないで働き始めました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争[せんそう]のため、小学校[しょうがっこう]を卒業[そつぎょう]しないで働[はたら]き始[はじ]めました。", "sentence_source": "generated"}, {"text": "三年間いっしょだった友だちと、卒業のあとも連絡を取り合っています。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "三年間[さんねんかん]いっしょだった友[とも]だちと、卒業[そつぎょう]のあとも連絡[れんらく]を取[と]り合[あ]っています。", "sentence_source": "generated"}, {"text": "彼女は大学を卒業するまで、毎日図書館で勉強しました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]を卒業[そつぎょう]するまで、毎日[まいにち]図書館[としょかん]で勉強[べんきょう]しました。", "sentence_source": "generated"}, {"text": "母は看護学校を卒業して、すぐに病院で働きました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "母[はは]は看護[かんご]学校[がっこう]を卒業[そつぎょう]して、すぐに病院[びょういん]で働[はたら]きました。", "sentence_source": "generated"}, {"text": "卒業が近づくと、教室の黒板に寄せ書きが増えていきました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]が近[ちか]づくと、教室[きょうしつ]の黒板[こくばん]に寄[よ]せ書[が]きが増[ふ]えていきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "卒業", "label": "基本形"}, {"form": "卒業する", "label": "辞書形"}, {"form": "卒業した", "label": "過去形"}, {"form": "卒業して", "label": "て形"}], "register": "中立", "sense_fingerprint": "学校の全課程を終えてその学校を出ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 寄せ書き (Zipf 2.49)']::text[], 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卒業", "is_correct": true, "explanation": "学校の全課程を終えて出る意味で、「大学を卒業して、出版社に入った」と流れが合う。"}, {"text": "採用", "is_correct": false, "explanation": "「大学を採用して」は人や物を選び入れる意味で、大学を目的語にすると成立しない。"}, {"text": "配達", "is_correct": false, "explanation": "「大学を配達して」は物を届ける動作で、大学は届ける対象にならず意味が通らない。"}, {"text": "注射", "is_correct": false, "explanation": "「大学を注射して」は医療行為を表し、大学を目的語にすると文が成り立たない。"}], "explanations": {"卒業": "学校の全課程を終えて出る意味で、「大学を卒業して、出版社に入った」と流れが合う。", "採用": "「大学を採用して」は人や物を選び入れる意味で、大学を目的語にすると成立しない。", "配達": "「大学を配達して」は物を届ける動作で、大学は届ける対象にならず意味が通らない。", "注射": "「大学を注射して」は医療行為を表し、大学を目的語にすると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "卒業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工事は予定どおり、夏までに卒業しました。", "explanation": "ここは〈完成〉の意味。卒業は学校の全課程を終えて出ることを指し、工事が終わる意味では使わない。"}, {"text": "試合は三時間で卒業しました。", "explanation": "ここは〈終了〉の意味。卒業は学校を出ることを指し、試合が終わる意味には使わない。"}, {"text": "手続きは昨日、すべて卒業しました。", "explanation": "ここは〈完了〉の意味。卒業は学校の課程を修めて出ることで、事務手続きの完了には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卒業", "is_correct": true, "explanation": "学校を終えて出た後も連絡を続けるという文脈に合う。"}, {"text": "出版", "is_correct": false, "explanation": "「出版のあと」では友だちとの連絡の時期にならず、文脈が合わない。"}, {"text": "散髪", "is_correct": false, "explanation": "「散髪のあと」は連絡を続ける時期として意味が通らない。"}, {"text": "献血", "is_correct": false, "explanation": "「献血のあと」は連絡を続ける時期として文脈に合わない。"}], "explanations": {"卒業": "学校を終えて出た後も連絡を続けるという文脈に合う。", "出版": "「出版のあと」では友だちとの連絡の時期にならず、文脈が合わない。", "散髪": "「散髪のあと」は連絡を続ける時期として意味が通らない。", "献血": "「献血のあと」は連絡を続ける時期として文脈に合わない。"}, "sentence_index": 6, "correct_answer": "卒業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社を卒業して、来月から旅行に出かけます。", "explanation": "ここは〈退職〉の意味。卒業は学校の全課程を終えて出ることを指し、会社を辞める意味には使わない。"}, {"text": "この契約は来月で卒業します。", "explanation": "ここは〈解約〉の意味。卒業は学校を出ることなので、契約を終わらせる意味では使わない。"}, {"text": "注文品は昨日、すべて卒業しました。", "explanation": "ここは〈納品〉の意味。卒業は学校の課程を終えることで、品物を届ける意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は高校を卒業に、大学へ進みました。", "corrected_sentence": "妹は高校を卒業して、大学へ進みました。", "error_description": "「卒業」の後は「して」で文をつなぐ。「卒業に」は「に」が続いても文がつながらないので誤り。誤りは「に」の部分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は大学を卒業まで、毎日図書館で働きました。", "corrected_sentence": "兄は大学を卒業するまで、毎日図書館で働きました。", "error_description": "「まで」の前の動詞は辞書形の「卒業する」が必要。「卒業まで」は「する」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "卒業の対義語で、学校の課程に入ること。"}, {"text": "出発", "is_correct": false, "explanation": "出て行くことで、到着の対義語ではあるが卒業との対義関係はない。"}, {"text": "開会", "is_correct": false, "explanation": "会を始めることで、閉会の対義語ではあるが卒業とは対義関係にない。"}, {"text": "乗車", "is_correct": false, "explanation": "車両に乗ることで、下車の対義語ではあるが卒業とは対義関係にない。"}], "correct_answer": "入学", "explanations": {"入学": "卒業の対義語で、学校の課程に入ること。", "出発": "出て行くことで、到着の対義語ではあるが卒業との対義関係はない。", "開会": "会を始めることで、閉会の対義語ではあるが卒業とは対義関係にない。", "乗車": "車両に乗ることで、下車の対義語ではあるが卒業とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "卒業の対義語で、学校の課程に入ること。"}, {"text": "発売", "is_correct": false, "explanation": "商品を売り出すことで、卒業の対義語ではない。"}, {"text": "購読", "is_correct": false, "explanation": "新聞や雑誌を定期的に読むことで、卒業とは対義関係にない。"}, {"text": "着任", "is_correct": false, "explanation": "任地に着いて任務に就くことで、卒業とは対義関係にない。"}], "correct_answer": "入学", "explanations": {"入学": "卒業の対義語で、学校の課程に入ること。", "発売": "商品を売り出すことで、卒業の対義語ではない。", "購読": "新聞や雑誌を定期的に読むことで、卒業とは対義関係にない。", "着任": "任地に着いて任務に就くことで、卒業とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "学校の課程を修了して、その学校を出ること。また、ある段階を終えること。", "primary_collocate": null, "pronunciation": "そつぎょう", "ipa": "sotsɯɡʲoː", "syllable_count": 4, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "高校[こうこう]を卒業[そつぎょう]したばかりの10代[じゅうだい]の彼[かれ]が選[えら]んだ道[みち]は、地方[ちほう]の有機[ゆうき]農家[のうか]で働[はたら]くことでした。", "sentence_source": "mined"}, {"text": "兄は来月大学を卒業して、春から銀行で働きます。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "兄[あに]は来月[らいげつ]大学[だいがく]を卒業[そつぎょう]して、春[はる]から銀行[ぎんこう]で働[はたら]きます。", "sentence_source": "generated"}, {"text": "三月に小学校を卒業する妹は、中学校の制服を楽しみにしています。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "三月[さんがつ]に小学校[しょうがっこう]を卒業[そつぎょう]する妹[いもうと]は、中学校[ちゅうがっこう]の制服[せいふく]を楽[たの]しみにしています。", "sentence_source": "generated"}, {"text": "卒業のあとも、私たちは月に一度集まる約束をしました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]のあとも、私[わたし]たちは月[つき]に一度[いちど]集[あつ]まる約束[やくそく]をしました。", "sentence_source": "generated"}, {"text": "彼は大学を卒業できず、もう一年勉強を続けることになりました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]を卒業[そつぎょう]できず、もう一年[いちねん]勉強[べんきょう]を続[つづ]けることになりました。", "sentence_source": "generated"}, {"text": "子どもっぽい服は卒業して、落ち着いた色を選ぶようになりました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "子[こ]どもっぽい服[ふく]は卒業[そつぎょう]して、落[お]ち着[つ]いた色[いろ]を選[えら]ぶようになりました。", "sentence_source": "generated"}, {"text": "卒業した学校の先生に、手紙を書いて近況を伝えました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]した学校[がっこう]の先生[せんせい]に、手紙[てがみ]を書[か]いて近況[きんきょう]を伝[つた]えました。", "sentence_source": "generated"}, {"text": "高校を卒業してから十年たち、昔の友だちに会いたくなりました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "高校[こうこう]を卒業[そつぎょう]してから十年[じゅうねん]たち、昔[むかし]の友[とも]だちに会[あ]いたくなりました。", "sentence_source": "generated"}, {"text": "父は工業高校を卒業すると、すぐに工場で働き始めました。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "父[ちち]は工業[こうぎょう]高校[こうこう]を卒業[そつぎょう]すると、すぐに工場[こうじょう]で働[はたら]き始[はじ]めました。", "sentence_source": "generated"}, {"text": "卒業するまでに、この研究をまとめなければなりません。", "target_word": "卒業", "complexity_tier": "T3", "furigana": "卒業[そつぎょう]するまでに、この研究[けんきゅう]をまとめなければなりません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "卒業", "label": "基本形"}, {"form": "卒業する", "label": "辞書形"}, {"form": "卒業した", "label": "過去形"}, {"form": "卒業して", "label": "て形"}], "register": "中立", "sense_fingerprint": "学校の課程を終えて出ること、またある段階を終えて次へ進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3d3110-d507-4b02-8197-8f3e9eb5d27a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卒業", "is_correct": true, "explanation": "学校の課程を修了して出ることで、「高校を〜したばかり」に入り文が成り立つ。"}, {"text": "出席", "is_correct": false, "explanation": "授業や会合に出ることで、「高校を出席したばかり」は文が成り立たない。"}, {"text": "完成", "is_correct": false, "explanation": "物事が仕上がることで、学校を出るという意味では文が成り立たない。"}, {"text": "購入", "is_correct": false, "explanation": "物を買うことで、学校の課程を終えるという文には合わない。"}], "explanations": {"卒業": "学校の課程を修了して出ることで、「高校を〜したばかり」に入り文が成り立つ。", "出席": "授業や会合に出ることで、「高校を出席したばかり」は文が成り立たない。", "完成": "物事が仕上がることで、学校を出るという意味では文が成り立たない。", "購入": "物を買うことで、学校の課程を終えるという文には合わない。"}, "sentence_index": 0, "correct_answer": "卒業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病気のため、大学を卒業しました。", "explanation": "ここは〈退学〉の意味。卒業は課程を修了して出ることで、病気などで途中で辞めた場合には使わないので合わない。"}, {"text": "会社の卒業のあと、同僚と食事に行きました。", "explanation": "ここは〈終業〉の意味。卒業は学校の課程を終えることで、会社の一日の仕事の終わりには使わないので合わない。"}, {"text": "この本は三時間で卒業しました。", "explanation": "ここは〈読了〉の意味。卒業は学校を出ることや課程を修めることで、本を読み終える意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卒業", "is_correct": true, "explanation": "学校の課程を修了して出ることで、「卒業した学校の先生」と続けて自然。"}, {"text": "出勤", "is_correct": false, "explanation": "職場に出て働くことで、「出勤した学校」は文が成り立たない。"}, {"text": "開店", "is_correct": false, "explanation": "店を始めることで、「開店した学校」は不自然で文に合わない。"}, {"text": "閉店", "is_correct": false, "explanation": "店を閉じることで、「閉店した学校」は文が成り立たない。"}], "explanations": {"卒業": "学校の課程を修了して出ることで、「卒業した学校の先生」と続けて自然。", "出勤": "職場に出て働くことで、「出勤した学校」は文が成り立たない。", "開店": "店を始めることで、「開店した学校」は不自然で文に合わない。", "閉店": "店を閉じることで、「閉店した学校」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "卒業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来年、自分の店を卒業するために準備します。", "explanation": "ここは〈開業〉の意味。卒業は学校の課程を終えたり、ある段階を終えたりすることで、自分の店を始めるときには使わないので合わない。"}, {"text": "家の事情で、一年間学校を卒業することにしました。", "explanation": "ここは〈休学〉の意味。卒業は課程を修了して学校を出ることで、一年だけ学校を休む場合には使わないので合わない。"}, {"text": "この薬は三日で卒業しました。", "explanation": "ここは〈服用終了〉の意味。卒業は学校の課程を修めて出ることで、薬を飲み終える意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は来月大学を卒業した。春から銀行で働きます。", "corrected_sentence": "兄は来月大学を卒業する。春から銀行で働きます。", "error_description": "「来月」は未来の予定なので、動詞は現在形の「卒業する」を使う。「卒業した」は過去形で合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51550, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は高校を卒業に、春から看護学校へ行きます。", "corrected_sentence": "妹は高校を卒業して、春から看護学校へ行きます。", "error_description": "「卒業」の後は「して」で続ける。「卒業に」の「に」は誤りで、正しくは「卒業して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9af296b1-f96d-4031-ab4c-8208a8b01acf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜い", "is_correct": true, "explanation": "見た目が心地よく立派だという「美しい」の対義語で、見た目が劣るという意味を表す。"}, {"text": "明るい", "is_correct": false, "explanation": "光や雰囲気を表す語で、「美しい」の対義語ではない。"}, {"text": "速い", "is_correct": false, "explanation": "速さを表す語で、「美しい」とは対義の関係にない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、「美しい」の対義語ではない。"}], "correct_answer": "醜い", "explanations": {"醜い": "見た目が心地よく立派だという「美しい」の対義語で、見た目が劣るという意味を表す。", "明るい": "光や雰囲気を表す語で、「美しい」の対義語ではない。", "速い": "速さを表す語で、「美しい」とは対義の関係にない。", "重い": "重さを表す語で、「美しい」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "醜くて", "is_correct": true, "explanation": "「美しくて」の対義にあたる、見た目が劣るという意味の形。"}, {"text": "遅くて", "is_correct": false, "explanation": "速さや時刻を表す語で、「美しい」の対義語ではない。"}, {"text": "大きくて", "is_correct": false, "explanation": "大きさを表す語で、「美しい」とは対義の関係にない。"}, {"text": "柔らかくて", "is_correct": false, "explanation": "手触りを表す語で、「美しい」の対義語ではない。"}], "correct_answer": "醜くて", "explanations": {"醜くて": "「美しくて」の対義にあたる、見た目が劣るという意味の形。", "遅くて": "速さや時刻を表す語で、「美しい」の対義語ではない。", "大きくて": "大きさを表す語で、「美しい」とは対義の関係にない。", "柔らかくて": "手触りを表す語で、「美しい」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "見たり聞いたりしたときに、心が気持ちよくなるようす。", "primary_collocate": null, "pronunciation": "うつくしい", "ipa": "ɯtsɯkɯɕiː", "syllable_count": 5, "sentences": [{"text": "朝日にてらされた海は、とても美しい。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "朝日[あさひ]にてらされた海[うみ]は、とても美[うつく]しい。", "sentence_source": "generated"}, {"text": "彼女の歌声は美しくて、聞いていると心が落ち着く。", "target_word": "美しくて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の歌声[うたごえ]は美[うつく]しくて、聞[き]いていると心[こころ]が落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "京都の秋は、紅葉が美しい季節です。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "京都[きょうと]の秋[あき]は、紅葉[こうよう]が美[うつく]しい季節[きせつ]です。", "sentence_source": "generated"}, {"text": "美しい花がさいている庭で、お茶を飲んだ。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "美[うつく]しい花[はな]がさいている庭[にわ]で、お茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "山の上から見た夕焼けは、言葉にできないほど美しかった。", "target_word": "美しかった", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]た夕焼[ゆうや]けは、言葉[ことば]にできないほど美[うつく]しかった。", "sentence_source": "generated"}, {"text": "この町の古い橋は、夜になるとライトで美しく光る。", "target_word": "美しく", "complexity_tier": "T3", "furigana": "この町[まち]の古[ふる]い橋[はし]は、夜[よる]になるとライトで美[うつく]しく光[ひか]る。", "sentence_source": "generated"}, {"text": "彼は美しい字を書くので、手紙をもらうとうれしい。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "彼[かれ]は美[うつく]しい字[じ]を書[か]くので、手紙[てがみ]をもらうとうれしい。", "sentence_source": "generated"}, {"text": "ピアノの美しい音が、となりの部屋から聞こえてきた。", "target_word": "美しい", "complexity_tier": "T3", "furigana": "ピアノの美[うつく]しい音[おと]が、となりの部屋[へや]から聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "雨上がりの空にかかった虹は、とても美しく見えた。", "target_word": "美しく", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの空[そら]にかかった虹[にじ]は、とても美[うつく]しく見[み]えた。", "sentence_source": "generated"}, {"text": "湖にうつる星空があまりに美しくて、時間を忘れた。", "target_word": "美しくて", "complexity_tier": "T3", "furigana": "湖[みずうみ]にうつる星空[ほしぞら]があまりに美[うつく]しくて、時間[じかん]を忘[わす]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美しい", "label": "終止形・連体形"}, {"form": "美しく", "label": "連用形"}, {"form": "美しかった", "label": "過去形"}, {"form": "美しくない", "label": "否定形"}, {"form": "美しければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "景色・音・姿などが見聞きして心地よいほど立派できれいなこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: てらさ (Zipf 2.08)']::text[], 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美しい", "is_correct": true, "explanation": "見て心地よいという意味で、「とても美しい」と海の様子を評価する文に合う。"}, {"text": "眠い", "is_correct": false, "explanation": "人の眠気を表す語で、海の様子には使わない。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す語で、海を見た感想としては成り立たない。"}, {"text": "忙しい", "is_correct": false, "explanation": "人の仕事の多さを表す語で、海には使わない。"}], "explanations": {"美しい": "見て心地よいという意味で、「とても美しい」と海の様子を評価する文に合う。", "眠い": "人の眠気を表す語で、海の様子には使わない。", "固い": "硬さを表す語で、海を見た感想としては成り立たない。", "忙しい": "人の仕事の多さを表す語で、海には使わない。"}, "sentence_index": 0, "correct_answer": "美しい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店員は美しく説明してくれた。", "explanation": "ここは〈丁寧〉の意味。説明の仕方が親切で細かいことを表すので、「美しく説明する」とは言わない。"}, {"text": "この薬は、美しく効く。", "explanation": "ここは〈よく効く〉の意味。美しいは見た目や心地よさを表す語で、薬の効き目を表すときは「よく効く」と言い、「美しく効く」とは言わない。"}, {"text": "時計は美しい時間を示していた。", "explanation": "ここは〈正しい〉の意味。時計の時刻が合っていることは「正しい」で表し、見た目の美しさとは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美しい", "is_correct": true, "explanation": "見た目や書いた字の心地よさを表し、「美しい字を書く」と自然に続く。"}, {"text": "寒い", "is_correct": false, "explanation": "温度を表す語で、「寒い字」では意味が通らない。"}, {"text": "暑い", "is_correct": false, "explanation": "温度を表す語で、「暑い字を書く」とは言えない。"}, {"text": "痛い", "is_correct": false, "explanation": "体の感覚を表す語で、字を修飾する場面には合わない。"}], "explanations": {"美しい": "見た目や書いた字の心地よさを表し、「美しい字を書く」と自然に続く。", "寒い": "温度を表す語で、「寒い字」では意味が通らない。", "暑い": "温度を表す語で、「暑い字を書く」とは言えない。", "痛い": "体の感覚を表す語で、字を修飾する場面には合わない。"}, "sentence_index": 6, "correct_answer": "美しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅から美しいので、毎日歩いて通える。", "explanation": "ここは〈近い〉の意味。距離が短いことは「近い」で表し、美しいは見た目の心地よさなので距離には使わない。"}, {"text": "この服は値段が美しく、なかなか買えない。", "explanation": "ここは〈高い〉の意味。値段が高いことを表す語で、美しいは見た目の評価で値段には使わない。"}, {"text": "電車が遅れたので、到着が美しくなった。", "explanation": "ここは〈遅い〉の意味。時刻が遅れることは「遅い」で表し、美しいは時刻には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕暮れの海は、とても美しいかった。", "corrected_sentence": "夕暮れの海は、とても美しかった。", "error_description": "「美しい」の過去形は「美しかった」。「美しいかった」は形容詞の活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "美しくて", "is_correct": true, "explanation": "て形。「〜て」で後ろの「聞いていると」へ続く形で、文の流れに合う。"}, {"text": "美しかった", "is_correct": false, "explanation": "過去形。「〜て」で続ける場面ではなく、ここでは文が続かない。"}, {"text": "美しくない", "is_correct": false, "explanation": "否定形。意味が反対になり、後ろの「聞いていると心が落ち着く」と合わない。"}, {"text": "美しさ", "is_correct": false, "explanation": "名詞形。活用形ではなく、「歌声は〜、聞いていると」の文の述語にならない。"}], "correct_form": "美しくて", "base_form": "美しい", "form_label": "て形", "sentence_index": 1, "explanations": {"美しくて": "て形。「〜て」で後ろの「聞いていると」へ続く形で、文の流れに合う。", "美しかった": "過去形。「〜て」で続ける場面ではなく、ここでは文が続かない。", "美しくない": "否定形。意味が反対になり、後ろの「聞いていると心が落ち着く」と合わない。", "美しさ": "名詞形。活用形ではなく、「歌声は〜、聞いていると」の文の述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51551, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その音楽は、美しい体重で心を癒した。", "corrected_sentence": "その音楽は、美しい音色で心を癒した。", "error_description": "「美しい」が修飾する名詞は「音色」。「体重」は美しさを表す語ではないので合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "美しい", "is_correct": true, "explanation": "連体形。名詞「音」の前に置いて修飾する形で、この文に合う。"}, {"text": "美しく", "is_correct": false, "explanation": "連用形。名詞「音」を直接修飾することはできない。"}, {"text": "美しいだろう", "is_correct": false, "explanation": "推量の形。名詞の前に置いて修飾することはできない。"}, {"text": "美しかったら", "is_correct": false, "explanation": "たら形。条件を表すので、名詞「音」を修飾しない。"}], "correct_form": "美しい", "base_form": "美しい", "form_label": "連体形", "sentence_index": 7, "explanations": {"美しい": "連体形。名詞「音」の前に置いて修飾する形で、この文に合う。", "美しく": "連用形。名詞「音」を直接修飾することはできない。", "美しいだろう": "推量の形。名詞の前に置いて修飾することはできない。", "美しかったら": "たら形。条件を表すので、名詞「音」を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
