INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51553, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "「裏腹」は、見た目や思っていることと、本当のことが反対になることを言います。", "primary_collocate": null, "pronunciation": "うらはら", "ipa": "ɯɾahaɾa", "syllable_count": 4, "sentences": [{"text": "彼は強がりの言葉とは裏腹に、手が小さく震えていた。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "彼[かれ]は強[つよ]がりの言葉[ことば]とは裏腹[うらはら]に、手[て]が小[ちい]さく震[ふる]えていた。", "sentence_source": "generated"}, {"text": "平気そうな顔とは裏腹に、一人になると涙が止まらなかった。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "平気[へいき]そうな顔[かお]とは裏腹[うらはら]に、一人[ひとり]になると涙[なみだ]が止[と]まらなかった。", "sentence_source": "generated"}, {"text": "彼女は冷たい態度とは裏腹に、実はとても優しい人だ。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は冷[つめ]たい態度[たいど]とは裏腹[うらはら]に、実[じつ]はとても優[やさ]しい人[ひと]だ。", "sentence_source": "generated"}, {"text": "彼の言葉と行動は裏腹で、誰も信じなくなった。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]と行動[こうどう]は裏腹[うらはら]で、誰[だれ]も信[しん]じなくなった。", "sentence_source": "generated"}, {"text": "心とは裏腹に、つい意地悪なことを言ってしまった。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "心[こころ]とは裏腹[うらはら]に、つい意地悪[いじわる]なことを言[い]ってしまった。", "sentence_source": "generated"}, {"text": "好きだという思いとは裏腹に、彼女の前では目も合わせられない。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "好[す]きだという思[おも]いとは裏腹[うらはら]に、彼女[かのじょ]の前[まえ]では目[め]も合[あ]わせられない。", "sentence_source": "generated"}, {"text": "彼は「平気だ」と笑ったが、顔色は言葉と裏腹だった。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "彼[かれ]は「平気[へいき]だ」と笑[わら]ったが、顔色[かおいろ]は言葉[ことば]と裏腹[うらはら]だった。", "sentence_source": "generated"}, {"text": "大人しそうな外見とは裏腹に、彼は驚くほど大胆な人だ。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "大人[おとな]しそうな外見[がいけん]とは裏腹[うらはら]に、彼[かれ]は驚[おどろ]くほど大胆[だいたん]な人[ひと]だ。", "sentence_source": "generated"}, {"text": "謝る言葉とは裏腹に、その目は少しも反省していなかった。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "謝[あやま]る言葉[ことば]とは裏腹[うらはら]に、その目[め]は少[すこ]しも反省[はんせい]していなかった。", "sentence_source": "generated"}, {"text": "本心と裏腹のことを言うと、あとで後悔することが多い。", "target_word": "裏腹", "complexity_tier": "T3", "furigana": "本心[ほんしん]と裏腹[うらはら]のことを言[い]うと、あとで後悔[こうかい]することが多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "裏腹だ", "label": "終止形"}, {"form": "裏腹な", "label": "連体形"}, {"form": "裏腹に", "label": "連用形"}, {"form": "裏腹で", "label": "連用形(で)"}], "register": "neutral", "sense_fingerprint": "言葉・態度・見た目と本心や実際が反対であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51553, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裏腹", "is_correct": true, "explanation": "「とは裏腹に」で『言葉と反対に』の意味になり、強がりの言葉と震える手の対比に合う。"}, {"text": "対等", "is_correct": false, "explanation": "「対等に」は『同じ立場で』の意味で、言葉と震えの対比にならない。"}, {"text": "平凡", "is_correct": false, "explanation": "「平凡に」は『ありふれて』の意味で、強がりとの対比が成り立たない。"}, {"text": "過剰", "is_correct": false, "explanation": "「過剰に」は『度を超えて』の意味で、言葉と手の様子の関係を表せない。"}], "explanations": {"裏腹": "「とは裏腹に」で『言葉と反対に』の意味になり、強がりの言葉と震える手の対比に合う。", "対等": "「対等に」は『同じ立場で』の意味で、言葉と震えの対比にならない。", "平凡": "「平凡に」は『ありふれて』の意味で、強がりとの対比が成り立たない。", "過剰": "「過剰に」は『度を超えて』の意味で、言葉と手の様子の関係を表せない。"}, "sentence_index": 0, "correct_answer": "裏腹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の考えは裏腹で、会議ではぴったり一致していた。", "explanation": "ここは〈一致〉の意味。裏腹は反対になることを言うので、同じ方向を指す一致には使えない。"}, {"text": "父の意見と私の考えは裏腹で、話はすぐにまとまった。", "explanation": "ここは〈調和〉の意味。裏腹は食い違いを表すので、折り合いがついた様子には使えない。"}, {"text": "彼の言葉と行動は裏腹で、まるで同じ人物のようだった。", "explanation": "ここは〈同一〉の意味。裏腹は反対になることを言うので、同一であることの説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51553, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "裏腹", "is_correct": true, "explanation": "「言葉と裏腹だ」で、顔色が言葉と反対だという意味になり、文の内容に合う。"}, {"text": "熱心", "is_correct": false, "explanation": "「熱心だ」は『一生懸命だ』の意味で、顔色を言葉と比べる文には合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "「陰気だ」は暗い様子の意味で、言葉と顔色の関係を表せない。"}, {"text": "手軽", "is_correct": false, "explanation": "「手軽だ」は簡単だという意味で、顔色の説明にならない。"}], "explanations": {"裏腹": "「言葉と裏腹だ」で、顔色が言葉と反対だという意味になり、文の内容に合う。", "熱心": "「熱心だ」は『一生懸命だ』の意味で、顔色を言葉と比べる文には合わない。", "陰気": "「陰気だ」は暗い様子の意味で、言葉と顔色の関係を表せない。", "手軽": "「手軽だ」は簡単だという意味で、顔色の説明にならない。"}, "sentence_index": 6, "correct_answer": "裏腹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの案は裏腹で、どちらを選んでも結果は同じだ。", "explanation": "ここは〈同一〉の意味。裏腹は反対になることを言うので、同じだという意味では使えない。"}, {"text": "父と私の意見は裏腹で、いつも互いに同調していた。", "explanation": "ここは〈一致〉の意味。裏腹は反対になることを言うので、同調している様子には使えない。"}, {"text": "チームの連携は裏腹で、どの場面でも息が合っていた。", "explanation": "ここは〈調和〉の意味。裏腹は食い違いを表すので、息が合う様子には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51553, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は平気な顔とは裏腹な、心の中で不安を抱えていた。", "corrected_sentence": "彼は平気な顔とは裏腹に、心の中で不安を抱えていた。", "error_description": "「裏腹」に続く形が連体形の「な」になっている。副詞句として「に」で続ける必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "裏腹", "is_correct": true, "explanation": "文中は「とは裏腹に」の形で、語幹の「裏腹」に「に」が続いている。"}, {"text": "裏腹だ", "is_correct": false, "explanation": "終止形。「とは〜に」と副詞句でつなぐ形には使えない。"}, {"text": "裏腹な", "is_correct": false, "explanation": "連体形。名詞を修飾する形なので、ここの副詞句には合わない。"}, {"text": "裏腹で", "is_correct": false, "explanation": "連用形（で）。後ろの「に」とはつながらず、ここでは合わない。"}], "correct_form": "裏腹", "base_form": "裏腹だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"裏腹": "文中は「とは裏腹に」の形で、語幹の「裏腹」に「に」が続いている。", "裏腹だ": "終止形。「とは〜に」と副詞句でつなぐ形には使えない。", "裏腹な": "連体形。名詞を修飾する形なので、ここの副詞句には合わない。", "裏腹で": "連用形（で）。後ろの「に」とはつながらず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51553, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "皆の期待とは裏腹を、彼女は冷たい態度を取った。", "corrected_sentence": "皆の期待とは裏腹に、彼女は冷たい態度を取った。", "error_description": "「裏腹」に続く助詞が「を」になっている。「期待とは裏腹に」と副詞句で続ける必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "裏腹", "is_correct": true, "explanation": "「大人しそうな外見とは裏腹に」の副詞句で、語幹の「裏腹」に「に」が続いている。"}, {"text": "裏腹だった", "is_correct": false, "explanation": "過去の形。後ろの「に」で続く副詞句には入らないので、ここでは合わない。"}, {"text": "裏腹ではない", "is_correct": false, "explanation": "否定の形。「とは〜に」の副詞句ではつながらないので、ここでは合わない。"}, {"text": "裏腹さ", "is_correct": false, "explanation": "名詞化した形。「さに」とはつながらず、この位置では不自然になる。"}], "correct_form": "裏腹", "base_form": "裏腹だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"裏腹": "「大人しそうな外見とは裏腹に」の副詞句で、語幹の「裏腹」に「に」が続いている。", "裏腹だった": "過去の形。後ろの「に」で続く副詞句には入らないので、ここでは合わない。", "裏腹ではない": "否定の形。「とは〜に」の副詞句ではつながらないので、ここでは合わない。", "裏腹さ": "名詞化した形。「さに」とはつながらず、この位置では不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「かく」の対象（目的語）は「を」で示す。「旅先の風景をかく」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」を使うと風景が主語になり、「かいている」の主語が彼である文と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到着点や相手を示すので、「風景にかく」では対象が示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」で名詞をつなぐと、「かいている」が続く文の形にならない。"}], "correct_answer": "を", "explanations": {"を": "「かく」の対象（目的語）は「を」で示す。「旅先の風景をかく」が正しい。", "が": "「が」を使うと風景が主語になり、「かいている」の主語が彼である文と合わない。", "に": "「に」は到着点や相手を示すので、「風景にかく」では対象が示せない。", "の": "「の」で名詞をつなぐと、「かいている」が続く文の形にならない。"}, "error_tags": {"が": "主語", "に": "方向", "の": "名詞をつなぐ形では文が成立しない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "見える景色のこと。自然のながめ。", "primary_collocate": null, "pronunciation": "ふうけい", "ipa": "ɸɯːkeː", "syllable_count": 4, "sentences": [{"text": "窓の外の風景が、だんだん雪におおわれてきた。", "target_word": "風景", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]の風景[ふうけい]が、だんだん雪[ゆき]におおわれてきた。", "sentence_source": "generated"}, {"text": "旅行で見た山の風景は、今でも忘れられない。", "target_word": "風景", "complexity_tier": "T3", "furigana": "旅行[りょこう]で見[み]た山[やま]の風景[ふうけい]は、今[いま]でも忘[わす]れられない。", "sentence_source": "generated"}, {"text": "この丘からの風景は、四季によってまったく違う。", "target_word": "風景", "complexity_tier": "T3", "furigana": "この丘[おか]からの風景[ふうけい]は、四季[しき]によってまったく違[ちが]う。", "sentence_source": "generated"}, {"text": "風景を見ながら、ゆっくりお弁当を食べた。", "target_word": "風景", "complexity_tier": "T3", "furigana": "風景[ふうけい]を見[み]ながら、ゆっくりお弁当[べんとう]を食[た]べた。", "sentence_source": "generated"}, {"text": "ふるさとの風景は、子どものころとあまり変わっていない。", "target_word": "風景", "complexity_tier": "T3", "furigana": "ふるさとの風景[ふうけい]は、子[こ]どものころとあまり変[か]わっていない。", "sentence_source": "generated"}, {"text": "電車から見える海の風景が好きで、いつも窓側にすわる。", "target_word": "風景", "complexity_tier": "T3", "furigana": "電車[でんしゃ]から見[み]える海[うみ]の風景[ふうけい]が好[す]きで、いつも窓側[まどがわ]にすわる。", "sentence_source": "generated"}, {"text": "霧がかかると、見慣れた町の風景も別の場所のように見える。", "target_word": "風景", "complexity_tier": "T3", "furigana": "霧[きり]がかかると、見慣[みな]れた町[まち]の風景[ふうけい]も別[べつ]の場所[ばしょ]のように見[み]える。", "sentence_source": "generated"}, {"text": "彼は旅先の風景を、ノートに絵でかいている。", "target_word": "風景", "complexity_tier": "T3", "furigana": "彼[かれ]は旅先[たびさき]の風景[ふうけい]を、ノートに絵[え]でかいている。", "sentence_source": "generated"}, {"text": "新しいビルが建って、駅前の風景が大きく変わった。", "target_word": "風景", "complexity_tier": "T3", "furigana": "新[あたら]しいビルが建[た]って、駅前[えきまえ]の風景[ふうけい]が大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "夕方の風景は、赤い光でやさしくつつまれていた。", "target_word": "風景", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]の風景[ふうけい]は、赤[あか]い光[ひかり]でやさしくつつまれていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "風景", "label": "基本形"}], "register": "中立", "sense_fingerprint": "目に見える自然や町のながめ、景色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: すわる (Zipf 1.95)']::text[], 'c1b78f96-7558-4900-998d-122c0e9e9878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "風景", "is_correct": true, "explanation": "窓の外に見える景色を指す「風景」が、雪におおわれる主語として自然につながる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は雪におおわれる対象ではないので、この文の主語として合わない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は雪におおわれるものではないので、この文の主語として合わない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の計画のことで、雪におおわれるものではないので、この文の主語として合わない。"}], "explanations": {"風景": "窓の外に見える景色を指す「風景」が、雪におおわれる主語として自然につながる。", "天気": "天気は雪におおわれる対象ではないので、この文の主語として合わない。", "気温": "気温は雪におおわれるものではないので、この文の主語として合わない。", "予算": "お金の計画のことで、雪におおわれるものではないので、この文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "風景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女には、長年の仕事で身についた風景がある。", "explanation": "ここは「風格」の意味。人の品格や貫禄は風格と言い、目に見えるながめを表す風景は人には使わない。"}, {"text": "この地域は風景が強く、発電に使われている。", "explanation": "ここは「風力」の意味。風の強さを表す風力なら自然だが、見えるながめの風景では強さを表せないので合わない。"}, {"text": "健康志向の風景が強まっている。", "explanation": "ここは「風潮」の意味。世の中の流れや傾向を指す風潮なら強まるが、見えるながめの風景は強まらないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "風景", "is_correct": true, "explanation": "見慣れた町の見え方を指す「風景」が、「の風景も別の場所のように見える」と自然につながる。"}, {"text": "給料", "is_correct": false, "explanation": "働いて受け取るお金のことで、見え方が変わるものではないので文に合わない。"}, {"text": "方言", "is_correct": false, "explanation": "方言は言葉の一種で、別の場所のように見える対象ではない。"}, {"text": "時刻表", "is_correct": false, "explanation": "時刻表は紙の資料で、見慣れた町の見え方を言う文には合わない。"}], "explanations": {"風景": "見慣れた町の見え方を指す「風景」が、「の風景も別の場所のように見える」と自然につながる。", "給料": "働いて受け取るお金のことで、見え方が変わるものではないので文に合わない。", "方言": "方言は言葉の一種で、別の場所のように見える対象ではない。", "時刻表": "時刻表は紙の資料で、見慣れた町の見え方を言う文には合わない。"}, "sentence_index": 6, "correct_answer": "風景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の風景は、いつも明るくて周りを和ませる。", "explanation": "ここは「人柄」の意味。性格や人の性質は人柄と言い、目に見えるながめの風景とは合わない。"}, {"text": "この国の風景が回復し、雇用も増えてきた。", "explanation": "ここは「景気」の意味。経済の状態は景気と言い、目に見えるながめの風景とは合わない。"}, {"text": "商店街の福引きで、大きな風景が当たった。", "explanation": "ここは「景品」の意味。くじやおまけで渡される品物は景品と言い、風景は当たるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山頂からは、遠くの風景を見える。", "corrected_sentence": "山頂からは、遠くの風景が見える。", "error_description": "誤りは「風景を」の「を」。「見える」は自然に目に入る意味で、対象は「が」で示す。「風景を見える」は誤りで、「風景が見える」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺から夕焼けの風景が眺めた。", "corrected_sentence": "窓辺から夕焼けの風景を眺めた。", "error_description": "誤りは「風景が」の「が」。「眺める」の対象は目的語なので「を」で示す。「風景が」では主語になり、「眺めた」の動作主と合わない。「夕焼けの風景を眺めた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2d6732-0271-43f9-847d-10a5d4dc0790') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
