INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51559, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じことが、つぎつぎとおこること。", "primary_collocate": null, "pronunciation": "れんぞく", "ipa": "ɾeɲzokɯ", "syllable_count": 4, "sentences": [{"text": "今月は事故が連続して起こり、工場は操業を止めた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "今月[こんげつ]は事故[じこ]が連続[れんぞく]して起[お]こり、工場[こうじょう]は操業[そうぎょう]を止[と]めた。", "sentence_source": "generated"}, {"text": "台風が連続して上陸し、各地で被害が出た。", "target_word": "連続", "complexity_tier": "T3", "furigana": "台風[たいふう]が連続[れんぞく]して上陸[じょうりく]し、各地[かくち]で被害[ひがい]が出[で]た。", "sentence_source": "generated"}, {"text": "三日連続で同じ夢を見て、少し怖くなった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "三日[みっか]連続[れんぞく]で同[おな]じ夢[ゆめ]を見[み]て、少[すこ]し怖[こわ]くなった。", "sentence_source": "generated"}, {"text": "この町では火事が連続し、住民は不安になった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "この町[まち]では火事[かじ]が連続[れんぞく]し、住民[じゅうみん]は不安[ふあん]になった。", "sentence_source": "generated"}, {"text": "彼は十回連続で試験に落ちてしまった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "彼[かれ]は十回[じっかい]連続[れんぞく]で試験[しけん]に落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "チームは四試合連続で負け、監督が交代した。", "target_word": "連続", "complexity_tier": "T3", "furigana": "チームは四試合[よんしあい]連続[れんぞく]で負[ま]け、監督[かんとく]が交代[こうたい]した。", "sentence_source": "generated"}, {"text": "不運が連続して、今年は何もうまくいかない。", "target_word": "連続", "complexity_tier": "T3", "furigana": "不運[ふうん]が連続[れんぞく]して、今年[ことし]は何[なに]もうまくいかない。", "sentence_source": "generated"}, {"text": "同じ場所で落雷が連続し、停電が何度も起きた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "同[おな]じ場所[ばしょ]で落雷[らくらい]が連続[れんぞく]し、停電[ていでん]が何度[なんど]も起[お]きた。", "sentence_source": "generated"}, {"text": "彼女は二年連続で最優秀選手に選ばれた。", "target_word": "連続", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は二年[にねん]連続[れんぞく]で最優秀選手[さいゆうしゅうせんしゅ]に選[えら]ばれた。", "sentence_source": "generated"}, {"text": "休む間もなく、いやな知らせの連続だった。", "target_word": "連続", "complexity_tier": "T3", "furigana": "休[やす]む間[ま]もなく、いやな知[し]らせの連続[れんぞく]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "連続する", "label": "終止形"}, {"form": "連続して", "label": "て形"}, {"form": "連続した", "label": "た形"}, {"form": "連続で", "label": "で格"}], "register": "neutral", "sense_fingerprint": "同じ出来事が次々に繰り返し起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb7d6c3d-f83b-4e4e-9225-ca1e02731215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51559, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "連続", "is_correct": true, "explanation": "「連続して」で同じ事故が次々起こる意味になり、文に合う。"}, {"text": "延長", "is_correct": false, "explanation": "「延長して」では事故の起こり方が合わず、文が不自然になる。"}, {"text": "交代", "is_correct": false, "explanation": "「交代して」は入れ替わる意味で、事故の説明にならない。"}, {"text": "沈黙", "is_correct": false, "explanation": "「沈黙して」は黙る意味で、事故が起こる文には合わない。"}], "explanations": {"連続": "「連続して」で同じ事故が次々起こる意味になり、文に合う。", "延長": "「延長して」では事故の起こり方が合わず、文が不自然になる。", "交代": "「交代して」は入れ替わる意味で、事故の説明にならない。", "沈黙": "「沈黙して」は黙る意味で、事故が起こる文には合わない。"}, "sentence_index": 0, "correct_answer": "連続"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事の役割を連続した。", "explanation": "ここは〈分担〉の意味。連続は同じ事が次々起こることで、役割を分けて受け持つ意味はない。"}, {"text": "重大な判断を連続した。", "explanation": "ここは〈保留〉の意味。結論を先送りする意味は連続にはない。"}, {"text": "チラシを町中に連続した。", "explanation": "ここは〈配布〉の意味。配って回る意味は連続では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51559, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "連続", "is_correct": true, "explanation": "「連続して」で不運が次々起こる意味になり、文に合う。"}, {"text": "経路", "is_correct": false, "explanation": "道筋の意味で、不運を説明する文には合わない。"}, {"text": "作物", "is_correct": false, "explanation": "農産物の意味で、不運と結びつかない。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの意味で、文の内容に合わない。"}], "explanations": {"連続": "「連続して」で不運が次々起こる意味になり、文に合う。", "経路": "道筋の意味で、不運を説明する文には合わない。", "作物": "農産物の意味で、不運と結びつかない。", "寝具": "布団などの意味で、文の内容に合わない。"}, "sentence_index": 6, "correct_answer": "連続"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "データから必要な情報を連続した。", "explanation": "ここは〈抽出〉の意味。必要なものを選び出す意味は連続にはない。"}, {"text": "必要な食料品を連続した。", "explanation": "ここは〈購入〉の意味。買い求める意味は連続では表せない。"}, {"text": "荷物を倉庫に連続した。", "explanation": "ここは〈保管〉の意味。物をしまって管理する意味は連続にはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51559, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その地域では地震が連続を起こった。", "corrected_sentence": "その地域では地震が連続して起こった。", "error_description": "「連続」に続く「を」が誤り。「連続して起こる」と動詞を修飾する形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51559, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は三年連続が表彰された。", "corrected_sentence": "彼女は三年連続で表彰された。", "error_description": "「連続」に続く助詞が「が」になっている。副詞的に「連続で」と使う必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「連続で」は『続けて』の意味で、「十日連続で雨が降り」に合う。"}, {"text": "に", "is_correct": false, "explanation": "「連続に」は副詞としては不自然で、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「連続を」は目的語の形で、後ろの「雨が降り」とつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「連続へ」は方向を表す助詞で、期間の意味に合わない。"}], "correct_answer": "で", "explanations": {"で": "「連続で」は『続けて』の意味で、「十日連続で雨が降り」に合う。", "に": "「連続に」は副詞としては不自然で、文が成り立たない。", "を": "「連続を」は目的語の形で、後ろの「雨が降り」とつながらない。", "へ": "「連続へ」は方向を表す助詞で、期間の意味に合わない。"}, "error_tags": {"に": "副詞の形", "を": "目的語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断続", "is_correct": true, "explanation": "「切れ目なく続く」の対義語で、途切れ途切れに続くことを表す。"}, {"text": "天候", "is_correct": false, "explanation": "空模様の意味で、連続の対義語にはならない。"}, {"text": "経路", "is_correct": false, "explanation": "道筋の意味で、連続と対になる関係ではない。"}, {"text": "作物", "is_correct": false, "explanation": "農産物の意味で、連続の対義語ではない。"}], "correct_answer": "断続", "explanations": {"断続": "「切れ目なく続く」の対義語で、途切れ途切れに続くことを表す。", "天候": "空模様の意味で、連続の対義語にはならない。", "経路": "道筋の意味で、連続と対になる関係ではない。", "作物": "農産物の意味で、連続の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51560, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断続", "is_correct": true, "explanation": "「切れ目なく続く」の対義語で、途切れ途切れの音を表す。"}, {"text": "寝具", "is_correct": false, "explanation": "布団などの意味で、連続の対義語ではない。"}, {"text": "乗車", "is_correct": false, "explanation": "車に乗る意味で、連続とは対になる関係ではない。"}, {"text": "料金", "is_correct": false, "explanation": "代金の意味で、連続の対義語にはならない。"}], "correct_answer": "断続", "explanations": {"断続": "「切れ目なく続く」の対義語で、途切れ途切れの音を表す。", "寝具": "布団などの意味で、連続の対義語ではない。", "乗車": "車に乗る意味で、連続とは対になる関係ではない。", "料金": "代金の意味で、連続の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126782c3-a424-46d3-899b-c2efd02da1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
